def _load_tool(name):
    """按脚本同目录 import（从任何工作目录启动都能找到兄弟模块）。"""
    tools = os.path.dirname(os.path.abspath(__file__))
    if tools not in sys.path:
        sys.path.insert(0, tools)
    return __import__(name)


