def _rect_hit(a, b, tol=1):
    """两个 (x, y, w, h) 矩形是否相交（带 tol 容差）。v25.18：找"哪几条遮色条压在旧框上"。"""
    return not (a[0] + a[2] + tol < b[0] or b[0] + b[2] + tol < a[0]
                or a[1] + a[3] + tol < b[1] or b[1] + b[3] + tol < a[1])


def _invalidate_rect(tree, box):
    """把一块矩形（tree 客户区坐标）标成"需要重画" —— win32 `InvalidateRect`，微秒级。

    只标脏、不画：由 `_flush_screen`（v25.17）的 `UpdateWindow` 当场落实（同步、不进消息队列）。
    ⚠️ 必须在 **place 的 unmap / map 已落实**（`update_idletasks`）之后调才有效 —— v25.9 踩过
    "unmap 还没生效时画不动"。非 Windows / 调用失败一律静默跳过（只是刷新提示，坏了不影响 UI）。
    """
    try:
        from ctypes import wintypes
        x, y, w, h = (int(v) for v in box)
        rect = wintypes.RECT(x - 1, y - 1, x + w + 1, y + h + 1)
        ctypes.windll.user32.InvalidateRect(tree.winfo_id(), ctypes.byref(rect), True)
    except Exception:
        pass


