                                 # 趁幕布盖着把这几十毫秒等掉，撤幕那一下 md 已经在画上。
CURTAIN_HOLD_CLOSE_MS = 0        # 收预览：没有要等的东西（表是本地重画，settle 已泵完）。
SWAP_SETTLE_ROUNDS = 4           # `_settle_preview_swap` 泵几轮（v84：级联重排要好几轮才落完，
                                 # 见那个函数里 v84 那段注释；幕布盖着时多泵几轮不花用户的时间）。
PREVIEW_COLD_CAP_MS = 2500       # v94：**冷启动**开预览时幕布最多多等多久（等页面真画出内容）。
                                 # 实测（2026-10-08，本机）：宿主 ready ≈0.5s → 导航 → 页面
                                 # complete + 滚好锚点 ≈1.2~1.7s；上限给 2.5s 留余量。热档不走这条
                                 # （已导航过 = 立即返回，v84 的 40ms 时序一个字不动）。
PREVIEW_COLD_SETTLE_MS = 80      # v94：页面就绪后再多等这么一下 —— 锚点滚动是导航完成后
                                 # 另发的一发 JS，等它落位再亮窗口（免得先露 md 顶部再跳一下）。


class _CurBMIH(ctypes.Structure):
    """幕布截屏用的 BITMAPINFOHEADER（**放模块级** —— 类体里嵌套类引不到外层类体的名字）。"""
    _fields_ = [("biSize", ctypes.c_uint32), ("biWidth", ctypes.c_int32),
                ("biHeight", ctypes.c_int32), ("biPlanes", ctypes.c_uint16),
                ("biBitCount", ctypes.c_uint16), ("biCompression", ctypes.c_uint32),
                ("biSizeImage", ctypes.c_uint32), ("biXPelsPerMeter", ctypes.c_int32),
                ("biYPelsPerMeter", ctypes.c_int32), ("biClrUsed", ctypes.c_uint32),
                ("biClrImportant", ctypes.c_uint32)]


class _CurBMI(ctypes.Structure):
    _fields_ = [("bmiHeader", _CurBMIH), ("bmiColors", ctypes.c_uint32 * 3)]


class _Curtain:
    r"""v84：**幕布** —— 开 / 收题解预览时，先把当前画面原样「冻」成一张静态图盖住整窗，
    底下从容换页 / 重画（用户全程看到的就是「变前」那张静止画面），最后**一拍撤幕**：
    屏幕上只存在「变前」「变后」两个画面，中间一帧都不露。

    为什么要重做（2026-10-07 用户口径「收起 md 时显示出错，已经改了很久，重做收起打开
    的方式，要求画面流畅不闪烁」）：
      * v73 的「两页常驻、只翻 z 序」已经把「表重排 ~70ms」这条根拔了，但**被盖住的那一页
        从来没收到过 WM_PAINT**（Windows 不给被遮窗口发重绘），`lift` / `lower` 露出来的
        是一块没画过的区域 —— 补画要 1~2 帧，50fps 抓帧总能抓到「左半已切换、右半还是旧
        画面」的复合帧（v56 → v61 → v66 → v82 四代补丁各修掉一部分，没清零）。
      * 本机实验（`jobs\e1305a61\tmp\exp6~8.py`，逐帧抓屏判态）两句话：
        ① **跨顶层窗口不构成兄弟遮挡** —— v73 那条「被遮窗口不发 WM_PAINT」只对**同一个
           窗口树里的兄弟**成立；顶上压一个**别的顶层窗口**，底下照样画得动。
        ② 所以「盖着一张静态画、底下画完了再掀」是**可做到一帧到位**的：撤幕当刻不泵不睡
           立刻采样 = 新画面（实验实测）。
      * 幕布本体 = **分层窗口（WS_EX_LAYERED）+ `UpdateLayeredWindow`（截屏 DIB）**：
        实测「建窗 + 上屏」4.9ms、撤幕 1.1ms；内容不走 WM_PAINT（上屏即最终样子，
        没有黑框 / 白框那一拍）。`WS_EX_NOACTIVATE` 不抢焦点、`WS_EX_TOOLWINDOW` 不进
        任务栏、`WS_EX_TRANSPARENT` 鼠标穿透（这几十毫秒里点哪儿都还是点在 TB 上）。
      * 任何一步失败一律静默退场（`open()` 返回 False）—— 没有幕布就是今天的行为，绝不更差。
    """

    _cls_name = "TbSwapCurtain"
    _proto_ready = False
    _cls_ready = False
    _hinst = None
    _cb = None                   # WNDPROC 回调必须留引用（被 GC 掉 = 该窗口的消息没人接）

    _WS_EX_LAYERED = 0x00080000
    _WS_EX_TRANSPARENT = 0x00000020
    _WS_EX_TOOLWINDOW = 0x00000080
    _WS_EX_NOACTIVATE = 0x08000000
    _WS_POPUP = 0x80000000
    _SW_SHOWNOACTIVATE = 4
    _ULW_ALPHA = 2
    _SRCCOPY = 0x00CC0020

    _BMIH = _CurBMIH                  # 结构体定义在模块级（类体里嵌套类互相引用不到，见那里注释）
    _BMI = _CurBMI

    class _BLENDFN(ctypes.Structure):
        _fields_ = [("BlendOp", ctypes.c_ubyte), ("BlendFlags", ctypes.c_ubyte),
                    ("SourceConstantAlpha", ctypes.c_ubyte), ("AlphaFormat", ctypes.c_ubyte)]

    class _PT(ctypes.Structure):
        _fields_ = [("x", ctypes.c_long), ("y", ctypes.c_long)]

    class _SZ(ctypes.Structure):
        _fields_ = [("cx", ctypes.c_long), ("cy", ctypes.c_long)]

    def __init__(self):
        self.hwnd = None
        self.dc = None
        self.bmp = None
        self._old_bmp = None

    # ------------------------------------------------------------ Win32 原型（进程内一次）
    @classmethod
    def _prep_win32(cls):
        r"""把用到的 Win32 函数原型一次设好。

        **64 位下必须显式声明句柄类型** —— ctypes 默认把 Python int 按 32 位 C int 传 / 收，
        句柄一大就被截断：`GetParent()` 返回截断值、`CreateWindowExW()` 静默失败（返回 0）。
        本机真 TB 里实测就是栽在这上面（幕布建不出来、`_curtain_up` 静默退场；小实验里
        窗口句柄小、侥幸能过 —— 典型的"只在玩具里成立"）。只设本类用的这几个函数，
        不动 `status_gui.py` 别处那三处调用（`InvalidateRect` / `SetFocus` / `UpdateWindow`）。
        """
        if cls._proto_ready:
            return
        from ctypes import wintypes
        HWND = ctypes.c_void_p
        u, g = ctypes.windll.user32, ctypes.windll.gdi32
        u.GetParent.restype = HWND
        u.GetParent.argtypes = [HWND]
        u.GetWindowRect.restype = ctypes.c_int
        u.GetWindowRect.argtypes = [HWND, ctypes.c_void_p]
        u.IsIconic.restype = ctypes.c_int
        u.IsIconic.argtypes = [HWND]
        u.GetSystemMetrics.restype = ctypes.c_int
        u.GetSystemMetrics.argtypes = [ctypes.c_int]
        u.GetDC.restype = HWND
        u.GetDC.argtypes = [HWND]
        u.ReleaseDC.restype = ctypes.c_int
        u.ReleaseDC.argtypes = [HWND, HWND]
        u.CreateWindowExW.restype = HWND
        u.CreateWindowExW.argtypes = [ctypes.c_uint32, ctypes.c_wchar_p, ctypes.c_wchar_p,
                                      ctypes.c_uint32, ctypes.c_int, ctypes.c_int,
                                      ctypes.c_int, ctypes.c_int, HWND, HWND, HWND,
                                      ctypes.c_void_p]
        u.DestroyWindow.restype = ctypes.c_int
        u.DestroyWindow.argtypes = [HWND]
        u.ShowWindow.restype = ctypes.c_int
        u.ShowWindow.argtypes = [HWND, ctypes.c_int]
        u.RegisterClassExW.restype = ctypes.c_uint16
        u.RegisterClassExW.argtypes = [ctypes.c_void_p]
        u.UpdateLayeredWindow.restype = ctypes.c_int
        u.UpdateLayeredWindow.argtypes = [HWND, HWND, ctypes.c_void_p, ctypes.c_void_p,
                                          HWND, ctypes.c_void_p, ctypes.c_uint32,
                                          ctypes.c_void_p, ctypes.c_uint32]
        g.CreateDIBSection.restype = HWND
        g.CreateDIBSection.argtypes = [HWND, ctypes.c_void_p, ctypes.c_uint32,
                                       ctypes.c_void_p, HWND, ctypes.c_uint32]
        g.CreateCompatibleDC.restype = HWND
        g.CreateCompatibleDC.argtypes = [HWND]
        g.SelectObject.restype = ctypes.c_void_p
        g.SelectObject.argtypes = [HWND, ctypes.c_void_p]
        g.DeleteDC.restype = ctypes.c_int
        g.DeleteDC.argtypes = [HWND]
        g.DeleteObject.restype = ctypes.c_int
        g.DeleteObject.argtypes = [ctypes.c_void_p]
        g.BitBlt.restype = ctypes.c_int
        g.BitBlt.argtypes = [HWND, ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_int,
                             HWND, ctypes.c_int, ctypes.c_int, ctypes.c_uint32]
        # ⚠️ `AlphaBlend` **不在 gdi32 里**（实测 `gdi32.AlphaBlend` = AttributeError:
        #    function not found —— 本机第一次就因为这句异常把整个 `_curtain_up` 掀掉、
        #    又被外层 `except` 静默吞成"幕布没建出来"）。它在 **msimg32.dll**：
        try:
            _ab = ctypes.windll.msimg32.AlphaBlend
            _ab.restype = ctypes.c_int
            _ab.argtypes = [HWND, ctypes.c_int, ctypes.c_int, ctypes.c_int,
                            ctypes.c_int, HWND, ctypes.c_int, ctypes.c_int,
                            ctypes.c_int, ctypes.c_int, ctypes.c_void_p]
            cls._alphablend = _ab
        except Exception:
            cls._alphablend = None       # 拿不到就跳过那一发兜底（主路 BitBlt 照走）
        cls._proto_ready = True

    # ------------------------------------------------------------ 窗口类（进程内一次）
    @classmethod
    def _prep_class(cls):
        """注册窗口类。`hbrBackground` 留空（NULL）—— 幕布内容**只由 UpdateLayeredWindow 给**，
        绝不让 WM_ERASEBKGND 擦一下（那就是一闪白/黑）。"""
        if cls._cls_ready:
            return True
        cls._prep_win32()
        from ctypes import wintypes
        user32 = ctypes.windll.user32
        lresult, wparam, lparam = ctypes.c_ssize_t, ctypes.c_size_t, ctypes.c_ssize_t
        user32.DefWindowProcW.restype = lresult
        user32.DefWindowProcW.argtypes = [wintypes.HWND, ctypes.c_uint, wparam, lparam]
        proc_t = ctypes.WINFUNCTYPE(lresult, wintypes.HWND, ctypes.c_uint, wparam, lparam)

        def _wp(hwnd, msg, wp, lp):
            return user32.DefWindowProcW(hwnd, msg, wp, lp)

        cls._cb = proc_t(_wp)            # 留引用（见类头）

        class WNDCLASSEX(ctypes.Structure):
            _fields_ = [("cbSize", ctypes.c_uint), ("style", ctypes.c_uint),
                        ("lpfnWndProc", proc_t), ("cbClsExtra", ctypes.c_int),
                        ("cbWndExtra", ctypes.c_int), ("hInstance", ctypes.c_void_p),
                        ("hIcon", ctypes.c_void_p), ("hCursor", ctypes.c_void_p),
                        ("hbrBackground", ctypes.c_void_p),
                        ("lpszMenuName", ctypes.c_wchar_p),
                        ("lpszClassName", ctypes.c_wchar_p), ("hIconSm", ctypes.c_void_p)]

        wc = WNDCLASSEX()
        wc.cbSize = ctypes.sizeof(WNDCLASSEX)
        wc.lpfnWndProc = cls._cb
        km = ctypes.windll.kernel32
        km.GetModuleHandleW.restype = ctypes.c_void_p     # v84：不声明原型会返回截断值
        km.GetModuleHandleW.argtypes = [ctypes.c_wchar_p]
        wc.hInstance = km.GetModuleHandleW(None)
        wc.lpszClassName = cls._cls_name
        cls._hinst = wc.hInstance
        if not user32.RegisterClassExW(ctypes.byref(wc)):
            return False
        cls._cls_ready = True
        return True

    # ------------------------------------------------------------ 盖上 / 撤掉
    def open(self, owner, x, y, w, h):
        """截屏 → 建分层窗口 → 上屏（全在屏幕物理坐标里）。成功 True；任何一步失败 False。"""
        user32 = ctypes.windll.user32
        gdi32 = ctypes.windll.gdi32
        if w <= 0 or h <= 0 or not self._prep_class():
            return False
        scr = user32.GetDC(0)
        if not scr:
            return False
        try:
            # ① 截屏：屏幕 DC（**不是窗口 DC** —— md 是 WebView2 的 DComp 画面，窗口 DC 拷不到）
            bi = self._BMI()
            bi.bmiHeader.biSize = ctypes.sizeof(self._BMIH)
            bi.bmiHeader.biWidth = w
            bi.bmiHeader.biHeight = -h                 # 负数 = 顶朝下（跟屏幕同向）
            bi.bmiHeader.biPlanes = 1
            bi.bmiHeader.biBitCount = 32
            pbits = ctypes.c_void_p()
            self.bmp = gdi32.CreateDIBSection(scr, ctypes.byref(bi), 0,
                                              ctypes.byref(pbits), None, 0)
            if not self.bmp:
                return False
            self.dc = gdi32.CreateCompatibleDC(scr)
            self._old_bmp = gdi32.SelectObject(self.dc, self.bmp)
            gdi32.BitBlt(self.dc, 0, 0, w, h, scr, x, y, self._SRCCOPY)
            # alpha 通道：实测本机屏幕 DC 拷出来就是 255（不透明）；万一不是（别的显卡 /
            # 驱动给 0），用不带 AC_SRC_ALPHA 的 AlphaBlend 再拷一遍 —— 它会把目标
            # alpha 写成 SourceConstantAlpha（=255）。只读两个字节判断，不整块取回来。
            pb = ctypes.cast(pbits, ctypes.POINTER(ctypes.c_ubyte))
            if pb[3] != 255 or pb[(w * h - 1) * 4 + 3] != 255:
                ab = getattr(self.__class__, "_alphablend", None)
                if ab is not None:
                    bf = self._BLENDFN(0, 0, 255, 0)
                    ab(self.dc, 0, 0, w, h, scr, x, y, w, h, ctypes.byref(bf))
            # ② 建分层窗口，owner = TB 主窗（永远压在它上面、随它一起销毁）
            ex = (self._WS_EX_LAYERED | self._WS_EX_TRANSPARENT
                  | self._WS_EX_TOOLWINDOW | self._WS_EX_NOACTIVATE)
            self.hwnd = user32.CreateWindowExW(ex, self._cls_name, "", self._WS_POPUP,
                                               x, y, w, h, owner, None, self._hinst, None)
            if not self.hwnd:
                raise OSError("CreateWindowExW 失败")
            pt_src, pt_dst = self._PT(0, 0), self._PT(x, y)
            size = self._SZ(w, h)
            blend = self._BLENDFN(0, 0, 255, 1)        # AC_SRC_ALPHA：逐像素用 DIB 的 alpha
            if not user32.UpdateLayeredWindow(self.hwnd, None, ctypes.byref(pt_dst),
                                              ctypes.byref(size), self.dc,
                                              ctypes.byref(pt_src), 0,
                                              ctypes.byref(blend), self._ULW_ALPHA):
                raise OSError("UpdateLayeredWindow 失败")
            user32.ShowWindow(self.hwnd, self._SW_SHOWNOACTIVATE)
            return True
        except Exception:
            self.close()
            return False
        finally:
            user32.ReleaseDC(0, scr)

    def close(self):
        """撤幕（DestroyWindow 就一帧的事）+ 释放 DC / 位图；重复调用无害。"""
        user32 = ctypes.windll.user32
        gdi32 = ctypes.windll.gdi32
        if self.hwnd:
            try:
                user32.DestroyWindow(self.hwnd)
            except Exception:
                pass
            self.hwnd = None
        if self.dc:
            try:
                if self.bmp:
                    gdi32.SelectObject(self.dc, self._old_bmp)
                gdi32.DeleteDC(self.dc)
            except Exception:
                pass
            self.dc = None
        if self.bmp:
            try:
                gdi32.DeleteObject(self.bmp)
            except Exception:
                pass
            self.bmp = None


class _RowBorder:
    r"""给 Treeview 的**选中行**画一圈 3px 边框（v23 主题「选择当前行 ▸ 边框」用；v41 起 2px→3px）。

    为什么自己画：Treeview 的 tag 只有背景 / 前景，**没有边框这一项**；而"铺一个选中底色"
    会把行底色（Radix 配色的状态色）吃掉。做法照 v22 的列间竖线 —— 四条 `tk.Frame` 盖在
    控件**内部**，位置取 `tree.bbox(iid)`；滚动 / 改窗大小 / 换选中行 / 换页都要重摆，
    `bbox` 返回空（行不在视口里）就 `place_forget()` 收起来。

    **v25.2 性能修（连按方向键「旧框还没消失新框就出现」的根）**：真表 119 行实测每步
    27.8ms（>按键重复间隔 ~33ms 的八成），重绘被挤没 → 旧位置擦除迟到。三处开销砍掉：
    ① **位置缓存** —— 目标框跟上一次逐值相同就**一个 Tcl 调用都不发**（Select 的"立即画"
       和空闲重摆各来一发，去重后第二发是空的）；
    ② **`lift()` 只在新显示时做一次**（place 到新位置不改 z 序，每帧 lift 纯属浪费）；
    ③ 失焦重画只走 `set_focused`（颜色真变了才动）。
    可行性早先用 `~\.dsh\tasks\status-gui\row_border_probe.py --selftest` 验过（退出码 0）。
    """

    def __init__(self, tree, width=SEL_BORDER_W):
        self.tree = tree
        self.w = width
        self.line = "#000000"        # 聚焦时的线色
        self.line_blur = "#CCCCCC"   # 失焦时的线色（v25.2：焦点一变就换色重画）
                                     # v41 定为 `#CCCCCC`；v55 曾加深（改错了对象）；v57 随「改回3px」一并回滚
                                     #      （失焦再压淡一档，跟聚焦的纯黑拉开距离）
        self.color = self.line
        self.iid = None
        self.focused = True
        self._placed = None          # 上一次摆过的 (x, y, w, h)；None = 不在屏幕上
        self.frames = [tk.Frame(tree, bg=self.color, highlightthickness=0, takefocus=0)
                       for _ in range(4)]

    def cur_color(self):
        """此刻该用的线色（聚焦 / 失焦两支）。"""
        if self.line is None:
            return None
        return self.line if self.focused else (self.line_blur or self.line)

    def set_style(self, border):
        """换主题：按「当前行边框」档给线色（黑 / 白两档各有聚焦 / 失焦两支），「无」档把线收掉。

        v75.3：输入从"四合一档"（旧 SEL_THEME，带 mode）改为**纯边框档** dict ——
        底色归「当前行颜色」组管，这里只管线（两组自由搭配）。

        注意"收掉"时要**显式清掉颜色** —— 原写法 `line or self.color` 会留着上一次的颜色，
        `redraw()` 里判 `not self.color` 就永远为假，边框会留一屏（冒烟逮到过）。
        """
        line = (border or {}).get("line")
        if line:
            self.line = line
            self.line_blur = (border or {}).get("line_blur") or self.line
        else:
            self.line = self.line_blur = None
        self.color = self.cur_color()
        for f in self.frames:
            try:
                f.configure(bg=(self.color or "#000000"))
            except tk.TclError:
                pass
        if not line:
            self.iid = None
            self._hide()             # ⚠️ 别在 _hide() 之前清 _placed：会短路掉"收边框"（冒烟逮到过）

    def set_focused(self, focused):
        """表格族拿到 / 丢掉键盘焦点（v25.2：失焦线变淡）。颜色真变了才算事。"""
        if focused == self.focused:
            return
        self.focused = focused
        c = self.cur_color()
        if c == self.color:
            return
        self.color = c
        for f in self.frames:
            try:
                f.configure(bg=(c or "#000000"))
            except tk.TclError:
                pass

    def show(self, iid):
        self.iid = iid
        return self.redraw()

    def hide(self):
        """收掉整个框（v25.5「先收 → 当场擦 → 再画」的第一步，`_on_tree_sel_change` 用）。

        v25.6：收之前先把**旧框那块矩形**主动标脏（`InvalidateRect`）—— hide 的 unmap 暴露
        **不一定会被系统标脏**，实测会留下"整套旧框像素"几百毫秒（用户看到的「早期那一行闪现
        一下再消失」就是它：截图里两个**完整**的框、而控件账上只有一套 4 条 Frame）。
        """
        if self._placed is not None:
            self._invalidate(self._placed)
        self.iid = None
        self._hide()

    def _invalidate(self, box):
        """把一块矩形（tree 客户区坐标）标成"需要重画"（win32 `InvalidateRect`，微秒级）。

        只标脏、不画：落实统一走 `_flush_screen()`（v25.17：先把 place 落实（update_idletasks）、
        再标脏、最后 `UpdateWindow` 同步重画）。⚠️ 顺序照旧：**必须在 unmap / place 落实之后**
        才有效（v25.9 踩过：unmap 没生效时打不动）。模块级 `_invalidate_rect` 同一套实现，
        主类（`_flush_screen`）直接调它。
        """
        _invalidate_rect(self.tree, box)

    def _hide(self):
        if self._placed is None:
            return                   # 本来就不在屏幕上：不重复发 place_forget
        self._placed = None
        for f in self.frames:
            try:
                f.place_forget()
            except tk.TclError:
                pass

    def redraw(self):
        if not self.iid or not self.color:
            self._hide()
            return None
        try:
            box = self.tree.bbox(self.iid)      # (x, y, w, h)；行不在视口里返回 ""
        except tk.TclError:
            return None
        if not box:
            self._hide()
            return None
        x, y, w, h = (int(v) for v in box)
        top, bottom, left, right = self.frames
        if self._placed is None:
            # 从隐藏回到显示：整摆一遍 + lift 一次（之后 place 挪位置不改 z 序，不用每帧 lift）
            top.place(x=x, y=y, width=w, height=self.w)
            bottom.place(x=x, y=y + h - self.w, width=w, height=self.w)
            left.place(x=x, y=y, width=self.w, height=h)
            right.place(x=x + w - self.w, y=y, width=self.w, height=h)
            for f in self.frames:
                f.lift()                        # 压在行内容之上（v88 前还有"与列间竖线"）
        else:
            if (x, y, w, h) == self._placed:
                return box                      # 位置一个字没变：一个 Tcl 调用都不发
            # v25.5：**纯摆放**（不碰事件循环）——「先收 → 当场擦 → 再画」的时序搬到
            # `_on_tree_sel_change` 里做，"擦"统一走带护栏的 `_flush_screen()`。
            # 为什么不能在这里 update()：它会被「积压的 Select 回放链」逐层嵌套调用 —— 每层
            # 各画一帧中间态，用户看到的「鬼畜回放」（停手后框从 9、8、7…依次闪现）就是这么来的。
            # 本分支只服务**滚动 / 重绘**路径（`_sync_all_row_borders`，它们不先收）。
            top.place_configure(x=x, y=y, width=w)
            bottom.place_configure(x=x, y=y + h - self.w, width=w)
            left.place_configure(x=x, y=y, height=h)
            right.place_configure(x=x + w - self.w, y=y, height=h)
        self._placed = (x, y, w, h)
        return box


class _RowPads:
    r"""「遮色条」阵列（v25.7「重药」）—— 把「黑框残留像素」从物理上盖没。

    背景：黑框是 4 条会移动的小 Frame；它挪走后，"旧位置的一整套框像素"要靠 Tk / Windows 的
    暴露重绘才被擦 —— 实测那套机制会被消息队列吊住（`InvalidateRect` + `UpdateWindow` 都打
    不动），残留能挂几百毫秒（用户看到的「早期那一行闪现一下再消失」）。

    做法：黑框**永远只画在"行位网格"的四条边上**（行位 = 表头下第 k 格、屏幕位置固定）——
    那就在**每一条边位**上铺一条**该行底色**的小 Frame（**永不动**，只随行底色换色）：
    残留"出现在这些位置"时被**窗口直接盖住**（覆盖靠 z 序、立即生效、**不经过重绘机制**），
    从此不可见。4 条/行 × 可见约 19 行 ≈ 76 条；窗口变高按需长池。
    边缘（v41 起 3px，`SEL_BORDER_W`）处没有行内容（文字有内边距），所以条不会挡字。
    只在总表用（看板 / 统计页要扩再加）。
    """

    def __init__(self, tree):
        self.tree = tree
        self.pads = []          # Frame 池（顺序 = [上,下,左,右] × 行位）
        self.state = []         # 每条的 (x, y, w, h, color) 指纹（没变不发 Tcl）

    def _pad(self, i):
        while len(self.pads) <= i:
            f = tk.Frame(self.tree, bd=0, highlightthickness=0, takefocus=0, bg=C_PANEL)
            self.pads.append(f)
            self.state.append(None)
        return self.pads[i]

    def sync(self, rows, left_w=SEL_BORDER_W):
        """rows = [(box, color)]（可见行的 bbox 与行底色，按屏幕上到下的顺序）。

        位置用**序数**：滚动后"第 k 个可见行"仍在"第 k 格"——位置的 place 全被缓存跳过，
        只有入屏新行的**颜色**会更新（连按 / 滚动时每步只动 2 行 × 4 条）。
        `left_w`（v25.18）：左侧那条的宽度 —— Radix 档给 6（= `TODAY_BAR_W`，要盖住今天竖条的
        旧像素；那时最左是 6px 窄列、条下面没有文字），默认 2。
        """
        i = 0
        for box, color in rows:
            x, y, w, h = (int(v) for v in box)
            # v41：4 条的粗细跟选中框同宽（`SEL_BORDER_W`）—— 条窄了会在旧框位置留残线
            specs = ((x, y, w, SEL_BORDER_W),
                     (x, y + h - SEL_BORDER_W, w, SEL_BORDER_W),
                     (x, y, left_w, h),
                     (x + w - SEL_BORDER_W, y, SEL_BORDER_W, h))
            for spec in specs:
                f = self._pad(i)
                st = (spec, str(color))
                if self.state[i] != st:
                    f.place(x=spec[0], y=spec[1], width=spec[2], height=spec[3])
                    try:
                        f.configure(bg=color)
                    except tk.TclError:
                        pass
                    self.state[i] = st
                i += 1
        for j in range(i, len(self.pads)):          # 行数变少（窗口变矮）：多余的收起
            if self.state[j] is not None:
                try:
                    self.pads[j].place_forget()
                except tk.TclError:
                    pass
                self.state[j] = None


