def _rb_val(rb):
    """v75.2：主题块某颗钮的"值" —— Radiobutton 用 `value` 选项；Checkbutton（黑夜模式开关）
    没有 `value`，建钮时贴了 `_tb_value` 属性（焦点记忆 `"组:值"` 两处读取共用这一个口径）。"""
    v = getattr(rb, "_tb_value", None)
    if v is not None:
        return str(v)
    return str(rb.cget("value"))

