#   与看板类标题行用）+ `lvl0` / `lvl1` / `lvl2` / `lvl3`（统计页**平台行 / 父行 / 子行 / 三层行**
#   各自的深浅两档 —— 用户口径「父行之间是一种配合色、子行之间是一种配合色」，每套各配一组：按
#   「离该套六个状态色最远」选色相，亮套掺白生成、深套按 HSL 压暗；**v86** 新增 `lvl0` = 按场次
#   视图的平台层（牛客 / 洛谷 / AtCoder / Codeforces 那一行），同法生成：色相离该套**全部已用色**
#   （六状态底 + lvl1 + lvl2 + 斑马）最远、浓淡沿用 lvl1，对比度自动留 0.35 余量；
#   **v97**（2026-10-08，知识点词典升两级桶「数学 → 数论 → 素数」）新增 `lvl3` = 统计页知识点树的
#   **第三层**（第 3 层及更深都用它），同法生成、外加「与 lvl1 / lvl2 色相差 ≥40°」的同屏可辨约束）
#   + `today_fg`（今天日期字）/ `bar`（行首竖条）。
#   色值出处 = 各设计系统官方发布（Tailwind / Radix / Catppuccin / Chakra / Rose Pine / Kanagawa /
#   Nord / Bootstrap / Dracula；对照见桌面那份 HTML）。
#   用户拍板的口径（2026-10-07）：① **状态行 = 该套自己的彩色状态字**（v25「整行染色」口径回归，
#   色 = HTML chip 的字色）；② 无状态的行 = 该套**默认正文色**（用户「这些主题都要配上默认字色」）；
#   ③ 「未做」行**继续走斑马纹**（不铺各套的「未做」底色；那支底色与「未做字色」只在表里留档）。
#   ① 的初版（v71）曾是「所有亮套 #1F2430 / 所有深套 #E6EAF0」的统一墨色 —— 用户看后否掉、改回本口径。


def _mk_scheme(bgs, inks, ink, zebra, lvl0, lvl1, lvl2, lvl3, today_fg, bar):
    """拼一套配色。`bgs` / `inks` 按 `STATES` 顺序（inks 给单个字符串 = 六状态共用）。

    v86：加 `lvl0` 槽（平台层两档）—— 参数位置在 `zebra` 与 `lvl1` 之间。
    v97：加 `lvl3` 槽（知识点统计第三层的两档）—— 参数位置在 `lvl2` 与 `today_fg` 之间。
    """
    return {"status": {s: (bgs[i], inks if isinstance(inks, str) else inks[i])
                       for i, s in enumerate(STATES)},
            "ink": ink, "zebra": zebra, "lvl0": lvl0, "lvl1": lvl1, "lvl2": lvl2,
            "lvl3": lvl3, "today_fg": today_fg, "bar": bar}


_WZ = ("#ffffff", "#eef2f8")         # 亮套斑马（= C_PANEL / C_ZEBRA，v70 前的老样子）

