    #   再朝原值退 10% —— **避免与 muted 等其它槽同值**：深↔浅两端颜色映射要求每套 13 槽
    #   两两唯一，同值就分不清"刷回浅色时该还原成哪个槽"（v75.2 修的一个真雷：d1/d2 等的
