    #   Dark）同逻辑的**深底 + 亮字**：底 = 该状态色的同色相压暗（H 保持、S×0.65 夹 0.40-0.80），
    #   字 = **原来的亮底色**；参数拿 d1/d5 的「字 → 底」实测对照当标杆校准 —— **关键关系 =
