# v75（黑夜模式）：**深色框架板**（逐套配套）—— 键与 `SCHEME` 同一批（d1~d6）。
#   用途 = 黑夜模式下**非表行部分**的全部颜色（窗口底 / 第一行 / 表头 / 滚动条 / 设置页 / 弹窗 /
#   输入控件…），槽位与浅色板一一对应（浅色板 `FRAME_LIGHT` 在 C_* 常量区定义）：
#   bg=C_BG / panel=C_PANEL / text=C_TEXT / muted=C_MUTED / accent=C_ACCENT /
#   accent_dark=C_ACCENT_DARK / accent_light=C_ACCENT_LIGHT / line=C_LINE /
#   select_off=C_SELECT_OFF / placeholder=C_PLACEHOLDER / ok=C_OK / err=C_ERR。
#   （v88：`grid=C_GRID` 槽已删 —— 列间竖线整条去掉，见 v88 节。）
#   色值出处 = 各设计系统官方深色板（Radix gray 阶 / Catppuccin Mocha / Nord / Kanagawa Wave /
#   Bootstrap Dark / Dracula；d6 表头底 #343746 取社区 "current line darker"）。
#   对比度全量实测（text/bg ≥7、accent_dark/accent_light ≥4.5、线类 ≥1.1 —— 脚本留档于
#   `dark_mode_probe.py` 的会话记录；两处按实测微调过：d3 表头底 #434C5E→#3B4252、
#   d6 表头底 #44475A→#343746）。亮色配色（l1~l6）开黑夜 → `FRAME_FALLBACK`（中性深灰，
#   = d1 那套；用户拍板「亮色配色下用中性深灰兜底」）。
#   **v75.2**（用户拍板「所有白字在暗色主题都变暗」）：`text` 槽从浅墨调暗一档 —— 与 SCHEME 的
#   `ink` / `today_fg` **同值同口径**（每套取"最暗可行点"再退 10% 避开与 muted 同值；
#   亮色配色 + 黑夜的兜底板 = d1 板同步生效）。另：d2~d6 各有 1~3 个弱槽（grid / accent_light /
#   placeholder / select_off）做了 ±1 档微调，使**每套 13 槽两两唯一**（同上映射唯一性；观感不变）。
