# 状态 tag 的名字（只有配色开了 status 才挂；名字固定，切配色时好清）
SCHEME_TAG_PREFIX = "st_"
# v28：`TODAY_ZEBRA_TAG`（"todayz" 淡绿底 tag）已删 —— 今天改走行首竖条，不再有底色 tag


def theme_tag(scheme):
    """某个状态的行 tag 名（只有 Radix 这类"铺整行"的配色才会用到）。"""
    return SCHEME_TAG_PREFIX + scheme


def show_items(tree):
    """`tree.cget("show")` 的规范化 —— ttk 有时回字符串 "tree headings"、有时回元组
    `(<index object: 'tree'>, …)`（本机 8.6.18 实测），统一成小写词表再判。"""
    v = tree.cget("show")
    if isinstance(v, (list, tuple)):
        return [str(x).lower() for x in v]
    return str(v).lower().split()


def normalize_sel(border, color):
    """v75.3：选择当前行的**两组**脏值归位（认不出的键一律回默认：边框 none / 颜色 blue）。"""
    if border not in SEL_BORDER:
        border = "none"
    if color not in SEL_COLOR:
        color = "blue"
    return border, color


def normalize_scheme(scheme):
    """v71：配色 12 套（键见 `THEME_SCHEME_ITEMS`）—— 任何认不出的键（含旧配置里的
    `"default"`）一律回 `"radix"`（= Radix，老配置零迁移）。"""
    return scheme if scheme in SCHEME else "radix"


def normalize_theme_focus(raw):
    """v76：主题设置块「上次焦点」的配置值 = `"组:值"`（如 `"scheme:d3"`）。

    组 / 值认不出、类型不对 —— 一律 None（= 进块落第一件控件，脏值不崩；口径同 `normalize_theme`）。
    """
    if not isinstance(raw, str) or ":" not in raw:
        return None
    gk, _sep, val = raw.partition(":")
    for key, _label, items in THEME_GROUPS:
        if key == gk:
            if key == "daynight":       # v75.2：单开关——值域仍是 day / night（旧配置零迁移）
                return raw if val in (THEME_DAYNIGHT_DAY, THEME_DAYNIGHT_NIGHT) else None
            return raw if val in [v for v, _l in items] else None
    return None


# v82（用户口径「记住最后一次退出设置页时的焦点位置」）：设置界面记两样 ——
#   ① `set_focus` = 退出那一刻焦点在**哪一站**（左列表 / 快捷键表 / 主题块），见 `_set_focus_mem`；
#   ② `set_block` = 当时**摆着哪一块**（左列表的选中项 = `SET_ITEMS` 的 iid），见 `set_panel`。
# 认不出 / 类型不对一律 None（= 老口径：进设置落左列表第一项），脏值不崩（口径同 `normalize_theme`）。
SET_FOCUS_STATIONS = ("left", "keys", "theme", "help")   # v87：加 help（一览块）


def normalize_set_focus(raw):
    """v82：设置界面「上次焦点在哪一站」的配置值 —— left / keys / theme / help（v87），其余一律 None。"""
    return raw if raw in SET_FOCUS_STATIONS else None


def normalize_set_block(raw):
    """v82：设置界面「上次摆着哪一块」的配置值 —— `SET_ITEMS` 里的 iid，其余一律 None。"""
    return raw if raw in [k for k, _l in SET_ITEMS] else None


# v86（用户口径「记住上次的状态」）：按场次视图展开状态（iid：`P|平台` / `S|系列` / `R|场次`）
#   随配置持久化 —— 开窗还原、关窗写回。只留非空字符串、去重保序、封顶（防配置被手改爆掉）；
#   对不上的旧项无害（重画时找不到那行，等于已收起）。
ROUND_OPEN_CAP = 4000


def normalize_round_open(raw):
    """v86：按场次视图展开状态的配置值 —— list[str]（保序去重、封顶）；其余一律 None。"""
    if not isinstance(raw, list):
        return None
    out, seen = [], set()
    for v in raw[:ROUND_OPEN_CAP]:
        if isinstance(v, str) and v and v not in seen:
            seen.add(v)
            out.append(v)
    return out


# ================================================================ 自定义快捷键（v26）
