# 导航 / 系统键：不可被拿走（弹窗里按到它们 → 拒绝并提示）；`<KP…>` 前缀的也算
KEY_RESERVED = frozenset((
    "<Shift-Tab>", "<ISO_Left_Tab>",
    # v65（解锁批）：`<Tab>` = focus_next 主键、`<Escape>` = cancel 主键（都从保留表放开 = 可改）；
    # 副键（Shift-Tab / ISO_Left_Tab / BackSpace）必须留在表里 —— 7423 那条不变量：副键不可被拿。
    "<Left>", "<Right>", "<Up>", "<Down>",
    "<BackSpace>", "<Delete>", "<space>", "<Key-space>", "<Key-slash>",
    # v65：`<Prior>` / `<Next>`（PgUp/PgDn）从保留表放开 —— 已成注册表动作，键可改
    # v65：`<Home>` / `<End>` 也放开 —— 它们背后是 Tk 内建（树的首 / 末行），没人占用时照旧；
    #      用户可以把别的动作绑上去（我们 widget 级 handler 返回 break，会压过内建）。

))

_RE_KEYSEQ = re.compile(r"^<([A-Za-z]+-)*[A-Za-z0-9_]+>$")

# 纯修饰键的 keysym：捕获时跳过（等真正的组合键）
_MOD_KEYSYMS = frozenset((
    "Shift_L", "Shift_R", "Control_L", "Control_R", "Alt_L", "Alt_R",
    "Meta_L", "Meta_R", "Super_L", "Super_R", "Hyper_L", "Hyper_R",
    "Caps_Lock", "Num_Lock", "Scroll_Lock", "ISO_Level3_Shift", "Win_L", "Win_R",
))

# 「特殊键」keysym（不产字符：回车 / 功能键 / 方向 / 翻页…）—— 捕获时它们走 `<Return>` 这种
# 裸名拼法、Shift 要进修饰串（Shift+Enter ≠ Enter）；其余多字符 keysym（question / slash…）
# 是「字符名」，走程序既有的 `<Key-question>` 拼法、Shift 已编进 keysym 不进修饰串。
_KEY_SPECIAL = (frozenset((
    "Return", "KP_Enter", "Escape", "Tab", "ISO_Left_Tab", "BackSpace", "Delete",
    "Insert", "Home", "End", "Prior", "Next", "Up", "Down", "Left", "Right"))
    | frozenset("F%d" % i for i in range(1, 36))
    | frozenset("KP_%d" % i for i in range(10)))


def _seq_mods_key(seq):
    """拆 Tk 序列 → (修饰键集合, 键名)。`<Control-Key-z>` → ({"Control"}, "z")。"""
    parts = seq[1:-1].split("-")
    mods, i = set(), 0
    while i < len(parts) - 1 and parts[i] in ("Control", "Alt", "Shift"):
        mods.add(parts[i])
        i += 1
    key = "-".join(parts[i:])
    if key.startswith("Key-"):
        key = key[4:]
    return mods, key


def key_case_variants(seq):
    """裸字母键的大小写变体：无修饰的单字母（`<Key-f>` / `<Key-F>`）→ [小写写法, 大写写法]；
    其余序列原样返回 `[seq]`（带修饰的不动 —— Ctrl+Z 与 Ctrl+Shift+Z 是两个不同组合）。

    v68（用户口径「按大小写 f 都触发」）：f 与 F 是**同一个物理键**的两种写法 —— 区别只在
    Shift / CapsLock，Tk 事件里已经编进 keysym（实测：Shift+f 送来的 keysym 就是 "F"）。
    「跳到搜索框」默认键 `<Key-F>`，`_seqs_for` 绑定时两种写法一起挂，怎么按都进框；
    `keymap_assign` / `resolve_keymap` 的**撞键判定**也按变体集合相交来（f 与 F 不许分给两家）。
    """
    mods, key = _seq_mods_key(seq)
    if not mods and len(key) == 1 and key.isalpha():
        return ["<Key-%s>" % key.lower(), "<Key-%s>" % key.upper()]
    return [seq]


def keyseq_reject_reason(seq, aid=None):
    """这个序列能不能当自定义键？可以 → None；不可以 → 中文原因（弹窗 / 配置洗脏都用它）。

    aid 给了就按该操作的级别加一条规则：**根级操作**（挂 root 的）的**新键**要带
    Ctrl / Alt（或 F1~F12 这类功能键）—— 不然在搜索框里打字会把它误触发；
    「恢复默认」永远合法（`?` 这种默认键本身不满足上面那条，但它得能还原）。
    """
    if not isinstance(seq, str) or not _RE_KEYSEQ.match(seq):
        return "不是有效的按键写法"
    _parts = seq[1:-1].split("-")
    if _parts and _parts[-1].isdigit() and "Key" not in _parts:
        # v26.2：`<Control-1>` 在 Tk 里 = Ctrl+鼠标左键（数字不写 Key- 会被当成鼠标键）
        return "数字键要写成 Key-1 这样（光写 1 会被 Tk 当成鼠标键）"
    if seq in KEY_RESERVED or seq.upper().startswith("<KP"):
        if not (aid == "key_reset" and seq == "<Delete>"):
            # v57.3：`<Delete>` 是「快捷键：此项恢复默认」的默认键（用户拍板）—— 只给它豁免，
            #        别的操作拿 Delete 照旧拒；它自己**换**成别的保留键也照旧拒。
            return "固定键位（导航 / 系统键），不能拿"
    if aid is not None and seq == DEFAULT_KEYMAP.get(aid):
        return None
    if aid in KEY_ROOT_ACTIONS:
        mods, keysym = _seq_mods_key(seq)
        if not (mods & {"Control", "Alt"}) and \
                not (len(keysym) > 1 and keysym[0] == "F" and keysym[1:].isdigit()):
            return "根级操作要带 Ctrl / Alt（或 F1~F12）——光秃秃的键会跟搜索框打字打架"
    return None


def capture_seq(keysym, state):
    """弹窗里按到一键 → 翻成 Tk 绑定序列（纯逻辑，selftest 直接断言）。

    拼法跟程序既有默认逐字对齐：单字符 带修饰 = `<Control-z>`、光键 = `<Key-1>`；
    特殊键 = `<Return>` / `<Control-Home>`（Shift 进修饰串 —— Shift+Enter ≠ Enter）；
    其余字符名 = `<Key-question>`（Shift 已编进 keysym，不进修饰串）。纯修饰键 / 空键名 → None。
    state 位（Windows Tk 8.6 口径）：Shift=0x1、Control=0x4、Alt=0x8 | 0x20000（取并集；
    探针实测 Tk 里 `Key-` 前缀与其省略等价、以上各种拼法全可 bind）。
    """
    if not keysym or keysym in _MOD_KEYSYMS:
        return None
    mods = []
    if state & 0x4:
        mods.append("Control")
    if state & (0x8 | 0x20000):
        mods.append("Alt")
    if keysym in _KEY_SPECIAL and state & 0x1:
        mods.append("Shift")
    pre = ("-".join(mods) + "-") if mods else ""
    if len(keysym) == 1:
        if mods:
            if keysym.isdigit():
                # v26.2：**数字必须带 Key-** —— `<Control-1>` 在 Tk 里是「Ctrl+鼠标左键」！
                # （字母没有歧义，保持 <Control-z> 老拼法）
                return "<%sKey-%s>" % (pre, keysym)
            return "<%s%s>" % (pre, keysym)          # <Control-z>（同既有默认拼法）
        return "<Key-%s>" % keysym                   # <Key-1>
    if keysym in _KEY_SPECIAL:
        return "<%s%s>" % (pre, keysym)              # <Return> / <Control-Home>
    return "<%sKey-%s>" % (pre, keysym)              # <Key-question> / <Key-slash>


_KEY_PRETTY = {"Return": "Enter", "KP_Enter": "小键盘回车", "question": "?",
               "slash": "/", "space": "空格", "Prior": "PageUp", "Next": "PageDown",
               "Left": "←", "Right": "→", "Up": "↑", "Down": "↓", "Escape": "Esc",
               "apostrophe": "'", "quoteright": "'"}   # v93：单引号键（know_mode 新默认）


def pretty_seq(seq):
    """Tk 序列 → 给人看的写法（Ctrl+Z / Shift+Enter / ? / 1 …）；空 / None = 未绑定。"""
    if not seq or not isinstance(seq, str) or not (seq.startswith("<") and seq.endswith(">")):
        return "未绑定"
    mods, key = _seq_mods_key(seq)
    out = [{"Control": "Ctrl", "Alt": "Alt", "Shift": "Shift"}[m]
           for m in ("Control", "Alt", "Shift") if m in mods]
    key = _KEY_PRETTY.get(key, key)
    if mods and len(key) == 1 and key.isalpha():
        key = key.upper()
    return "+".join(out + [key])


KEY_LEADER_DOTS = 600               # v68：设置页快捷键表「操作」列点线的填充长度（Treeview 逐格裁到列缘）


def key_leader_text(name, dots=KEY_LEADER_DOTS):
    """设置页快捷键表「操作」列的一行文本 = 名字 + 空格 + 点线。

    v68（用户口径「左侧的操作跟右侧的键距离太远，左右文字中间用虚线做辅助线连接」）：
    点线固定填 `dots` 个「·」—— 超长部分由 Treeview **逐格裁剪**到列缘（实测裁在单元格
    右缘前 ~7px、不侵入「当前键」列），所以窗口拉伸 / 列宽变化全自动跟随，不用重算。
    """
    return name + " " + "·" * dots


def resolve_keymap(raw):
    """把配置里的差量（可能被手改坏）解析成完整 keymap。

    认不出的 id / 非法序列 / 保留键 / 根级规则不过 → 丢（保持默认）；
    文件里撞键（手改出来的）→ 按注册表顺序先占先得、后来者变「未绑定」（与界面里的「顶掉」同语义）。
    """
    km = dict(DEFAULT_KEYMAP)
    if isinstance(raw, dict):
        for aid, seq in raw.items():
            if aid not in km:
                continue
            if seq is None:
                km[aid] = None
            elif keyseq_reject_reason(seq, aid) is None:
                km[aid] = seq
    used = {}
    for aid, _n, _d in KEY_ACTIONS:
        s = km.get(aid)
        if s is None:
            continue
        vs = key_case_variants(s)        # v68：大小写变体算同一个物理键（f / F 先占先得）
        if any(v in used for v in vs):
            km[aid] = None
        else:
            for v in vs:
                used[v] = aid
    return km


def resolve_keymap2(raw, km1=None):
    """v74：键2（替代键）的解析 —— 结构照 `resolve_keymap`，两条规则不同：

    ① 键2 的默认是**全 None**（没设过 = 未绑定），不是 DEFAULT_KEYMAP；
    ② **键1 先占先得** —— km1 已占的键（含大小写变体），键2 不能再占（撞了就丢回 None）；
       键2 池内部照旧按注册表顺序先占先得。
    """
    km2 = {aid: None for aid, _n, _d in KEY_ACTIONS}
    if isinstance(raw, dict):
        for aid, seq in raw.items():
            if aid not in km2 or seq is None:
                continue
            if keyseq_reject_reason(seq, aid) is None:
                km2[aid] = seq
    used = {}
    for aid, _n, _d in KEY_ACTIONS:              # 键1 池先占位（v68：变体算同一个物理键）
        s = (km1 or {}).get(aid)
        if s is None:
            continue
        for v in key_case_variants(s):
            used[v] = aid
    for aid, _n, _d in KEY_ACTIONS:              # 键2 池：先占先得，撞键1 的丢
        s = km2.get(aid)
        if s is None:
            continue
        vs = key_case_variants(s)
        if any(v in used for v in vs):
            km2[aid] = None
        else:
            for v in vs:
                used[v] = aid
    return km2


# --- `?` 一览的现渲染（v26：跟着当前键显示；默认逐字节 == KEY_TABLE，selftest 钉死）---------
# KEY_TABLE 原文按「键列 / 间隔 / 说明」拆开；可改的行按当前键现拼，其余原样透传。
_HELP_LINES = []
for _ln in KEY_TABLE.splitlines():
    _m = re.match(r"^(\S.*?)(\s{2,})(\S.*)$", _ln)
    _HELP_LINES.append((_m.group(1), _m.group(2), _m.group(3), _ln)
                       if _m else (_ln, "", "", _ln))


def _help_disp(aid, km):
    return pretty_seq(km.get(aid))


def _help_pick(default_lit, aids, km, join=" / "):
    """有改动就现拼、没改就用原字面（保住默认逐字节一致）。"""
    if all(km.get(a) == DEFAULT_KEYMAP[a] for a in aids):
        return default_lit
    return join.join(_help_disp(a, km) for a in aids)


def _help_digits(km):
    return _help_pick("1~6", ["status_%d" % i for i in range(1, 7)], km)


def _help_sortdirs(km):
    """统计页那行用的「Ctrl+方向键」整体替换串。"""
    aids = ("sort_prev", "sort_next", "sort_asc", "sort_desc")
    if all(km.get(a) == DEFAULT_KEYMAP[a] for a in aids):
        return "Ctrl+方向键"
    return " / ".join(_help_disp(a, km) for a in aids)


