def help_text_for(km):
    """`?` 一览全文：没改过的行原样透传（因此默认 == KEY_TABLE 逐字节）；改过的行现拼。"""
    lines = []
    for i, (kt, gap, desc, raw) in enumerate(_HELP_LINES):
        spec = _HELP_ROWS.get(i)
        if spec:
            # v27 起允许「只有 desc、没有 key」的 spec（键列原样透传）——并发加的统计页视图行就用这个形态
            kt2 = spec["key"](kt, km) if "key" in spec else kt
            desc2 = spec["desc"](desc, km) if spec.get("desc") else desc
            if (kt2, desc2) != (kt, desc):
                pad = max(1, len(kt) + len(gap) - len(kt2))
                lines.append(kt2 + " " * pad + desc2)
                continue
        lines.append(raw)
    return "\n".join(lines)


