# ================================================================ 文本读写
def read_text(path):
    """整文件读成 str；newline="" 关掉换行翻译，字节原样进来。"""
    with io.open(path, "r", encoding="utf-8", newline="") as f:
        return f.read()


def write_text(path, text):
    """整文件写回：UTF-8 无 BOM、不翻译换行（因此写出去就是纯 LF）。

    v67：**原子替换** —— 先写同目录临时文件（mkstemp）、flush + fsync，再 os.replace 换上去。
    原实现「直接 open('w') 截断写」在写一半崩掉时会把原文件留成半截；现在最坏情况只是临时
    文件残留、原文件完好。临时文件必须与目标同目录（同卷 rename 才是原子的）。
    """
    d = os.path.dirname(os.path.abspath(path)) or "."
    fd, tmp = tempfile.mkstemp(prefix=os.path.basename(path) + ".", suffix=".tmp", dir=d)
    try:
        with io.open(fd, "w", encoding="utf-8", newline="") as f:
            f.write(text)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, path)
    except BaseException:
        try:
            os.remove(tmp)
        except OSError:
            pass
        raise


def assert_plain(path):
    """写后自检：纯 LF、无 BOM。"""
    with open(path, "rb") as f:
        raw = f.read()
    if raw.startswith(b"\xef\xbb\xbf"):
        raise RuntimeError("文件带 BOM：%s" % path)
    if b"\r" in raw:
        raise RuntimeError("文件不是纯 LF（出现 CR）：%s" % path)


