def config_path_default():
    """「记住上次」的配置文件 = 脚本同目录的 status_gui.config.json。

    frozen（exe）下脚本在一个**一次性临时解包目录**里 —— 写那儿等于每次开窗都丢；
    跟着 exe 走（`toolutil.REPO_ROOT` 在 frozen 下就是 exe 所在目录）。
    """
    d = (toolutil.REPO_ROOT if getattr(sys, "frozen", False)
         else os.path.dirname(os.path.abspath(__file__)))
    return os.path.join(d, CONFIG_NAME)


def _geometry_ok(g, sw=None, sh=None):
    """`1200x800+100+80` 这种 geometry 值认不认。

    sw / sh 不给 = 只查格式（读配置时）；给了屏幕尺寸 = 连「窗口得有一块留在屏幕里」一起查，
    跑出屏幕（拔了副屏、换了分辨率）就当没有，回默认居中（v4 派发要求）。
    """
    m = re.match(r"^(\d{3,5})x(\d{3,5})\+(-?\d+)\+(-?\d+)$", g or "")
    if not m:
        return False
    if sw is None or sh is None:
        return True
    w, h, x, y = (int(v) for v in m.groups())
    return x >= -w + 120 and y >= 0 and x <= sw - 120 and y <= sh - 80


def load_config(path):
    """读上次的 窗口大小位置 / 排序字段 / 升降序。

    文件没有 / 读不动 / 不是 JSON / 值不对 —— 一律回默认，**不抛错、不崩**（v4 派发要求）。
    """
    cfg = dict(DEFAULT_CFG)
    if not path:
        return cfg
    try:
        with io.open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
    except (OSError, ValueError):
        return cfg
    if not isinstance(data, dict):
        return cfg
    g = data.get("geometry")
    if isinstance(g, str) and _geometry_ok(g):
        cfg["geometry"] = g
    if data.get("sort_col") in SORTABLE:
        cfg["sort_col"] = data["sort_col"]
    if isinstance(data.get("sort_desc"), bool):
        cfg["sort_desc"] = data["sort_desc"]
    if isinstance(data.get("know_desc"), bool):     # v17：统计页升降序
        cfg["know_desc"] = data["know_desc"]
    # v22：上次停在哪一页（0~2；越界 / 类型不对一律回 0，不抛错）。
    # `type(v) is int` 是有意的：Python 里 True == 1，用 `in (0,1,2)` 会把 JSON 的 true 放进来。
    # v29：last_seg 随看板四段合并删除 —— 旧配置里带的值读都不读（键不在 DEFAULT_CFG 里）。
    if type(data.get("last_page")) is int and data["last_page"] in (0, 1, 2):
        cfg["last_page"] = data["last_page"]
    # v23：主题两项（认不出的键回默认 —— 配置被手改坏了也不崩，走 normalize_theme）
    # v75.3：选择当前行 = 两个新键；老配置（单个 theme_sel）开窗自动迁移——
    #   blue / soft → 颜色档 + 边框无；none（黑框）/ white（白框）→ 边框档 + 颜色无（观感不变）。
    _b, _c = data.get("theme_sel_border"), data.get("theme_sel_color")
    if _b is None and _c is None:
        _b, _c = {"blue": ("none", "blue"), "soft": ("none", "soft"),
                  "none": ("black", "none"), "white": ("white", "none")}.get(
                      data.get("theme_sel"), ("none", "blue"))
    cfg["theme_sel_border"], cfg["theme_sel_color"] = normalize_sel(_b, _c)
    cfg["theme_scheme"] = normalize_scheme(data.get("theme_scheme"))
    # v28：今天标记开关（脏值归 on）
    if data.get("theme_today") in (THEME_TODAY_ON, THEME_TODAY_OFF):
        cfg["theme_today"] = data["theme_today"]

    # v75：界面模式（白天 / 黑夜）—— 认不出的值一律回白天
    if data.get("theme_daynight") in (THEME_DAYNIGHT_DAY, THEME_DAYNIGHT_NIGHT):
        cfg["theme_daynight"] = data["theme_daynight"]
    # v45：P 键题解显示方式（脏值归 side = 现状；认不出的档不崩）
    if data.get("preview_mode") in (PREVIEW_MODE_SIDE, PREVIEW_MODE_FULL):
        cfg["preview_mode"] = data["preview_mode"]
    # v76：主题块「上次焦点」（"组:值"；认不出 / 脏值 → None = 进块落第一件）
    cfg["theme_focus"] = normalize_theme_focus(data.get("theme_focus"))
    # v82：设置界面「焦点站 / 摆哪一块」（认不出 / 脏值 → None = 进设置落左列表第一项）
    cfg["set_focus"] = normalize_set_focus(data.get("set_focus"))
    cfg["set_block"] = normalize_set_block(data.get("set_block"))
    # v86：按场次视图展开状态（脏值 / 旧项无害 —— 对不上那行等于已收起）
    cfg["round_open"] = normalize_round_open(data.get("round_open"))
    # v27：统计页视图（know / round）+ 场次顺序（脏值一律归默认）
    if data.get("know_mode") in ("know", "round"):
        cfg["know_mode"] = data["know_mode"]
    if isinstance(data.get("round_desc"), bool):
        cfg["round_desc"] = data["round_desc"]
    # v26：自定义快捷键 —— 只认注册表里的 id + 合法 / 保留 / 根级规则；脏条目一律丢（回默认）
    rawk = data.get("keys")
    if isinstance(rawk, dict):
        cfg["keys"] = {k: v for k, v in rawk.items()
                       if isinstance(k, str) and k in DEFAULT_KEYMAP
                       and (v is None or keyseq_reject_reason(v, k) is None)}
    # v74：键2（替代键）—— 同一套过滤；None 不落（键2 的默认就是未绑定）
    rawk2 = data.get("keys2")
    if isinstance(rawk2, dict):
        cfg["keys2"] = {k: v for k, v in rawk2.items()
                        if isinstance(k, str) and k in DEFAULT_KEYMAP
                        and isinstance(v, str) and keyseq_reject_reason(v, k) is None}
    return cfg


def save_config(path, cfg):
    """关窗时存一次：纯 LF、UTF-8 无 BOM、键用小写英文；写不动就返回 False（不抛）。"""
    if not path:
        return False
    data = {"geometry": cfg.get("geometry") or "",
            "sort_col": cfg.get("sort_col") if cfg.get("sort_col") in SORTABLE else "场次",
            "sort_desc": bool(cfg.get("sort_desc", False)),
            "know_desc": bool(cfg.get("know_desc", True)),
            # v22：上次停在哪一页 —— 越界值写回时归 0（别把脏值带进配置）；v29：last_seg 已删
            "last_page": cfg.get("last_page") if cfg.get("last_page") in (0, 1, 2) else 0,
            # v75.3：选择当前行两键（写回前过 normalize，脏值不进文件；theme_sel 老键不再写）
            "theme_sel_border": normalize_sel(cfg.get("theme_sel_border"),
                                              cfg.get("theme_sel_color"))[0],
            "theme_sel_color": normalize_sel(cfg.get("theme_sel_border"),
                                             cfg.get("theme_sel_color"))[1],
            "theme_scheme": normalize_scheme(cfg.get("theme_scheme")),
            # v28：今天标记开关（脏值写回时归 on）
            "theme_today": cfg.get("theme_today") if cfg.get("theme_today") in (THEME_TODAY_ON, THEME_TODAY_OFF) else THEME_TODAY_ON,
            # v75：界面模式（脏值写回时归 day）
            "theme_daynight": cfg.get("theme_daynight") if cfg.get("theme_daynight") in (THEME_DAYNIGHT_DAY, THEME_DAYNIGHT_NIGHT) else THEME_DAYNIGHT_DAY,
            # v45：P 键题解显示方式（脏值写回时归 side）
            "preview_mode": cfg.get("preview_mode") if cfg.get("preview_mode") in (PREVIEW_MODE_SIDE, PREVIEW_MODE_FULL) else PREVIEW_MODE_SIDE,
            # v76：主题块「上次焦点」（"组:值"；脏值写回时归 None）
            "theme_focus": normalize_theme_focus(cfg.get("theme_focus")),
            # v82：设置界面「焦点站 / 摆哪一块」（脏值写回时归 None）
            "set_focus": normalize_set_focus(cfg.get("set_focus")),
            "set_block": normalize_set_block(cfg.get("set_block")),
            # v86：按场次视图展开状态（脏值写回时归 None）
            "round_open": normalize_round_open(cfg.get("round_open")),
            # v27：统计页视图两项（脏值写回时归默认；round_desc 用 isinstance 查 —— bool("x") 是 True，不能硬转）
            "know_mode": cfg.get("know_mode") if cfg.get("know_mode") in ("know", "round") else "know",
            "round_desc": cfg.get("round_desc") if isinstance(cfg.get("round_desc"), bool) else False,
            # v26：自定义快捷键（只写差量；脏值不进文件。读回来时再走 resolve_keymap 消解撞键）
            "keys": {k: v for k, v in (cfg.get("keys") or {}).items()
                     if k in DEFAULT_KEYMAP
                     and (v is None or keyseq_reject_reason(v, k) is None)},
            # v74：键2（替代键）—— 只写有值的；读回来时走 resolve_keymap2 消解（键1 先占先得）
            "keys2": {k: v for k, v in (cfg.get("keys2") or {}).items()
                      if k in DEFAULT_KEYMAP
                      and isinstance(v, str) and keyseq_reject_reason(v, k) is None}}
    txt = json.dumps(data, ensure_ascii=False, indent=2, sort_keys=True) + "\n"
    try:
        with io.open(path, "w", encoding="utf-8", newline="") as f:
            f.write(txt)
    except OSError:
        return False
    return True


# ================================================================ 表格行
def row_segments(line):
    """表格行 → (segments, cells)。

    segments = 每格「两竖线之间」的 [起, 止) 区间（用于原地替换）；
    cells    = 去掉首尾空白、还原 \\| 之后的单元格文本。不是表格行返回 (None, None)。
    """
    if not line.lstrip().startswith("|"):
        return None, None
    pipes, i, n = [], 0, len(line)
    while i < n:
        if line[i] == "\\" and i + 1 < n and line[i + 1] == "|":
            i += 2
            continue
        if line[i] == "|":
            pipes.append(i)
        i += 1
    if len(pipes) < 2:
        return None, None
    segs, cells = [], []
    for k in range(len(pipes) - 1):
        a, b = pipes[k] + 1, pipes[k + 1]
        segs.append((a, b))
        cells.append(line[a:b].strip().replace("\\|", "|"))
    return segs, cells


def render_row(cells):
    """按本表的排版风格拼一行（每格两侧各一个空格，空格格写两个空格 —— 与真表
    `| 未做 |  |` 的既定形态一致；v6.1 修复前这里写单空格，会让「空日期格」与
    replace_cells 的写回形态对不上）。"""
    return "|" + "|".join((" " + c + " ") if c else "  " for c in cells) + "|"


def replace_cells(line, changes):
    """只替换 changes = {列名: 新值} 指定的单元格；该行其余字节原样保留。"""
    segs, cells = row_segments(line)
    if segs is None or len(segs) != len(HEADER):
        raise ValueError("不是状态表数据行：%r" % line)
    edits = []
    for name, val in changes.items():
        if name not in HEADER:
            raise ValueError("没有这一列：%s" % name)
        text = (val or "").replace("|", "\\|")          # 半角竖线要转义，别把表格切断
        a, b = segs[HEADER.index(name)]
        edits.append((a, b, (" " + text + " ") if text else "  "))
    for a, b, seg in sorted(edits, key=lambda e: e[0], reverse=True):
        line = line[:a] + seg + line[b:]
    return line


def _header_row(lines):
    """找表头行下标：整行切分结果必须**精确等于** v2 的 7 列。找不到返回 None。"""
    for i, ln in enumerate(lines):
        if SR.split_cells(ln) == HEADER:
            return i
    return None


def locate_row(lines, key):
    """按（场次, 题号）在原文里定位唯一数据行，返回 0 基行下标。

    扫描范围与 status_report.parse_table 一致（表头 + 分隔线之后、到主表结束为止）。
    命中 0 行或 >1 行都报错——宁可拒绝写，也不改错行。
    """
    start = _header_row(lines)
    if start is None:
        raise ValueError("没找到表头「| %s |」" % " | ".join(HEADER))
    hits = []
    for i in range(start + 2, len(lines)):
        cells = SR.split_cells(lines[i])
        if not cells or len(cells) != len(HEADER):
            break                                       # 主表结束
        if set("".join(cells)) <= set("-: "):
            continue
        if cells[0] == key[0] and cells[1] == key[1]:
            hits.append(i)
    if len(hits) != 1:
        raise ValueError("定位到 %d 行（应恰好 1 行）：%s %s" % (len(hits), key[0], key[1]))
    return hits[0]


def _parse_table_local(path):
    """status_report.parse_table 的等价实现，只把表头常量换成 v2 的 7 列。

    tools/status_report.py 的 HEADER 同步成新表头后本函数不再被走到（见 parse_rows）。
    """
    text = read_text(path)
    lines = text.split("\n")
    start = _header_row(lines)
    if start is None:
        raise SystemExit("★ 没找到表头「| %s |」：%s" % (" | ".join(HEADER), path))
    rows = []
    for ln in lines[start + 2:]:          # +2：表头下面紧跟一行分隔线
        c = SR.split_cells(ln)
        if not c:
            break                          # 主表结束（后面是别的段落）
        if len(c) != len(HEADER):
            break
        if set("".join(c)) <= set("-: "):
            continue
        r = dict(zip(HEADER, c))
        r["_i"] = len(rows)
        rows.append(r)
    return rows


def parse_rows(path):
    """读状态表：优先用 status_report.parse_table，没同步时用等价兜底。"""
    if SR_SYNCED:
        return SR.parse_table(path)
    return _parse_table_local(path)


def _check_changes(changes):
    """只许改两格；状态必须是 6 个合法值之一，日期必须是空或 YYYY-MM-DD。"""
    for name in changes:
        if name not in EDITABLE:
            raise ValueError("只许改 %s，不收：%s" % (" / ".join(EDITABLE), name))
    if "状态" in changes and changes["状态"] not in STATES:
        raise ValueError("状态「%s」不在 6 个合法值里" % changes["状态"])
    if changes.get("日期") and SR.parse_date(changes["日期"]) is None:
        raise ValueError("日期「%s」不是 YYYY-MM-DD" % changes["日期"])


# ================================================================ 写回
def backup_file(path, src_root=None):
    """备份规则的唯一实现（toolutil.backup_to_repo）；返回 .bak 路径。"""
    return toolutil.backup_to_repo(path, src_root)


def save_changes(path, key, changes, backup_src_root=None):
    """写回：重读文件 → 定位唯一目标行 → 只替换「状态 / 日期」→ 备份 → 落盘 → 复读校验。

    v67：重读**之前**先记 (mtime_ns, size)、备份后落盘前再复核 —— 多实例并发的乐观锁：
    别处（另一个窗口 / tb_sync）刚写过就放弃本次写入（写前重读只挡得住「上一版」，
    挡不住「读 → 写」之间那一小段；标记必须先于重读取，否则「读前后脚被外改」会漏拦）。
    返回 (备份路径, 旧文本, 新文本)；两格都没变时返回 (None, 原文本, 原文本)（不写盘、不备份）。
    """
    _check_changes(changes)
    st0 = os.stat(path)                      # v67：先记版本标记，再重读 ——
    old = read_text(path)                    # 顺序反过来会漏掉「读前后脚被外改」的窗口
    old_lines = old.split("\n")
    i = locate_row(old_lines, key)
    new_line = replace_cells(old_lines[i], changes)
    if new_line == old_lines[i]:
        return None, old, old
    new_lines = list(old_lines)
    new_lines[i] = new_line
    diff = [k for k in range(len(old_lines)) if old_lines[k] != new_lines[k]]
    if diff != [i]:
        raise RuntimeError("内部错误：应当只改第 %d 行，实际改了 %r" % (i, diff))
    new = "\n".join(new_lines)
    bak = backup_file(path, backup_src_root)
    st1 = os.stat(path)                      # v67：写盘前复核 —— 不一致就放弃本次写入
    if (st1.st_mtime_ns, st1.st_size) != (st0.st_mtime_ns, st0.st_size):
        raise RuntimeError(
            "文件刚被其他程序改过（比如另一个 TB 窗口），本次已放弃写入；请重按一次")
    write_text(path, new)
    if read_text(path) != new:
        raise RuntimeError("写后复读不一致：%s" % path)
    assert_plain(path)
    return bak, old, new


# ================================================================ 统计、队列、排序
def annotate(rows, today):
    """补 _date / _ago（口径同 status_report.build）。"""
    for r in rows:
        d = SR.parse_date(r["日期"]) if r["日期"] else None
        r["_date"] = d
        r["_ago"] = (today - d).days if d else None
    return rows


def state_counts(rows):
    return {s: sum(1 for r in rows if r["状态"] == s) for s in STATES}


def done_count(rows):
    """最近 N 天做对的题数（v9 口径）：窗口 = SR.RECENT_DAYS 天（默认 7）。

    「做对」= 状态 ∈ DONE_STATES（独立AC / 复现AC）——**「巩固」不算**，超期（_ago >= N）
    与没日期的（_ago is None）也都不算。
    """
    return sum(1 for r in rows if r["状态"] in DONE_STATES
               and r["_ago"] is not None and 0 <= r["_ago"] < SR.RECENT_DAYS)


def knowledge_counts(rows):
    """v17：知识点频次 [(名字, 次数)] —— 统计页的纯逻辑（不碰窗口，自测直接断言）。

    口径（用户 2026-10-05 拍板）：
      * 计数 = 拆到最细的每个知识点各 +1（`双指针[主] + 排序` → 双指针、排序）；
      * **一题里重复写的算多次**（`组合计数 ； 组合计数` → 组合计数 +2）—— 用
        `KD.split_names_all`（保重复版；去重版 `split_names` 是给 manifest 的，别用错）；
      * 名字取 **知识点列的原文**（不去括号、不查词表归一）—— 与目录表 / 状态表
        「同一写法算同一知识点」的口径一致；显示的就是题解里写的那个串。
    返回按名字**保序**的去重列表；排序（正序 / 倒序）交给调用方，这里不动。
    """
    count = {}
    order = []
    for r in rows:
        for name in KD.split_names_all(r.get("知识点", "")):
            if name not in count:
                count[name] = 0
                order.append(name)
            count[name] += 1
    return [(n, count[n]) for n in order]


def knowledge_tree(rows, groups=None):
    """v17 追加（**v97：多级**）：把知识点频次按**父子关系**折成树。返回 (顶层列表, 子表)：

      * 顶层列表 = [(名字, 次数, 是否有子, 子数)]，**父行的次数 = 子孙合计**；
      * 子表 = {名字: [(子名, 子次数, 子是否有子, 子子数), …]} —— **递归**：任何一层的行都从这里
        取它的下一层（子行也带"是否有子 / 子数"——统计页多层展开，如 `数学 → 数论 → 素数`）；
      * `groups`（父子关系表 `{父: [子,…]}`）缺省取词典；空 / None = 全平铺。

    口径（用户 2026-10-05 拍板；v97 扩到多级）：
      * **父行 = 子孙合计**（DP 行 = DP + 区间 DP + 树形 DP + … 的次数之和）；
      * 子行**不再单独计入顶层**（顶层只出现「最高祖先桶」或「没被折进去的平铺知识点」）；
      * 父自己若同时是个落地知识点（如 `DP` 桶里有 `DP` 本身），它照常作为一行子显示
        （计数 = 那个「泛用 DP」自身的次数）—— 即用户举的 `DP{DP, 树形DP, …}`；
      * **桶也可以当子**（多级：`图论 → 树 → LCA`）—— 只有"真出现过知识点"的枝才进树。
    纯逻辑、不碰窗口；排序交给 `sort_knowledge`（对顶层）/ 调用方（对子）。
    """
    flat = dict(knowledge_counts(rows))              # {名字: 次数}
    if groups is None:
        groups = getattr(KD.load(), "groups", {}) or {}
    if not groups:                                   # 无父子表 = 全平铺（保持旧口径）
        return [[n, c, False, 0] for n, c in knowledge_counts(rows)], {}
    child_to_parent = {}
    for parent, kids in groups.items():
        for kid in kids:
            child_to_parent[kid] = parent

    def total(name):                                 # 桶 = 子孙合计；知识点 = 自身次数
        if name in groups:                           #   自指（桶含同名成员，如 `DP` 桶含 `DP`）：
            return sum((flat.get(k, 0) if k == name else total(k))   # 那一段按知识点自身算
                       for k in groups[name])
        return flat.get(name, 0)

    def has_any(name):                               # 这枝上有没有真出现过的知识点
        if name in flat:
            return True
        if name not in groups:
            return False
        return any((k in flat) or (k != name and has_any(k)) for k in groups[name])

    def kids_of(name):                               # 只列「真出现过东西」的直接子（含子桶）
        out = []
        for k in groups.get(name, []):
            if k == name:                            # 自指子 = 「泛用 X」这个知识点本身：
                if k in flat:                        # 只有它自己真出现过才列（不让桶的子孙"带"出它）
                    out.append(k)
            elif has_any(k):
                out.append(k)
        return out

    def fill(name):                                  # 递归把整棵子树的子表都备好（渲染按展开状态取用）
        kids = kids_of(name)
        # 自指子（桶含同名成员，如 DP 桶的 `DP`）显示**它自身的次数**（flat）、且按**叶行**处理
        # （不再套娃展开——展开它只会又得到同一张子表）；其余子走 total
        subs[name] = [((k, flat.get(k, 0) if k == name else total(k),
                        False if k == name else bool(kids_of(k)),
                        0 if k == name else len(kids_of(k)))) for k in kids]
        for k in kids:
            if k in groups and k != name:            # 自指（同上）不递归——它的子表就是本次产物
                fill(k)

    tops, subs = [], {}
    emitted = set()                                  # 已经作为顶层出现过的最高祖先（保序去重）
    for name, _n in knowledge_counts(rows):          # 按平铺顺序走：最高祖先插在它第一个后代出现的位置
        cur, seen_up = name, set()                   # 上溯到最高祖先（词典防环；这里 seen_up 再兜一层）
        while cur in child_to_parent and cur not in seen_up:
            seen_up.add(cur)
            cur = child_to_parent[cur]
        root = cur
        if root in emitted:
            continue
        tops.append([root, total(root), bool(kids_of(root)), len(kids_of(root))])
        emitted.add(root)
        if root in groups:
            fill(root)
    return tops, subs


def sort_knowledge(stats, desc=False):
    """v17：统计结果排序 —— 次数为主键、名字为次键（同次数按名字，结果稳定可预期）。

    desc=True 倒序（次数多的在前）。名字次键一律升序（不跟着倒），同次数那几行才不会
    因倒序而整块翻个底朝天。
    """
    return sorted(stats, key=lambda t: (-t[1] if desc else t[1], t[0]))


def round_num(s):
    """场次文本 → 号（排序用）；认不出 → 10**9（排最后）。

    正常路径走 `contest_key`（新命名 `周赛 164` / `Div.2 1124` 都认）；工具链没加载出来 /
    旧写法时退旧口径（场次文本里第一串数字）。
    """
    name, num = contest_key(s)
    if name is not None and num is not None:
        return num
    m = ROUND_RE.search(s or "")
    return int(m.group(1)) if m else 10 ** 9


def contest_key(s):
    """场次文本 → (系列名, 号)；认不出给 (None, None)（照工具链 parse_contest 的口径，不猜）。

    v6 追加 6（2026-10-07 随新命名方案更新）：正常路径走 `toolutil.parse_contest`
    （「周赛 164」与「Div.2 1124」是不同系列，只按裸号排会互相插队；旧写法
    `牛客周赛 Round 161` 已随全库迁移废弃）；只有 toolutil 加载失败 / 没有这个函数时，
    才退到本地旧口径（裸号，比赛名给空串）—— 别让 GUI 因工具链改版打不开。
    """
    fn = getattr(toolutil, "parse_contest", None)
    if fn is not None:
        try:
            name, num = fn(s)
            return (name, num)
        except Exception:
            pass
    if ROUND_RE is not None:
        m = ROUND_RE.search(s or "")
        if m:
            return ("", int(m.group(1)))
    return (None, None)


def contest_num(s):
    """场次排序键：认得出 → (0, 比赛名, 号)（比赛名先分组、组内按号）；认不出 → (1, "", 0) 排最后。

    用 0 / 1 前缀打头，是为了让「认不出」与「认得出」在同一位置上可比（None 与 str / int 不可比）。
    """
    name, num = contest_key(s)
    if name is None:
        return (1, "", 0)
    return (0, name, num if num is not None else 10 ** 9)


# ================================================================ v27：按场次视图 + 难度范围词（纯逻辑）
_PLAT_RE = re.compile(r"^(.*?)\s*Round\s*(\d+)\s*$")
_DIFF_RANGE_RE = re.compile(r"^(>=|<=|>|<)(\d+)$")
_DIFF_BETWEEN_RE = re.compile(r"^(\d+)-(\d+)$")

# ---- v86：按场次视图再加一层「平台」父目录（用户 2026-10-07 拍板）----
#   需求逐字：「按场次再加一个父目录：牛客 / 洛谷 / AtCoder / Codeforces」「比赛目录的默认排序
#   按 ABC，比如牛客是 N、洛谷是 L、Codeforces 是 C、AtCoder 是 A」「Div.2 在子目录上、Div.3 在
#   中、Div.4 在下，其它比赛同理排序」→ 口径：
#   ① 树三层：平台行 → 系列行 → 场次行 →（展开后）题目行；
#   ② 平台层排序 = **代号字母序** A(AtCoder) → C(Codeforces) → L(洛谷) → N(牛客)，「其他场次」恒最后；
#   ③ 系列层排序（平台内）= **《系列总表》序**（= `toolutil.SERIES` 的键序，CF 恰为
#      Div.2 → Div.3 → Div.4，与用户例子一致；本地 `_SERIES_SEQ` 是同源兜底）。
PLAT_NOWCODER = "牛客"
PLAT_LUOGU = "洛谷"
PLAT_ATCODER = "AtCoder"
PLAT_CODEFORCES = "Codeforces"
_PLAT_BY_KEY = {"nowcoder": PLAT_NOWCODER, "luogu": PLAT_LUOGU,
                "atcoder": PLAT_ATCODER, "codeforces": PLAT_CODEFORCES}
_PLAT_ORDER = {PLAT_ATCODER: 0, PLAT_CODEFORCES: 1, PLAT_LUOGU: 2, PLAT_NOWCODER: 3}
#   本地兜底表（工具链加载失败时用）：系列 → 平台，且**顺序即《系列总表》序**（与 toolutil.SERIES 同源）
_SERIES_FALLBACK = {
    "周赛": PLAT_NOWCODER, "小白月赛": PLAT_NOWCODER,
    "练习赛": PLAT_NOWCODER, "挑战赛": PLAT_NOWCODER,
    "入门赛": PLAT_LUOGU, "基础赛": PLAT_LUOGU, "月赛": PLAT_LUOGU,
    "ABC": PLAT_ATCODER, "ARC": PLAT_ATCODER, "AGC": PLAT_ATCODER,
    "Div.2": PLAT_CODEFORCES, "Div.3": PLAT_CODEFORCES, "Div.4": PLAT_CODEFORCES,
}
_SERIES_SEQ = list(_SERIES_FALLBACK)
#   旧写法 / 兜底名的关键词（只在表里查不到时用；如 fixture 的 `牛客周赛 Round 200` → 系列名
#   「牛客周赛」→ 含「牛客」→ 牛客平台）；"Div." 照新命名（`Div.2 1124` 直接命中系列表，这里是双保险）
_PLAT_KEYWORDS = (("牛客", PLAT_NOWCODER), ("洛谷", PLAT_LUOGU),
                  ("AtCoder", PLAT_ATCODER), ("Codeforces", PLAT_CODEFORCES),
                  ("Div.", PLAT_CODEFORCES))


def series_platform(name):
    """系列名（= `contest_platform` 的输出）→ 平台显示名；认不出一律归 `ROUND_OTHER_PLAT`。

    v86：主路径走 `toolutil.SERIES[name]["plat"]`（v79 起的四平台定义，唯一事实来源）；
    工具链加载失败 → 本地 `_SERIES_FALLBACK`；仍查不到（旧写法组名 / 自定义名）→ 关键词兜底
    （「牛客周赛」这种含平台名的前缀）；再认不出 → 「其他场次」（与系列层同一组名，收尾排最后）。
    """
    if not name or name == ROUND_OTHER_PLAT:
        return ROUND_OTHER_PLAT
    s = getattr(toolutil, "SERIES", None)
    if isinstance(s, dict):
        ent = s.get(name)
        if isinstance(ent, dict):
            p = _PLAT_BY_KEY.get(ent.get("plat"))
            if p:
                return p
    p = _SERIES_FALLBACK.get(name)
    if p:
        return p
    for kw, disp in _PLAT_KEYWORDS:
        if kw in name:
            return disp
    return ROUND_OTHER_PLAT


def _series_sort_key(name):
    """系列层排序键（v86）：按《系列总表》序（= `toolutil.SERIES` 键序，本地表兜底）；
    认不出的系列名排本平台最后（按原文，结果稳定）；「其他场次」恒**最最**后（与平台层同口径）。"""
    if name == ROUND_OTHER_PLAT or not name:
        return (2, 0, "")
    s = getattr(toolutil, "SERIES", None)
    if isinstance(s, dict) and name in s:
        return (0, list(s).index(name), "")
    if name in _SERIES_SEQ:
        return (0, _SERIES_SEQ.index(name), "")
    return (1, 0, name)


def _platform_sort_key(plat):
    """平台层排序键（v86）：用户拍板「默认排序按 ABC」= 代号字母序 A/C/L/N；「其他场次」恒最后。"""
    i = _PLAT_ORDER.get(plat)
    return (0, i) if i is not None else (1, 0)


def plat_label(plat, n_rounds, n_prob, n_ac):
    """平台行后缀（v86，用户拍板「平台行带、系列行不带」）：`牛客（27 场·148 题·AC 12·8%）`。

    进度口径与场次行一致（独立AC / 总题数、四舍五入到整数个百分点）；空平台不会建行。
    """
    pct = int(round(100.0 * n_ac / n_prob)) if n_prob else 0
    return "%s（%d 场·%d 题·AC %d·%d%%）" % (plat, n_rounds, n_prob, n_ac, pct)


def contest_platform(s):
    """场次文本 → 平台组名（2026-10-07 起 = 系列名：「周赛」/「小白月赛」/…/「Div.2」）。

    走 `contest_key`（正常路径即 `toolutil.parse_contest`；认不出统一归
    `ROUND_OTHER_PLAT`「其他场次」）；工具链加载失败 / 旧写法（`… Round N`）退本地口径
    （`_PLAT_RE` 取「Round」前面的比赛名当组名）。
    """
    name, _num = contest_key(s)
    if name:
        return name
    m = _PLAT_RE.match(s or "")          # 兜底：工具链没加载出来 / 旧写法
    if m:
        return m.group(1).strip() or ROUND_OTHER_PLAT
    return ROUND_OTHER_PLAT


def _plat_sort_key(s):
    """组内排序键：认得出 → (0, 号)；认不出 → (1, 原文, 0)。"""
    name, num = contest_key(s)
    if name is not None and num is not None:
        return (0, num, 0)
    m = _PLAT_RE.match(s or "")          # 兜底：旧写法按 Round 号排序
    if m:
        return (0, int(m.group(2)), 0)
    return (1, s or "", 0)


def rounds_group(rows, desc=False):
    """rows → [(平台, [(系列, [(场次, [该场全部行], 独立AC 数), …]), …]), …]（v86：三层）。

    v27 立两层（系列 → 场次）；v86（用户 2026-10-07 拍板「按场次再加一个父目录」）加平台层：
    - **平台层**：牛客 / 洛谷 / AtCoder / Codeforces（`series_platform` 认），按**代号字母序**
      A(AtCoder) → C(Codeforces) → L(洛谷) → N(牛客)，「其他场次」恒最后（`_platform_sort_key`）；
    - **系列层**：平台内按《系列总表》序（CF = Div.2 → Div.3 → Div.4；其它平台同理，
      `_series_sort_key`）；
    - **场次层**：系列内按号升序，`desc=True` 反转（表头 ▲/▼ 只管这一层）。
    进度口径（用户 2026-10-06 拍板）：**AC = 独立AC**、进度 = 独立AC / 题数。
    """
    buckets = {}                                   # 平台 → {系列: {场次: [行]}}
    for r in rows:
        sr = contest_platform(r.get("场次", ""))
        pl = series_platform(sr)
        buckets.setdefault(pl, {}).setdefault(sr, {}).setdefault(r.get("场次", ""), []).append(r)
    out = []
    for pl in sorted(buckets, key=_platform_sort_key):
        series = []
        for sr in sorted(buckets[pl], key=_series_sort_key):
            rs = []
            for s, lst in buckets[pl][sr].items():
                ac = sum(1 for r in lst if r.get("状态") == "独立AC")
                rs.append((s, lst, ac))
            rs.sort(key=lambda t: _plat_sort_key(t[0])[1:], reverse=desc)
            series.append((sr, rs))
        out.append((pl, series))
    return out


_ROUND_WORD_RE = re.compile(r"\s+Round\s+(?=\d)")
_ROUND_HASH_RE = re.compile(r"\s*#\s*(?=\d)")


def short_round(s):
    """场次的**显示名**（v41 用户口径「把场次名字改成比赛名+回合名，比如：牛客周赛 123」）：
    `牛客周赛 Round 146` → `牛客周赛 146`（只摘掉 `Round` 这个词）；`AtCoder ABC 380` 这类
    本来就没有 `Round` 字样的原样返回。
    v90（2026-10-08 用户口径）：`#` 也去掉——`入门赛 #52` → `入门赛 52`（数据已全库清洗，
    这里兜底旧行）。

    ⚠️ **只用于显示** —— TB.md 的数据、搜索 / 筛选、排序、打开原题（`parse_problem_url`）、
    导出题解包的场次下拉，全走 `row["场次"]` 原串，一个字不动（`Round` 是那几处的定位依据）。
    """
    t = _ROUND_WORD_RE.sub(" ", (s or "").strip())
    return _ROUND_HASH_RE.sub(" ", t)


_ISO_DATE_RE = re.compile(r"^(\d{4})-(\d{2})-(\d{2})$")


def short_date(s):
    """日期的**显示名**（v41.1 用户口径「把日期的 20 去掉，改成 26-10-07 这个格式」）：
    `2026-10-07` → `26-10-07`（年只留后两位）。空 / 不是 ISO 日期的原样返回。

    ⚠️ **只用于显示** —— TB.md 数据、按日期排序、今天标记（`日期 == date.today().isoformat()`）、
    D+7 / D+30 队列、写回文件，全是 ISO 原串（少一位就认不出「今天」了）。
    """
    m = _ISO_DATE_RE.match((s or "").strip())
    if not m:
        return s or ""
    return "%s-%s-%s" % (m.group(1)[2:], m.group(2), m.group(3))


_TITLE_PREFIX_LOCAL = re.compile(r"^[\[「【][^\]」】]*[\]」】][ \t　]*")


def short_title(s):
    """题名的**显示名**（v90，2026-10-08 用户口径「题名的前缀去掉」）：
    `[语言月赛 202605] 火车` → `火车`；`「YLLOI-R4-T2」听妈妈的话` → `听妈妈的话`。

    实现走 `toolutil.strip_title_prefix`（全库唯一实现；工具链加载不到时本地兜底同规则）。
    ⚠️ **只用于显示** —— TB.md 数据 / 搜索 / 对账走 `row["题名"]` 原串；数据已随全库清洗
    去前缀，这里兜底旧行（新场次不再带）。
    """
    fn = getattr(toolutil, "strip_title_prefix", None)
    if callable(fn):
        return fn(s)
    t = (s or "").strip()
    return _TITLE_PREFIX_LOCAL.sub("", t).strip() or t


def short_cell(h, v):
    """表格单元格的显示值：「场次」走 `short_round`、「题名」走 `short_title`、
    「日期」走 `short_date`，其余列原样。"""
    if h == "场次":
        return short_round(v)
    if h == "题名":
        return short_title(v)
    if h == "日期":
        return short_date(v)
    return v


def round_label(name, n_total, n_ac, diffs=()):
    """场次行后缀（用户口径）：`周赛 146（5 题·AC 2·40%·难度 800-2100·差 1300）`。

    进度 = 独立AC / 题数（四舍五入到整数个百分点）；空场次不会建行，n_total 恒 > 0。
    v79 起（用户 2026-10-07 拍板）：AC 率后加难度范围与差值——`diffs` = 该场各行的
    「难度」列原文（`CF 800` 老写法也认）；取不出数字的不参与，全取不出就整段不显示；
    只有一个不同值时不带差值。
    """
    pct = int(round(100.0 * n_ac / n_total)) if n_total else 0
    seg = ""
    vs = sorted(v for v in (diff_value({"难度": d}) for d in diffs) if v is not None)
    if vs:
        if vs[0] == vs[-1]:
            seg = "·难度 %d" % vs[0]
        else:
            seg = "·难度 %d-%d·差 %d" % (vs[0], vs[-1], vs[-1] - vs[0])
    return "%s（%d 题·AC %d·%d%%%s）" % (short_round(name), n_total, n_ac, pct, seg)


def diff_value(row):
    """难度列的数值（`1800` → 1800；历史写法 `CF 1800` 也认）；取不出数字 → None。"""
    m = re.search(r"\d+", row.get("难度") or "")
    return int(m.group()) if m else None


def diff_range_hit(word, row):
    """v27：难度**范围词**命中该行吗 —— `1500-1800`（含两端）/ `>=1700` / `<=1300` / `>n` / `<n`。

    只在难度列生效；难度为空 / 取不出数字的行**不命中**任何范围词。
    返回 None = 这个词不是范围词（交回老的子串口径）；`1800-1500` 反着写也认（自动摆正）。
    """
    m = _DIFF_RANGE_RE.match(word)
    if m:
        op, n = m.group(1), int(m.group(2))
        d = diff_value(row)
        if d is None:
            return False
        return {"<": d < n, "<=": d <= n, ">": d > n, ">=": d >= n}[op]
    m = _DIFF_BETWEEN_RE.match(word)
    if m:
        lo, hi = int(m.group(1)), int(m.group(2))
        if lo > hi:
            lo, hi = hi, lo
        d = diff_value(row)
        return d is not None and lo <= d <= hi
    return None


def strip_cf_words(words):
    """v27：把「光 cf」词从查询里摘掉（`CF 1800` 等价 `1800`；2026-10-06 起难度列数据
    本身就是纯数字，这条只服务老写法）。

    整句只剩 cf 词 → 返回空表 → 调用方按 **0 条**处理（v19「光搜 CF = 0 条」的语义不变）。
    """
    return [w for w in words if w.replace(" ", "").lower().replace("cf", "")]


def cf_num(s):
    """难度列按数字比大小（历史 `CF 1800` 写法也认）；空的排最后。"""
    m = CF_RE.search(s or "")
    return int(m.group(1)) if m else 10 ** 9


def _row_order_key(r):
    """并列时的稳定次序（打底：比赛名 → 场次号 → 题号 → 原行序）。

    v6 追加 6：场次键改用工具链的 `toolutil.parse_contest`（见 contest_key / contest_num）——
    不同比赛各归各的组、不互相插队，认不出的场次（如「洛谷月赛 Round 5」）排最后；
    toolutil 加载失败时 contest_key 自会退到本地旧口径，GUI 照常能开。
    """
    return contest_num(r["场次"]) + (r["题号"], r["_i"])


def sort_rows(rows, col, desc):
    """排序：主键按 col（升 / 降），并列时永远按 比赛名→场次号→题号 升序（_row_order_key）。

    日期列的空值**永远排最后**（升序降序都一样）；场次列认不出的（非「比赛名 Round 号」
    形式）也排最后；场次键 v6 追加 6 起走 toolutil.parse_contest（不同比赛不互相插队）。
    """
    items = list(rows)
    items.sort(key=_row_order_key)              # 打底：比赛名 → 场次号 → 题号（并列时的稳定次序）
    if col == "日期":
        dated = [r for r in items if r["_date"]]
        undated = [r for r in items if not r["_date"]]
        dated.sort(key=lambda r: r["_date"], reverse=desc)
        return dated + undated
    if col == "场次":
        key = lambda r: contest_num(r["场次"])
    elif col == "难度":
        key = lambda r: cf_num(r["难度"])
    elif col == "知识点":
        key = lambda r: (r["知识点"] == "", r["知识点"])
    else:
        return items
    items.sort(key=key, reverse=desc)
    return items


def segment_specs():
    """看板四段：名字 + 判据（阈值与状态集合全部取 status_report 的常量）。"""
    return [
        ("待重写", "① 待重写"),
        ("待补题", "② 待补题"),
        ("D+%d 复习" % REVIEW_DAYS, "③ D+%d 复习" % REVIEW_DAYS),
        ("D+%d 抽检" % SR.KEEP_DAYS, "④ D+%d 抽检" % SR.KEEP_DAYS),
    ]


def segment_rows(rows, idx):
    """第 idx 段（0~3）的题目清单；规则与 status_report.build 的 ①–④ 完全一致。

    「未做」不进任何一段（照 status_report.py 的规则；v10 起状态收成 6 个，四段只认
    待重写 / 不会 / 独立AC+复现AC / 巩固）。
    """
    if idx == 0:
        return sorted([r for r in rows if r["状态"] == SR.TODO_HARD], key=_row_order_key)
    if idx == 1:
        return sorted([r for r in rows if r["状态"] in SR.TODO_FILL], key=_row_order_key)
    if idx == 2:
        return sorted([r for r in rows if r["状态"] in SR.REVIEW
                       and r["_ago"] is not None and r["_ago"] >= REVIEW_DAYS],
                      key=lambda r: -r["_ago"])
    return sorted([r for r in rows if r["状态"] == SR.KEEP
                   and r["_ago"] is not None and r["_ago"] >= SR.KEEP_DAYS],
                  key=lambda r: -r["_ago"])


