def fixture_text():
    """造一份自测用状态表：新表头 + 12 行（6 个状态各 2 行、含空日期 / 带 ｜ 的知识点 / 场次乱序）。"""
    lines = ["# 题目状态（status_gui 自测 fixture，可整份重建）", "",
             "| " + " | ".join(HEADER) + " |",
             "|" + "|".join(["---"] * len(HEADER)) + "|"]
    for c in FIXTURE_ROWS:
        lines.append(render_row(list(c)))
    lines += ["", "## 表后说明（不是表格行，用来验证解析器在表尾停住）",
              "- 日期 = 最后一次状态变更日；空日期表示还没变过状态。"]
    return "\n".join(lines) + "\n"


def write_fixture(path):
    write_text(path, fixture_text())
    return path


def control_fixture_text():
    """按 tools/status_report.py **当前**的表头造一份对照 fixture。

    只在「它的 HEADER 还没同步到 v2」时用来验证子进程调用链本身可用；
    同步之后这个函数不会再被走到（selftest 里走的是严格断言那一支）。
    """
    hdr = _SR_HEADER or ["场次", "题号", "题名", "难度", "状态", "日期", "备注"]
    lines = ["# 对照件（表头跟 tools 现在的一致）", "",
             "| " + " | ".join(hdr) + " |",
             "|" + "|".join(["---"] * len(hdr)) + "|"]
    for c in FIXTURE_ROWS:
        vals = []
        for h in hdr:
            vals.append("" if h in ("知识点", "备注") else c[HEADER.index(h)])
        lines.append(render_row(vals))
    return "\n".join(lines + [""]) + "\n"


# ================================================================ 输入法守卫（v8）
class ImeGuard(object):
    """v8：Windows 输入法守卫 —— 只留搜索框收中文，别的地方一律把输入法摘掉。

    症状（用户原话「现在中文输入法按快捷键会直接跳出输入法」）：中文输入法开着时，焦点在
    总表 / 看板清单上按 S / R / F / `/` / `?` / 数字键（浮层里的状态直选），输入法候选窗会跳出来把按键吃掉 ——
    Windows 给**每个窗口**默认都关联了输入法上下文（可编辑控件 Tk 自己会管，非输入控件没人摘）。

    机制：ImmAssociateContext(hwnd, 0) 摘掉、ImmAssociateContext(hwnd, imc) 还原（imc = 摘掉时
    返回的旧上下文，各自存好）；每个 HWND 各摘自己那一份、互不影响（2026-10-03 实测）。
    窗口建好后把主窗口里所有控件的 HWND 都摘一遍；之后靠 <FocusIn> 兜底（挂 root + 各 Toplevel
    —— 实测独立窗口的 <FocusIn> 不会冒到 root 上）：拿到焦点的是搜索框 → 还原 搜索框 + 主窗口，
    是别的控件 → 把它的 HWND 摘掉（没见过的 HWND 也照摘）。

    只在 sys.platform == "win32" 做；其余平台 / 拿不到 imm32 / 任何 API 异常 —— 全部静默降级成
    no-op（available = False 时所有方法直接返回），窗口行为与 v7 完全一致。
    """

    def __init__(self, root, keep=()):
        self.root = root
        self.keep = tuple(w for w in keep if w is not None)  # 允许收中文的控件（搜索框）
        self.available = False   # 「可用」标志：置假 = 整条守卫 no-op（冒烟 (gg) 用它验降级路径）
        self.default_ctx = None  # 摘之前主窗口的上下文（= 线程默认；系统没有输入法环境时是 None）
        self._imm = None
        self._saved = {}         # hwnd(int) -> 摘掉时存下的旧上下文（attach 用它还原）
        try:
            if sys.platform != "win32":
                return
            imm = ctypes.windll.imm32
            # 64 位下必须设 argtypes / restype = c_void_p（默认 c_int 有截断 HWND 的风险 —— 实测口径）
            imm.ImmGetContext.restype = ctypes.c_void_p
            imm.ImmGetContext.argtypes = [ctypes.c_void_p]
            imm.ImmAssociateContext.restype = ctypes.c_void_p
            imm.ImmAssociateContext.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
            self._imm = imm
            self.available = True
        except Exception:
            self._imm = None
            self.available = False

    # ---------------------------------------------------------- 对外
    def install(self):
        """窗口建好后调用一次：先取默认上下文、把主窗口全部控件摘一遍，再挂 <FocusIn>。"""
        if not self.available:
            return
        try:
            self.default_ctx = self._ctx(self.root)
            self.detach_tree(self.root)
            self.watch(self.root)
        except Exception:
            pass

    def watch(self, win):
        """给这个窗口（root / 各 Toplevel）挂 <FocusIn> 兜底；独立窗口的事件不会冒到 root 上。"""
        if not self.available:
            return
        try:
            win.bind("<FocusIn>", self.on_focus_in, add="+")
        except Exception:
            pass

    def on_focus_in(self, event=None):
        """焦点变了：搜索框拿到焦点 → 还原输入法；别的控件 → 摘掉它（搜索框也一并摘）。"""
        if not self.available:
            return
        try:
            w = event.widget if event is not None else None
            target = w if w in self.keep else None
            if target is None:                   # 顶层 / 别的窗口的 FocusIn：以 Tk 当前焦点为准兜底
                try:
                    f = self.root.focus_get()
                except Exception:
                    f = None
                target = f if f in self.keep else None
            if target is not None:
                for k in self.keep:
                    self.attach(k)
                # 主窗口 HWND 也还原：键盘焦点在顶层 / 子窗口两种口径下都能打中文
                self.attach(self.root)
            else:
                self.detach(w)               # 没见过的 HWND 也照摘
                for k in self.keep:
                    self.detach(k)           # 离开搜索框立刻摘：回表格再按快捷键不再弹输入法
                self.detach(self.root)
        except Exception:
            pass

    def detach_tree(self, win):
        """win 子树里每个控件都摘一遍（含 win 自己）。"""
        if not self.available:
            return
        try:
            self.detach(win)
            for c in win.winfo_children():
                self.detach_tree(c)
        except Exception:
            pass

    # ---------------------------------------------------------- 内部（都吞异常）
    def _hwnd(self, widget):
        """控件 → HWND（int）；拿不到（None / 已销毁）给 None。"""
        try:
            return int(widget.winfo_id()) if widget is not None else None
        except Exception:
            return None

    def _ctx(self, widget):
        """这个控件当前的输入法上下文；没挂 / 不可用 → None。"""
        if not self.available:
            return None
        h = self._hwnd(widget)
        if h is None:
            return None
        try:
            return self._imm.ImmGetContext(ctypes.c_void_p(h))
        except Exception:
            return None

    def detach(self, widget):
        """摘掉这个控件的输入法（旧上下文存起来供 attach 还原）；任何异常都吞掉。"""
        if not self.available:
            return
        h = self._hwnd(widget)
        if h is None:
            return
        try:
            old = self._imm.ImmAssociateContext(ctypes.c_void_p(h), None)
            if h not in self._saved:         # 已经摘过别再存：别把真正的旧上下文冲成 None
                self._saved[h] = old
        except Exception:
            pass

    def attach(self, widget):
        """还原这个控件的输入法（用摘掉时存的旧上下文）；没存过 / 不可用就不动。"""
        if not self.available:
            return
        h = self._hwnd(widget)
        if h is None or h not in self._saved:
            return
        try:
            old = self._saved.pop(h)
            self._imm.ImmAssociateContext(ctypes.c_void_p(h), old)
        except Exception:
            pass


# ================================================================ 窗口
class StatusGui(object):
    def __init__(self, root, path, quiet=False, config_path=None, curtain=None):
        """config_path = 「记住上次」的配置文件路径；None = 不读也不写
        （--selftest / --smoke 走 None，绝不碰脚本同目录的 status_gui.config.json）。

        v84：`curtain` = 换页幕布开关（`None` = 跟 `quiet` 走：冒烟 / 自测不开）。
        **探针要显式给 `curtain=True`** —— 帧级探针起窗时是 `quiet=True`（不弹框），
        但量的是产品真实路径，幕布必须在场。
        """
        self.root = root
        self.path = path
        self.quiet = quiet                  # 冒烟/自测里不弹 messagebox
        self._curtain_ok = (not quiet) if curtain is None else bool(curtain)
        self.backup_src_root = None         # 备份镜像目录的「来源目录」；None = 表自己所在目录
        self.config_path = config_path
        self.cfg = load_config(config_path)  # v4：窗口大小位置 + 排序字段 / 升降序
        self._msg_after = None               # 保存提示「3 秒后清空」的回调 id
        self.rows = []
        self.popup = None
        self.popup_lb = None
        self.popup_row = None
        self.popup_tree = None
        self.help_tx = None                  # v87：设置页「快捷键一览」块的只读文本控件（自测要核内容）；原 `?` 弹窗（help_win / help_prev / help_lbl）已删
        self.sort_col = self.cfg["sort_col"]  # 默认：场次升序 → 题号升序；有配置就照上次
        self.sort_desc = self.cfg["sort_desc"]
        self.know_desc = self.cfg["know_desc"]   # v17：统计页默认降序（考得最多的在上）
        self.know_open = set()               # v17：统计页展开着的父知识点（本窗口内记住）
        self.know_mode = self.cfg["know_mode"]    # v27：统计页视图（"know" 知识点 / "round" 按场次）
        self.round_desc = self.cfg["round_desc"]  # v27：按场次视图的场次顺序（False = 轮次号升序）
        # v27：按场次视图展开着的平台 / 系列 / 场次（iid："P|…" / "S|…" / "R|…"）
        # v86（用户口径「记住上次的状态」）：随配置持久化 —— 开窗还原 / 关窗写回（load_config / on_close）
        self.round_open = set(self.cfg.get("round_open") or [])
        # v29：看板四段合并成一个清单 —— seg_idx / _seg_sel / _seg_rebuild 整组退役（段的记忆不再需要）
        self.data_root = DATA_ROOT           # v6 追加：Alt+Enter 找资料的根（测试里换成沙箱）
        self._opener = getattr(os, "startfile", None)   # v6 追加：打开动作（测试里换假函数，绝不真开文件）
        self._undo_stack = []                # v12：Ctrl+Z 状态撤销栈（多步；只在内存、不跨重启）
        self._redo_stack = []                # v20：Ctrl+Y 状态**复原栈**（撤销掉的那步再放回来；真写盘 + 备份）
        self._last_change = None             # v6~v11：只记一步 → v12 起 = 栈顶那份（栈空即 None）
        self._search_undo_stack = []         # v19：搜索框撤销栈（v20 起**按词分段**；只在内存、不跨重启）
        self._search_baseline = ""           # v19：当前这段输入的起点（跳转 / 清空后重置）
        self._search_undo_suppress = False   # v19：Ctrl+Z 程序性还原搜索框时的静默开关
        self._search_redo_stack = []         # v20：搜索框**复原栈**（Ctrl+Y 把 Ctrl+Z 退掉的那段再放回去）
        self.last_windowed_geometry = None   # v11：进全屏前记下的窗口态 geometry（全屏中关窗存这份）
        self._ph_syncs = []                  # v15：三个占位提示的同步函数（程序改空 var 后手动喊一声）
        self._ph_search_lbl = None           # v17：搜索框占位 Label（切页换文案用）
        self._ph_search_sync = None          # v17：搜索框占位 sync（切页重跑）
        self._know_search_origin = None      # v17：统计页 Enter 跳转的来源 {name,parent}，供 Esc 原路退回
        self.last_page = self.cfg["last_page"]  # v22：上次停在哪一页（0 总表 / 1 看板 / 2 统计）；v29 起不再有 last_seg
        # v23/v25：主题（菜单「主题 ▸ 选择当前行 / 配色」）—— 都从配置来，默认「蓝底白字 + 默认」（= 现状）
        self.theme_sel_border, self.theme_sel_color = normalize_sel(
            self.cfg.get("theme_sel_border"), self.cfg.get("theme_sel_color"))
        self.theme_scheme = normalize_scheme(self.cfg.get("theme_scheme"))
        # v28：今天标记（行首竖条）开关 —— 默认开，脏值归 on
        self.theme_today = self.cfg.get("theme_today") \
            if self.cfg.get("theme_today") in (THEME_TODAY_ON, THEME_TODAY_OFF) else THEME_TODAY_ON
        # v75：界面模式（白天 / 黑夜）—— 默认白天，脏值归 day
        self.theme_daynight = self.cfg.get("theme_daynight") \
            if self.cfg.get("theme_daynight") in (THEME_DAYNIGHT_DAY, THEME_DAYNIGHT_NIGHT) else THEME_DAYNIGHT_DAY
        # v45：P 键的题解显示方式（side = 右侧栏 / full = 表格区整块换 md）—— 脏值归 side
        self.preview_mode = self.cfg.get("preview_mode") \
            if self.cfg.get("preview_mode") in (PREVIEW_MODE_SIDE, PREVIEW_MODE_FULL) else PREVIEW_MODE_SIDE
        self.md_full = False                 # v45：全屏 md 开着吗（v46 起：只由回车进、由 Esc 或 md 里回车出）
        self.md_full_key = None              # 开着时看的是哪一题 (场次, 题号)
        self._sel_vars = {}                  # v23：主题页里三组单选状态（tk 单选变量的 {key: var}）
        self._theme_focus_mem = None         # v76：主题块本次运行最后聚焦的那个钮（进块落回它）
        # v82：设置界面「上次退出时焦点在哪一站」= left / keys / theme（FocusIn 一路记；
        #      开窗先用配置里那份，运行中覆盖它，关窗写回 —— 见 `_restore_set_focus`）
        self._set_focus_mem = self.cfg.get("set_focus")
        # v40：菜单栏三个菜单（题解包 / 主题 / 快捷键，v39 的自绘按钮条）**整条删除** —— 改成
        # 「设置界面」：Ctrl+Tab 把**整个窗口内容**在主界面 ⇄ 设置界面之间切换，里面两块**全内联**
        # （v53 起只剩 快捷键设置 / 主题设置 —— 导入 / 导出题解包已删）。用户口径 2026-10-06：「取消现在的
        # 题解包,主题,快捷键菜单,用切换页状态替代…整个界面变成设置界面,不是新增…还是一样的
        # 上下左右,等等快捷键的操作逻辑」+ 拍板「左侧四项+右面板 / 全内联删弹窗 / Ctrl+Tab 开关式」。
        self.main_frame = None               # 主界面容器（第一行 + 三页表格；进设置时整块收起）
        self.settings_frame = None           # 设置界面容器（默认不摆；进设置才 pack）
        self._settings_from_cell = 0         # v55：进设置时在哪个格（退出回那儿；设置页独立、不再占格）
        self.set_left = None                 # 设置界面左列表（ttk.Treeview，show="tree"）
        self.set_panels = {}                 # 右面板：{"keys" / "theme": tk.Frame}（v53：导入 / 导出删除）
        self.set_panel = "keys"              # 当前摆着的右面板（对应左列表哪一项）
        self._set_focus = {}                 # 每块面板「进面板先落焦点 / ↑↓ 逐件走」的控件清单（v42）
        self._row_borders = {}               # v23：三张表各自的"选中行边框"画笔
        # v88：`_grid_frames` / `_grid_at`（v22 的列间竖线 + 位置缓存）已删 —— 竖线整条去掉
        self._bar_frames = []                # v25：Radix 的「今天竖条」（Frame 贴条，用多少补多少）
        self._bar_after = None               # v25：竖条重摆的 after_idle 句柄（合并连发的滚动事件）
        self._repainting = False             # v25.3：`_flush_screen` 的重入护栏（update() 嵌套限深 2）
        self._last_border_paint = 0.0        # v25.5：连按节流——上次"刷黑框"的时刻（monotonic 秒）
        self._scroll_repaint = False         # v25.6：本次重摆是不是滚动发起的（滚动不做"先收"）
        self._pads = {}                      # v25.7：遮色条阵列（tree → _RowPads；「重药」）
        self._rebuild_sel = {}               # v60：摆框时的选中快照（选中事件"重建回声"跳过用）
        self._scroll_settle = None           # v25.10：滚动"停稳"重摆的 after 句柄
        self._last_key_move = 0.0            # v25.12：上一发"方向键移动"的时刻（快按让位判定）
        self._last_step_force = 0.0          # v25.20：上一发"整洁刷新"（含强推重绘）的时刻
        self._show_after = None              # v25.14：单步"延迟显示"的 after 句柄（防"先亮再收"的闪）
        # v26：自定义快捷键 —— keymap 从配置还原（差量 + 默认合并、撞键消解）；捕获的临时状态
        # v40：设置从独立弹窗搬进设置界面 —— key_tv 恒指向界面里那张表（`_make_settings` 里给值）
        self.keymap = resolve_keymap(self.cfg.get("keys"))
        # v74：键2（替代键）—— 每操作第二个可绑键（两键都能触发同一操作）；默认全 None。
        #      解析时键1 先占先得（撞上键1 已占的键就丢回 None）
        self.keymap2 = resolve_keymap2(self.cfg.get("keys2"), self.keymap)
        self._key_col = 0                    # v74：快捷键表「当前要改的列」0 = 键1 / 1 = 键2
        self.key_tv = None                   # 「快捷键设置」那棵树（v40 起恒在，只是可能不露着）
        self.key_capture = False             # 在「等按键」状态吗
        self._key_scroll_settle = None       # v38：列表滚动"停稳"重摆选中框的 after 句柄
        self._key_bound = {}                 # {(widget, action_id): ([绑过的序列…], 是否 bind_all)}

        root.title("TB")
        root.geometry("1320x800")
        root.minsize(1000, 620)
        root.configure(bg=C_BG)
        self.fam = self._pick_family()
        self._init_style()

        # v40：主界面整块装进 main_frame —— 设置界面开着时它整块 pack_forget（退出设置切回来）
        self.main_frame = tk.Frame(root, bg=C_BG)
        self.main_frame.pack(fill="both", expand=True)
        # v63：body **先建**（原来在 `_make_head` 之后）—— 第一行现在也挂在它里面（见 `_make_head`）。
        # 起因（用户截图实证）：退全屏 md 时第一行要摆回来，v62 它挂在 main_frame 上 → `pack` 回来
        # 把 body 整块往下推 45px，而 `place` 钉住的预览栏坐标**相对 body**、跟着一起下移 →
        # `_settle_preview_swap()` 那一拍泵出「顶部一条空带 + md 整块下移」的中间态。
        # 挂进 body 后摆回第一行**不动 body**，钉住的 md 一个像素不移动。
        # v32：中间层 body 包住 Notebook + 右侧题解预览栏（P 键开合；默认收起、懒加载）。
        # nb 与预览栏的根窗口偏移与旧版一致（黑框 / 遮色条挂 tree、走 bbox，不受影响）。
        self.body = tk.Frame(self.main_frame, bg=C_BG)
        self.body.pack(fill="both", expand=True)
        self._make_head()                   # v9：第一行 = 搜索 + 统计 + 消息（v63：挂 body 顶部）
        # v18：搜索框下的**筛选下拉面板整套删除** —— 筛选并入搜索框（空格分隔多字段）
        self.nb = ttk.Notebook(self.body, takefocus=0)   # v6：页签不进 Tab 轮换（鼠标点不受影响）
        self.nb.pack(side="left", fill="both", expand=True, padx=12, pady=(2, 4))
        self.prev_holder = tk.Frame(self.body, bg=C_BG, width=PREVIEW_W)
        self.prev_holder.pack_propagate(False)   # 宽度固定，不吃子控件尺寸
        self.prev = None                         # tb_preview.MdPreview（首次按 P 才建组件）
        self.prev_open = False
        self.prev_cell = None                    # v50：预览**绑在哪一格**（0/1/2）；切走只是看不见、走回原样再现
        self.prev_w = 0                          # v41：预览栏当前宽度（改窗大小时只在"该变的"那一发 configure）
        self._prev_resize_bound = False          # v41：root <Configure> 只挂一次
        self._prev_key = None                    # 当前预览的 (场次, 题号)；同题再按 P = 收起
        self._curtain = None                     # v84：换页幕布（盖着的时候非 None）
        self._curtain_err = None                 # v84：幕布建不出来的原因（探针查它；正常 None）
        self._swap_busy = False                  # v84：换页进行中（幕布下泵消息时防重入）
        self.tab_all = tk.Frame(self.nb, bg=C_BG)
        self.tab_today = tk.Frame(self.nb, bg=C_BG)
        self.tab_know = tk.Frame(self.nb, bg=C_BG)      # v17：知识点统计页（索引 2，压在最后）
        self.nb.add(self.tab_all, text="总表")
        self.nb.add(self.tab_today, text="今天要做的")
        self.nb.add(self.tab_know, text="知识点统计")
        self._make_all_tab()
        self._make_split_tab()              # v66：分屏页（挤窄的七列表 + 右侧 md）—— 跟整张表页换页
        self._make_today_tab()
        self._make_know_tab()
        # v31：切页 → 第一行的「统计页计数」标签按当前页挂 / 收（`<<NotebookTabChanged>>`
        # 本机 Tk 8.6 实测有效：程序性 `nb.select()` 也发）；v50：侧栏预览也搭这趟车
        # （搜索框回总表那类**不经 `_goto_cell` 的跳页**同样照顾得到）
        self.nb.bind("<<NotebookTabChanged>>", lambda _e: self._on_tab_changed())
        if self.know_mode == "round":        # v27：上次停在「按场次」视图 → 开窗就摆好
            self.set_know_mode("round")

        # v14/v49：Tab / Shift+Tab = 两站焦点轮换（当前页清单 ⇄ 搜索框；见 _rotate_focus）
        # v65（解锁批）：Tab / Shift+Tab 收进注册表（`focus_next`，两把键同一处理器 ——
        # 方向看事件里有没有 Shift）—— 见 `_key_sites`。
        # v49：**md 预览那一站挪到「单按 Alt」**（用户口径「切换 md 文件与表行焦点改为 alt，
        #      tab 恢复为原来的作用」）。
        # v91：**再挪给「单按 Ctrl」**（用户口径「让焦点在 md 与主表之间转换的快捷键为 ctrl」）。
        #      **Ctrl 不能像 Alt 那样直接绑 KeyPress**：Tk 只在「光按 Alt」时发 <KeyPress-Alt_L/R>、
        #      Alt+回车这类组合根本不发（v49 时实测），但 **Ctrl 正好相反** —— 按 Ctrl+C / Ctrl+F
        #      这类组合时它也会先发一颗 <KeyPress-Control_L>，直接触发会把所有 Ctrl 组合全打乱。
        #      所以走「单按判定」三件套：① Ctrl↓ 记 flag（`_on_ctrl_down`）→ ② 期间任何别的键
        #      按下 / 松开都清 flag（`_ctrl_cancel_key`，**Shift 也算**：输入法 Ctrl+Shift 切换
        #      很常见，不做反向键）→ ③ Ctrl↑ 时 flag 还在才算单按（`_on_ctrl_up`）。
        #      ② 的捕获两条腿（2026-10-08 实测：具体绑定的 return "break" 会截断同层通配绑定）：
        #      · <Control-KeyPress>  = 兜**没被具体绑定接走**的 Ctrl 组合（按下那一半）；
        #      · <Control-KeyRelease> + <KeyRelease> = 兜**被接走的**组合（Ctrl+F / Ctrl+Z /
        #        Ctrl+Home…）的**松开**那一半 —— 没人绑带 Control 的具体 KeyRelease，截不掉。
        #      注册序在 `_apply_keys()`（下方）之前 —— 同 tag 同模式拼接时先注册先跑。
        #      Alt+Enter（跳转题目链接）不受影响（它挂在树上的具体模式，与这里无关）。
        self._ctrl_tap = False
        root.bind("<KeyPress-Control_L>", self._on_ctrl_down)
        root.bind("<KeyPress-Control_R>", self._on_ctrl_down)
        root.bind("<KeyRelease-Control_L>", self._on_ctrl_up)
        root.bind("<KeyRelease-Control_R>", self._on_ctrl_up)
        root.bind("<Control-KeyPress>", self._ctrl_cancel_key)
        root.bind("<Control-KeyRelease>", self._ctrl_cancel_key)
        root.bind("<KeyRelease>", self._ctrl_cancel_key)
        # v6：← / → 在一整条横排上走（v17 起 总表 + 统计 + 4 段 = 6 格，两头绕回；命中搜索框时让位）
        root.bind("<Left>", lambda e: self._nav_arrow(-1))
        root.bind("<Right>", lambda e: self._nav_arrow(1))
        # v26：其余可改键的操作（Ctrl+Z / Ctrl+Y / Ctrl+F、Ctrl+Home / End、Ctrl+方向键 ×4、F5、
        # F11、?，以及三棵树上的 1~6 / 回车 / Shift+Enter / Alt+Enter）全部走注册表挂（`_apply_keys`）——
        # 序列 = self.keymap（自定义）+ 固定副键；**默认值 = 原来写死的那批绑定，一个字没变**。
        # Alt+Enter 不挂 root：树自己的回车会先吃掉它（实测），所以它挂在两棵树上（见 _key_sites）。
        # Tab / ←→ / Esc / ↑↓ / 翻页这些导航键不进注册表（不可改）。
        self._sanitize_keymap_tk()
        self._make_settings()               # v40：设置界面（窗口内容的另一半；默认不摆）
        # v57.3：`_apply_keys()` 挪到 `_make_settings()` 之后 —— 「此项 / 全部恢复默认」两个挂点
        #        要挂在设置界面里的快捷键表（key_tv）上，这里必须已经建好。
        self._apply_keys()
        # v40：设置界面里 Esc = 返回主界面（函数里先判在不在设置界面）。
        # v65（解锁批）：Esc / Backspace 收进注册表（`cancel`，Backspace 是副键）—— 见 `_key_sites`。
        geom = self.cfg["geometry"]
        if geom and _geometry_ok(geom, root.winfo_screenwidth(), root.winfo_screenheight()):
            root.geometry(geom)             # v4：上次的窗口大小 / 位置（跑出屏幕就回默认）
        root.protocol("WM_DELETE_WINDOW", self.on_close)
        self._apply_theme()                 # v23：先把主题（勾选 / 样式映射 / 行 tag 配色）落到位
        self.reload()                       # 再读数重绘 —— 第一屏就是选中的那套主题
        self.tree.focus_set()
        # v22：还原「上次停在哪一页」。ttk.Notebook 没有 <<NotebookTabChanged>> 这类
        # 「切页完成」事件（探针实测），所以只能在打开时显式切一次；三页的内容 reload() 已经
        # 画好了，这里只补「选中页 + 焦点」。v29：看板四段合并后不再有段 —— 落到看板 = 切页 + 焦点。
        if self.last_page == 1:
            self.nb.select(1)
            self._active_tree().focus_set()
        elif self.last_page == 2:
            self.nb.select(2)
            self._active_tree().focus_set()   # v27：知识点 / 按场次 两种视图落在各自那张表
        self._sync_search_placeholder()      # v22：切了页 → 搜索框灰字按新页口径刷一遍
        # v8：输入法守卫 —— 只留搜索框收中文，其余（总表 / 清单 / 浮层 / 一览…）一律摘掉输入法；
        # win32 之外 / 拿不到 imm32 / 任何异常都静默降级，窗口行为与 v7 完全一致（见 ImeGuard）。
        # v18：面板拆除后，收中文的只剩搜索框一个。
        self.ime = ImeGuard(root, keep=(self.ent_search,))
        self.ime.install()
        # v78：收件箱 —— 打开工具时扫一遍（新增静默收、冲突弹窗问；quiet 的自测 / 冒烟 /
        # 探针不跑，绝不碰真数据）。F5 时也扫，见 _on_reload_key。
        self._inbox_win = None               # 冲突确认弹窗（开着时防重入）
        if not self.quiet:
            self.root.after(400, self._inbox_startup)

    # ------------------------------------------------------------ 配置 / 关窗
    def on_close(self):
        """关窗：先把 窗口大小 + 位置 + 排序 存下来（配置关闭时只关窗），再销毁。

        v11：全屏中关窗存的是「进全屏前」的窗口态 geometry（last_windowed_geometry）——
        别把整屏尺寸（或 1x1）留在配置里；窗口态下关窗照旧存当前 geometry。
        """
        if self._msg_after is not None:
            try:
                self.root.after_cancel(self._msg_after)
            except tk.TclError:
                pass
            self._msg_after = None
        if self.config_path:
            geom = self.root.geometry()
            if self._is_fullscreen() and self.last_windowed_geometry:
                geom = self.last_windowed_geometry            # v11：全屏中关窗 → 存进全屏前的窗口态
            save_config(self.config_path, {"geometry": geom,
                                           "sort_col": self.sort_col,
                                           "sort_desc": self.sort_desc,
                                           "know_desc": self.know_desc,       # v17：统计页升降序
                                           "know_mode": self.know_mode,        # v27：统计页视图 + 场次顺序
                                           "round_desc": self.round_desc,
                                           "last_page": self._current_page(),  # v22：停在哪一页（v29：段已合并）
                                           # v23：主题两项（下次开窗还原）
                                           "theme_sel_border": self.theme_sel_border,
                                           "theme_sel_color": self.theme_sel_color,
                                           "theme_scheme": self.theme_scheme,
                                           "theme_today": self.theme_today,   # v28：今天标记开关
                                           "theme_daynight": self.theme_daynight,  # v75：白天 / 黑夜
                                           "preview_mode": self.preview_mode,  # v45：P 键题解档（侧栏 / 全屏）
                                           "theme_focus": self._theme_focus_key(),  # v76：主题块上次焦点
                                           # v82：设置界面上次退出时的焦点站 / 摆着的块
                                           "set_focus": self._set_focus_key(),
                                           "set_block": self._set_block_key(),
                                           # v86：按场次视图展开状态（「记住上次的状态」）
                                           "round_open": sorted(self.round_open),
                                           # v26：自定义快捷键（只存差量；没改过就是空 {}）
                                           "keys": self._key_overrides(),
                                           # v74：键2（替代键）差量
                                           "keys2": self._key_overrides2()})
        self.root.destroy()

    # ------------------------------------------------------------ 全屏（v11）
    def _is_fullscreen(self):
        """现在在全屏吗？`wm attributes -fullscreen` 的返回值随平台 / Tk 版本是 int 或 str
        （实测 = int 0/1）—— 一律归一成 bool；拿不到就当没全屏。"""
        try:
            v = self.root.attributes("-fullscreen")
        except tk.TclError:
            return False
        try:
            return bool(int(v))
        except (TypeError, ValueError):
            return str(v).strip().lower() in ("1", "true", "yes")

    def toggle_fullscreen(self):
        """F11：全屏 ⇄ 窗口态（浏览器同款，再按一次退出）。

        v11：进入前把当时的窗口态 geometry 记进 last_windowed_geometry（全屏中关窗存这份）；
        退出全屏后同步成当前（= 系统恢复出来的）geometry —— 窗口态下拖动改过大小，关窗仍存当前值。
        """
        if self._is_fullscreen():
            try:
                self.root.attributes("-fullscreen", False)
            except tk.TclError:
                return
            self.last_windowed_geometry = self.root.geometry()  # 退出 = 回到窗口态，同步缓存
        else:
            self.last_windowed_geometry = self.root.geometry()  # 记在进入前（此刻还是窗口态）
            try:
                self.root.attributes("-fullscreen", True)
            except tk.TclError:
                pass

    def _on_f11_key(self, event=None):
        """F11 按键处理：切换全屏；return "break"（挂在 bind_all 上，任何焦点都走这里）。"""
        self.toggle_fullscreen()
        return "break"

    # ------------------------------------------------------------ 外观
    def _pick_family(self):
        try:
            fams = set(tkfont.families(self.root))
        except tk.TclError:
            return "TkDefaultFont"
        for c in ("Microsoft YaHei UI", "Microsoft YaHei", "微软雅黑", "Segoe UI", "DejaVu Sans"):
            if c in fams:
                return c
        return "TkDefaultFont"

    def _init_style(self):
        st = ttk.Style(self.root)
        try:
            st.theme_use("clam")               # clam 才认下面的配色；vista 会吃掉一部分
        except tk.TclError:
            pass
        self._setup_styles()

    def _setup_styles(self):
        """v75：ttk 样式统一配置（原 `_init_style` 的一整段 —— 抽出来，黑夜模式切换时按新
        框架色**再配一遍**；一律读模块常量，`_apply_framework` 已先 global 覆盖）。
        `Status.Treeview` 的**选中行 map** 不在这（归 `_apply_theme` 按「选择当前行」档设 / 清）。"""
        st = ttk.Style(self.root)
        st.configure(".", background=C_BG, foreground=C_TEXT, font=(self.fam, 13))
        st.configure("TNotebook", background=C_BG, borderwidth=0)
        # v7：页签栏整条隐藏。页签高度来自「TNotebook.Tab」这个元素的布局（TNotebook 自己的布局
        # 本来就只含 Notebook.client，改它没用 —— 实测 delta 仍 48px），把 Tab 的布局清空后
        # 标签区不画、不占高度（实测 48px → 2px），客户端区贴顶。nb.select() / nb.index() 照旧。
        st.layout("TNotebook.Tab", [])
        st.configure("TNotebook.Tab", font=(self.fam, 13, "bold"), padding=(20, 9))
        # 选中只换颜色（v3：clam 默认会给选中页签加大 padding，显式压平成同一个值，尺寸不变）
        st.map("TNotebook.Tab",
               background=[("selected", C_PANEL), ("!selected", C_BG)],
               foreground=[("selected", C_ACCENT_DARK), ("!selected", C_MUTED)],
               padding=[("selected", (20, 9)), ("!selected", (20, 9))],
               font=[("selected", (self.fam, 13, "bold")),
                     ("!selected", (self.fam, 13, "bold"))])
        st.configure("Status.Treeview", background=C_PANEL, fieldbackground=C_PANEL,
                     foreground=C_TEXT, font=(self.fam, 13), rowheight=34, borderwidth=0)
        st.configure("Status.Treeview.Heading", font=(self.fam, 13, "bold"),
                     background=C_ACCENT_LIGHT, foreground=C_ACCENT_DARK, padding=(6, 9),
                     relief="flat")
        st.map("Status.Treeview.Heading", background=[("active", C_ACCENT_LIGHT)])
        # v6：选中行在「有焦点 / 没焦点」下两套颜色 —— 这就是表格 / 清单的焦点指示
        # （focus 状态由 ttk 自己维护：控件拿到键盘焦点时是真状态，探针实测 8.6.18 成立）
        st.map("Status.Treeview",
               background=[("selected", "focus", C_ACCENT),
                           ("selected", "!focus", C_SELECT_OFF)],
               foreground=[("selected", "focus", "#ffffff"),
                           ("selected", "!focus", C_TEXT)])
        # v6 / v9：唯一的输入控件（搜索框）焦点指示 = 强调色边框 + 淡蓝底（没焦点时灰边框 + 白底）
        # v15：统一内边距（7, 5）—— 字不贴边、三个输入框一样高（占位提示的 x 偏移也照这个来）
        # v89（用户口径「暗主题搜索框焦点改成白色」）：**深色界面**下焦点边框 = 纯白（原来无论
        #   深浅都是强调色）；亮色界面照旧强调色。深浅判定与 `_apply_framework` 的 `night` 同一把尺
        #   （`frame_palette(...) is not FRAME_LIGHT` = D 系配色恒深 / 亮色配色 + 黑夜兜底），
        #   所以切主题时 `_setup_styles` 重配一发就自动跟上。聚焦底色（C_ACCENT_LIGHT）不动。
        _dark_ui = frame_palette(self.theme_scheme, self.theme_daynight) is not FRAME_LIGHT
        _focus_border = "#ffffff" if _dark_ui else C_ACCENT
        # v92（用户追认：「我说的是焦点,在搜索框提示位置的那个竖线的颜色」）：那条**光标竖线**
        #   （插入符）也走同一条尺 —— 深色界面纯白 / 浅色界面纯黑。它是 ttk 的**元素选项**
        #   `-insertcolor`（ttkEntry.c 里默认 = 黑），从样式上配；`_setup_styles` 换框架色时
        #   会重配一发，切主题自动跟上。（**不是** `insertbackground` —— 那是经典 Entry 的选项，
        #   ttk.Entry 建框时传它会直接 `TclError: unknown option`，2026-10-08 实撞。）
        st.configure("Nav.TEntry", fieldbackground=C_PANEL, bordercolor=C_LINE,
                     lightcolor=C_LINE, darkcolor=C_LINE, padding=(7, 5),
                     insertcolor=("#ffffff" if _dark_ui else "#000000"))
        st.map("Nav.TEntry",
               bordercolor=[("focus", _focus_border)], lightcolor=[("focus", _focus_border)],
               darkcolor=[("focus", _focus_border)],
               fieldbackground=[("focus", C_ACCENT_LIGHT)])
        # v16：弹窗主按钮（「开始 / 开始导出 / 应用到数据根」）—— 强调色底 + 白字，
        # 禁用时整颗变浅灰（选包窗空路径时「开始」禁用靠它）
        st.configure("Accent.TButton", background=C_ACCENT, foreground="#ffffff",
                     font=(self.fam, 13, "bold"), padding=(14, 6),
                     relief="flat", borderwidth=0,
                     bordercolor=C_ACCENT, lightcolor=C_ACCENT, darkcolor=C_ACCENT)
        st.map("Accent.TButton",
               background=[("disabled", C_SELECT_OFF), ("pressed", C_ACCENT_DARK),
                           ("active", C_ACCENT_DARK),
                           ("focus", C_ACCENT_DARK)],   # v26.1：键盘聚焦再深一档（焦点可见）
               foreground=[("disabled", C_MUTED)],
               bordercolor=[("disabled", C_SELECT_OFF)],
               lightcolor=[("disabled", C_SELECT_OFF), ("pressed", C_ACCENT_DARK),
                           ("active", C_ACCENT_DARK)],
               darkcolor=[("disabled", C_SELECT_OFF), ("pressed", C_ACCENT_DARK),
                          ("active", C_ACCENT_DARK)])
        # v26.1：快捷键设置窗的次级按钮 —— 键盘聚焦时给个看得见的底色（ttk 默认太不明显）
        st.configure("KeyDlg.TButton", padding=(10, 5), font=(self.fam, 12))
        st.map("KeyDlg.TButton",
               background=[("focus", C_ACCENT_LIGHT)],
               foreground=[("focus", C_ACCENT_DARK)])
        # v75（黑夜模式）：滚动条的深色样式 —— 派生名 "Dark.VScrollbar"（浅色下没人用、不碰默认
        #   外观）；`_recolor_framework` 负责把控件 style 属性切过去 / 切回来。
        # v82（用户报「收起 md 时中间一竖列白色间隔色块」）：**样式名必须带方向前缀** ——
        #   ttk 的竖向滚动条把 `-style` 的值当**布局名**查（查 "Vertical." + 名字），
        #   "Dark.VScrollbar" 会被拼成 "Vertical.Dark.VScrollbar"、查不到就抛
        #   `TclError: Layout Vertical.Dark.VScrollbar not found`，而 `_recolor_one` 里
        #   `except tk.TclError: pass` 把它吞了 —— 于是 v75 起这套深色滚动条**从来没生效过**，
        #   深色界面里滚动条一直是 clam 默认的浅色槽 #bab5ab（浅色界面下不显眼，深色界面下
        #   就是接缝/右缘那一竖列白色色块）。名字带前缀 + 继承默认布局即可。
        st.configure("Vertical.Dark.VScrollbar", background=C_SELECT_OFF, troughcolor=C_PANEL,
                     bordercolor=C_LINE, arrowcolor=C_MUTED,
                     lightcolor=C_LINE, darkcolor=C_LINE)
        _vlay = st.layout("Vertical.TScrollbar")      # 继承默认布局（换主题 / 非 clam 时它可能是空的）
        if _vlay:
            st.layout("Vertical.Dark.VScrollbar", _vlay)
        # v87：横向滚动条的深色样式（设置页「快捷键一览」块配了水平滚动条 —— 键位表有些行比窗口宽）——
        #   同款做法：名字带 "Horizontal." 方向前缀 + 继承默认布局（ttk 横向滚动条查 "Horizontal." + 名字）。
        st.configure("Horizontal.Dark.HScrollbar", background=C_SELECT_OFF, troughcolor=C_PANEL,
                     bordercolor=C_LINE, arrowcolor=C_MUTED,
                     lightcolor=C_LINE, darkcolor=C_LINE)
        _hlay = st.layout("Horizontal.TScrollbar")
        if _hlay:
            st.layout("Horizontal.Dark.HScrollbar", _hlay)
        # v9：`Nav.TCombobox`（状态筛选下拉的样式，v7 加的）随筛选整块删除 —— 窗口里没有下拉框了。

    def _make_head(self):
        """v9：窗口第一行 = 搜索标签 + 搜索框 + … + 消息 + 统计行。

        v51：搜索标签 + 搜索框只在**总表页**挂出来（`_apply_search_visible`）；统计行挪到
        这一行**最右端**（先挂 = 最右、永不挪位），它左边依次是 消息 /「筛出 N 题」/
        （统计页的）「共 N 个知识点」。

        原来的两行页头（大标题 `题目状态跟踪表`、路径行 `%s ｜ 今天 %s`）与窗口最底下那条
        消息行都删了；窗口标题栏（root.title）保留。消息启动时为空（不再写「已读入 …」），
        改状态 / 撤销时出现、3 秒自动消失。

        v63：这一行挂 **body**（原来挂 main_frame）—— 全屏 md 退出时整行摆回不推 body，
        见 `_md_full_hide_view`。摆回顺序 = body 里**先 head 后 nb**（`_md_full_hide_view` 里两条
        `pack` 就按这个次序），body 侧栏展开（`before=self.nb`）照旧。
        """
        head = tk.Frame(self.body, bg=C_BG)      # v63：挂 body 顶部（原来挂 main_frame —— 摆回时会推走 body）
        head.pack(fill="x", padx=16, pady=(10, 2))
        self.head = head                         # v62：全屏 md 独立界面要整行收起它（那儿只有 md 本身）
        self.lbl_search = tk.Label(head, text="搜" + LABEL_PAD + "索", bg=C_BG, fg=C_TEXT,
                                   font=(self.fam, 13))       # v7：去掉「（场次 / 题名 / 知识点）」；v15：插全角空格 = 三字宽（与面板三行标签对齐）
        self.lbl_search.pack(side="left")
        self.var_search = tk.StringVar(value="")
        self.ent_search = ttk.Entry(head, textvariable=self.var_search, width=26,
                                    font=(self.fam, 13),
                                    style="Nav.TEntry")         # v6：聚焦时边框 / 底色变强调；v15：宽 13 → 26
        self.ent_search.pack(side="left", padx=(6, 16))
        self.ent_search.bind("<KeyRelease>", self._on_search_typed)   # v17：按页分派（统计页搜知识点 / 其余搜题）
        self.ent_search.bind("<Return>", self._jump_to_table)   # v5：Enter 跳回总表（搜索词保留）
        self.ent_search.bind("<Escape>", self._esc_search)      # v17：有字先清空、空则回主页面
        # v49：焦点一走开就把**选区**清掉 —— F 进来会全选（用户口径「方便修改删除」），
        #      但从那儿 Tab / Alt / 点别处走开后选区还留着 = 框里一直「选中」的灰底白字（用户报的）。
        self.ent_search.bind("<FocusOut>", self._on_search_focus_out, add="+")
        # v21：搜索框里 ↑ / ↓ = 进主表 —— 跟 Enter 同一条路（回总表 + 焦点给表格 + 搜索词保留）。
        # 只挂在搜索框上（不挂 root）：主表里 ↑ / ↓ 仍归 Treeview 自己挪选中行。
        self.ent_search.bind("<Up>", self._jump_to_table)
        self.ent_search.bind("<Down>", self._jump_to_table)
        # v15：空框灰字提示；v17：留住 Label + sync，切页时换文案（统计页 = `知识点名`）
        # v18：主表口径改成「多字段」提示（空格分隔、任一命中）
        self._ph_search_lbl, self._ph_search_sync = \
            self._add_placeholder(self.ent_search, SEARCH_HINT_MAIN)

        # v31：统计页的计数挂第一行（`共 14 个知识点` / `共 5 个场次`）—— 只有统计页才挂出来，
        #      由 `<NotebookTabChanged>` 按当前页挂 / 收（页面里原来那行小字已删）。
        #      v51：统计行搬到最右端后，它挂到统计行**左边**（`after=self.lbl_count`）。
        self._know_count_text = ""
        self.var_know_min = tk.StringVar(value="")
        self.lbl_know_min = tk.Label(head, textvariable=self.var_know_min, bg=C_BG, fg=C_MUTED,
                                     font=(self.fam, 12), anchor="w")

        self.var_count = tk.StringVar(value="")
        self.lbl_count = tk.Label(head, textvariable=self.var_count, bg=C_BG, fg=C_TEXT,
                                  font=(self.fam, 12), anchor="w")
        # v51（用户口径「共XXX题…这行放到最右侧」）：统计行贴第一行**最右端** ——
        # pack 顺序 = 先挂先贴右，所以它先挂、消息 / 筛出 / 知识点评数随后挂（依次排它左边）。
        self.lbl_count.pack(side="right")

        self.var_msg = tk.StringVar(value="")
        self.lbl_msg = tk.Label(head, textvariable=self.var_msg, bg=C_BG, fg=C_MUTED,
                                font=(self.fam, 11), anchor="e")
        # v9：消息挪到这一行最右端；v51：最右端让给统计行，消息在它左边（padx 留 16px 间隔）
        self.lbl_msg.pack(side="right", padx=(0, 16))

        self.var_hits_min = tk.StringVar(value="")
        self.lbl_hits_min = tk.Label(head, textvariable=self.var_hits_min, bg=C_BG, fg=C_ACCENT_DARK,
                                     font=(self.fam, 11), anchor="e")
        self.lbl_hits_min.pack(side="right", padx=(0, 16))      # v14：面板收起时「筛出 N 题」挂这儿（v15：与消息之间留 16px）
        # v5 那条常驻快捷键提示（「按 ? 看快捷键」…）早已删；v9 把计数行并进这一行、
        # 消息挪到最右端（原底部行删除），并删掉状态筛选（下拉框 + F 键）。

        # v52：第一行高度对齐占位 —— 这一行的最高控件是搜索框（44px 档），切到看板 /
        #      统计页时它撤下、第一行矮 11px，下面整块内容跟着往上跳（用户报「高低差
        #      变化」）。占位 = 宽 0 的空 Frame、高取搜索框那一档（reqheight 动态取值，
        #      换字体 / DPI 变化自动跟随），由 `_apply_search_visible` 在撤搜索框前挂上、
        #      挂回来后撤下 —— 三页 + 设置界面第一行恒等高。
        self.head_spacer = tk.Frame(head, bg=C_BG)

    # ------------------------------------------------------------ 占位提示（v15）
    def _add_placeholder(self, ent, text, register=True):
        """空框且没焦点时浮一句浅灰提示语；聚焦 / 有字就隐。

        提示是**浮在输入框上的 Label**（`place` 在框内），不写进 textvariable ——
        `ent.get()` 仍是空串，匹配逻辑 / 命令行看不到它，不参与搜索。
        x=8 是给 Nav.TEntry 的 padding(7,5) + 1px 边框留的位置。
        register=False = 弹窗里的临时输入框（v16）：不进 `_ph_syncs`，窗销毁后
        主窗的「程序性清空 → 重同步」不会再碰它。
        """
        lbl = tk.Label(ent, text=text, bg=C_PANEL, fg=C_PLACEHOLDER,
                       font=(self.fam, 13), takefocus=0)

        def click(_e):
            ent.focus_set()                  # 点提示 = 点框（提示别把鼠标吃掉）
            return "break"

        def sync(_e=None):
            if ent.get() or ent.focus_get() is ent:
                lbl.place_forget()
            else:
                lbl.place(x=8, rely=0.5, anchor="w")

        lbl.bind("<Button-1>", click)
        ent.bind("<FocusIn>", sync, add="+")
        ent.bind("<FocusOut>", sync, add="+")
        ent.bind("<KeyRelease>", sync, add="+")     # 打字 / 删空都走这条
        if register:                                # v16：弹窗临时框不登记
            self._ph_syncs.append(sync)
        sync()
        return lbl, sync

    def _sync_search_placeholder(self):
        """v51：搜索框只属于总表页 —— 灰字提示恒为主表口径（v17 的「按页换文案」随
        统计页搜索一并作废）；顺带重跑一次 sync（切回总表时若框空着要重新浮出来）。
        """
        if self._ph_search_lbl is not None:
            self._ph_search_lbl.configure(text=SEARCH_HINT_MAIN)
        if self._ph_search_sync is not None:
            self._ph_search_sync()

    def update_hits(self, n):
        """`筛出 N 题`：只在**总表页**、且搜索框有词时有字（N = 当前总表可见行数）。

        v18：筛选下拉面板拆除后，只剩**窗口第一行右端**一处挂点 `var_hits_min`
        （原面板底部那处 `var_hits` 随面板一起删）。清空就消失（v10 删掉的常驻
        「搜出 M 题」不复活）。这里是「搜索命中数」提示，不再点名难度写法
        （难度已并入搜索框、认不出的写法就是命中 0 条）。
        v51：它属于搜索框那一条 —— 搜索框只在总表页显示，切走时 `_apply_search_visible` 顺手清字。
        """
        on_main = self.nb.index(self.nb.select()) == 0
        self.var_hits_min.set("筛出 %d 题" % n
                              if on_main and self.var_search.get().strip() else "")

    # ------------------------------------------------------------ 总表页
    def _make_split_tab(self):
        r"""v66：**分屏页** —— 左边一张挤窄的七列表 + 右边题解 md；跟「整张表页」来回切页。

        用户口径（2026-10-07）：「把这个退出变成切换界面的思路 —— 从设置页返回主表不会闪；
        左右分屏的页面跟整张主表的页面是两个页面，然后退出做的实际是页面切换，这样会又快又好」。

        起因（v61 之后的实据）：预览一开一收，表要在「全宽 ↔ 挤窄」之间重排 —— ttk 的列重排 +
        重画要 ~70ms（> 1 帧），无论怎么安排顺序都会有一帧"表还停在老样子"。分屏页自带**第二张表**
        （布局一次定死、开着期间永不重排），开 / 收预览 = 整页换掉 —— 跟设置页 / 看板页同一套机制
        （`pack_forget` + `pack`），零重排、零闪烁。

        `tree_split` 的数据 / 列宽 / 选中 / 滚动跟 `self.tree` 逐项同步（见 `_mirror_split`）。
        """
        self.split_tab = tk.Frame(self.body, bg=C_BG)      # 跟 nb **同框叠放**、常驻 mapped
        #     两页都摆着、只翻 z 序（`lift` / `lower`）：被盖住那页的窗口不 unmount、像素不丢 ——
        #     开 / 收预览那一拍屏幕上没有任何重画，这才是「页面切换」该有的零闪烁（实测：拆成
        #     pack/unpack 换页仍会露出 2~3 帧没画好的空表）。
        self._place_split_tab()                            # v70：摆到「第一行下面那一格」（见该函数）
        self.split_tab.lower()                             # 默认压在整张表页底下
        self.split_left = tk.Frame(self.split_tab, bg=C_BG)   # 分屏页左半 = 表格那块
        self.split_left.pack(side="left", fill="y")
        self.split_left.pack_propagate(False)              # 宽度由 `_sync_split_width` 反推着给
        mid = tk.Frame(self.split_left, bg=C_BG)
        # v70：右缘 0 内边距 —— 表格（含滚动条）跟右侧 md 像素级贴合（原来左右各 2px，
        #      右缘那条 2px 底色缝虽然细，但「无缝衔接」要的是零）
        mid.pack(fill="both", expand=True, padx=(2, 0), pady=(SPLIT_PAD_TOP, SPLIT_PAD_BOTTOM))
        self.tree_split = ttk.Treeview(mid, columns=HEADER, show="tree headings",
                                       selectmode="browse", style="Status.Treeview")
        weights = self._tree_weights                     # 跟总表同一套权重（v41 口径）
        anchors = {"题号": "center", "难度": "center", "状态": "center", "日期": "center"}
        for h in HEADER:
            if h in SORTABLE:
                self.tree_split.heading(h, text=h, command=lambda c=h: self.on_sort(c))
            else:
                self.tree_split.heading(h, text=h)
            self.tree_split.column(h, width=max(40, int(1200 * weights[h])), minwidth=40,
                                   anchor=anchors.get(h, "w"), stretch=False)
        self.tree_split.column("#0", width=TODAY_BAR_W, minwidth=TODAY_BAR_W, stretch=False)
        self.tree_split.heading("#0", text="")
        vsb = ttk.Scrollbar(mid, orient="vertical", command=self.tree_split.yview, takefocus=0)
        self.tree_split.configure(
            yscrollcommand=lambda f, l, v=vsb: self._on_split_scrolled(f, l, v))
        # v73：**滚动条先 pack** —— 反过来的话，分屏树「列宽贴合上一次实际宽度」后的需求宽度
        #      仍 ≥ 可用空间，会把滚动条挤成 ~3px 细线（用户口径「左侧表格行没有铺满最右端,
        #      溜了一条线」）。主表页没这毛病是运气（需求宽度 < 空间）；这里不赌，先给滚动条占位。
        vsb.pack(side="right", fill="y")
        self.tree_split.pack(side="left", fill="both", expand=True)
        self._split_settle = None
        self._split_up = False            # v66：分屏页此刻在**上面**吗（两页常驻，认这个不认 pack）
        self._split_dirty = True          # v66：收着时改过数据 → 开预览那一拍先补画（那时还在底下）
        self.tree_split.bind("<Configure>", self._on_split_configure)
        self.tree_split.bind("<Double-1>", self._on_double)
        self._bind_theme_events(self.tree_split)
        self._bar_frames_split = []                      # 分屏页自己的「今天竖条」框池
        # v73：md 常驻挂载 + 闭态 z 序一次定死 = 「分屏页 < md < 整张表页」（低→高）。
        #      nb 在上面时两张都看不见；开 / 收预览从此**只动 nb 一个窗口**（`nb.lower()` /
        #      `nb.lift()` 各一步，见 `_show_split_page` / `_show_table_page`）—— v66 那套
        #      「split_tab.lift() + prev_holder.lift()」两步换页实测会抓到「左半边已切换、
        #      右半边还是旧画面」的复合帧（用户报「不是同时消失出现」；50fps 抓帧复现 1 帧）。
        #      md 不再 place_forget —— 常驻挂载、只显隐 WebView2 本体（`set_visible`）。
        self._place_holder()
        self.split_tab.lower()                           # 分屏页压最底
        self.nb.lift()                                   # 整张表页压最上（闭态）
        # v81（用户报「搜索框显示不全」）：**上面那两发首摆跑在布局之前**（那时 head / nb 还
        #      没有几何，`_split_region()` 只能走兜底 —— 实测算出 y=13 / h=783，真实那一格是
        #      y=58 / h=738），于是两张常驻叠层从第一行**中段**起铺、把搜索框连同搜索标签 /
        #      计数压掉大半。此后只有「开预览」与「开着预览拉窗口」（`_on_root_resize_preview`
        #      在预览收起时直接 return）会重摆 → 没开过预览的整个会话里搜索框都是截断的。
        #      补法：nb 的 `<Configure>`（首次布局必定发一次、之后每次改窗 / 布局变化也发）
        #      上重摆一次 —— 那两个摆放函数各自带幂等闸，算出来一样就一个 Tcl 调用都不发。
        self.nb.bind("<Configure>", self._on_region_configure, add="+")

    def _on_region_configure(self, event=None):
        """v81：表格区（nb）几何一变 → 分屏页 / 预览栏重摆到它上面（见 `_make_split_tab` 尾注）。

        **全屏 md 档跳过**：那一档 holder 是被 `_md_full_show` 特意摆成「铺满 body」的
        （`relwidth=1 / relheight=1`），而 `_md_full_show` 里两发 `pack_forget`（head → nb）
        会让 nb 先量到一次新几何 —— 那个 `<Configure>` 是**排队**送达的，很可能落在
        「holder 已铺满」之后；此时若照常重摆，holder 会被打回右侧栏那一格、全屏 md 当场缩水。
        退出全屏时 md_full 已置假，`_md_full_hide_view` 自己会 `_place_holder()` 收尾。
        """
        if self.md_full:
            return
        self._place_split_tab()
        self._place_holder()

    def _on_split_configure(self, event=None):
        """分屏页那张表的 `<Configure>`：列宽按同一套权重重排 + 网格线 / 黑框 / 竖条跟上。"""
        self._on_tree_configure(event, tree=self.tree_split)
        self._sync_today_bar(self.tree_split)

    def _on_split_scrolled(self, first, last, vsb):
        """分屏页那张表滚动 → 更新滚动条 + 空闲重摆浮层（`_on_tree_scrolled` 的简版）。"""
        vsb.set(first, last)
        if self._split_settle is not None:
            try:
                self.tree_split.after_cancel(self._split_settle)
            except (tk.TclError, ValueError):
                pass
        self._split_settle = self.tree_split.after(80, self._on_split_settled)

    def _on_split_settled(self):
        self._split_settle = None
        try:
            self._sync_all_row_borders()
            self._sync_today_bar(self.tree_split)
        except tk.TclError:
            pass

    def _split_shown(self):
        """分屏页这会儿**露在上面**吗（v66：两页常驻，认"翻没翻上来"这个账，不认 pack 管理器）。"""
        return bool(getattr(self, "_split_up", False))

    def _split_region(self):
        """v70：分屏页 / 预览栏共用的「表格区那一格」—— 第一行（搜索框）下面、到窗口底。

        整张表页的 nb 就是这一格（`pack(side="left", padx=12, pady=(2, 4))` 挂在 head 后面）：
        布局完成后直接读它的 `winfo_y` / `winfo_height`；窗口还没完成首次布局
        （`winfo_* ≤ 1`，探针早期调用实测就是这个值）按第一行的请求高度推。
        """
        bh = self.body.winfo_height()
        if bh <= 1:
            bh = self.root.winfo_height()
        if bh <= 1:
            bh = 800
        ny = self.nb.winfo_y()
        nh = self.nb.winfo_height()
        if ny <= 1 or nh <= 1:
            hy, hh = self.head.winfo_y(), self.head.winfo_height()
            if hy <= 1 or hh <= 1:
                hy, hh = 10, (self.head.winfo_reqheight() or 44)
            ny = hy + hh + 2
            nh = max(1, bh - ny - 4)
        return ny, nh

    def _place_split_tab(self):
        """v70：分屏页摆到「表格区那一格」—— 从第一行（搜索框那一行）**下面**开始。

        改前它 `place(y=2, relheight=1)` 从窗口顶整块铺起，把第一行连搜索框一起盖掉
        （用户口径：「不要遮盖搜索框,只在搜索框以下显示」）。y / height 现在按 `_split_region()`
        现算（不再是 relheight —— 窗口高度变了由 `_on_root_resize_preview` 重摆）；算出来跟
        上次一样、且它还在盘上就一个 Tcl 调用都不发（窗口拖动时 Configure 连发，防自激）。
        """
        ny, nh = self._split_region()
        geo = (ny, nh)
        if geo == getattr(self, "_split_geo", None) and self.split_tab.winfo_manager():
            return
        self._split_geo = geo
        self.split_tab.place(x=12, y=ny, relwidth=1, width=-24, height=nh)

    def _sync_split_width(self):
        """分屏页左半（表格那块）的宽度 = 页面宽 − 预览栏宽（预览收起时按目标宽留位）。

        只在这里改宽度 → 分屏页那张表的重排永远发生在它**还压在整张表页底下**的时候（看不见）。
        v70：不再留那 12px 缝 —— 左表右缘（含滚动条）直接贴住 md 左缘（用户口径「无缝衔接」）；
        宽度算出来没变同样一个 Tcl 调用都不发。
        """
        page_w = self.split_tab.winfo_width()
        if page_w <= 1:
            page_w = self.root.winfo_width() or 1320
        pw = self.prev_w or self._preview_target_w()
        w = max(240, page_w - pw)
        if w == getattr(self, "_split_left_w", None):
            return
        self._split_left_w = w
        self.split_left.configure(width=w)

    def _place_holder(self):
        """v66：预览栏改用 `place` 钉在 body 右侧 —— 整张表页的宽度从此与它无关（永不重排）。

        v70：跟分屏页同格、与表格内容**上下齐平** —— 从第一行（搜索框）下面开始，上下各退
        `SPLIT_PAD_TOP` / `SPLIT_PAD_BOTTOM`（表格那几像素内边距，同源），右缘跟分屏页右缘
        一致（表与 md 零缝隙；用户拍板「与表格上下齐平」）。值没变且它还在盘上就什么都不发。
        """
        self.prev_w = self._preview_target_w()
        bw = self.body.winfo_width()
        if bw <= 1:
            bw = self.root.winfo_width() or 1320
        ny, nh = self._split_region()
        y = ny + SPLIT_PAD_TOP
        h = max(1, nh - SPLIT_PAD_TOP - SPLIT_PAD_BOTTOM)
        x = max(0, bw - self.prev_w - 12)
        geo = (x, y, self.prev_w, h)
        if geo == getattr(self, "_holder_geo", None) and self.prev_holder.winfo_manager():
            return
        self._holder_geo = geo
        # v73：**必须显式把 relwidth / relheight 归零** —— Tcl place 不传这两个参数时**保留旧值**，
        # 而全屏档（`_md_full_show`）给它设过 relwidth=1 / relheight=1；退出全屏后不归零的话，
        # 实际宽度 = 父宽 + prev_w（冒烟实测 1000 + 640 = 1640，把 (vv70) 零缝隙断言顶红）。
        self.prev_holder.place(x=x, y=y, width=self.prev_w, height=h,
                               relwidth=0, relheight=0)

    def _make_all_tab(self):
        mid = tk.Frame(self.tab_all, bg=C_BG)
        mid.pack(fill="both", expand=True, padx=2, pady=(6, 8))
        self.tree = ttk.Treeview(mid, columns=HEADER, show="headings", selectmode="browse",
                                 style="Status.Treeview")
        # v41（用户口径「压缩题名跟知识点跟场次行的宽度」）：三列权重下调 —— 题名 .23→.18、
        #   知识点 .28→.24、场次 .15→.14（场次名同样改短，见 `short_round`）；让出的权重给
        #   原来偏窄的难度 .08→.11、日期 .10→.14、状态 .11→.12（实测这三列在 1320 窗口下
        #   本来就会被截断）。权重和恒为 1.00 —— 和 < 1 会在表格右侧留一条空白。
        # v90（用户 2026-10-08 口径「减小场次列的列宽、增加题名列的列宽」）：场次 .14→.11、
        #   题名 .18→.21（场次名去 `#` / 题名去比赛前缀后都更短，场次列 132px 仍够放
        #   「小白月赛 137」这种最长的名字）。和仍是 1.00。
        weights = {"场次": .11, "题号": .07, "题名": .21, "知识点": .24,
                   "难度": .11, "状态": .12, "日期": .14}
        anchors = {"题号": "center", "难度": "center", "状态": "center", "日期": "center"}
        for h in HEADER:
            if h in SORTABLE:
                self.tree.heading(h, text=h, command=lambda c=h: self.on_sort(c))
            else:
                self.tree.heading(h, text=h)
            self.tree.column(h, width=max(40, int(1200 * weights[h])), minwidth=40,
                             anchor=anchors.get(h, "w"), stretch=False)
        # v25：最左 #0 窄列 = 「今天竖条」专用（宽 6px、无表头文字、不参与伸缩）。
        #      平时 show="headings" 把它藏起来（默认配色下界面与 v22.2 一字不差），
        #      Radix 配色才由 `_apply_theme` 切换成 "tree headings" 放它出来。
        self.tree.column("#0", width=TODAY_BAR_W, minwidth=TODAY_BAR_W, stretch=False)
        self.tree.heading("#0", text="")
        # v23：行 tag（斑马纹 / 今天 / 六状态色）**一律由主题那一套去配**（`_apply_theme` →
        # `_configure_scheme_tags`）—— 这里不再写死，免得跟「配色」切换打架。
        # （v22 那两行 `tag_configure("odd"/"even"/"today", ...)` 已按 v23 口径撤掉。）
        vsb = ttk.Scrollbar(mid, orient="vertical", command=self.tree.yview,
                            takefocus=0)                 # v6：滚动条不进 Tab 轮换
        # v25：yscrollcommand 顺带重摆「今天竖条」——ttk 每次视口变化都会喊这个钩子
        # （滚轮 / 拖动条 / PgUp / see()），After_idle 合并连发（见 `_on_tree_scrolled`）。
        self.tree.configure(yscrollcommand=lambda f, l, v=vsb: self._on_tree_scrolled(f, l, v))
        self.tree.pack(side="left", fill="both", expand=True)
        vsb.pack(side="right", fill="y")
        self._tree_weights = weights
        self.tree.bind("<Configure>", self._on_tree_configure)
        # v25：切页回来（控件重新 Map，比如从看板页切回总表）补一次「今天竖条」同步
        self.tree.bind("<Map>", lambda e: self._sync_today_bar(), add="+")
        # v26：回车（浮层）/ Shift+Enter / Alt+Enter / 1~6（含小键盘）几组改由注册表挂（`_apply_keys`，
        # 支持自定义键）—— 原来写死的绑定原样搬进 KEY_ACTIONS，默认值一个字没变。
        # Alt+Enter 比 <Return> 更具体、先命中；数字绑树上（不是 root）：焦点在搜索框里时照常打字。
        self.tree.bind("<Double-1>", self._on_double)
        # v17：行上 Esc 清搜索（v65 起 Esc / Backspace 都走注册表的 `cancel`，见 `_key_sites`）
        self._bind_theme_events(self.tree)                       # v23：选中行边框跟着选中 / 滚动重摆

    # ------------------------------------------------------------ 看板页
    def _make_today_tab(self):
        """看板页（v29：四个大块卡片删除 —— 四类合并成**一个清单**）。

        清单里两种行：**类标题行**（`待重写 · 3`，v34 起不再有淡蓝底、改走斑马纹；**v34.1**：
        与题目行**分开计数** —— 标题行 4 条之间自己交替；iid = `seg0` ~ `seg3`，只在有题时
        才插入，插入逻辑在 `refresh_today`）+ **题目行**（iid = `str(_i)`，
        跟总表一致 —— 1~6 直改状态 / 回车浮层 / 打开原题这些照旧落得到）。
        四类全空时清单完全空白（无占位行）。
        """
        # v29：原来顶部那排四个大块卡片（大数字 + 段标题、点击切段）整块删除 ——
        # 现在四类直接合并在下面这一张清单里，空类连行都不出现。
        # v7：原来这里还有一行页内键盘提示（← / → 换段 ｜ ↑↓ 移动 ｜ 回车 / 双击 = 改状态浮层），
        # 早已整条删掉 —— 看板页不挂任何提示行（快捷键说明只有 `?` 一览一处）。
        mid = tk.Frame(self.tab_today, bg=C_BG)
        mid.pack(fill="both", expand=True, padx=2, pady=(8, 8))
        # v41：与总表同口径压缩（题名 / 知识点 / 场次让位给难度、日期）
        # v90：跟总表同一口径 —— 场次 .17→.13、题名 .20→.24（和恒 1.00）
        w2 = {"场次": .13, "题号": .07, "题名": .24, "知识点": .27, "难度": .11, "日期": .18}
        self.today_tree = ttk.Treeview(mid, columns=TODAY_COLS, show="headings",
                                       selectmode="browse", style="Status.Treeview")
        anchors = {"题号": "center", "难度": "center", "日期": "center"}
        for h in TODAY_COLS:
            self.today_tree.heading(h, text=h)
            self.today_tree.column(h, width=int(1200 * w2[h]), minwidth=40,
                                   anchor=anchors.get(h, "w"), stretch=False)
        self.today_tree.tag_configure("odd", background=C_PANEL)
        self.today_tree.tag_configure("even", background=C_ZEBRA)
        # v34：类标题行不再有专属底色 —— v29 的 `seg` tag（浅蓝整行底）整条删除，标题行改走
        # 斑马纹（挂 odd / even）；**v34.1**：与题目行**分开计数**（用户口径「这四个跟题目是
        # 不同的结构、分开算的」）—— 标题行 4 条之间自己交替（`refresh_today` 的 k_seg），
        # 题目行照旧跨类连续（k_all）。
        # v23：看板清单的行 tag 也由主题那套配（`_apply_theme` 会按配色覆盖 odd / even / today）
        vsb = ttk.Scrollbar(mid, orient="vertical", command=self.today_tree.yview,
                            takefocus=0)                 # v6：滚动条不进 Tab 轮换
        self.today_tree.configure(yscrollcommand=vsb.set)
        self.today_tree.pack(side="left", fill="both", expand=True)
        vsb.pack(side="right", fill="y")
        self._today_weights = w2
        self.today_tree.bind("<Configure>",
                             lambda e: self._on_tree_configure(e, self.today_tree,
                                                               self._today_weights))
        # v26：回车 / Shift+Enter / Alt+Enter / 数字键几组改由注册表挂（理由同总表）
        self.today_tree.bind("<Double-1>", self._on_double)
        # v17：行上 Esc 清搜索（v65 起走注册表 `cancel`）
        self._bind_theme_events(self.today_tree)                 # v23：选中行边框（v29：段记忆那条 Select 绑定已删）
        # v6：原来这里挂着数字键 1~4 切段，已删（v29：段本身也合并了 —— 数字键仍是树上 1~6 直改状态）

    # ------------------------------------------------------------ 知识点统计页（v17）
    def _make_know_tab(self):
        """知识点统计页：一张两列清单（知识点 / 次数），**全量统计**（不受搜索 / 筛选影响）。

        排序：点「次数」列头 = 升 / 降切换（默认降序 = 考得最多的在上）；`S` / `R` 同效。
        键盘：↑↓ 移动、Enter / 双击 = 跳回总表并把该知识点填进搜索框（当导航入口用）；
        PgUp / PgDn 翻页。清单行是**知识点**不是题目，所以状态浮层 / 数字改状态这些
        题目操作在这里不成立 —— 那些键绑的是别的树，落不到本页。
        """
        # v31（用户口径「统一成：顶层标题 + 表信息；占布局空间的快捷键提示全删」）：
        # 原来这页顶上那行小字（计数 + 快捷键提示）**整行删除** —— 计数折进**页签标题**
        # （页签即标题，见 `_sync_know_tab_title`）；三页从此统一成「页签 → 表格」。
        mid = tk.Frame(self.tab_know, bg=C_BG)
        mid.pack(fill="both", expand=True, padx=2, pady=(8, 8))
        # v27：统计页两个视图各占一个容器（知识点 / 按场次），切换 = 换 pack 的那个
        self.know_box = tk.Frame(mid, bg=C_BG)
        self.know_box.pack(fill="both", expand=True)
        w3 = {"知识点": .78, "次数": .22}
        anchors = {"次数": "center"}
        self.know_tree = ttk.Treeview(self.know_box, columns=KNOW_COLS, show="headings",
                                      selectmode="browse", style="Status.Treeview")
        for h in KNOW_COLS:
            if h == "次数":
                self.know_tree.heading(h, text=h, command=self._know_sort_click)
            else:
                self.know_tree.heading(h, text=h)
            self.know_tree.column(h, width=int(1200 * w3[h]), minwidth=40,
                                  anchor=anchors.get(h, "w"), stretch=False)
        self.know_tree.tag_configure("odd", background=C_PANEL)
        self.know_tree.tag_configure("even", background=C_ZEBRA)
        # v33 层级色阶二改：顶层行（父行 + 平铺知识点）= 杏黄「浅 ↔ 深」整片交替（行底无白）；
        #      子行 = 草绿「浅 ↔ 深」（块内从浅档起）
        #      （v30 的"层色 ↔ 白"按用户新口径作废；v28.1 的"全行同一套斑马"更早已废）
        self.know_tree.tag_configure("lvl1", background=C_LVL1)
        self.know_tree.tag_configure("lvl1b", background=C_LVL1B)
        self.know_tree.tag_configure("lvl2", background=C_LVL2)
        self.know_tree.tag_configure("lvl2b", background=C_LVL2B)
        # v97：知识点统计**第三层**（多级桶，如 数学 → 数论 → 素数）—— 第 3 层及更深都用它
        self.know_tree.tag_configure("lvl3", background=C_LVL3)
        self.know_tree.tag_configure("lvl3b", background=C_LVL3B)
        vsb = ttk.Scrollbar(self.know_box, orient="vertical", command=self.know_tree.yview, takefocus=0)
        self.know_tree.configure(yscrollcommand=vsb.set)
        self.know_tree.pack(side="left", fill="both", expand=True)
        vsb.pack(side="right", fill="y")
        self._know_weights = w3
        self.know_tree.bind("<Configure>",
                            lambda e: self._on_tree_configure(e, self.know_tree, self._know_weights))
        # v26：回车（展开父行 / 跳搜）由注册表挂（跟总表的浮层是同一个「回车」操作，各自处理器）
        self.know_tree.bind("<Double-1>", self._on_know_enter)
        # v17：行上 Esc 清搜索（统计页清的是知识点词；v65 起走注册表 `cancel`）
        self._bind_theme_events(self.know_tree)                  # v23：选中行边框跟着选中 / 滚动重摆
        self._make_round_view(mid)                               # v27：同页的「按场次」视图（默认不出场）

    # ------------------------------------------------------------ v27：统计页「按场次」视图
    def _make_round_view(self, parent):
        """按场次视图 —— 平铺三层：平台（牛客周赛…）→ 场次（… Round 146）→ 每场每一题。

        用户口径（2026-10-06）：跟知识点页同款展开互动（回车展开 / 收起），展开到题目行时
        **跟看板页同级** —— 1~6 直改状态、Ctrl+Enter 弹状态浮层、Alt+Enter 跳题目链接、回车展开 / 收起题解 md
        （v46 起；原来题目行回车 = 状态浮层）。
        行是**平铺**的（箭头 / 缩进写在文本里，跟知识点页同一套做法），所以选中、翻页、
        改状态下移这些既有机制原样复用；平台 / 场次行 iid 带 `P|` / `R|` 前缀（row_by_iid
        自然认不出 → 题目操作不会落到它们头上），题目行 iid = `str(_i)`（跟看板一致）。
        """
        self.round_box = tk.Frame(parent, bg=C_BG)
        # v41：场次列要装「    ▾ 牛客周赛 146（5 题·AC 2·40%）」（缩进 + 标签 ≈373px），权重 .30→.32；
        #   让出的空间从题名 / 知识点出（.22→.15 / .20→.14），难度 .07→.11、状态 / 日期同步补齐
        # v90（用户口径「减小场次列、增加题名列」）：**这张表不动** —— 场次列装的是层级标签
        #   （v86 三层树），实测最长「    ▸ 小白月赛 137（8 题·AC 3·38%·难度 800-1800·差 1000）」
        #   = 408px，.32 × 1200 = 384px 本就贴着上限，再收会截断；总表 / 看板两处已按口径调整。
        w = {"场次": .32, "题号": .04, "题名": .15, "知识点": .14,
             "难度": .11, "状态": .12, "日期": .12}
        anchors = {"题号": "center", "难度": "center", "状态": "center", "日期": "center"}
        self.round_tree = ttk.Treeview(self.round_box, columns=ROUND_COLS, show="headings",
                                       selectmode="browse", style="Status.Treeview")
        for h in ROUND_COLS:
            self.round_tree.heading(h, text=h)
            self.round_tree.column(h, width=int(1200 * w[h]), minwidth=40,
                                   anchor=anchors.get(h, "w"), stretch=False)
        self.round_tree.tag_configure("odd", background=C_PANEL)
        self.round_tree.tag_configure("even", background=C_ZEBRA)
        # v33 层级色阶二改、v86 三层：平台行 = 新 `lvl0`「浅 ↔ 深」（整片交替）、
        #      系列行 = 杏黄「浅 ↔ 深」、场次行 = 草绿「浅 ↔ 深」、
        #      题目行**不动**（even/odd 或状态色，跟主表一致）——
        #      v30 的"层色 ↔ 白"按用户新口径作废；v27 的 "group" 淡蓝底 tag 早已删
        self.round_tree.tag_configure("lvl0", background=C_LVL0)
        self.round_tree.tag_configure("lvl0b", background=C_LVL0B)
        self.round_tree.tag_configure("lvl1", background=C_LVL1)
        self.round_tree.tag_configure("lvl1b", background=C_LVL1B)
        self.round_tree.tag_configure("lvl2", background=C_LVL2)
        self.round_tree.tag_configure("lvl2b", background=C_LVL2B)
        vsb = ttk.Scrollbar(self.round_box, orient="vertical", command=self.round_tree.yview, takefocus=0)
        self.round_tree.configure(yscrollcommand=vsb.set)
        self.round_tree.pack(side="left", fill="both", expand=True)
        vsb.pack(side="right", fill="y")
        self._round_weights = w
        self.round_tree.bind("<Configure>",
                             lambda e: self._on_tree_configure(e, self.round_tree, self._round_weights))
        self.round_tree.bind("<Double-1>", self._on_round_double)   # v46：双击照旧「平台 / 场次 = 展开 · 题目行 = 浮层」
        # v65 起走注册表 `cancel`（按场次视图的行上 Esc）
        self._bind_theme_events(self.round_tree)                 # 选中行边框跟着选中 / 滚动重摆
        self._round_head_mark()                                  # v27.2：表头带当前排序的 ▲ / ▼

    def _round_head_mark(self):
        """v27.2（用户点名）：按场次视图的表头给**当前排序**一个三角提示 ——
        **v74：降序 `场次 ▲` / 升序 `场次 ▼`**（用户拍板「三角在上 = 降序、在下 = 升序」；
        口径与总表表头、知识点页三处统一 —— v27.2~v72 是反的，v73 对调）。
        v31：首列「比赛场次」改名「场次」，与总表同名列对齐。
        `Ctrl+方向键`（走 `_know_sort_toggle`）反转场次顺序后同步刷新。"""
        self.round_tree.heading("场次",
                                text="场次" + (" ▲" if self.round_desc else " ▼"))

    def _sync_know_count(self, text):
        """v31（用户口径「计数并进窗口第一行」）：统计页的计数挂**窗口第一行**（`共 14 个知识点` /
        `共 5 个场次`）—— 页内那行小字已整行删除；v51：搜索框撤出统计页后不再有「筛出 X /」形态。

        只在统计页显示：文本先存 `self._know_count_text`，由 `<NotebookTabChanged>` →
        `_apply_know_count()` 按当前页决定挂不挂出来（其他页清空）。
        """
        self._know_count_text = text
        self._apply_know_count()

    def _apply_know_count(self):
        """v31：按当前页挂 / 收第一行的统计页计数标签（统计页才有字）。

        v51：计数行搬到最右端后，它挂到计数行**左边**（`after=self.lbl_count`，两个计数
        贴成一个右端小簇）。不显示时 `pack_forget`，计数行的位置不受影响。
        """
        try:
            on_know = self.nb.index(self.nb.select()) == 2
        except tk.TclError:
            on_know = False
        if on_know and self._know_count_text:
            self.var_know_min.set(self._know_count_text)
            if not self.lbl_know_min.winfo_manager():
                self.lbl_know_min.pack(side="right", padx=(0, 12), after=self.lbl_count)
        else:
            self.var_know_min.set("")
            if self.lbl_know_min.winfo_manager():
                self.lbl_know_min.pack_forget()

    def _apply_search_visible(self):
        """v51（用户口径「取消除主表以外界面的搜索框」）：搜索标签 + 搜索框 + 「筛出 N 题」
        只在**总表页**显示 —— 切到看板 / 统计页整条 `pack_forget`（「筛出」同时清字），
        切回来按 `before=self.lbl_count` 挂回原位（保持「搜索在最左、计数在最右」的分配次序）。

        只藏不删：`var_search` 的值原样留着（v51 口径：搜索词归属总表、切页保留、切回仍筛）。

        v52：撤 / 挂搜索框都跟 `head_spacer`（等高占位）成对走 —— **先把撑高的挂上、再撤
        矮的**（回总表反过来：先挂搜索框、再撤占位），第一行高度自始至终不变、
        下面整块内容不再跟着跳（用户报「切换到其他界面再返回主表会有高低差变化」）。
        """
        if self.nb.index(self.nb.select()) == 0:
            if not self.lbl_search.winfo_manager():
                self.lbl_search.pack(side="left", before=self.lbl_count)
            if not self.ent_search.winfo_manager():
                self.ent_search.pack(side="left", padx=(6, 16), before=self.lbl_count)
            if self.head_spacer.winfo_manager():          # v52：搜索框已回来 → 占位撤下
                self.head_spacer.pack_forget()
            self.update_hits(len(self.tree.get_children()))
        else:
            self.var_hits_min.set("")
            if not self.head_spacer.winfo_manager():      # v52：先撑住（等高一档），再撤搜索框
                self.head_spacer.configure(height=self.ent_search.winfo_reqheight())
                self.head_spacer.pack(side="left", before=self.lbl_count)
            if self.lbl_search.winfo_manager():
                self.lbl_search.pack_forget()
            if self.ent_search.winfo_manager():
                self.ent_search.pack_forget()

    def set_know_mode(self, mode):
        """v27：切统计页视图 —— `know` = 知识点清单、`round` = 按场次（平台 → 场次 → 每场每一题）。

        只换显示（pack / pack_forget 两个容器）+ 刷灰字提示 + 重画；页签（← / → 的第几格）
        一个字不动。
        """
        self.know_mode = "round" if mode == "round" else "know"
        try:
            if self.know_mode == "round":
                self.know_box.pack_forget()
                self.round_box.pack(fill="both", expand=True)
            else:
                self.round_box.pack_forget()
                self.know_box.pack(fill="both", expand=True)
        except tk.TclError:
            return
        self._sync_search_placeholder()
        self.refresh_know()
        self._active_tree().focus_set()

    def _on_know_mode_key(self, event=None):
        """v27：Ctrl+K（可自定义）—— 统计页在「知识点 / 按场次」间切换。

        只在本页生效：在别的页上按 → 提示一句（不跨页抢动作，免得跟 ← / → 的走法打架）。
        """
        if self._busy() or self._in_text_widget():
            return None
        if self.nb.index(self.nb.select()) != 2:
            self.set_msg("视图切换键只在统计页生效（← / → 走过去）", clear_after=TOAST_MS)
            return "break"
        self.set_know_mode("know" if self.know_mode == "round" else "round")
        return "break"

    def _on_goto_today(self, event=None):
        """v65：Ctrl+1 —— 直达看板（今天要做的）。设置界面 / 输入框里不响应（跟同类键同规）。"""
        if self._busy() or self._in_text_widget() or self._in_settings():
            return None
        self._goto_cell(2)
        return "break"

    def _on_goto_know(self, event=None):
        """v65：Ctrl+2 —— 直达统计页。"""
        if self._busy() or self._in_text_widget() or self._in_settings():
            return None
        self._goto_cell(1)
        return "break"

    def _on_theme_cycle(self, event=None):
        """v65：Ctrl+T —— 切主题档（蓝底白字 → 淡蓝色底 → 黑色边框 → 白色边框 轮换；v72 加末档）。

        改的是内存值（跟设置页主题块同源），关窗统一存盘；设置页下次打开按新值建勾选。
        """
        if self._busy() or self._in_text_widget() or self._in_settings():
            return None
        # v75.3：Ctrl+T 循环 **「当前行颜色」** 三档（边框不参与 —— 拆两组后日常最常切的是颜色）
        ids = [k for k, _lab in THEME_SELC_ITEMS]
        cur = self.theme_sel_color if self.theme_sel_color in ids else ids[0]
        self.theme_sel_color = ids[(ids.index(cur) + 1) % len(ids)]
        self._apply_theme()
        self.set_msg("当前行颜色：%s（再按继续切）"
                     % dict(THEME_SELC_ITEMS).get(self.theme_sel_color, self.theme_sel_color),
                     clear_after=TOAST_MS)
        return "break"

    def _on_preview_cycle(self, event=None):
        """v65：Ctrl+P —— 切题解预览档（右侧栏 ⇄ 全屏）。

        与设置页「主题设置 ▸ 题解预览」同一条状态机：切档当场把另一种显示收掉
        （切去全屏收右侧栏、切回右侧栏收全屏 —— 与 `on_theme_pick` 里那段一字同规）。
        """
        if self._busy() or self._in_text_widget() or self._in_settings():
            return None
        if self.preview_mode == PREVIEW_MODE_SIDE:
            self.preview_mode = PREVIEW_MODE_FULL
            self._hide_preview()
        else:
            self.preview_mode = PREVIEW_MODE_SIDE
            self._exit_md_full()
        self.set_msg("题解预览档：%s" % dict(THEME_PREVIEW_ITEMS).get(self.preview_mode),
                     clear_after=TOAST_MS)
        return "break"

    def refresh_rounds(self):
        """v27 立、v86 改三层：平台行（带汇总）+ 系列行 + 场次行（后缀统计）+ 展开场次的题目行。

        展开状态存 `self.round_open`（键 = iid：`P|平台` / `S|系列` / `R|场次`；v86 起随配置
        **持久化**（开窗还原 / 关窗写回，见 `load_config` / `on_close`）—— 用户口径「记住上次的状态」）。
        v51：不再按搜索词过滤（原来「按场次 / 平台名筛 + 有词自动展开平台」随搜索框撤出统计页
        作废）；题目行值 = 总表同款六列。
        重建前记着原选中 iid，尽力保选中（那行没了就贴回第一行）。
        """
        tree = self.round_tree
        sel = list(tree.selection())
        keep_iid = sel[0] if sel else None
        for iid in tree.get_children():
            tree.delete(iid)
        today = datetime.date.today().isoformat()
        groups = rounds_group(self.rows, desc=self.round_desc)
        n_round_all = sum(len(rs) for _p, series in groups for _sr, rs in series)
        # v86 层级色阶（用户口径「自己给每种主题适配对应新父级斑马色配色」）：
        #   平台行 = `lvl0` 浅 ↔ `lvl0b` 深（**整片**交替、从浅档起）；
        #   系列行 = `lvl1` 浅 ↔ `lvl1b` 深（**平台块内**从浅档起）；
        #   场次行 = `lvl2` 浅 ↔ `lvl2b` 深（**系列块内**从浅档起）；
        #   题目行**不动**（`_row_tags`：跟主表一致；k3+1 的"第 1 题落 even"口径原样保留）。
        k0 = 0
        for plat, series in groups:
            if not series:
                continue
            pid = "P|" + plat
            open_p = pid in self.round_open                    # v51：词不再撑开平台行
            n_rounds = sum(len(rs) for _sr, rs in series)
            n_prob = sum(len(lst) for _sr, rs in series for _s, lst, _ac in rs)
            n_ac = sum(ac for _sr, rs in series for _s, _lst, ac in rs)
            tree.insert("", "end", iid=pid,
                        values=[("▾ " if open_p else "▸ ")
                                + plat_label(plat, n_rounds, n_prob, n_ac),
                                "", "", "", "", "", ""],
                        tags=["lvl0" if k0 % 2 == 0 else "lvl0b"])
            k0 += 1
            if not open_p:
                continue
            for k1, (sr, rounds) in enumerate(series):
                sid = "S|" + sr
                open_s = sid in self.round_open
                tree.insert("", "end", iid=sid,
                            values=["    " + ("▾ " if open_s else "▸ ") + sr,
                                    "", "", "", "", "", ""],
                            tags=["lvl1" if k1 % 2 == 0 else "lvl1b"])
                if not open_s:
                    continue
                for k2, (s, lst, ac) in enumerate(rounds):
                    rid = "R|" + s
                    open_r = rid in self.round_open
                    tree.insert("", "end", iid=rid,
                                values=["        " + ("▾ " if open_r else "▸ ")
                                        + round_label(s, len(lst), ac,
                                                      [r.get("难度", "") for r in lst]),
                                        "", "", "", "", "", ""],
                                tags=["lvl2" if k2 % 2 == 0 else "lvl2b"])
                    if not open_r:
                        continue
                    for k3, r in enumerate(sorted(lst, key=lambda x: (x["题号"], x["_i"]))):
                        tree.insert("", "end", iid=str(r["_i"]),
                                    values=["", r["题号"], short_cell("题名", r["题名"]),
                                            r["知识点"], r["难度"],
                                            r["状态"], short_cell("日期", r["日期"])],
                                    tags=self._row_tags(r, k3 + 1, r["日期"] == today))
        iids = list(tree.get_children())
        self._round_head_mark()                  # v27.2：表头 ▲ / ▼ 跟着当前排序（换序 / 重画都刷）
        # v31：计数并进窗口第一行（页内那行小字连同快捷键提示一起删了）；v51：不再有「筛出 X /」
        self._sync_know_count("共 %d 个场次" % n_round_all)
        if not iids:
            return
        pick = keep_iid if keep_iid in iids else iids[0]
        tree.selection_set(pick)
        tree.focus(pick)
        tree.see(pick)

    def _round_toggle_open(self, iid):
        """按场次视图：平台 / 场次行展开 ⇄ 收起（Enter / 双击共用）。"""
        if iid in self.round_open:
            self.round_open.discard(iid)
        else:
            self.round_open.add(iid)
        self.refresh_rounds()
        self._round_focus_iid(iid)

    def _round_popup_if_row(self, iid):
        """按场次视图：题目行 → 状态浮层（平台 / 场次行静默，不切页）。"""
        row = self.row_by_iid(iid)
        if row:
            self.open_status_popup(row, self.round_tree)

    def _round_sel_iid(self):
        """按场次视图当前选中行 iid（没选中 → None）。"""
        sel = list(self.round_tree.selection())
        return sel[0] if sel else None

    def _on_round_enter(self, event=None):
        """v27 立、v46 改：按场次视图 **Enter** —— 平台 / 场次行 = 展开 · 收起；题目行 = 展开 / 收起题解 md。

        （原来的「题目行 = 状态浮层」随 v46 挪去 Ctrl+Enter，见 `_on_round_ctrl_enter`；
        双击照旧走浮层，见 `_on_round_double`。）
        """
        iid = self._round_sel_iid()
        if iid is None:
            return "break"
        if iid.startswith(("P|", "S|", "R|")):
            self._round_toggle_open(iid)
            return "break"
        return self._toggle_preview(event)      # 题目行：展开 / 收起题解 md（是不是题目行由它自己再判一道）

    def _on_round_ctrl_enter(self, event=None):
        """v46：按场次视图 **Ctrl+Enter** —— 题目行 = 状态浮层；平台 / 场次行不响应（它的主动作是回车展开）。"""
        iid = self._round_sel_iid()
        if iid is not None and not iid.startswith(("P|", "S|", "R|")):
            self._round_popup_if_row(iid)
        return "break"

    def _on_round_double(self, event=None):
        """v27 立、v46 拆出：按场次视图 **双击** —— 平台 / 场次行 = 展开 · 收起；题目行 = 状态浮层（与总表双击同款）。"""
        iid = self._round_sel_iid()
        if iid is None:
            return "break"
        if iid.startswith(("P|", "S|", "R|")):
            self._round_toggle_open(iid)
        else:
            self._round_popup_if_row(iid)
        return "break"

    def _round_focus_iid(self, iid):
        """把选中 / 焦点挪到 iid 那行（不在列表里就静默）。"""
        tree = self.round_tree
        if tree.exists(iid):
            tree.selection_set(iid)
            tree.focus(iid)
            tree.see(iid)

    def _round_esc_collapse(self):
        """按场次视图上「收起」：选中行是展开的平台 / 系列 / 场次、或展开场次下的题目行 → 收掉它、
        光标移到那一行；什么都没收成 → False（交给清搜索 / 送焦点那两条）。

        v35（用户口径「所有的分层结构：在当前父行的子行或当前父行上按 Esc 都收起当前父行」）：
        **收着的结构行**上按 Esc → 收起它上面**那一层**（逐级往上退，一步一层）；展开着的结构行
        照旧先收自己、题目行照旧收所在场次、收着的平台行（顶层）不归这条管。
        v86（三层）：系列行收着的 → 收上面的平台行；场次行收着的 → 收上面的系列行。
        （v51：原来「有搜索词时不走这条」随搜索框撤出统计页作废 —— 词不再撑开平台。）
        """
        tree = self.round_tree
        sel = list(tree.selection())
        if not sel:
            return False
        iid = sel[0]
        if iid.startswith("P|"):                      # 平台行：展开 → 收自己；收着 → 顶层，不归这条管
            if iid in self.round_open:
                self.round_open.discard(iid)
                self.refresh_rounds()
                self._round_focus_iid(iid)
                return True
            return False
        if iid.startswith("S|"):                      # 系列行：展开 → 收自己；收着 → 收上面的平台行（v86）
            if iid in self.round_open:
                self.round_open.discard(iid)
                self.refresh_rounds()
                self._round_focus_iid(iid)
                return True
            pid = self._round_platform_iid(iid)
            if pid and pid in self.round_open:
                self.round_open.discard(pid)
                self.refresh_rounds()
                self._round_focus_iid(pid)
                return True
            return False
        if iid.startswith("R|"):                      # 场次行：展开 → 收自己（v27）；收着 → 收上面的系列行（v86）
            if iid in self.round_open:
                self.round_open.discard(iid)
                self.refresh_rounds()
                self._round_focus_iid(iid)
                return True
            sid = self._round_series_iid(iid)
            if sid and sid in self.round_open:
                self.round_open.discard(sid)
                self.refresh_rounds()
                self._round_focus_iid(sid)
                return True
            return False
        row = self.row_by_iid(iid)                    # 题目行 → 收所在场次行（v27）
        if row:
            rid = "R|" + row["场次"]
            if rid in self.round_open:
                self.round_open.discard(rid)
                self.refresh_rounds()
                self._round_focus_iid(rid)
                return True
        return False

    def _round_platform_iid(self, rid):
        """v35 立、v86 起也对系列行用：结构行 iid（`S|…` / `R|…`）→ 它上面那条平台行的 iid（`P|…`）。

        清单是拍平排的（平台行 + 它的系列 / 场次行按序往下）—— 往上找最近一条 `P|` 行就是它；
        找不到（理论不该发生）→ None。
        """
        pid = None
        for x in self.round_tree.get_children():
            if x.startswith("P|"):
                pid = x
            elif x == rid:
                return pid
        return None

    def _round_series_iid(self, rid):
        """v86：场次行 iid（`R|…`）→ 它上面那条系列行的 iid（`S|…`）（Esc 逐级上退用）。

        同上：拍平序里往上找最近一条 `S|` 行；找不到（理论不该发生）→ None。
        """
        sid = None
        for x in self.round_tree.get_children():
            if x.startswith("S|"):
                sid = x
            elif x == rid:
                return sid
        return None

    def _on_round_esc(self, event=None):
        """v27 立：按场次视图行上 Esc = 收起展开的平台 / 场次（v35 起收着的场次行再逐级往上收）。

        v51：原来的「② 有词清词 → ③ 焦点送搜索框」随「搜索框只留总表页」作废 —— 统计页
        不再碰搜索词、也不往框里送焦点；没东西可收时 Esc 就到此为止。
        v43：预览栏开着时先收起预览（与总表 `_on_row_esc` 同口径：只关预览、一步一件事）。
        v45：全屏 md 开着时同理 —— Esc 收 md 回主表（唯一出口）。
        v50：预览要**露着**才算（藏起来的不算 —— 同 `_on_row_esc`）。"""
        if self.md_full:
            return self._exit_md_full()
        if self._prev_shown():
            self._hide_preview()
            return "break"
        self._round_esc_collapse()
        return "break"

    def _round_next_key(self, row):
        """按场次视图里这道题的**下一题**（同场、按题号序）→ (场次, 题号)；已是最后一题 → None。"""
        same = sorted([r for r in self.rows if r["场次"] == row["场次"]],
                      key=lambda r: (r["题号"], r["_i"]))
        for i, r in enumerate(same):
            if r["_i"] == row["_i"]:
                if i + 1 < len(same):
                    return (same[i + 1]["场次"], same[i + 1]["题号"])
                return None
        return None

    def _round_select_key(self, key):
        """在按场次视图里选中 (场次, 题号) 那一行（找不到就静默）。"""
        tree = getattr(self, "round_tree", None)
        if tree is None:
            return
        for iid in tree.get_children():
            r = self.row_by_iid(iid)
            if r and (r["场次"], r["题号"]) == key:
                tree.selection_set(iid)
                tree.focus(iid)
                tree.see(iid)
                break

    def refresh_know(self, keep_row=False, keep_name=None):
        """按当前行重画统计页（v17）：全量统计 + 父子折叠 + 排序（`self.know_desc`）+ 保选中。

        v27：本函数是「统计页重画」的**总入口** —— `know_mode == "round"` 时整段转给
        `refresh_rounds()`（按场次视图）；下面这些知识点视图的逻辑一个字没改。

        v17 追加（树）：按词典「父子关系表」把子知识点折到父下 —— 父行显示**子孙合计**，
        行首 `▸`（收着）/ `▾`（展开）；展开的行（父行下的子行 / 普通叶行）行首空一格缩进。
        展开状态存 `self.know_open`（父名集合，本窗口内记住；重画不丢）。

        keep_row=True（换排序 / 点列头，用户口径）→ 选中**钉在原行号**：原来第 x 行就还是
        第 x 行，只是行里的知识点换成了别的（跟总表 v4 的规矩一致 —— 别跟着知识点跑）；
        keep_name 指名（展开 / 收起后）→ 选中那个知识点；都没给（读表重绘）→ 按当前
        选中行的名字保选中，那个知识点没了就贴回第一行。
        """
        if self.know_mode == "round":        # v27：在按场次视图上 → 重画交给它
            self.refresh_rounds()
            return
        tree = self.know_tree
        keep_idx = None
        if keep_row:
            keep_idx = self._index_of(tree)       # 重建前先拿住原行号
        elif keep_name is None:
            sel = list(tree.selection())
            if sel:
                v = tree.item(sel[0], "values")
                keep_name = v[0].lstrip("▸▾ ") if v else None
        tops, subs = knowledge_tree(self.rows)
        tops = sort_knowledge(tops, desc=self.know_desc)
        # v51（用户口径「主表的搜索结果不会影响其他界面」）：统计页不再按搜索词过滤 ——
        # v17 的「统计页搜知识点名」随「搜索框只留总表」作废。
        for iid in tree.get_children():
            tree.delete(iid)
        shown = 0
        top_k = 0      # v33：顶层行的交替计数（父行 + 平铺知识点一起数、按出现顺序连续）

        # v97（多级）：第 1 层 = lvl1、第 2 层 = lvl2、第 3 层及更深 = lvl3；
        #   每层「浅 ↔ 深」在自己的父块内从浅档起交替（与 v33 的"每层各自计数、不串相位"同口径）。
        def _layer_tag(depth, j):
            base = {1: "lvl1", 2: "lvl2"}.get(depth, "lvl3")
            return base if j % 2 == 0 else base + "b"

        def _emit_children(parent_name, iid_prefix, depth):
            for j, (kid, kn, kid_has, _nk) in enumerate(subs.get(parent_name, [])):
                mark = ("▾ " if kid in self.know_open else "▸ ") if kid_has else ""
                tree.insert("", "end", iid="%s.%d" % (iid_prefix, j),
                            values=["    " * (depth - 1) + mark + kid, kn],
                            tags=[_layer_tag(depth, j)])
                if kid_has and kid in self.know_open:
                    _emit_children(kid, "%s.%d" % (iid_prefix, j), depth + 1)

        for k, (name, n, has_kids, nkids) in enumerate(tops):
            mark = ("▾ " if name in self.know_open else "▸ ") if has_kids else "  "
            # v33（用户口径「白色重了」）：顶层行（带箭头的父行 + 平铺知识点）走杏黄
            #   「浅 ↔ 深」整片交替（无白行）—— 父行不连片、平铺行同层同色；第一个 = lvl1。
            #   二 / 三层行走 lvl2 / lvl3「浅 ↔ 深」、在每个父块内从浅档起（块内行数一眼可数）。
            tags = ["lvl1" if top_k % 2 == 0 else "lvl1b"]
            top_k += 1
            tree.insert("", "end", iid="k%d" % k,
                        values=[mark + name, n], tags=tags)
            shown += 1
            if has_kids and name in self.know_open:
                _emit_children(name, "k%d" % k, 2)
        arrow = "▲" if self.know_desc else "▼"      # v74：▲ = 降序、▼ = 升序（用户拍板）
        tree.heading("次数", text="次数 " + arrow)
        n_total = len(knowledge_tree(self.rows)[0])     # 顶层数（v31：并进第一行）
        # v31：计数并进窗口第一行（页内那行小字连同快捷键提示一起删了）；v51：不再有「筛出 X /」
        self._sync_know_count("共 %d 个知识点" % n_total)
        iids = list(tree.get_children())
        if not iids:
            return
        if keep_idx is not None:                  # 钉行号：越界贴最后一行、空表不动（_select_index 管）
            self._select_index(tree, keep_idx)
            return
        pick = None
        if keep_name is not None:
            for iid in iids:
                if tree.item(iid, "values")[0].lstrip("▸▾ ") == keep_name:
                    pick = iid
                    break
        if pick is None:
            pick = iids[0]                    # 原来那行没了（知识点了消失）→ 贴回第一行
        tree.selection_set(pick)
        tree.focus(pick)
        tree.see(pick)

    def _know_sort_click(self):
        """统计页点「次数」列头：升 / 降切换（默认降序）。"""
        self.know_desc = not self.know_desc
        self.refresh_know(keep_row=True)
        self.know_tree.focus_set()

    def _know_sort_toggle(self):
        """统计页 Ctrl+方向键：知识点视图 = 反转次数升降序；v27 按场次视图 = 反转场次顺序。"""
        if self.know_mode == "round":
            self.round_desc = not self.round_desc
            self.refresh_rounds()
            self.round_tree.focus_set()
            return "break"
        self.know_desc = not self.know_desc
        self.refresh_know(keep_row=True)
        return "break"

    def _know_row_info(self, iid):
        """统计行 iid（`k<top>` / `k<top>.<j>[.…]`）→ (知识点名, 是不是顶层行, 这行有没有子)。

        `k<top>` = 顶层行（父或平铺叶）；带 `.` 的 = 某层展开出来的行。名字从单元格剥掉
        行首标注（`▸` / `▾` / 缩进）再取。
        v97（多级）："有没有子" = 该名字在树里带子（任意层，含子桶）—— 名字全局唯一，直接查子表。
        """
        if iid is None:
            return None, False, False
        v = self.know_tree.item(iid, "values")
        name = v[0].lstrip("▸▾ ") if v else None
        top = "." not in iid
        has_kids = False
        if name:
            _tops, subs = knowledge_tree(self.rows)
            has_kids = bool(subs.get(name))
            if has_kids and "." in iid:              # v97：自指行（桶里的同名成员，如 DP 桶的 `DP`）
                try:                                 #       = 叶行（展开它只会又是同一张子表）
                    pv = self.know_tree.item(iid.rsplit(".", 1)[0], "values")
                except tk.TclError:
                    pv = None
                if pv and pv[0].lstrip("▸▾ ") == name:
                    has_kids = False
        return name, top, has_kids

    def _on_know_enter(self, event=None):
        """统计页 Enter / 双击：**带子的行（任意层）** = 展开 / 收起；叶行 = 跳回总表搜该知识点。

        v97（多级）：展开 / 收起对任何"有子"的行都成立（以前只有顶层父行）。
        """
        sel = list(self.know_tree.selection())
        if not sel:
            return "break"
        iid = sel[0]
        name, top, has_kids = self._know_row_info(iid)
        if name is None:
            return "break"
        if has_kids:                              # 有子（任意层，含子桶）→ 展开 / 收起（不跳转）
            if name in self.know_open:
                self.know_open.discard(name)
            else:
                self.know_open.add(name)
            self.refresh_know(keep_name=name)
            return "break"
        return self._know_search(name, parent=self._know_parent_of(iid))

    def _know_parent_of(self, iid):
        """统计行 iid → 它挂在哪个父行下（顶层行 / 无父返回 None）。用来记住「从哪一行跳走的」。

        v97（多级）：直接沿词典的「子 → 父」反查**直接父名**（名字全局唯一）—— 不再取 iid 前缀。
        """
        if iid is None or "." not in iid:
            return None
        name, _t, _h = self._know_row_info(iid)
        if not name:
            return None
        groups = getattr(KD.load(), "groups", {}) or {}
        for parent, kids in groups.items():
            if name in kids:
                return parent
        return None

    def _know_search(self, name, parent=None):
        """统计页跳总表搜该知识点（叶行 / 子行 Enter 走这条）。

        v17：记住**来源行**（名字 + 父行），供 `_on_row_esc` 在「没改过搜索」时原路退回；
        程序性改 `var_search` 不触发 KeyRelease —— 手动 sync 一次，否则灰字提示会浮在
        新填的词上（用户报的 `知识点名` 挡住 `分布压缩 DP` 就是这处）。
        """
        self.var_search.set(name)
        self._reset_search_undo()           # v19：跳转整框换词 → 搜索撤销栈从这段新词重新开始
        self._know_search_origin = {"name": name, "parent": parent}
        self._select_page(0)                # 切回总表页（v59：当场落实搜索框）
        self._sync_search_placeholder()     # 切页 + 有词：换回总表文案并隐掉灰字（程序改 var 不触发 sync）
        self.refresh_view()
        self.tree.focus_set()
        return "break"

    def _on_know_jump(self, event=None):
        """统计页双击 / Enter 的旧入口 —— 转给 `_on_know_enter`（展开 or 搜索，看行有没有子）。"""
        return self._on_know_enter(event)

    def _know_jump_leaf(self, event=None):
        """（保留）直接搜选中行那个知识点、不管有没有子 —— 目前不绑键，留给落点扩展。"""
        sel = list(self.know_tree.selection())
        if not sel:
            return "break"
        name, _t, _h = self._know_row_info(sel[0])
        if name is None:
            return "break"
        return self._know_search(name, parent=self._know_parent_of(sel[0]))

    # ------------------------------------------------------------ 列宽铺满
    def _on_tree_configure(self, event=None, tree=None, weights=None):
        """窗口 / 表格变宽变窄时按权重等比重排列宽（知识点列最宽）。

        v88：v22 那条「排完列宽顺带重排列间竖线」已删（用户点名去掉表格每列之间的竖线）
        —— 列宽照旧伸缩，只是不再往表里摆竖线控件。
        """
        tree = tree or (event.widget if event else self.tree)
        total = tree.winfo_width() - 4
        if "tree" in show_items(tree):              # v25：#0 竖条窄列也吃宽度，从总宽里扣掉
            total -= int(tree.column("#0", "width"))
        if total >= 300:
            for h, frac in (weights or self._tree_weights).items():
                tree.column(h, width=max(40, int(total * frac)))
        self._sync_all_row_borders()                # v23：列宽变了 → 选中行边框跟着重摆
        self._sync_today_bar()                      # v25：列宽变了 → 今天竖条跟着重摆

    # ------------------------------------------------------------ 读盘 / 重绘
    def reload(self, note=None, clear_after=None):
        """从磁盘重读（别处改过也能看到），再重绘三个页面。

        v9：不再写「已读入 …」——note 不给（启动 / F5）就一个字不加，消息行保持原样；
        读表失败照样报（弹窗 + 消息行）。
        """
        keep = self.selected_key()
        try:
            self.rows = parse_rows(self.path)
        except SystemExit as e:
            self.rows = []
            note = "读表失败：%s" % e
            self._error("读表失败", str(e))
        except (OSError, ValueError) as e:
            self.rows = []
            note = "读表失败：%s" % e
            self._error("读表失败", str(e))
        annotate(self.rows, datetime.date.today())
        self.refresh_view(keep=keep)
        self.refresh_today()
        self.refresh_know()                  # v17：统计页全量，不受搜索 / 筛选影响，随读表一起重画
        if note is not None:
            self.set_msg(note, clear_after=clear_after)

    # ------------------------------------------------------------ 消息行（第一行最右端）
    def set_msg(self, text, clear_after=None):
        """消息行那行字（v9：在第一行最右端；原底部行）。clear_after（毫秒）给了就定时清空
        （v4：保存提示 3 秒后自动消失）。

        v40：主界面 / 设置界面**各有一条**消息行（整窗替换，另一条看不见）—— 两边一起写，
        哪个界面露着都能看见。
        """
        if self._msg_after is not None:
            try:
                self.root.after_cancel(self._msg_after)
            except tk.TclError:
                pass
            self._msg_after = None
        self.var_msg.set(text or "")
        var2 = getattr(self, "var_msg2", None)
        if var2 is not None:
            try:
                var2.set(text or "")
            except tk.TclError:
                pass
        if clear_after:
            self._msg_after = self.root.after(clear_after, self._clear_msg)

    def _clear_msg(self):
        """定时器到点：清空提示行（冒烟里直接调它，不用真等 3 秒）。"""
        self._msg_after = None
        self.var_msg.set("")
        var2 = getattr(self, "var_msg2", None)
        if var2 is not None:
            try:
                var2.set("")
            except tk.TclError:
                pass

    def visible_rows(self):
        """总表当前该显示的行 = **搜索命中**（v18：筛选并入搜索框，不再有下拉面板）。

        规则（v18，用户拍板）= **空格分隔、多字段任一命中**：
          查询按空白切词（半角 / 全角空格都算），**每个词都要命中**才显示；一个词只要在
          「场次 / 题号 / 题名 / 知识点 / 难度 / 状态」任一字段里出现（子串、忽略该字段内空白、
          忽略大小写）就算命中 —— **词序无所谓**。所以 `210 E 动态规划 1700 待重写` 等价于
          「场次含 210 ∧ 题号含 E ∧ 知识点含动态规划 ∧ 难度含 1700 ∧ 状态含待重写」。

        v19 两条细化（用户拍板）：
          ① **难度只认数字** —— 难度列就是纯数字（2026-10-06 起去掉 `CF ` 前缀）；查询里的
             `CF` 前缀仍被剥掉（`CF1800` ≡ `1800`，老习惯照用），剩下的纯数字串再走子串匹配。
             所以 `1800` 有结果、光搜 `CF` = 0 条。
          ② **单个字母只当题号** —— 词去掉空白后**恰好是一个 ASCII 字母**（如 `E` / `F`）→ 只
             在**题号**列里匹配，不去撞知识点 / 题名（搜 `F` 不会再筛出 DFS）。只认「单个」：
             `dp` 这类多字母词照旧搜全部字段；单个数字 / 单个汉字（`1` / `树`）也照旧全字段
             —— 用 `isascii()` 把汉字挡在外面（`"树".isalpha()` 是 True，只看 `isalpha` 会误伤）。
        沿用 v10 的「忽略空格」：`牛客周赛Round` ≡ `牛客周赛 Round`、`CF1900` ≡ `CF 1900`（前缀剥掉）。
        v27 追加：**光 `cf` 词被摘掉** —— `CF 1800` 等价 `1800`（整句只有 cf 仍 = 0 条）；
        难度可写**范围词**（`1500-1800` / `>=1700` / `<=1300` / `>n` / `<n`，见 `diff_range_hit`）。
        """
        raw = self.var_search.get().split()
        if not raw:
            return sort_rows(self.rows, self.sort_col, self.sort_desc)
        words = strip_cf_words(raw)          # v27：光 cf 词摘掉；全摘光 → 下面按 0 条
        if not words:
            return []
        keep = []
        for r in self.rows:
            if all(self._word_hits_row(w, r) for w in words):
                keep.append(r)
        return sort_rows(keep, self.sort_col, self.sort_desc)

    @staticmethod
    def _word_hits_row(word, row):
        """一个搜索词命中某一行吗？—— v19 的匹配内核（`visible_rows` 逐行逐词调用）。

        v27 追加：剥掉 `cf` 前缀后若是**范围词**（`1500-1800` / `>=1700` / `<=1300` / `>n` / `<n`）
        → 走 `diff_range_hit`（只在难度列生效）；不是范围词才回到老的多字段子串口径。
        光 `cf` 词到不了这里（`visible_rows` 已摘掉）。
        """
        w = re.sub(r"\s+", "", word).lower()
        if not w:
            return True                              # 空白词不管（`.split()` 后其实不会出现）
        if len(w) == 1 and w.isascii() and w.isalpha():   # ② 恰一个 ASCII 字母 → 只认题号列
            return w in re.sub(r"\s+", "", row.get("题号", "")).lower()
        # ① 「cf」前缀在匹配前剥掉（v19 立）：`CF1800` → `1800`；难度列里的前缀一并剥。
        #   2026-10-06 起难度列数据已是纯数字，这条现在主要兼容老写法。剥完是空串的词
        #   （光搜 `CF`）无处可匹配 → 这一列不命中。
        w = w.replace("cf", "")
        if w:
            hit = diff_range_hit(w, row)             # v27：范围词只在难度列生效
            if hit is not None:
                return hit
        fields = [re.sub(r"\s+", "", row.get(f, "")).lower() for f in SEARCH_FIELDS]
        diff_idx = SEARCH_FIELDS.index("难度")
        fields[diff_idx] = fields[diff_idx].replace("cf", "")
        if not w:
            return False
        return any(w in f for f in fields)

    def _head_text(self, col):
        if col == self.sort_col:
            return col + (" ▲" if self.sort_desc else " ▼")   # v74：▲ = 降序、▼ = 升序（用户拍板）
        return col

    def _on_search_typed(self, event=None):
        """v17 立、v51 收窄：搜索框敲字 → 重画**总表**（`refresh_view`）。

        v17 当时是「按页分派」（统计页 = 筛知识点名）；v51 起搜索只属于总表 —— 统计页不再
        按词过滤，框在别的页也不可见（`_apply_search_visible`）。搜索词切页保留、只作用于总表。

        v19：① **不再在这里重判原路退回资格** —— 原路退回（Esc）的资格改成**判的时候现算**
           （`_return_to_know_row` → `_origin_valid()`）。旧写法边打字边判，打到「二分查找 」
           （还差个「前缀和」）那一瞬搜索框不含原名，origin 就被永久清掉，后面补全也回不去。
        ② 顺手把这次编辑**按停顿分段**推进搜索撤销栈（`_search_note_edit`），好让 Ctrl+Z 能连撤。
        """
        self._search_note_edit()
        self.refresh_view()      # v51：搜索只作用于总表（统计页分支随「按页切语义」作废）

    # ------------------------------------------------------------ v19：搜索框撤销（v20：按词分段 + 复原）
    def _reset_search_undo(self):
        """v19：清空搜索撤销栈、并把**当前框里的内容**记成新的起点 —— **跳转 / 清空这类
        程序性整框改写**之后调用。之后 Ctrl+Z 最多退到这个起点（退不回跳转前的老词）。
        v20：复原栈一并清掉（换了整框内容，旧的重做记录对不上现在这串字）。"""
        self._search_undo_stack = []
        self._search_redo_stack = []
        self._search_baseline = self.var_search.get()

    @staticmethod
    def _search_seg_split(text):
        """把搜索框内容切成「词」—— 与搜索口径一致：空白分隔，连续非空白 = 一个词。"""
        return text.split()

    @classmethod
    def _search_same_seg(cls, prev, cur):
        """v20：两次输入算不算**同一段**（同一段 = 叠在一起、Ctrl+Z 一次退掉整段）。

        分段口径由用户拍板 = **按词（空格）分段**：一个词 = 一个最小撤回点。
        规则（只看词结构，不看时间）：
          * 词数变了（多打出一个词 / 整个词被删掉）→ 新段；
          * 词数没变、但**最后一个词之前**的部分动了（中间改字）→ 新段；
          * 词数没变、动的只是**最后一个词**（正在敲的这个词）→ 仍算同段。
        于是「吃饭 睡觉」= 两段（先退「睡觉」、再退「吃饭」）；连着敲的同一个词 = 一段。
        """
        pw, cw = cls._search_seg_split(prev), cls._search_seg_split(cur)
        if len(pw) != len(cw):
            return False
        return cw[:-1] == pw[:-1]

    def _search_note_edit(self):
        """把搜索框**当前内容**推进搜索撤销栈（按词合并）。

        只在**打字时**（KeyRelease → `_on_search_typed`）调用；程序性改 `var_search`（跳转 / 清空）
        不走这里。Ctrl+Z / Ctrl+Y 还原时用 `_suppress` 压住，免得把还原动作本身又记一段。
        v20：① 分段改成 `_search_same_seg` 的**按词分段**（原来是按停顿时间）；
             ② 手打新内容 = 新分支，**把复原栈清空**（老的重做记录作废）—— 与文本编辑器一致。
        """
        if self._search_undo_suppress:
            return
        cur = self.var_search.get()
        st = self._search_undo_stack
        before = st[-1]["after"] if st else self._search_baseline
        self._search_redo_stack = []                 # 新编辑 → 复原栈作废
        if st and self._search_same_seg(st[-1]["after"], cur):
            st[-1]["after"] = cur                    # 还在敲同一个词 → 并进当前这段
        else:
            st.append({"before": before, "after": cur})
            if len(st) > SEARCH_UNDO_MAX:
                del st[0]

    def _search_set_text(self, text):
        """程序性改搜索框内容：压住撤销记录、同步灰字提示、按当前页刷新、焦点回搜索框。"""
        self._search_undo_suppress = True
        try:
            self.var_search.set(text)
        finally:
            self._search_undo_suppress = False
        for sync in self._ph_syncs:                  # 程序改词不触发 KeyRelease → 手动同步灰字
            sync()
        if self.nb.index(self.nb.select()) == 2:
            self.refresh_know()
        else:
            self.refresh_view()
        self.ent_search.focus_set()

    def _search_undo(self, event=None):
        """v19（v20 改按词分段）：搜索框里的 Ctrl+Z —— 退掉**当前这个词**（连按一个词一个词往回退）。

        跟状态撤销（`_undo`）分派：焦点在搜索框 → 退回搜索框内容；焦点在表格 / 清单 → 退回状态。
        每退掉一段，把那段**压进复原栈**（供 Ctrl+Y 放回来）。栈空 / 没有变化 → 只提示、框里不动。
        """
        if self._busy():
            return None
        st = self._search_undo_stack
        cur = self.var_search.get()
        # 退的目标 = **被弹掉那段的起点**（`before`），不能只看弹完后的新栈顶：
        #   ① 只有一段时弹完栈就空了 —— 起点可能是空框（第一次打字）、也可能是跳转带来的词
        #      （基线非空），所以一律取那段自己的 `before`，别写死退到空。
        #   ② 框里内容被手改过、跟栈顶对不上（如右键粘贴不触发 KeyRelease）→ 先退到栈顶那段的结果。
        if st and st[-1]["after"] == cur:
            seg = st.pop()
            prev = seg["before"]
            self._search_redo_stack.append(seg)       # v20：退掉的这段留着给 Ctrl+Y
        elif st:
            prev = st[-1]["after"]
        elif cur != self._search_baseline:
            prev = self._search_baseline
        else:
            self.set_msg("没有可撤销的输入", clear_after=TOAST_MS)
            return "break"
        self._search_set_text(prev)
        return "break"

    def _search_redo(self, event=None):
        """v20：搜索框里的 Ctrl+Y —— 把刚被 Ctrl+Z 退掉的那个词**放回来**（撤销的反向）。

        复原栈空 → 只提示「没有可复原的输入」、框里不动。
        """
        if self._busy():
            return None
        rs = self._search_redo_stack
        if not rs:
            self.set_msg("没有可复原的输入", clear_after=TOAST_MS)
            return "break"
        seg = rs.pop()
        self._search_undo_stack.append(seg)           # 放回来 → 再回到撤销栈顶（还能再 Ctrl+Z）
        self._search_set_text(seg["after"])
        return "break"

    def _on_ctrl_z(self, event=None):
        """v19：Ctrl+Z 按焦点分派 —— 搜索框里退搜索输入；其余处退状态改动。

        v40：设置界面里不响应（退的是主界面的表格 / 搜索框，不外溢到设置界面）。
        """
        if self._busy() or self._in_settings():
            return None
        if self._focus_widget() is self.ent_search:
            return self._search_undo(event)
        return self._undo(event)

    def _on_ctrl_y(self, event=None):
        """v20：Ctrl+Y 按焦点分派 —— 搜索框里复原搜索输入；其余处复原状态改动（真写盘 + 备份）。

        v40：设置界面里不响应（同 Ctrl+Z）。
        """
        if self._busy() or self._in_settings():
            return None
        if self._focus_widget() is self.ent_search:
            return self._search_redo(event)
        return self._redo(event)

    def _origin_valid(self):
        """v18：原路退回资格 —— 搜索框里是否**仍有那个知识点名**（一个完整的词）。

        「词」的口径跟搜索一致：搜索框按空白切词后，把相邻词两两拼起来（`分布压缩` + `DP`
        → `分布压缩DP`，覆盖名字里自带空格的情况）、再忽略大小写比对 —— 名字**作为独立词**
        还在（后面可再追加 `E 1300` 等字段）→ True；被改动（`DPX`）或删掉 → False。
        """
        origin = self._know_search_origin
        if not origin:
            return False
        target = re.sub(r"\s+", "", origin["name"]).lower()
        words = [re.sub(r"\s+", "", w).lower() for w in self.var_search.get().split()]
        if not target:
            return False
        if any(w == target for w in words):            # 名字正好是一个词（`DP` / `并查集`）
            return True
        for i in range(len(words) - 1):                # 名字拆成两个相邻词（`分布压缩 DP`）
            if words[i] + words[i + 1] == target:
                return True
        return False

    def refresh_view(self, keep=None, keep_index=None):
        """重画总表。

        - keep_index 给了（v4：点表头 / S / R 换排序）→ 选中**原行号**：原来第 x 行就选第 x 行
          （行里的题换成别的），越界贴最后一行。
        - 否则（搜索 / 换表 / 改状态）→ **跟题**：按「场次 + 题号」保住选中，
          该题被搜掉时兜底贴回第一行；一行都没有就不选（v9：不再插占位行）。
        """
        if keep_index is None:
            keep = keep or self.selected_key()
        tree = self.tree
        for iid in tree.get_children():
            tree.delete(iid)
        rows = self.visible_rows()
        today = datetime.date.today().isoformat()
        for k, r in enumerate(rows):
            # v23：行 tag 改由 `_row_tags` 按「配色」决定（Radix = 整行铺状态色 / 默认 = 斑马纹 + 今天淡绿底）。
            # v22.1 的教训在这里照样成立：**同一属性只让一个 tag 说话** —— 今天那行不再挂斑马纹。
            tags = self._row_tags(r, k, r["日期"] == today)
            # v41：单元格显示值走 `short_cell`（只有场次列换成「比赛名 + 回合号」的短名）
            tree.insert("", "end", iid=str(r["_i"]),
                        values=[short_cell(h, r[h]) for h in HEADER], tags=tags)
        for h in HEADER:
            tree.heading(h, text=self._head_text(h))
        self.update_count()
        self.update_hits(len(rows))         # v13：筛选的「筛出 N 题」（v14：面板底部 / 收起时第一行右端）
        if keep_index is not None:
            self._select_index(tree, keep_index)
        elif keep:
            self.select_key(keep, focus=False)
        first = tree.get_children()
        if not tree.selection() and first:          # 选中的题被搜掉 / 换表 → 贴回第一行
            tree.selection_set(first[0])
            tree.focus(first[0])
            tree.see(first[0])
        self._sync_all_row_borders()                # v23：行重建过 → 选中行边框重摆
        self._sync_today_bar()                      # v25：行重建过 → 今天竖条重挂
        self._cancel_pending_repaint()              # v60：重建已是全新画面 → 撤掉排队中的延迟重摆
        self._mirror_split(rows)                    # v66：分屏页那张表跟着重画（同一份行 / tag / 选中）

    def _mirror_split(self, rows):
        """v66：把总表刚画好的那一份照搬进**分屏页那张表**（`tree_split`）。

        跟 `refresh_view` 同一个口径：行 / tag / 表头 一个不差。
        **分屏页收着（压在整张表页底下）时不立刻画** —— 只记脏，等开预览那一拍再补
        （`_prev_show_view` ①）：那时它还在底下，补画 / 重排全看不见；平时也不白花这份钱
        （两页常驻 = 它一直 mapped，随手重画是真要花 ~40ms 的）。
        """
        t = getattr(self, "tree_split", None)
        if t is None:
            return
        if not self._split_shown():
            self._split_dirty = True
            return
        self._fill_split(rows)

    def _fill_split(self, rows):
        """v66：真正把行 / tag / 表头照搬进分屏页那张表（+ 选中与滚动跟主表对齐）。

        调用点两处：`_mirror_split`（露着 → 当场画）；`_prev_show_view`（收着但脏 → 开预览前
        补画）。**注意后者**：那一拍分屏页还没 `lift`（`_split_shown()` 还是 False）—— 补画
        必须走这个**不带闸**的本体，回头调 `_mirror_split` 会被判"收着"又记回脏、白跑一趟。
        """
        t = getattr(self, "tree_split", None)
        if t is None:
            return
        today = datetime.date.today().isoformat()
        for iid in t.get_children():
            t.delete(iid)
        for k, r in enumerate(rows):
            t.insert("", "end", iid=str(r["_i"]),
                     values=[short_cell(h, r[h]) for h in HEADER],
                     tags=self._row_tags(r, k, r["日期"] == today))
        for h in HEADER:
            t.heading(h, text=self._head_text(h))
        sel = self.tree.selection()
        if sel:
            t.selection_set(sel[0])
            t.focus(sel[0])
            t.see(sel[0])
        try:
            t.yview_moveto(self.tree.yview()[0])
        except tk.TclError:
            pass
        self._sync_today_bar(t)                  # 行重建过 → 分屏页自己的「今天竖条」也重挂

    def _mirror_split_sel(self, tree):
        """v66：总表 ⇄ 分屏页那张表，**选中行互相跟**（在哪张表上点 / 按方向键，另一张跟着选）。

        `_sel_mirror` 是防乒乓的重入闸（`selection_set` 会再发一发 `<<TreeviewSelect>>`）。
        """
        other = self.tree_split if tree is self.tree else self.tree
        if other is None or getattr(self, "_sel_mirror", False):
            return
        sel = tree.selection()
        if not sel:
            return
        try:
            if other.selection() == sel:
                return
        except tk.TclError:
            return
        self._sel_mirror = True
        try:
            other.selection_set(sel[0])
            other.focus(sel[0])
            other.see(sel[0])
        except tk.TclError:
            pass
        finally:
            self._sel_mirror = False

    def update_count(self):
        """计数行（v10 口径）：`共 X 题 ｜ 未做 Y ｜ …（6 个状态）｜ N天内做对：M 题`。

        M = 日期在最近 N 天内且状态 ∈ {独立AC, 复现AC}（不含「巩固」）；v10 起这行固定
        按全量算 —— 原来行首那段 `搜出 M 题 ｜` 已删，搜不搜都是同一行字。
        """
        c = state_counts(self.rows)
        s = "共 %d 题" % len(self.rows)
        s += " ｜ " + " ｜ ".join("%s %d" % (k, c[k]) for k in STATES)
        s += " ｜ %d天内做对：%d 题" % (SR.RECENT_DAYS, done_count(self.rows))
        self.var_count.set(s)

    def refresh_today(self):
        """重画看板：四类合并成一个清单（v29；v34 起标题行与题目行同一条斑马序列）。

        行序 = 逐类（待重写 → 待补题 → D+N 复习 → D+N 抽检）：该类有题 → 先插一条**类标题行**
        （`待重写 · 3`，iid = `seg<i>`，只在有题时才出现），再跟该类题目行（段内次序照
        `segment_rows` 原判据）；四类全空 → 清单完全空白（连标题行都没有）。
        **v34**：类标题行不再有专属淡蓝底、改挂 odd / even；**v34.1（用户口径「这四个跟题目是
        不同的结构、分开算的」）**：标题行与题目行**分开计数** —— 标题行自己一条序列（`k_seg`：
        4 条之间交替：白 → 浅灰 → 白 → 浅灰），题目行自己一条序列（`k_all`：跨类连续交替，
        跟 v33 前一致）；两层之间可能出现同色相邻（如标题①白 + 题 1 白），属预期。
        重建后：原来选中的行还在（且不是标题行）就贴回去，否则选**第一道题目行** ——
        v29：选中不落标题行；一道题都没有就留空，不报错（v9 口径）。
        """
        tree = self.today_tree
        sel = list(tree.selection())
        old_iid = sel[0] if sel else (tree.focus() or None)
        today = datetime.date.today().isoformat()
        for iid in tree.get_children():
            tree.delete(iid)
        first_pick, k_all, k_seg = None, 0, 0
        for i, (cap, _) in enumerate(segment_specs()):
            rows = segment_rows(self.rows, i)
            if not rows:
                continue                    # v29：没题的类连标题行都不出现
            # v34.1：标题行与题目行**分开计数**（两层结构）—— 标题行走自己的 k_seg（4 条之间交替）
            tree.insert("", "end", iid=SEG_PREFIX + str(i),
                        values=["%s · %d" % (cap, len(rows))] + [""] * (len(TODAY_COLS) - 1),
                        tags=["even" if k_seg % 2 else "odd"])
            k_seg += 1
            for r in rows:
                # v23：看板清单的行 tag 也走主题（Radix = 整行铺状态色），口径与总表一字不差
                tree.insert("", "end", iid=str(r["_i"]),
                            values=[short_cell(h, r[h]) for h in TODAY_COLS],   # v41：场次列走短名
                            tags=self._row_tags(r, k_all, r["日期"] == today))
                if first_pick is None:
                    first_pick = str(r["_i"])
                k_all += 1
        pick = None
        if old_iid and not old_iid.startswith(SEG_PREFIX) and old_iid in tree.get_children():
            pick = old_iid
        elif first_pick is not None:
            pick = first_pick
        if pick is not None:
            tree.selection_set(pick)
            tree.focus(pick)
            tree.see(pick)
        self._sync_all_row_borders()                # v23：清单重建 → 选中行边框重摆

    # ------------------------------------------------------------ 选中 / 键盘
    def row_by_iid(self, iid):
        if not iid:
            return None
        try:
            return self.rows[int(iid)]
        except (ValueError, IndexError):
            return None

    def tree_row(self, tree):
        sel = list(tree.selection())
        if not sel:
            cur = tree.focus()
            sel = [cur] if cur else []
        return self.row_by_iid(sel[0]) if sel else None

    def _active_tree(self):
        """当前页的那张表：0 → 总表、1 → 看板、2 → 统计（v22 起与 _current_page 共用页判定）。

        v27：统计页按 `know_mode` 分派 —— 知识点视图 = `know_tree`、按场次视图 = `round_tree`
        （后者的题目行是真题目，1~6 / 浮层 / 打开原题这些操作在它上面成立）。
        """
        page = self._current_page()
        if page == 0 and self._split_shown():
            return self.tree_split       # v66：分屏页露着 → 当前页那张表就是分屏页那张
        if page == 1:
            return self.today_tree
        if page == 2:
            if self.know_mode == "round" and getattr(self, "round_tree", None) is not None:
                return self.round_tree
            return self.know_tree          # v17：统计页的知识点清单（行 iid 不是题目下标，改状态那类操作自然落空）
        return self.tree

    def _current_page(self):
        """当前选中的页下标（0 总表 / 1 今天要做的 / 2 知识点统计）。v22：关窗存配置用。"""
        try:
            return self.nb.index(self.nb.select())
        except tk.TclError:
            return 0                        # nb 正在销毁（关窗竞态）→ 当总表

    def selected_key(self):
        r = self.tree_row(self._active_tree())
        return (r["场次"], r["题号"]) if r else None

    def select_key(self, key, focus=True):
        # 各页都选上：在看板 / 统计页改完也能接着改；v27 起按场次视图（round_tree）一并认
        trees = [self.tree, self.today_tree]
        if getattr(self, "tree_split", None) is not None:
            trees.append(self.tree_split)       # v66：分屏页那张表也一起选上
        if getattr(self, "round_tree", None) is not None:
            trees.append(self.round_tree)
        for tree in trees:
            for iid in tree.get_children():
                r = self.row_by_iid(iid)
                if r and (r["场次"], r["题号"]) == key:
                    tree.selection_set(iid)
                    tree.focus(iid)
                    tree.see(iid)
                    break
        if focus:
            self._active_tree().focus_set()

    def _index_of(self, tree):
        """当前选中行在 tree 可见列表里的行号（0 起）；没选中 / 列表空 → None。"""
        iids = list(tree.get_children())
        sel = list(tree.selection())
        iid = sel[0] if sel else tree.focus()
        return iids.index(iid) if iid in iids else None

    def _select_index(self, tree, idx, skip_seg=False):
        """选中 tree 里第 idx 行（0 起）：v4 的「换排序钉行号」「改完状态下移一行」都走这条。
        越界贴最后一行；列表空就不动（v9：空表不许报错）。
        v29：skip_seg=True（看板合并清单专用）时**不落类标题行** —— 落点若是 `seg` 开头的
        标题行，先往下找下一道题目行；到底了就往回找最近的一道；只有标题行（理论上不会有）
        就保持原样，不报错。"""
        iids = list(tree.get_children())
        if idx is None or not iids:
            return False
        i = max(0, min(int(idx), len(iids) - 1))
        if skip_seg and iids[i].startswith(SEG_PREFIX):
            nxt = next((j for j in range(i + 1, len(iids))
                        if not iids[j].startswith(SEG_PREFIX)), None)
            if nxt is None:
                nxt = next((j for j in range(i - 1, -1, -1)
                            if not iids[j].startswith(SEG_PREFIX)), None)
            if nxt is not None:
                i = nxt
        iid = iids[i]
        tree.selection_set(iid)
        tree.focus(iid)
        tree.see(iid)
        return True

    def _move_sel(self, tree, kind):
        iids = list(tree.get_children())
        if not iids:                                # v9：空表上 ↑↓ / 翻页不报错
            return "break"
        sel = list(tree.selection())
        idx = iids.index(sel[0]) if sel and sel[0] in iids else 0
        if kind == "pgup":
            idx = max(0, idx - 12)
        elif kind == "pgdn":
            idx = min(len(iids) - 1, idx + 12)
        tree.selection_set(iids[idx])
        tree.focus(iids[idx])
        tree.see(iids[idx])
        tree.focus_set()
        return "break"

    def _on_wasd(self, event):
        """v47：W / S / A / D = ↑ / ↓ / ← / → —— 把按键**转发成同控件的方向键事件**。

        为什么转发而不是照抄一遍动作：表格里 ↑↓ 是 ttk.Treeview 的**内建行为**（class binding）、
        ← / → 挂在 root（`_nav_arrow`）—— 合成真方向键事件能让这些**原样复刻**：选中行边框重画
        （`<<TreeviewSelect>>`）、连按节流、看板跳标题行、统计页的换页守卫，一条都不用重写。
        带 Ctrl / Alt 的组合不劫持（留给注册表那套）；Shift+W 的 keysym 是大写 "W"，天然不命中。
        挂点见 `_bind_wasd_all`（四棵树 + 分屏页那张表 + v80 的设置页控件）与 `open_status_popup`
        （浮层的 W / S）；**搜索框不挂**；题解 md 预览里那半边走 `tb_preview` 的 JS（v85）。
        v80：改键捕获中 W/A/S/D 是**新键候选** —— 焦点在快捷键表时把原始事件交给捕获通道
        （转发成方向键会变成「方向键不能拿」的误提示）；别的控件上吞掉不动。
        """
        if event.state & (0x0004 | 0x20000):        # Control / Alt 按下 → 不劫持
            return None
        arrow = WASD_ARROWS.get(event.keysym)
        if not arrow:
            return None
        if self.key_capture:                        # v80：捕获中 —— 别转发成方向键
            if event.widget is self.key_tv:
                return self._key_dialog_key(event)
            return "break"
        event.widget.event_generate("<%s>" % arrow)
        return "break"

    def _bind_wasd_all(self):
        """v47：把 WASD 挂上四棵树（浮层的 W / S 在 `open_status_popup` 里单挂）。

        调用点是 `_apply_keys` 的**开头**（撤绑之后、注册表绑定之前）—— 它是**基础层**：
        用户把某个操作设成 W / A / S / D 时注册表后挂、以用户为准；改回去时这里重挂、
        WASD 自动复活（否则 `_apply_keys` 撤旧键那一步会把 WASD 一起撤没）。

        v80（用户点名「WASD 也当方向键」）：**设置页也挂** —— 左列表 / 快捷键表 / 主题块
        全部单选钮（v47 那会儿「不挂」的口径作废）。
        v85（用户点名「WASD 跟上下左右分别对应，接上所有界面」）：**分屏页那张表（`tree_split`）
        补挂** —— 它一直是焦点环里的一员，却漏在 v47 的名单外（漏网之鱼）。
        """
        targets = [self.tree, getattr(self, "tree_split", None),   # v85：分屏页那张表补挂
                   self.today_tree, self.know_tree,
                   getattr(self, "round_tree", None),
                   self.set_left, self.key_tv,         # v80：设置页两件
                   getattr(self, "help_tx", None)]     # v87：一览块（W / S = 滚动；A / D = ← / → 同义，含「回左列表」）
        for _rbs in getattr(self, "_set_groups", {}).values():
            targets.extend(_rbs)                       # v80：主题块全部单选钮
        for t in targets:
            if t is None:
                continue
            for k in WASD_ARROWS:
                try:
                    t.bind("<Key-%s>" % k, self._on_wasd)
                except tk.TclError:
                    continue

    def _jump_row(self, idx, event=None):
        """v22：Ctrl+Home / Ctrl+End —— 跳到**当前页清单**的第一行 / 最后一行。

        idx = 0 跳首行、-1 跳末行（`_select_index` 越界会自己贴边，负方向也已归一）。
        让位规则同 ← / →：搜索框里归 Entry（Home / End 挪光标）、浮层 / 一览开着不响应；
        v40 起设置界面里也不响应（跳的是主界面的表格）。
        """
        if self._busy() or self._in_text_widget() or self._in_settings():
            return None
        tree = self._active_tree()
        iids = list(tree.get_children())
        if not iids:                            # 空清单：不报错、不抢焦点
            return "break"
        # v29：看板页清单带类标题行 —— 跳首行时跳过它、落第一道题目行（末行恒是题目行，无妨）
        self._select_index(tree, 0 if idx == 0 else len(iids) - 1,
                           skip_seg=(tree is self.today_tree))
        tree.focus_set()
        return "break"

    def _nav_arrow(self, delta, event=None):
        """v6：← / → 在一整条横排上左右走（替代 v5 的两页来回绕）。

        横排 3 格（v29：看板四类合并后从 6 格收成 3 格）：[总表] [统计] [今天要做的]，
        两头绕回：总表按 → 进统计、按 ← 进看板；统计按 ← 回总表、按 → 进看板；
        看板按 ← 回统计、按 → 回总表。进看板时 refresh_today 把清单（类标题行 + 题目行）
        重画一遍、选中落第一道题目行、焦点落到清单上。
        v55：**设置页已独立出这条环**（不再占主表那一格）—— 在设置里 ← / → 一律不响应
        （页内分工：左列表 `→` 进面板、面板里 `←` 回列表，见 `_make_settings` 的绑定）。
        v62：**全屏 md 也独立出这条环**（跟设置页同款）—— 在它里面 ← / → 一律不响应
        （md 里的 ← / → 被 JS 拦下回传后同样不换界面，见 `_on_preview_status('nav')`；
        Esc / md 里回车才是出口）。
        v83：全屏 md 里那一对**改作「上一题 / 下一题」**（v96 起 = `_md_row_nav`，两档通用）——
        这一条（换界面）在它里面照旧不许走。

        防冲突（v5 的规则原样保留；v18 起让位对象 = 搜索框）：
          * 焦点在搜索框里时**不抢** —— return None（不 break），那儿的 ← / → 归 Entry 自己挪光标；
          * 状态浮层 / `?` 一览打开时不响应（_busy）；
          * 表格 / 清单里 ← / → 没有别的用途，直接绑；
          * v55：设置界面里**一律不响应**（设置页独立、不在环上；页内 ← / → 分工见
            `_set_focus_panel` / `_set_to_menu` / `_set_theme_side`）；
          * v62：全屏 md 里**一律不响应**（独立界面、不在环上；v83 起这一对键在那儿
            改作「上一题 / 下一题」，见 `_md_row_nav` —— 换界面这条路照旧不通）。
        """
        if self._busy() or self._in_text_widget():
            return None
        if self._in_settings():
            return None          # v55：设置页独立、不在环上 —— ← / → 一律归页内分工，不换界面
        if self.md_full:
            return None          # v62：全屏 md = 独立界面（跟设置页同款）—— ← / → 不换界面
        cell = (self._cell_of_current_page() + delta) % 3     # 3 格两头绕回（v29）
        self._goto_cell(cell)
        return "break"

    def _cell_of_current_page(self):
        """当前页在 3 格横排的第几格（v29）：总表→0、统计→1、看板→2（段没了）。

        v45：全屏 md **占主表那一格**（`_md_full_shown`）—— 在它上面按 ← / → 走一步
        落到看板 / 统计，走回来 md 原样再现（状态不丢）。**v62 起作废** —— 全屏 md 独立成
        一层（不在环上，`← / →` 在它就进不来），这里按 `nb` 当前页照算。
        v55：**设置页不再占格**（独立成一层、不在环上）—— 在设置里时按 `nb` 当前页照算。
        """
        page = self.nb.index(self.nb.select())
        if page == 0:
            return 0
        if page == 2:
            return 1
        return 2

    def _select_page(self, page):
        """v59：切页**并把第一行当场落实**（搜索框 / 统计计数），不等 `<<NotebookTabChanged>>`。

        真根因（2026-10-07 探针实测）：`nb.select()` 发的 `<<NotebookTabChanged>>` 是**排队**的
        虚拟事件，要等下一次事件处理才跑；而切页重绘先发生 —— 抓 Expose 时间轴：head 在
        ~36ms 处已按「看板页」的样子重绘过一次（搜索框还撤着），搜索框的 pack 要等重绘之后
        （~55ms 处）才落地、再补一次重绘。用户看到的就是「切回主表后搜索框姗姗来迟」；
        顺带整棵树被多画 1~2 次（同一趟单切实测 50~87ms 不等）。
        修法：`nb.select(page)` 之后**显式**把第一行的两个可见性刷新跑一遍（`_apply_know_count`
        + `_apply_search_visible`，两条都幂等）——pack 赶在第一次重绘之前完成，一拍画好；
        等异步那一趟 `_on_tab_changed` 跑到时已是 no-op（它保留原样，兜底别的 `nb.select` 调用点）。
        实测：搜索框随第一次 head 重绘一起出现、整树重绘收敛到 1 次，同趟耗时稳定在 ~50ms。
        """
        self.nb.select(page)
        self._apply_know_count()
        self._apply_search_visible()
        if page == 0:
            self._flush_first_row()      # v64：先把第一行画上屏，再让表格重绘

    def _flush_first_row(self):
        """v64：切回总表这一拍 —— **先把第一行（含搜索框）画上屏，再让表格重绘**。

        用户口径（2026-10-07）：「先显示搜索框后重绘呢」。抓屏实测（真窗口 2540×1330，
        每 ~20ms 抓一次搜索框 / 表格两块像素）：不这么做时**表格 16~21ms 就先上屏、
        搜索框要 ~119ms 才出现**（它是最后一个画的）；用户的抱怨完全成立。

        手法（探针里先验证，实测搜索框 119ms → 23~39ms）：把树**临时撤下**（省掉它
        30ms 级的布局 idle，`update_idletasks` 就只做第一行）→ 落实布局 → 给
        `ent_search` / `lbl_search` 发 `<Expose>` 把它们画掉 → 把树挂回去（树的重绘
        照常在下一拍）。代价：切页同步链 5ms → ~14ms（按住连续翻页几乎无感）；
        表格上屏时刻与总耗时都不变。
        """
        tree = getattr(self, "tree", None)
        if tree is None:
            return
        try:
            info = tree.pack_info()
            saved = {k: info[k] for k in ("side", "fill", "expand") if k in info}
        except tk.TclError:
            return
        try:
            tree.pack_forget()
            self.root.update_idletasks()
            try:
                self.ent_search.event_generate("<Expose>")
                self.lbl_search.event_generate("<Expose>")
            except tk.TclError:
                pass
            self.root.update_idletasks()
        except tk.TclError:
            pass
        finally:
            try:
                tree.pack(**saved)
            except tk.TclError:
                try:
                    tree.pack(fill="both", expand=True)
                except tk.TclError:
                    pass

    def _goto_cell(self, cell):
        """切到 3 格横排的第 cell 格（v29）：0 = 总表、1 = 统计、2 = 今天要做的。

        三格都只切页 + 重画（搜索框两种语义、切页要把当前词应用到目标页）+ 灰字口径 +
        焦点落当前页清单 —— v29 起没有「段」，进看板不再有别的手续。
        v50：侧栏预览跟着**"打开它的那一格"**（总表 / 统计 / 看板里回车都能开）——
        末尾 `_sync_preview(cell)` 收尾：走开只是看不见、走回来原样再现。
        v55：设置页独立后**不再走这里**（`exit_settings` 直接调它回来源格）。
        v62：全屏 md 独立后**「跟着格走」那一层也删掉**（`_sync_md_full` 已删）—— 它开着时
        `← / →` 在 `_nav_arrow` / `_on_preview_status('nav')` 两处就被拦下，根本走不到这里。
        """
        if cell == 0:
            self._select_page(0)
            self.refresh_view()
            self._sync_search_placeholder()
            self._active_tree().focus_set()
        elif cell == 1:
            self._select_page(2)                # 统计页
            self.refresh_know()
            self._sync_search_placeholder()
            self._active_tree().focus_set()
        else:
            self._select_page(1)                # 今天要做的（v29：四类合并成一个清单）
            self.refresh_today()
            self._sync_search_placeholder()
            self._active_tree().focus_set()
        self._sync_preview(cell)            # v50：侧栏预览跟着格走（绑定的那一格露出 / 别格放走）

    def _focus_ring(self):
        """v32.3：Tab 轮换的一圈（2 站）= 当前页表格 ⇄ 右侧 md 预览。

        「左」= 当前页的表格 / 清单（总表页→总表树、看板页→看板清单、统计页→统计清单）。
        「右」= 预览栏 —— 用哨兵串 `'preview'` 占位（真实键盘焦点在 WebView2 的原生窗口上，
        不是 Tk 控件，没法放进 focus_set）。预览收起 → 只有一站（Alt 不响应，用户拍板）。
        v50：认的是「**露在这一格上**」（`_prev_shown()`）—— 切走藏起来的那份不算一站。
        """
        ring = [self._active_tree()]
        if self._prev_shown():
            ring.append("preview")
        return ring

    def _search_box_visible(self):
        """v49：搜索框这会儿挂出来没有 —— 给 Tab 轮换当站点判据用。

        判据用 `winfo_manager()`（有没有 pack 管理器）：窗口还没映射时它照样准，`winfo_ismapped`
        在没映射的窗口上会一律回 0（探针 / 自检里窗口就是没前台，实测踩过）。等「搜索框只留总表页」
        那条线落地后，别的页 pack_forget 掉它 → 这里自动回 False，Tab 就不会往看不见的控件上落焦点。
        """
        return bool(self.ent_search is not None and self.ent_search.winfo_manager())

    def _rotate_focus(self, delta, event=None):
        """Tab / Shift+Tab：**当前页清单 ⇄ 搜索框**轮换（v49 起回到 v32.3 之前的老两站）。

        - **md 预览那一站归 `_rotate_md_focus`**（v49 单按 Alt → **v91 单按 Ctrl**，见那个函数）。
        - 搜索框**挂着**才收它当一站（见 `_search_box_visible`）；收着 = 只有一站 → 不响应。
        - 跑到别处（md 里、浮层…）时贴回第一站（清单）。浮层 / 一览开着时不响应。
        - 设置界面：不搞两站轮换，交给 Tk 默认焦点环（v40，`_rotate_focus_settings`）。
        - v58：**落进搜索框那一下把光标送末尾**（用户报：知识点页回车跳回总表后按 `Tab`，接着打字
          插到了最前面）——「Tab 进来 = 接着补词」；`F` 进来仍是全选（「整框重打」），分工不变。
        Tab 的默认遍历不会跑：这个 root 级处理 return "break"。
        """
        if self._busy():
            return None
        if self.key_capture:
            return "break"                              # v80：改键捕获中 Tab 不动焦点
        if self._in_settings():
            return self._rotate_focus_settings(delta)   # v40/v80：设置界面两站环，见那个函数
        ring = [self._active_tree()]
        if self._search_box_visible():
            ring.append(self.ent_search)
        cur = self._focus_widget()
        if cur not in ring:
            ring[0].focus_set()                  # 别处（md 里等）：贴回第一站
            return "break"
        if len(ring) < 2:
            return "break"                       # 搜索框收着：唯一一站，不响应
        nxt = ring[(ring.index(cur) + delta) % len(ring)]
        nxt.focus_set()
        if nxt is self.ent_search:
            # v58：进搜索框 = 接着补词 —— 光标送末尾、顺手清掉选区（原来停在开头，打的字插到最前面）。
            self.ent_search.select_clear()
            self.ent_search.icursor("end")
        return "break"

    def _rotate_md_focus(self, delta, event=None):
        """v49 立 / v91 改键：**单按 Ctrl** —— 当前页清单 ⇄ 右侧 md 预览 的焦点轮换。

        从 v32.3 的 Tab 处理整段搬来（那一站是 `_focus_ring()`，哨兵串 `'preview'`）。
        v91：触发键从「单按 Alt」换成「单按 Ctrl」（判定三件套 = `_on_ctrl_down` /
        `_ctrl_cancel_key` / `_on_ctrl_up`，见绑定区注释）；两站环单键就够（delta=1 在两站间
        来回，进预览那一下走 `focus_webview`），旧 Shift+Alt 那套反向随 Alt 一起退役。

        - 预览收起 = 只有一站 → 不响应（2026-10-06 用户拍板，原样保留）。
        - 进预览 = `prev.focus_webview()`：SetFocus 交给 WebView2 的原生窗口（跨线程，组件侧已
          AttachThreadInput；外层控件收到焦点后 WebView2 内部自动转给 Chrome 内层窗口 —— 实测）。
        - **从预览回来不走这里**：预览页里按 Tab / 单按 Ctrl / Esc 被 JS 拦住 → postMessage →
          宿主线程 → `_on_preview_status('tab' / 'ctrl' / 'esc')` → 焦点收回表格
          （v32.3 / v43 全链路实测；`'ctrl'` 是 v91 新加的）。
        - 跑到别处（搜索框等）时贴回第一站。浮层 / 一览 / 设置界面里不响应。
        """
        if self._busy() or self._in_settings():
            return None
        ring = self._focus_ring()
        if len(ring) < 2:
            return "break"                       # 预览没开：唯一一站，不响应
        cur = self._focus_widget()
        if cur not in ring:
            ring[0].focus_set()                  # 搜索框等处：贴回第一站
            return "break"
        nxt = ring[(ring.index(cur) + delta) % len(ring)]
        if nxt == "preview":
            if self.prev is not None:
                self.prev.focus_webview()
        else:
            nxt.focus_set()
        return "break"

    def _on_ctrl_down(self, event=None):
        """v91：单按 Ctrl 判定之「起」—— 配套三件套见 `__init__` 绑定区的长注释。"""
        self._ctrl_tap = True
        return None

    def _on_ctrl_up(self, event=None):
        """v91：单按 Ctrl 判定之「收」—— flag 还在（按下期间没碰别的键）= 单按 → 焦点轮换。

        「期间没碰别的键」由 `_ctrl_cancel_key` 保证（挂在 <Control-KeyPress> /
        <Control-KeyRelease> / <KeyRelease> 三条通配上）；轮换本身走 `_rotate_md_focus`，
        自带守卫（预览收起 = 单站不响应 / 设置页 / 忙时 / 浮层）。
        """
        if self._ctrl_tap:
            self._rotate_md_focus(1)
        self._ctrl_tap = False
        return None

    def _ctrl_cancel_key(self, event=None):
        """v91：单按 Ctrl 的「作废」信号 —— Ctrl 按住期间任何别的键动过。

        **Shift 也算**（不做反向键）：输入法 Ctrl+Shift 切换太常见，不能让它误判成单按。
        Ctrl 自己（Control_L / R）的按下 / 松开要豁免 —— 那是判定链的两端，不是「别的键」。
        三条通配各兜一段（实测：具体绑定的 return "break" 会截断同层通配，见绑定区注释）：
        · <Control-KeyPress>   = 没被具体绑定接走的 Ctrl 组合（按下那一半）；
        · <Control-KeyRelease> = 被接走的组合（Ctrl+F / Ctrl+Z…）的**松开**那一半；
        · <KeyRelease>         = Ctrl 已松开后别的键才松开的尾巴（Ctrl↓ F↓ Ctrl↑ F↑）。
        不 break —— 事件照常继续给后面的绑定（这里只是被动记 flag）。
        """
        if event is not None and event.keysym in ("Control_L", "Control_R"):
            return None
        self._ctrl_tap = False
        return None

    def _rotate_focus_settings(self, delta, event=None):
        """设置界面里的 Tab / Shift+Tab：**两站环「左列表 ⇄ 当前面板」**（v80 改自管）。

        v40 曾是「交给 Tk 默认焦点环」——实测按 Tab 会**一颗一颗经过全部 23 颗单选钮**
        （12 颗配色一颗不漏），用户口径「Tab 环瘦身」；v80 起自管两站：
        面板落点 = 快捷键块落表、主题块落「上次焦点 / 第一颗」（`_theme_focus_target`，
        与 `_set_focus_panel` 同一套口径）。块内走位仍归方向键（表选行 / 主题组间与网格）。
        两站环对称，delta（Shift 与否）不分支；捕获中不动（`_rotate_focus` 已先拦）。
        """
        cur = self._focus_widget()
        if cur is self.set_left:
            w = None
            if self.set_panel == "keys" and self.key_tv is not None:
                w = self.key_tv
            elif self.set_panel == "theme":
                w = self._theme_focus_target()
            if w is None:                        # 主题块没记过焦点 / 脏配置 → 落第一件
                for x in self._set_focus.get(self.set_panel, []):
                    w = x
                    break
            try:
                (w or self.set_left).focus_set()
            except tk.TclError:
                pass
        else:                                    # 在面板里（或跑到别处）→ 回左列表
            try:
                self.set_left.focus_set()
            except tk.TclError:
                pass
        return "break"

    # v46：原 `_open_material`（Alt+Enter「打开这题的资料」）连同 `_do_open` 整段删除 ——
    # 用户要求「alt+回车的快捷键变为跳转题目链接,原来的功能删除」；Alt+Enter 现在走
    # `_on_problem_key`（打开牛客原题网页：只读解析 + `_do_open_url`，不碰任何文件、不产生备份）。

    # ------------------------------------------------------------ v32：右侧题解预览栏
    def _preview_source(self, row, quiet=False):
        """v45：选中行的题解资料 `(path, anchor)`；没有 → None（顺带给出提示消息）。

        场题解 `<号>题解.md`（路径 = `toolutil.contest_paths`，2026-10-07 新命名方案）
        + anchor = 题号字母（滚到「E. 题名」那一节，v32 起口径）；场次认不出 →
        「看不了：这场还没接」；题解不在 → 「这题还没有资料」。
        （2026-10-06 起算法库已删，不再有记录 md 兜底。）
        v83：`quiet=True` = **只探有没有、不出提示** —— 全屏 md 里 ← / → 跳过「没有题解」
        的行时用它（那一档消息行收着，提示根本看不见，别去占消息位）。
        """
        name, num = toolutil.parse_contest(row["场次"])
        if name is None:
            if not quiet:
                self.set_msg("看不了：这场还没接", clear_after=TOAST_MS)
            return None
        _rdir, sol = toolutil.contest_paths(self.data_root, name, num)
        if os.path.isfile(sol):
            return sol, row["题号"]             # 题解正文 + 跳到该题那一节
        if not quiet:
            self.set_msg("这题还没有资料", clear_after=TOAST_MS)
        return None

    def _toggle_preview(self, event=None):
        """v32 立、v46 改：**回车** —— 展开 / 收起选中这题的题解 md（只读，不碰任何文件）。

        v45：**两种模式由设置页「主题设置 ▸ 题解预览」决定**（`self.preview_mode`）：
          * `side`（默认）= 右侧栏（v32 起的原行为）：同一题再按 = 收起；换一题按 = 换内容；
          * `full` = **整窗换成 md = 独立界面**（进全屏只由这里；v62 起第一行也收起 ——
            没有搜索框 / 计数 / 消息，只有 md 本身；`← / →` 在里面 = 上一题 / 下一题（v83），
            Esc / md 里回车退出）。
            全屏里表格侧的回车 **不响应**（表被盖、焦点在 md 里 —— 那边按回车 = 收起，走 JS 回传）。
        v46 起 side 档展开成功后**焦点送进 WebView2**：这样「回车展开 → 在 md 里再按回车收起」
        是一条闭环（Tab 回表格、Esc 收起照旧）—— 用户口径「在md文件再按回车会收起md文件」。
        首次才懒加载预览组件 —— 不按回车就永远不会起 WebView2。
        v50：side 档的开合 / 换题都以「**露着的**」为准（`_prev_shown()`）—— 切到别的格藏起来
        的那份不算；在别的格上回车 = 把这题开在**当前格**（绑定跟着走）。
        v69（用户口径：**这不是 bug、是要的效果**）：md **已经开着**时换一题 —— **只换内容、
        焦点不动**（焦点留在左表，可以继续 ↓ / ↑ 换行、回车逐个看题解）；只有「**新开**」那一发
        才把焦点送进 md（v46 那条闭环照旧）。
        """
        if self._busy() or self._in_text_widget():
            return None
        if self._swap_busy:
            return "break"                      # v84：幕布下换页中（泵消息泵进来的这一发）→ 忽略
        if self.md_full:
            return "break"                      # 全屏 md 里表格侧回车不响应（md 里的回车走 _on_preview_status）
        row = self.tree_row(self._active_tree())
        if not row:
            return "break"
        if self.preview_mode == PREVIEW_MODE_FULL:
            return self._enter_md_full(row)
        key = (row["场次"], row["题号"])
        if self._prev_shown() and key == self._prev_key:
            self._hide_preview()                # v50：只有"露着的"同一题才算再按收起
            return "break"
        src = self._preview_source(row)
        if src is None:
            return "break"
        path, anchor = src
        if not self._ensure_preview():
            return "break"
        was_open = self._prev_shown()           # v69：本来就开着 → 这一下是「换题」不是「新开」
        # v94：**先点菜后摆桌** —— 页面请求排在显形前面（原来反过来：窗口先亮出来、页面还没
        #      开始加载，冷启动那一拍露的就是 WebView2 的白底）。显形那一套在幕布下跑，
        #      冷档它会先等页面就绪（`_wait_preview_first_paint`）。
        if not self.prev.show_md(path, anchor=anchor):
            self.set_msg("打不开：%s" % os.path.basename(path), clear_after=TOAST_MS)
            return "break"
        self._show_preview()
        self._prev_key = key
        if not was_open:
            # v46：**新开**才把焦点送进 md —— 「回车展开 → 在 md 里再按回车收起」是一条闭环。
            self.prev.focus_webview()
        # v69（用户口径：**这不是 bug、是要的效果**）：md 已经开着时换一题 —— **只换内容、焦点不动**：
        #   焦点留在左表，可以继续用 ↓ / ↑ 换行、回车逐个看题解（画面里 md 跟着换）。
        return "break"

    def _ensure_preview(self):
        """v32：懒加载预览组件（首次按 P 才起 WebView2）；起不来给一次提示，TB 其余功能不受影响。"""
        if self.prev is not None:
            return True
        try:
            import tb_preview
            self.prev = tb_preview.MdPreview(self.prev_holder, on_status=self._on_preview_status)
            # v75：预览是懒加载的（可能晚于黑夜模式开启）—— 把当前界面模式的深色档补上
            # （页面还没加载时 set_dark 只记账，首次 show_md 构建页面会带上）
            self.prev.set_dark(self.theme_scheme
                               if self.theme_daynight == THEME_DAYNIGHT_NIGHT else None)
            return True
        except Exception as e:
            self.set_msg("预览组件起不来：%s" % e, clear_after=TOAST_MS * 2)
            return False

    def _on_preview_status(self, kind, msg):
        """预览组件的事件（宿主线程 → 主线程 poll 转来）：报错误 / 收焦点 / 切界面 / 收起。

        Tab（v32.3）、Esc（v43）、← / →（v45）、回车（v46）、单按 Ctrl（v91）都是预览页里
        被 JS 拦下回传的 —— 分侧栏 / 全屏两档。
        """
        if kind == "error":
            self.set_msg("预览出错：%s" % msg, clear_after=TOAST_MS * 2)
        elif kind == "tab":
            if self.md_full:
                return                          # v45：全屏 md 里 Tab 无处可轮（表格被盖）→ 忽略
            # v32.3：预览页里按 Tab / Shift+Tab → 焦点收回左边当前页表格。
            self._refocus_active_tree()
        elif kind == "esc":
            if self.md_full:
                return self._exit_md_full()     # v45：全屏 md 里 Esc = 收 md 回主表
            # v43：预览页里按 Esc → 收起预览栏、焦点收回左边当前页表格（同 Tab 的抢焦处理）。
            self._hide_preview()
            self._refocus_active_tree()
        elif kind == "enter":
            # v46：md 里按回车 = 收起（用户口径「在md文件再按回车会收起md文件」）——
            # 两档同一条语义：侧栏档 = 收栏 + 抢回焦点；全屏档 = 收 md 回主表。
            if self.md_full:
                return self._exit_md_full()
            self._hide_preview()
            self._refocus_active_tree()
        elif kind == "ctrl":
            # v91：md 预览里单按 Ctrl（网页侧 JS 判完回传 `tbprev:ctrl`；替 v53 的 Alt 那条路）——
            #   与 Tab 同路：焦点从 WebView2 收回当前页表格（预览不收起）。全屏档不响应
            #   （跟 Tab 一样：全屏 md 里表格被盖着，无处可轮）。
            if self.md_full:
                return
            self._refocus_active_tree()
        elif kind == "nav":
            # v45 原口径「全屏 md 里 ← / → 照走换界面的环」→ v62 改：全屏 md = 独立界面
            # （跟设置页同款）—— 不换界面。v83：全屏档这一对键改作「列表行的上一题 / 下一题」；
            # v96：**侧栏档也接上**（原来"侧栏档仍不响应"，用户口径「侧栏也加上」）—— 两档
            # 现在同走 `_md_row_nav`（换 md 内容 + **表格当前行自动跟随**，焦点不抢）。
            # JS 侧照旧拦下回传（tb_preview 不动）。
            self._md_row_nav(msg)
            return

    def _refocus_active_tree(self):
        """v32.3/v43：把系统焦点从 WebView2 抢回「当前页清单」。

        光 focus_set 不够：WebView 抢焦后 Tk 收不到焦点通知、focus_get() 记成 None；
        显式 SetFocus 把系统焦点拿回 Tk 窗口树，Tk 的焦点账才恢复（preview_probe [5] 实测）。
        """
        t = self._active_tree()
        t.focus_set()
        try:
            import ctypes
            ctypes.windll.user32.SetFocus(t.winfo_id())
        except Exception:
            pass

    def _preview_target_w(self):
        """v32.1：预览栏目标宽度 = 窗口宽 − 主表预留（clamp 在 [PREVIEW_W, PREVIEW_W_MAX]）。

        窗口拉宽 / 全屏时预览跟着吃增量，主表按列权重自然收窄（题名 / 知识点列压得最狠）。
        `winfo_width ≤ 1` = 窗口还没完成首次布局（早期调用 / 未映射，实测探针里就是这个值）
        —— 按默认窗口宽 1320 算，别让 clamp 吃成最小值。
        """
        w = int(self.root.winfo_width())
        if w <= 1:
            w = 1320
        return max(PREVIEW_W, min(PREVIEW_W_MAX, w - MAIN_MIN_W))

    # ------------------------------------------------------------ v84：换页幕布
    def _curtain_up(self):
        """把当前画面冻成一张静态图盖住整个窗口（＝ `_Curtain`）。

        拿不到窗口几何 / 窗口最小化 / 幕布组件建不起来 → 一律**静默返回 None**，调用方
        照旧走原路（没有幕布 = 今天的行为，绝不更差）。开关 = `_curtain_ok`（v84：
        `--smoke` / `--selftest` 默认关 —— 那些窗口多半没真显示在屏上、盖幕还会挡用户桌面；
        探针要量产品真实路径，起窗时显式给 `curtain=True`，见 `__init__` 的说明）。
        """
        if not getattr(self, "_curtain_ok", True) or self._curtain is not None:
            return None
        try:
            from ctypes import wintypes
            _Curtain._prep_win32()               # 句柄原型先设好（64 位下不设会被截断，见那里注释）
            user32 = ctypes.windll.user32
            hwnd = self.root.winfo_id()
            owner = user32.GetParent(hwnd) or hwnd
            if user32.IsIconic(owner):
                return None
            rect = wintypes.RECT()
            if not user32.GetWindowRect(hwnd, ctypes.byref(rect)):
                return None
            x, y = rect.left, rect.top
            w, h = rect.right - rect.left, rect.bottom - rect.top
            # 只盖「屏幕里看得见」的那块（窗口拖出屏幕时不抓屏外区域 —— 抓回来是黑的）
            vx = user32.GetSystemMetrics(76)          # SM_XVIRTUALSCREEN
            vy = user32.GetSystemMetrics(77)          # SM_YVIRTUALSCREEN
            vw = user32.GetSystemMetrics(78)          # SM_CXVIRTUALSCREEN
            vh = user32.GetSystemMetrics(79)          # SM_CYVIRTUALSCREEN
            nx, ny = max(x, vx), max(y, vy)
            nw = min(x + w, vx + vw) - nx
            nh = min(y + h, vy + vh) - ny
            if nw <= 0 or nh <= 0:
                return None
            cur = _Curtain()
            if not cur.open(owner, nx, ny, nw, nh):
                self._curtain_err = "open 返回 False"
                return None
            self._curtain = cur
            self._curtain_err = None
            return cur
        except Exception as e:
            # 失败照旧静默退场（没有幕布 = 今天的行为），但**记一笔** —— 教训：v84 第一次
            # 落地时 `gdi32.AlphaBlend` 那句 AttributeError 被这里吞成"幕布没建出来"，
            # 白查了一轮。探针要查"幕布到底建没建"看 `_curtain_err`。
            self._curtain_err = repr(e)
            return None

    def _curtain_down(self, hold_ms=0):
        """撤幕。`hold_ms` > 0 = 幕布下再停这么久（把对面「会晚到的那一拍」等掉，见常量注释）。"""
        cur = self._curtain
        self._curtain = None
        if cur is None:
            return
        if hold_ms:
            try:
                self.root.update_idletasks()      # 停之前先把排队的重画落实
                time.sleep(hold_ms / 1000.0)
                self.root.update_idletasks()
                self.root.update()
            except tk.TclError:
                pass
        try:
            cur.close()
        except Exception:
            pass

    def _swap_under_curtain(self, fn, hold_ms=0):
        r"""v84：把 `fn`（换页那一整段）罩在幕布下 —— 用户全程看到的是「变前」那张静止画面，
        幕布一撤就是画好的「变后」。**先把幕布盖稳，再动任何东西**（`fn` 里怎么翻 z 序 /
        摆浮层 / 泵消息都行，屏幕上都不会露）。

        重入闸 `_swap_busy`：`fn` 里要泵消息（`_settle_preview_swap` 的 `update()`），
        泵进来的按键可能再触发一次换页 —— 换页期间新按键一律忽略（整段只有几十毫秒）。
        返回 False = 这次没换（正在换 / 幕布拿不到也不影响：照样跑 `fn`）。
        """
        if self._swap_busy:
            return False
        self._swap_busy = True
        try:
            cur = self._curtain_up()
            try:
                fn()
            finally:
                self._curtain_down(hold_ms if cur is not None else 0)
        finally:
            self._swap_busy = False
        return True

    def _prev_shown(self):
        """v50：侧栏预览这会儿**看得见**吗（跟 `_md_full_shown` 同构）。

        `prev_open` = 开着（状态）；再跟"分屏页翻没翻上来"合起来才是"露在这一格上"。
        切到别的格只收显示、`prev_open` 还留着 —— 那时的 Esc / 同题回车 / Alt 轮换都不许
        认它（见 `_sync_preview`）。
        v73：判据从 `prev_holder.winfo_manager()` 改成 `_split_shown()` —— md 改常驻挂载后
        管理器恒在、判不了；露没露全看「分屏页在上面吗」（两页一起翻，同一件事）。
        """
        return bool(self.prev_open and self._split_shown())

    def _show_preview(self):
        """v50：开预览 = 记下**绑在当前这一格** + 摆显示（幂等）。同题换内容也走这里。"""
        self.prev_open = True
        self.prev_cell = self._cell_of_current_page()
        self._prev_show_view()

    def _settle_preview_swap(self):
        """v61：预览栏显隐这一拍，把「重排 + **整块重绘**」同步做完，再让对面的东西显 / 隐。

        v56 只做了 `body.update_idletasks()`，抓帧实证不够 —— Tk 的**几何**当拍就落实，
        但 ttk 树的**内容**（列宽 / 各行）是下一拍才重画的，那一拍就是用户报的「闪原来的表」：
          * 收起：左半还是那张**窄表**（列挤在 420px 里、题名被截），右半空白；
          * 展开：整张**宽表**压在刚出现的 md 底下（列还停在老位置）。
        做法 = v25.18 `_flush_screen(deep=True)` 的同一条：先给「表格区（nb）/ 预览栏 / 当前页
        那棵树」各发一发 `<Expose>` 整块标脏，再 `update_idletasks()` 当场落实；树重画会盖掉
        浮层 → 跟着按新宽度重摆黑框 / 今天竖条 / 遮色条并补画（顺序照 v25.18.4）。
        """
        try:
            tree = self._active_tree()
        except tk.TclError:
            tree = getattr(self, "tree", None)
        # v82b：**分屏页那两件也一起标脏** —— 侧栏档来回翻时露出来的可能是两页里的任意一面
        #       （收起 = 整张表页露、展开 = 分屏页 + md 露）。用户报的「收起 / 展开 md 那一瞬间
        #       中间闪一竖列色块」= 被盖住那页没重画、露出上一版像素（v61 同一族的病）。
        for w in (self.nb, self.prev_holder, tree,
                  getattr(self, "split_tab", None), getattr(self, "tree_split", None)):
            if w is None:
                continue
            try:
                w.event_generate("<Expose>")
            except tk.TclError:
                pass
        try:
            for _ in range(SWAP_SETTLE_ROUNDS):   # v84：**多泵几轮**（原来只有一轮）
                self.body.update_idletasks()    # ① 先把布局 / place 落实
                self.body.update()              # ② 再把**整个消息泵**过一遍
                                                #   —— ttk 树的 <Configure>（列宽重算）与
                                                #   WM_PAINT 都只在真事件循环里处理，
                                                #   `update_idletasks` 两条都跳过（抓帧实证：
                                                #   只 idle 时那一帧的表还是窄的）
        except tk.TclError:
            pass
        #     v84 为什么是"几轮"而不是一轮：换页会引发一串**级联**重排 —— `split_left` 改宽
        #     → 分屏树的 `<Configure>` → 七列按权重重算 → 整树重画 → 浮层重摆；每一环都要
        #     下一轮消息泵才轮得到。只泵一轮时，末环（列宽那一下）落在**撤幕之后** ——
        #     50fps 抓帧实证：换页那一帧露出来的分屏表还是"3 列宽版"，下一帧才变成"挤窄
        #     七列"（用户长期抱怨的"收起/展开那一下显示出错"里就有这一条）。幕布盖着的时候
        #     多泵几轮一分钱不花（屏幕上就是那张静止画面），撤幕时整串已经落完。
        try:
            self._sync_all_row_borders()        # 黑框 / 竖条 / 遮色条按新宽度重摆
            self._sync_today_bar(getattr(self, "tree_split", None))   # v82b：分屏页那只框池
        except tk.TclError:
            pass
        self._repaint_overlays_now()            # 浮层补画上线（v25.18.4 顺序）

    def _show_split_page(self):
        """v73：翻 z 序 —— **只把整张表页 `lower` 下去**（单窗口一步）。

        v66 原来是 `split_tab.lift()` + `prev_holder.lift()` 两步 —— 50fps 抓帧实证存在
        「左半边已切换、右半边还是旧画面」的复合帧（两个窗口的 z 变化跨了两拍；探针原来的
        「谁都不像」判据对这类半对半画面不敏感、一直漏报）。现在闭态不变量 = nb 压住
        「分屏页 + md」（见 `_make_split_tab` 末尾），开预览 = nb 一沉、两页同时露 ——
        只动一个窗口，合成器一帧到位。
        """
        self.nb.lower()
        self._split_up = True

    def _show_table_page(self):
        """v73：翻 z 序 —— **只把整张表页 `lift` 上来**（单窗口一步）。

        v66 原来还要补一发 `split_tab.lower()`（那是两步里的第二拍 —— 收起方向的复合帧
        同样是它）；现在分屏页的 z 位从头到尾不动。
        """
        self.nb.lift()
        self._split_up = False

    def _wait_preview_first_paint(self):
        """v94：**冷启动**开预览那一拍 —— 页面从没导航过时，等它真把内容画上来再亮窗口。

        用户报的「启动第一次按回车,主表右侧闪白色空界面」根因就在这：预览是懒加载的，第一次
        开得先起宿主 + WebView2（本机实测：宿主 ready ≈0.5s、页面 complete + 滚好锚点
        ≈1.2~1.7s），而 v84 的幕布只按「热档 ~36ms 第一帧」留 40ms —— 中间整段露的就是
        WebView2 的白底。修法：幕布不撤到「页面就绪」—— 轮询 `prev.page_ready`（宿主
        NavigationCompleted 回传，v94 新加的那条消息），到了再多等 `PREVIEW_COLD_SETTLE_MS`
        （锚点那发 JS 落位）再往下走。**热档（ever_navigated）立即返回** —— v84 的时序一个字
        不动；上限 `PREVIEW_COLD_CAP_MS` 兜底（加载异常也不许把幕布挂死）。幕布盖着时泵消息
        是 v84 的既有做法（`_settle_preview_swap` 同一套）；泵进来的按键会被 `_swap_busy` 忽略。
        """
        pv = self.prev
        if pv is None or getattr(pv, "ever_navigated", True):
            return                              # 热档 / 老组件：老路，立刻走
        deadline = time.monotonic() + PREVIEW_COLD_CAP_MS / 1000.0
        while time.monotonic() < deadline:
            if getattr(pv, "page_ready", False):
                break
            self.root.update()
            time.sleep(0.01)
        end = time.monotonic() + PREVIEW_COLD_SETTLE_MS / 1000.0
        while time.monotonic() < end:           # 让锚点滚动 / 首帧呈现落位
            self.root.update()
            time.sleep(0.01)

    def _prev_show_view(self):
        """v50：只摆**显示**（幂等；`prev_open` / `_prev_key` / `prev_cell` 早就在）——
        打开、走回绑定那一格都从这儿过（走回来**不重导航**：WebView 里的页面 / 滚动位置原样）。

        v32.1：每次摆出按当前窗口宽重算宽度（关掉再开 / 走开再回 = 重新分配）。
        v66（**现行口径**，用户口径「左右分屏的页面跟整张主表的页面是两个页面，退出做的实际是
        页面切换，这样会又快又好」）：**两页常驻、只翻 z 序** —— 「整张表页」（`nb`）与
        「分屏页」（`split_tab` 挤窄七列表 + 右侧 md）永远都摆着、布局各自一次定死；开 / 收预览
        = `lift` / `lower` 一下，表一个像素都不重排、窗口一个像素都不重画 —— v56/v61 那条
        「ttk 重排 ~70ms 一定会在某处露一帧」的根就此拔掉。
        顺序讲究：**先把分屏页备好（列宽 / 行数据 / md 都就位，此刻它还压在整张表页底下、
        干什么都看不见），最后才翻 z 序** —— 翻上来那一帧就是最终样子。
        v84（用户口径「重做收起打开的方式，要求画面流畅不闪烁」）：上面那句「翻上来那一帧
        就是最终样子」对**被盖过的窗口**并不成立 —— 它压根没画过（Windows 不给被遮窗口发
        WM_PAINT），露出来的是没画过的区域。所以整段改罩在**幕布**下跑（`_swap_under_curtain`）：
        先把当前画面冻成静态图盖住整窗，底下把这一整套做完，最后**撤幕**。实体见
        `_prev_show_view_body`。
        """
        if self._split_shown():
            return                              # v73：判据同 `_prev_shown`（md 改常驻挂载）
        self._swap_under_curtain(self._prev_show_view_body, CURTAIN_HOLD_OPEN_MS)

    def _prev_show_view_body(self):
        """v84：`_prev_show_view` 的实体（在幕布下跑；步骤说明见那个函数的 docstring）。"""
        # ① 分屏页就位（还在底下）：格子、列宽、行数据、滚动 / 选中对齐
        self._place_split_tab()             # v70：先摆格（第一行下面那一格），再定列宽
        self._place_holder()                # v73：**md 先摆** —— `_sync_split_width` 要用它刷新的
                                            #     `prev_w`。原来它排在 sync 后面：init 起 md 常驻
                                            #     挂载、`prev_w` 不再是 0，过期宽度会漏进来把左表
                                            #     撑到 md 底下（实测 split_left 1086 ≠ 应有的 576）
        self._sync_split_width()
        if getattr(self, "_split_dirty", False):
            self._fill_split(self.visible_rows())
            self._split_dirty = False
        try:
            self.tree_split.yview_moveto(self.tree.yview()[0])
        except tk.TclError:
            pass
        sel = self.tree.selection()
        if sel:
            try:
                self.tree_split.selection_set(sel[0])
                self.tree_split.focus(sel[0])
            except tk.TclError:
                pass
        # ② md 预显形（v73：此刻它还压在 nb 底下 —— WebView2 是独立原生窗口，ShowWindow
        #    之后由 Chromium 异步呈现（实测 ~36ms）；提前亮出来抢这点呈现时间）
        #    v94：冷档（页面还没加载过）先把「页面画出内容」等掉再亮 —— 白闪就是从这来的。
        if self.prev is not None:
            self._wait_preview_first_paint()
            self.prev.set_visible(True)
        # ③ 翻 z 序：**只动 nb 一个窗口**（v73）—— 分屏页 + md 是两张常驻窗口，一起露出来。
        #    〔试过并撤掉的一招（留档）：在这里先 `split_tab.update()`「预画」分屏页 ——
        #    对全遮挡的窗口无效（Windows 不给被盖住的窗口发 WM_PAINT），帧级实测没差别、
        #    白添一次消息泵；真正的残差是**被遮窗口揭幕时必须重画的 GDI 内容**（下同）。〕
        self._show_split_page()
        # v82b：翻上来这一拍**强制把两面都重画一遍**（同 `_prev_hide_view` 那条口径）——
        #       露出来的这两页此前都被 nb 盖着，Windows 不给被遮窗口发 WM_PAINT，
        #       不补这一发就会露上一版的像素（用户报的「中间闪一竖列色块」）。
        self._settle_preview_swap()
        # v41：开着预览时窗口被拉宽 / 拉窄（含 F11 全屏、拖动边框、双击标题栏最大化）→
        #      同步重算宽度。原来只在"打开那一发"算宽度，窗口拉大后预览停在老宽度，
        #      「尽可能大」就落空了。只在算出来真的不同才 configure（防 Configure 自激）。
        if not self._prev_resize_bound:
            self.root.bind("<Configure>", self._on_root_resize_preview, add="+")
            self._prev_resize_bound = True

    def _prev_hide_view(self):
        """v50：只收**显示**（切走那一下）—— 状态一个都不动，走回来 `_prev_show_view` 原样再现。

        v56/v61 的病史：收起这一拍原来是「表要在 md 底下摊开重画完 → 再藏 WebView2」，靠落实
        布局 / 原地转 `place` 托管躲重排残留帧 —— **v66 起两页常驻、翻 z 序**，两条都不再需要：
        收起 = 把整张表页 `lift` 上来盖住（那张表本来就画好在盘上），md 在盖子底下收掉。
        """
        if not self._split_shown():
            return
        self._swap_under_curtain(self._prev_hide_view_body, CURTAIN_HOLD_CLOSE_MS)

    def _prev_hide_view_body(self):
        """v84：`_prev_hide_view` 的实体（在幕布下跑；步骤说明见那个函数的 docstring）。"""
        self._show_table_page()             # ① 整张表页翻上来（零重排；单窗口一步）
        # v82b（用户报「收起 md 时中间闪一竖列色块」）：**翻上来之后补一发整块重画** ——
        #   v73 的「表本来就画好在盘上」只对**露出来的那部分**成立：整张表页此前被
        #   分屏页 + md 两张窗口盖住，Windows 不给被遮窗口发 WM_PAINT，`lift` 那一下
        #   露出来的正是**从来没画过的区域**（分屏页右缘那一竖条最典型）→ 抢在下一帧
        #   补画完，屏幕上一帧都不露旧像素。md 的隐藏排在它后面（盖子底下收）。
        self._settle_preview_swap()
        if self.prev is not None:
            self.prev.set_visible(False)    # ② md 在盖子底下收掉（v73：只藏 WebView2 本体，
                                            #    holder 常驻留在原位、不再 place_forget）

    def _on_root_resize_preview(self, event=None):
        """v41：根窗口大小变了 → 预览栏 / 分屏页跟着走（只认根窗口自己的 Configure，子控件的不算）。

        v70：三道重摆**各自带幂等闸**（算出来跟上次一样就一个 Tcl 调用都不发 —— 窗口拖动时
        Configure 会连发，且 `configure(...)` 本身又会触发一轮布局，不设闸会自激）；分屏页
        那一格的高度也跟着窗口高走，所以每次都要过一遍 `_place_split_tab()`。
        """
        if event is not None and event.widget is not self.root:
            return
        if not self.prev_open:
            return
        self._place_split_tab()             # v70：分屏页那一格（高度变了也要重摆；幂等）
        self._place_holder()                # 预览栏（宽度 + 位置一起重算；幂等）
        self._sync_split_width()            # 分屏页左半跟着让位（幂等）

    def _hide_preview(self):
        """v50：**真收**（Esc / md 里 Esc·回车 / 同题再回车 / 切预览档）—— 显示收起 + 状态清干净。

        只切格那一下**不走这里**（走 `_prev_hide_view()`，状态留着）—— 见 `_sync_preview`。
        v84：幕布下换页进行中（泵消息泵进来的 Esc / 回车）→ 整发忽略，别把状态拆成两半。
        """
        if self._swap_busy:
            return
        self._prev_hide_view()
        self.prev_open = False
        self._prev_key = None
        self.prev_cell = None

    # ------------------------------------------------------------ v45：P 键「全屏 md」档
    def _md_full_shown(self):
        """全屏 md 现在**看得见**吗。

        v45：跟设置界面同构。v62：全屏 md 独立界面化后它恒等于 `md_full`（不再有"切走
        藏起来"的中间态），保留在这里给自测 / 探针当"真露着"的判据用。
        v73：md 常驻挂载后管理器恒在、判不了 —— 改认 `_md_full_up`（视图摆没摆出来这个账，
        `_md_full_show` / `_md_full_hide_view` 自己记）。
        """
        return bool(self.md_full and getattr(self, "_md_full_up", False))

    def _enter_md_full(self, row):
        """v45：进全屏 md —— 表格区（Notebook）整块收起，预览组件铺满它。
        （v45 用户口径：「对当前行按 P，整个主表界面就都变成了 md 文件」。）

        v62：**独立界面**（跟设置页同款）—— 第一行（搜索框 / 计数 / 消息）也收起，
        整个界面只有 md 本身；`← / →` 不换界面、Esc / md 里回车退出。
        v83：`← / →` 在里面 = **列表行的上一题 / 下一题**（v96 起 = `_md_row_nav`）—— 仍是
        独立界面（不换界面、焦点不出去），只是这一对键不再空着。
        v96：翻题同时**表格的当前行自动跟随**（用户口径「全屏自动跟随」）—— 退出全屏 /
        切走再回来，表格就停在刚看的那一行。
        （用户口径 2026-10-07：「这个独立界面没有搜索框等，只有 md 文件本身」。）
        资料 / 提示同右侧栏（`_preview_source`）；进不去就停在主表 + 消息。
        """
        if self._swap_busy:
            return "break"                      # v84：幕布下换页中 → 忽略
        src = self._preview_source(row)
        if src is None:
            return "break"
        path, anchor = src
        if not self._ensure_preview():
            return "break"
        if self.prev_open:
            self._hide_preview()                # 右侧栏（side 档留下的）先让位
        if not self.prev.show_md(path, anchor=anchor):
            self.set_msg("打不开：%s" % os.path.basename(path), clear_after=TOAST_MS)
            return "break"
        self.md_full = True
        self.md_full_key = (row["场次"], row["题号"])
        self._md_full_show()
        return "break"

    def _md_full_show(self):
        """v45：把全屏 md 摆出来（幂等）—— 第一行 + nb 收起、prev_holder 铺满 body、焦点进 WebView2。

        v62：跟设置页一个逻辑（整窗只有它自己）—— head 也收起；退出时 `_md_full_hide_view`
        照原样摆回（v63：head 与 nb 同挂 body —— 摆回顺序 = 先 head 后 nb，body 自己不动）。
        宽度不再走 `_preview_target_w()`（那是右侧栏的算法）—— `fill="both", expand=True`
        让组件吃满表格区（窗口缩放跟着走；WebView2 随 frame 的 <Configure> 自动 resize）。
        v84：整段罩在**幕布**下（同 `_prev_show_view` 那条口径）—— 实体见 `_md_full_show_body`。
        """
        if getattr(self, "_md_full_up", False):
            return
        self._swap_under_curtain(self._md_full_show_body, CURTAIN_HOLD_OPEN_MS)

    def _md_full_show_body(self):
        """v84：`_md_full_show` 的实体（在幕布下跑）。"""
        self.head.pack_forget()                 # v62：第一行（搜索框 / 计数 / 消息）整行收起
        self.nb.pack_forget()
        # v73：holder 改常驻 `place`（不再 pack / place_forget）—— 全屏档把它挪成「铺满」那一格
        #      （= v62 的 pack(padx=12, pady=(2,4)) 同一个框）；分屏页照旧在它下面被盖住。
        self.prev_holder.place(x=12, y=2, relwidth=1, width=-24, relheight=1, height=-6)
        self._holder_geo = None                 # 位置不是侧栏那套了 → 缓存作废，退出时重摆
        self._settle_preview_swap()             # v61：表格区收起这一拍落实完，再放 md 上来
        if self.prev is not None:
            self._wait_preview_first_paint()    # v94：冷档先等页面画出内容（同侧栏档那条）
            self.prev.set_visible(True)
            self.prev.focus_webview()           # 焦点进 md：滚轮 / 翻页 / ←→（JS 回传）都归它
        self.prev_holder.lift()                 # v66：常驻的分屏页在它下面 —— 抬上来盖住
        self._md_full_up = True

    def _md_full_hide_view(self):
        """v45：收全屏 md 的**显示** —— v62 起只剩一个调用方 = `_exit_md_full`（Esc / md 里回车）：
        第一行 + nb 摆回来、prev_holder 收起（v45「← / → 切走只收显示」那半随独立界面化删除）。

        v56：跟 `_prev_hide_view` 同款 —— `nb` 摆回来之后**先落实、再藏 WebView2**。
        v61：跟 `_prev_hide_view` 一起改走 `_settle_preview_swap()`（v56 只落了布局、
        ttk 树的内容还是下一拍才画 → 仍会闪一帧旧表）。
        v63：第一行现在挂在 **body** 里（v62 挂 main_frame）—— 摆回它不再把 body 往下推，
        钉住的 md 也不会跟着下移一截（用户报的「顶部一条空带 + md 整块下移」）。摆回顺序
        照旧 v61 那一套：先钉 md → 第一行 + 表在它**底下**摆回来 + 重画完 → 最后一拍才收 md
        （那块地方自始至终只有两种像素：md，或**已经画好的**第一行 + 表）。
        v84：整段罩在**幕布**下（同 `_prev_hide_view` 那条口径）—— 实体见 `_md_full_hide_view_body`。
        """
        if not getattr(self, "_md_full_up", False):
            return
        self._swap_under_curtain(self._md_full_hide_view_body, CURTAIN_HOLD_CLOSE_MS)

    def _md_full_hide_view_body(self):
        """v84：`_md_full_hide_view` 的实体（在幕布下跑）。"""
        # v61/v63 的次序照旧：md 先钉最上 → 第一行 + 表在它**底下**摆回来 + 重画完 → 最后才收 md。
        # v73：holder 本来就常驻 place、此刻就是满格 —— 「钉」只需再抬一下 z（原来那串
        #      pack_forget + place 是给 unmount 版用的；现在一个 z 调用就够，也没有 unmap 跳动）。
        self.prev_holder.lift()
        self.head.pack(fill="x", padx=16, pady=(10, 2))   # v63：第一行摆回（body 的第一件子控件）
        self.nb.pack(side="left", fill="both", expand=True, padx=12, pady=(2, 4))
        self._settle_preview_swap()             # 第一行 + 表格区在 md 底下摆好、重画完
        if self.prev is not None:
            self.prev.set_visible(False)
        # v73：md 回侧栏那一格（此刻 nb 已在最上、盖着 —— 屏幕上什么都不会闪）；
        #      再把 nb 顶回最上，恢复闭态不变量「分屏页 < md < 整张表页」。
        self._place_holder()
        self.nb.lift()
        self._md_full_up = False

    def _md_row_nav(self, delta):
        """md 里 ← / → = **列表行的上一行 / 下一行的题解**（v83 全屏档；v96 侧栏档也接上）。

        （v83 用户口径 2026-10-07：「全屏模式按左/右改为列表行的上一题/下一题，esc 退出后
        焦点落在最后一题题解所在行」；v96 用户口径：「在md按左右改为切换到上一行,下一行的
        题解」「侧栏也加上」「全屏自动跟随」。）

        行序 = `_active_tree()` 的**显示序**（`get_children()` 就是画在屏上的那一串 ——
        搜索筛过、排过序的那份；类标题行 / 平台行 / 场次行的 iid 认不出行 → 天然跳过）。
        某一行的题解拿不到（场次认不出 / md 不在）→ **顺着方向跳过它**，落到下一道有题解的
        题；到头（第一题再按 ← / 最后一题再按 →）→ 停住不动（跟列表 ↑↓ 一个口径，不绕回）。

        v96：**表格的当前行跟着走**（`select_key(..., focus=False)` —— 各页清单一起选中、
        **焦点不抢**，还留在 md 里接着翻）。两档的「当前题」记账各归各的：全屏 = `md_full_key`
        （Esc 退出靠它落回这一行）、侧栏 = `_prev_key`（同题再按 = 收起靠它）。
        """
        if self.prev is None or not delta:
            return
        tree = self._active_tree()
        iids = [iid for iid in tree.get_children() if self.row_by_iid(iid)]
        cur_key = self.md_full_key if self.md_full else self._prev_key
        cur = None
        for i, iid in enumerate(iids):
            r = self.row_by_iid(iid)
            if (r["场次"], r["题号"]) == cur_key:
                cur = i
                break
        if cur is None:
            return                          # 认不出当前题（表刚被重画 / key 丢了）→ 原地不动
        step = 1 if delta > 0 else -1
        i = cur + step
        while 0 <= i < len(iids):
            row = self.row_by_iid(iids[i])
            src = self._preview_source(row, quiet=True)
            if src is not None:
                path, anchor = src
                if self.prev.show_md(path, anchor=anchor):
                    key = (row["场次"], row["题号"])
                    self._prev_key = key
                    if self.md_full:
                        self.md_full_key = key
                    self.select_key(key, focus=False)   # v96：表格当前行自动跟随
                else:
                    self.set_msg("打不开：%s" % os.path.basename(path), clear_after=TOAST_MS)
                return
            i += step

    def _exit_md_full(self, event=None):
        """v45：Esc —— 收起全屏 md（v46 起出口两条：Esc、md 里按回车；全屏里表格侧回车不响应）。

        v62：独立界面后焦点回**进来的那个界面**（页面从头到尾没换过 —— `← / →` 在独立界面里
        不换界面，进来时在哪页就回哪页）。
        v83：`← / →` 变成「上一题 / 下一题」后，焦点落点跟着改 —— 不是"进来的那一行"，而是
        **最后看的那一题所在行**（`md_full_key` 一路跟着走）：先把行选上（`select_key`，
        各页清单一起同步）再抢焦点。
        焦点回当前页清单（`_active_tree`）；在设置界面里被换档清理调到时不碰焦点
        （那儿的焦点归设置界面自己的环）。
        """
        if self._swap_busy:
            return "break"                      # v84：幕布下换页中 → 忽略
        if not self.md_full:
            return "break"
        key = self.md_full_key
        self.md_full = False
        self.md_full_key = None
        self._md_full_hide_view()
        if not self._in_settings():
            if key:
                self.select_key(key, focus=False)   # v83：焦点落回最后看的那一题那一行
            self._refocus_active_tree()         # v43 同款：光 focus_set 不够，SetFocus 才拉得回
        return "break"

    def _sync_preview(self, cell):
        """v50：切格（← / → / 跳页）时同步侧栏预览 —— 只在它**打开时绑定的那一格**露面。

        跟设置页（v48）/ 全屏 md（v45）同一套规矩：走开 = 只是看不见（`prev_open` /
        `_prev_key` / `prev_cell` 都留着），走回来原样再现（`_prev_show_view`，不重导航）；
        Esc / 同题再回车才是真收（`_hide_preview`）。全屏 md 占着同一个 holder 时不动它
        （两档互斥 —— 切档 / 进全屏时侧栏已被真收，见 `on_theme_pick` / `_enter_md_full`）。
        """
        if not self.prev_open or self.md_full:
            return
        if cell == self.prev_cell:
            self._prev_show_view()
        else:
            self._prev_hide_view()

    def _on_tab_changed(self, event=None):
        """`<<NotebookTabChanged>>`：v31 的「统计页计数」+ v50 的侧栏预览 + v51 的搜索框可见性，
        都跟着切页走。

        `nb.select()` 的**所有**调用点都发这个事件（本机 Tk 8.6 实测：程序性的也发），
        所以搜索框回车回总表、统计页子行回车跳总表这类**不经 `_goto_cell` 的跳页**也照顾
        得到。`_goto_cell` 里另有一发显式 `_sync_preview` —— 同一格来回不发事件，那一路靠它。
        """
        self._apply_know_count()
        self._apply_search_visible()         # v51：搜索框 /「筛出 N 题」只留总表页（同趟车）
        self._sync_preview(self._cell_of_current_page())

    def parse_problem_url(self, row):
        """v12 立、v79 改：Alt+Enter 的解析链（**只读**：不改任何文件、不产生备份）。

        场次（如 `周赛 164` / `Div.2 1124`）→ 读该场题解 md（`toolutil.contest_paths`，
        就是本 GUI 回车打开的那份），取里面的比赛链接 → 拼单题页 URL：
          · 牛客 `ac.nowcoder.com/acm/contest/<cid>` → `…/<cid>/<字母>`
          · AtCoder `atcoder.jp/contests/<id>` → `…/tasks/<id>_<字母小写>`
          · CF `codeforces.com/contest/<id>` → `…/problem/<字母>`
          · 洛谷题面页按 pid——先从 `_work\题单.md` 找，找不到就报提示
        返回 (url, None)；失败 (None, 原因)：「这场还没接」（场次不认）/
        「没找到这场比赛的原题链接」（题解文件不在 / 里面没有链接行）。
        """
        name, num = toolutil.parse_contest(row["场次"])
        if name is None:
            return None, "这场还没接"
        rdir, sol = toolutil.contest_paths(self.data_root, name, num)
        try:
            with io.open(sol, "r", encoding="utf-8", errors="replace") as f:
                text = f.read()
        except OSError:
            return None, "没找到这场比赛的原题链接"
        plat = toolutil.SERIES[name]["plat"]
        lt = row["题号"]
        if plat == "nowcoder":
            m = re.search(r"ac\.nowcoder\.com/acm/contest/(\d+)", text)
            if m:
                return "https://ac.nowcoder.com/acm/contest/%s/%s" % (m.group(1), lt), None
        elif plat == "atcoder":
            m = re.search(r"atcoder\.jp/contests/([A-Za-z0-9_-]+)", text)
            if m:
                cid = m.group(1)
                return "https://atcoder.jp/contests/%s/tasks/%s_%s" % (cid, cid, lt.lower()), None
        elif plat == "codeforces":
            m = re.search(r"codeforces\.com/contest/(\d+)", text)
            if m:
                return "https://codeforces.com/contest/%s/problem/%s" % (m.group(1), lt), None
        else:                            # luogu：题面页按 pid——先从 _work\题单.md 找
            p = os.path.join(rdir, "_work", "题单.md")
            if os.path.exists(p):
                try:
                    with io.open(p, "r", encoding="utf-8", errors="replace") as f:
                        for ln in f.read().split("\n"):
                            c = toolutil.split_cells(ln)
                            if c and len(c) >= 3 and c[0] == lt \
                                    and re.fullmatch(r"[A-Za-z]+\d+", c[2]):
                                return ("https://www.luogu.com.cn/problem/%s" % c[2]), None
                except OSError:
                    pass
            return None, "洛谷按题号 pid 打开（_work\\题单.md 不在，订不到链接）"
        return None, "没找到这场比赛的原题链接"

    def _do_open_url(self, url):
        """v12：真正「打开」这一下 —— 单独一层好换：测试里把 self._opener 换成假函数，就绝不真开浏览器。"""
        if self._opener is not None:
            self._opener(url)

    def _on_problem_key(self, event=None):
        """v12 立、v46 改：**Alt+回车** —— 跳转题目链接（打开牛客原题页）。三棵题目树都挂。

        （v12~v45 这个功能在 `Shift+回车` 上，v46 按用户要求挪到 `Alt+回车` —— 「Shift+回车删除」，
        原 `Alt+回车` 的「打开这题的资料」整条删除。）
        解析只读（parse_problem_url）；打开走 _do_open_url（测试可打桩，绝不真开浏览器）。
        失败 → 右上角消息；浮层 / 一览开着时不响应。
        v45：全屏 md 开着（表格被盖）时同样不响应。
        """
        if self._busy() or self._in_text_widget() or self.md_full:
            return None
        row = self.tree_row(self._active_tree())
        if not row:
            return "break"
        url, why = self.parse_problem_url(row)
        if url is None:
            self.set_msg("打不开：%s" % why, clear_after=TOAST_MS)
            return "break"
        self._do_open_url(url)
        return "break"

    def _on_reload_key(self, event=None):
        """F5 从磁盘重读。v40：设置界面里不响应（重画的表在另一边，设置界面里的数据
        由 `show_set_panel` 在切块时自己刷新）。v62：全屏 md 里同样不响应（独立界面）。
        v78：重读前先扫一遍收件箱（收进来的题跟这一起重画）。"""
        if self._in_settings() or self.md_full:
            return None
        self._inbox_check()
        self.reload()
        return "break"

    # ------------------------------------------------------------ 收件箱（v78）
    def _inbox_startup(self):
        """v78：开窗后扫一遍收件箱 —— 写过盘就顺手重读表格（没有收到东西就什么都不做）。"""
        if self.quiet:
            return
        if self._inbox_check():
            self.reload()

    def _inbox_check(self):
        """v78：收件箱检查 —— 扫 <数据根>\\题解\\_收件箱 里的题解 md，自动收进 TB。

        新增题静默收（含签到）；已在表且一致的静默跳过（幂等）；不一致的弹窗等拍板
        （全部跳过 / 覆盖更新 / 取消本次）。触发：打开工具时（_inbox_startup）/
        F5（_on_reload_key）。quiet（自测 / 冒烟 / 探针）下不跑 —— 绝不碰真数据。
        返回是否写过盘（调用方据此决定要不要重读表格）。
        """
        if self.quiet or self._inbox_win is not None:
            return False
        try:
            plan = INBOX.scan(self.data_root, self.path)
        except Exception as e:                 # 收件箱任何毛病都不能把主程序带崩
            self.set_msg("收件箱：扫描出错（%s）" % e, clear_after=TOAST_MS * 2)
            return False
        if plan["fatal"] or plan["fatal_inbox"]:
            self.set_msg("收件箱：%s" % (plan["fatal"] or plan["fatal_inbox"]),
                         clear_after=TOAST_MS * 2)
            return False
        if not plan["adds"] and not plan["conflicts"] and not plan["errors"]:
            return False                       # 常态：无待办，一个字不说
        mode = "skip"
        if plan["conflicts"]:
            mode = self._inbox_ask(plan)       # "skip" / "overwrite" / None（取消本次）
            if mode is None:
                return False                   # 取消本次：连新题也不收
        try:
            res = INBOX.apply(plan, self.path, mode)
        except Exception as e:
            self.set_msg("收件箱：写入失败（%s）" % e, clear_after=TOAST_MS * 2)
            self._error("收件箱", "写入失败：%s\n（多半是状态表刚被别处改过；重按一次 F5 即可）" % e)
            return False
        parts = []
        if res["added"]:
            parts.append("新增 %d 题" % res["added"])
        if res["updated"]:
            parts.append("按题解更新 %d 题" % res["updated"])
        if res["skipped_conflicts"]:
            parts.append("冲突跳过 %d 题" % res["skipped_conflicts"])
        if res["skipped_existing"]:
            parts.append("已在表 %d 题" % res["skipped_existing"])
        if plan["errors"]:
            parts.append("%d 个文件读不了" % len(plan["errors"]))
        if parts:
            self.set_msg("收件箱：" + "、".join(parts), clear_after=TOAST_MS * 2)
        return bool(res["added"] or res["updated"])

    def _inbox_ask(self, plan):
        """v78：冲突确认弹窗 —— 列出不一致的题（含逐字段差异），三个按钮：
        全部跳过（保持 TB 现状 + 记备忘录）/ 覆盖更新（按题解改）/ 取消本次（什么都不做）。
        返回 "skip" / "overwrite" / None（取消 / 关窗 / Esc）。

        模态（grab_set，开着时主窗收不到键、天然防重入）；Esc = 取消、← / → 切按钮、
        回车 = 当前焦点按钮（初始焦点在「全部跳过」——最保守的一个）。
        """
        if self._inbox_win is not None:
            return None
        win = tk.Toplevel(self.root)
        win.title("收件箱：与 TB 不一致的题")
        self.ime.detach_tree(win)              # v8：独立 Toplevel 一样摘输入法
        self.ime.watch(win)
        win.configure(bg=C_BG)
        win.transient(self.root)
        panel = tk.Frame(win, bg=C_PANEL, highlightthickness=1,
                         highlightbackground=C_ACCENT_LIGHT)
        panel.pack(fill="both", expand=True, padx=12, pady=12)
        tk.Label(panel, text="收件箱：%d 道题与 TB 不一致" % len(plan["conflicts"]),
                 bg=C_PANEL, fg=C_ACCENT_DARK,
                 font=(self.fam, 14, "bold")).pack(pady=(10, 6))
        lines = []
        for it in plan["conflicts"]:
            lines.append("%s %s %s" % (it["contest_text"], it["letter"], it["title"]))
            for field, oldv, newv in it["diffs"]:
                lines.append("    %s：TB「%s」→ 题解「%s」" % (field, oldv, newv))
        if plan["adds"]:
            lines.append("")
            lines.append("另有 %d 道新题会直接收进 TB" % len(plan["adds"]))
        tk.Label(panel, text="\n".join(lines), bg=C_PANEL, fg=C_TEXT, justify="left",
                 anchor="w", font=(self.fam, 12)).pack(padx=18, pady=(0, 8))
        tk.Label(panel, text="跳过 = 保持 TB 现状，同一份题解不再提醒（文件一改会重新提示）",
                 bg=C_PANEL, fg=C_MUTED, font=(self.fam, 11)).pack(pady=(0, 6))
        btns = tk.Frame(panel, bg=C_PANEL)
        btns.pack(pady=(0, 10))
        result = {"mode": None}

        def close():
            self._inbox_win = None
            try:
                win.grab_release()
            except tk.TclError:
                pass
            try:
                win.destroy()
            except tk.TclError:
                pass

        def pick(mode):
            result["mode"] = mode
            close()

        b_skip = tk.Button(btns, text="全部跳过", width=10, command=lambda: pick("skip"))
        b_over = tk.Button(btns, text="覆盖更新", width=10, command=lambda: pick("overwrite"))
        b_cancel = tk.Button(btns, text="取消本次", width=10, command=lambda: pick(None))
        for b in (b_skip, b_over, b_cancel):
            b.pack(side="left", padx=6)

        def on_enter(event=None):
            f = win.focus_get()
            (f if isinstance(f, tk.Button) else b_skip).invoke()
            return "break"

        def on_arrow(step):
            lst = [b_skip, b_over, b_cancel]
            f = win.focus_get()
            i = lst.index(f) if f in lst else 0
            lst[(i + step) % len(lst)].focus_set()
            return "break"

        win.bind("<Escape>", lambda e: pick(None))
        win.bind("<Return>", on_enter)
        win.bind("<KP_Enter>", on_enter)
        win.bind("<Left>", lambda e: on_arrow(-1))
        win.bind("<Right>", lambda e: on_arrow(1))
        # v85：A / D 同 ← / →（「WASD 接上所有界面」——收件箱冲突弹窗这处漏网）
        win.bind("<Key-a>", lambda e: on_arrow(-1))
        win.bind("<Key-d>", lambda e: on_arrow(1))
        win.protocol("WM_DELETE_WINDOW", lambda: pick(None))
        win.update_idletasks()
        x = self.root.winfo_rootx() + max(0, (self.root.winfo_width() - win.winfo_reqwidth()) // 2)
        y = self.root.winfo_rooty() + max(0, (self.root.winfo_height() - win.winfo_reqheight()) // 3)
        win.geometry("+%d+%d" % (max(0, x), max(0, y)))
        try:
            win.grab_set()
        except tk.TclError:
            pass
        self._inbox_win = win
        b_skip.focus_set()
        win.focus_force()
        win.wait_window()                      # 模态等待（事件循环继续跑，界面不卡）
        return result["mode"]

    # ------------------------------------------------------------ 键盘进搜索
    def _focus_widget(self):
        try:
            return self.root.focus_get()
        except (KeyError, tk.TclError):
            return None

    def _in_text_widget(self):
        """焦点是不是在「要收普通字符」的控件里（v18：只剩搜索框一个）——那时快捷键让位。"""
        return self._focus_widget() is self.ent_search

    def _busy(self):
        return self.popup is not None

    def _on_search_focus_out(self, event=None):
        """v49：焦点离开搜索框 → 清掉选区（修「Tab 走开后残留灰底白字」）。

        只清选区：搜索词不动、撤销栈不动（`focus_search` 下次进来照旧全选）。
        """
        try:
            self.ent_search.select_clear()
        except Exception:
            pass

    def focus_search(self):
        self.ent_search.focus_set()
        self.ent_search.selection_range(0, "end")   # 全选已打的内容，直接重打
        return "break"

    def _on_focus_search(self, event=None):
        """`F` = 跳到搜索框（v32.3 挂在树上；v51 起搜索框只在总表页 —— 别的界面按 F
        先切回总表那一格再进框）。"""
        if self._busy() or self._in_text_widget():
            return None                             # 已在输入框里：让 / 当普通字符打进去
        if self.md_full:
            return "break"                          # v62：全屏 md 里没有搜索框（独立界面）→ 不响应
        if self._in_settings():                     # v40 / v55：搜索框在主界面那半边
            self.set_msg("搜索框在主界面 —— 先退出设置（? / Esc）", clear_after=TOAST_MS)
            return "break"
        if self.nb.index(self.nb.select()) != 0:
            self._goto_cell(0)                      # v51：搜索只在总表 —— 先切回总表那一格
        return self.focus_search()

    def _esc_search(self, event=None):
        """搜索框里 Esc：有字先清空（留在框里）；空 → 回总表表格。

        v17 的「清空后按当前页重画」在 v51 收窄成「重画总表」（搜索只属于总表页）。
        v18：面板拆除后不再有「先收面板」那一步。
        v45：全屏 md 开着 → Esc 先收 md（一步一件事；搜索词不动）。
        """
        if self.md_full:
            return self._exit_md_full()
        if self.var_search.get():
            self.var_search.set("")
            self._reset_search_undo()       # v19：清空 = 程序性整框改写 → 撤销栈重置
            self.refresh_view()             # v51：框只在总表页 —— 清完重画总表
            return "break"
        self._active_tree().focus_set()
        return "break"

    def _jump_to_table(self, event=None):
        """搜索框里 Enter / ↑ / ↓ —— 跳回总表看搜出来的题（搜索词保留）。

        v17 的「按页分派」（统计页 Enter = 落知识点清单）随 v51「搜索框只留总表页」作废：
        这组键只有在总表页才按得到；留下的 `select(0)` 兜底不删（防御）。
        """
        keep = self.selected_key()
        if self.nb.index(self.nb.select()) != 0:
            self._select_page(0)                    # v59：切页与第一行落实同一拍
        self.refresh_view(keep=keep)
        tree = self._active_tree()      # v70：分屏页露着时焦点落分屏页那张表（别落到被盖住的总表）
        sel = list(tree.selection())
        if sel:
            tree.see(sel[0])
        tree.focus_set()
        return "break"

    def _on_row_esc(self, event=None):
        """在**行（表格 / 清单）上**按 Esc。

        四条路（按顺序判）：
        ① **统计页**：焦点在**展开的父行**、或它下面的**子行**上 → **收起那个父行**、光标移到父行
           （= 把展开收回去，不走清搜索 / 退回）；到**未展开的父行 / 普通叶行** → 落到下面 ②③ 的一般逻辑。
        ② **从统计页跳来、且搜索框里**仍含**那个知识点名**（后面可再追加别的字段）→ 清词 + 原路
           退回统计页、展开来源行的父、选中那一行（`_know_search_origin` 记着来源；名字被改掉就不走这条）。
        ③ 有搜索词 → 清掉、回全量。
        ④ 没词 → 焦点送进搜索框（接着打字）。
        ③④ 只在**总表页**走（v51：搜索框只留总表）—— 看板 / 统计页上 ①② 都不命中就到此为止。
        搜索框自己的 `_esc_search`（清空 / 回表格）是另一回事。

        v43：**预览栏开着时整个 Esc 先给它** —— 第一下只收起右侧 md 预览（用户 2026-10-06 拍板
        「只关预览、一步一件事」）：搜索词 / 收父行都不动；再按一下才走上面那四条路。
        v45：**全屏 md 开着时同理、且它是唯一出口** —— P 在全屏里不响应，Esc 收 md 回主表
        （用户拍板「md 不会收起，md 只能按 Esc 收起」）。
        v50：「预览开着」改判「预览**露在这一格上**」（`_prev_shown()`）—— 切走藏起来的那份
        不算（别的格上没有题解页，Esc 走它自己那四条路）。
        """
        if self.md_full:
            return self._exit_md_full()
        if self._prev_shown():
            self._hide_preview()
            return "break"
        if self._collapse_open_parent():
            return "break"
        if self._return_to_know_row():
            return "break"
        if self.nb.index(self.nb.select()) != 0:
            # v51：搜索框只在总表页 —— 其他页（看板 / 统计）到此为止：不碰搜索词、也不送焦点
            return "break"
        if self.var_search.get():
            self.var_search.set("")
            self._reset_search_undo()        # v19：清空 = 程序性整框改写 → 撤销栈重置
            for sync in self._ph_syncs:      # v15：程序改空 var 不触发 KeyRelease，手动同步占位提示
                sync()
            self.refresh_view()              # v51：框只在总表页 —— 清完重画总表
            return "break"
        self.focus_search()                  # 没词 → 焦点送到搜索框（选中已打的字，直接重打）
        return "break"

    def _collapse_open_parent(self):
        """v18：统计页上「收起展开的行」—— 命中才做，返回 True 表示已处理。

        v97（多级）：焦点行若**自己展开着**（任意层，`▾` 且名字在 `know_open`）→ 收起它自己；
        否则（焦点在某个子行上）→ 收起它的**直接父行**。做：从 `know_open` 去掉那个名字、
        重画、光标移到那行。
        """
        if self.nb.index(self.nb.select()) != 2:
            return False
        sel = list(self.know_tree.selection())
        if not sel:
            return False
        iid = sel[0]
        name, _top, has_kids = self._know_row_info(iid)
        if name is None:
            return False
        if has_kids and name in self.know_open:
            target = name                            # 焦点正落在展开着的行上（任意层）→ 收它自己
        else:
            target = self._know_parent_of(iid)       # 子行 → 收起它的直接父行
            if target is None:
                return False
        if target not in self.know_open:
            return False                             # 那行没展开 → 不归这条管
        self.know_open.discard(target)
        self.refresh_know(keep_name=target)          # 收起后光标停到那行
        self.know_tree.focus_set()
        return True

    def _return_to_know_row(self):
        """Esc 的原路退回 —— 满足条件才做，返回 True 表示已处理。

        条件（v18 放宽）：① 现在在总表页；② `_know_search_origin` 还在；③ 搜索框里**仍完整包含**
        跳过来那个知识点名（`_origin_valid()`，后面可再追加别的字段如 `分布压缩 DP E 1300`）。
        命中就：清词 → 切回统计页 → 展开来源那行的父 → 选中那一行 → 焦点落统计清单。

        v19：资格**在这里现算**（不再靠打字时预判）—— 打到一半（如 `二分查找 ` 还差前缀和）不会
        把 origin 提前清掉，回到最终内容再判。
        """
        origin = self._know_search_origin
        if not origin or self.nb.index(self.nb.select()) != 0:
            return False
        if not self._origin_valid():
            return False                     # 知识点名被改动 / 删掉 → 不退回
        self._know_search_origin = None
        self.var_search.set("")
        self._reset_search_undo()            # v19：退回整框清词 → 撤销栈重置
        for sync in self._ph_syncs:          # 程序改空 var 不触发 KeyRelease，手动同步
            sync()
        self._select_page(2)                 # 切回统计页（v59：当场落实第一行）
        # v97（多级）：来源名沿词典「子 → 父」上溯，**整条祖先链**都展开，那行才看得见
        groups = getattr(KD.load(), "groups", {}) or {}
        child_to_parent = {}
        for p, kids in groups.items():
            for kid in kids:
                child_to_parent[kid] = p
        cur, seen_up = origin["name"], set()
        while cur in child_to_parent and cur not in seen_up:
            seen_up.add(cur)
            cur = child_to_parent[cur]
            self.know_open.add(cur)
        self._sync_search_placeholder()
        self.refresh_know(keep_name=origin["name"])   # 按名字保选中（子行 / 顶层行都认）
        self.know_tree.focus_set()
        return True

    # ------------------------------------------------------------ 排序
    def _apply_sort(self, col=None, desc=None):
        """col=None 不改字段、desc=None 不改方向。

        v4：换排序后选中行**钉在原行号**（点表头 / S / R 都走这条）—— 原来第 x 行就还是第 x 行，
        行里的题换成别的；越界贴最后一行。「跟着那道题走」自 v4 起作废（搜索仍跟题；v9 筛选删掉）。
        """
        keep_idx = self._index_of(self.tree)
        if col is not None:
            self.sort_col = col
        if desc is not None:
            self.sort_desc = bool(desc)
        self.refresh_view(keep_index=keep_idx)
        self.tree.focus_set()

    def on_sort(self, col):
        """点表头：首点升序，再点降序。"""
        if col not in SORTABLE:
            return
        self._apply_sort(col, (not self.sort_desc) if col == self.sort_col else False)

    def _sort_next_key(self, delta=1, event=None):
        """v21：Ctrl+← / Ctrl+→ —— 在三个排序字段之间退 / 进一格（场次 → 难度 → 日期 → 场次），
        切字段一律回到升序。delta = +1（→）/ -1（←）。

        （v3~v20 这两个动作挂光秃秃的 `S` / `R`；v21 按用户的键位方案改挂 Ctrl+方向键，
        旧字母键已解绑。）
        v17 起的规矩保留：焦点在统计页上时改走统计排序（Ctrl+方向键 = 反转统计升降序）——
        别把人弹回总表。v40：设置界面里不响应（排的是主界面的表）。
        """
        if self._busy() or self._in_text_widget() or self._in_settings():
            return None
        if self.nb.index(self.nb.select()) == 2:
            return self._know_sort_toggle()         # 统计页：Ctrl+方向键 = 反转统计升 / 降序
        if self.nb.index(self.nb.select()) != 0:
            self._select_page(0)                    # 排序只对总表页有意义，先把页切过去（v59）
        i = SORTABLE.index(self.sort_col) if self.sort_col in SORTABLE else 0
        self._apply_sort(SORTABLE[(i + delta) % len(SORTABLE)], False)
        return "break"

    def _sort_toggle_key(self, delta=1, event=None):
        """v21：Ctrl+↑ / Ctrl+↓ —— 在「升序 / 降序」两种之间翻转。

        （v3~v20 挂 `S` / `R`；v21 改挂 Ctrl+方向键，旧字母键已解绑。）
        v17 起的规矩保留：焦点在统计页上时改走统计排序（Ctrl+方向键 = 反转统计升降序）。
        v40：设置界面里不响应（翻的是主界面的表）。
        """
        if self._busy() or self._in_text_widget() or self._in_settings():
            return None
        if self.nb.index(self.nb.select()) == 2:
            return self._know_sort_toggle()         # 统计页：Ctrl+方向键 = 反转统计升 / 降序
        if self.nb.index(self.nb.select()) != 0:
            self._select_page(0)                    # v59：切页与第一行落实同一拍
        self._apply_sort(None, not self.sort_desc)
        return "break"

    def _on_sort_toggle_site(self, delta, event=None):
        """v85：**Ctrl+↑ / ↓ 的树级挂点** —— 走原动作（同 root 那份），**无条件 break**。

        为什么要有它（用户报「Ctrl+上/下不应该让当前行上下移动」）：ttk 的类绑定
        `<Key-Up>` / `<Key-Down>`（`ttk::treeview::Keynav`）**连带 Ctrl 的方向键一起认**
        —— 实测真窗口里 Ctrl+↑ / ↓ 除了翻升降序、还会把选中行挪一行。类绑定排在 root
        绑定**之前**，root 那边的 "break" 拦不住它；树级（widget 级）绑定先跑，这里 break
        就把 Keynav 压掉（与 PgUp/PgDn 的 `_move_sel` 同一条先例；见 2629 行「widget 级
        handler 返回 break 会压过内建」）。（Ctrl+← / → 不挂：Keynav 的左右只在真父子行上
        有活，本库四张表全平铺、那对本来就没动作 —— 2026-10-07 实测。）
        """
        self._sort_toggle_key(delta, event)
        return "break"

    # ------------------------------------------------------------ 快捷键一览（v87：并进设置页）
    # v87（用户点名「把快捷键一览并进设置页,在左边加一行,写快捷键一览,只读,右侧界面显示快捷键」）：
    # 原来是 `?` 弹独立 Toplevel（`open_help` / `close_help` / `toggle_help` / `_on_help_key` +
    # help_win / help_prev / help_lbl 三个字段）——整组删除，内容并进设置页第三块
    # （`_build_set_help`，只读 Text）；`help` 动作随之从注册表删除，`?` 让给「设置界面 开 / 关」。
    # `_mono_family` 留着：新块那份只读文本还用它（等宽字体才对齐）。
    def _mono_family(self):
        try:
            fams = set(tkfont.families(self.root))
        except tk.TclError:
            return "Courier New"
        for c in ("Consolas", "Courier New", "Lucida Console"):
            if c in fams:
                return c
        return "TkFixedFont"

    # ------------------------------------------------------------ 行内浮层
    def _on_open_key(self, event=None):
        """v5 立、v46 改：**Ctrl+回车** —— 弹状态浮层改状态（原「行上回车」的活，挪过来）。

        浮层内部照旧：↑↓ 选、1~6 直选、回车确认、Esc 取消（浮层里那份 `<Return>` 是它自己的固定键）。
        """
        if self.md_full:                     # v45：全屏 md 开着 → 不开状态浮层（表被盖着）
            return "break"
        tree = event.widget if event else self._active_tree()
        row = self.tree_row(tree)
        if row:
            self.open_status_popup(row, tree)
        return "break"

    def _on_double(self, event):
        tree = event.widget
        iid = tree.identify_row(event.y)
        if not iid:
            return "break"
        tree.selection_set(iid)
        tree.focus(iid)
        row = self.row_by_iid(iid)
        if row:
            self.open_status_popup(row, tree)
        return "break"

    def open_status_popup(self, row, tree):
        """在该行旁边弹 6 个带序号的状态（`1. 未做`…`6. 巩固`）：↑↓ 选、回车确认、Esc 取消。

        v5：每项前缀 = 序号；数字键 1~6 与序号一一对应（按下即确认第 N 项）；
        底部那行「数字直选 ｜ Enter 确认 ｜ Esc 取消」提示已删（`?` 一览是唯一说明处）。
        v10：当前值不在 6 项内（真表里历史遗留的旧值）→ **不预选**（curselection 为空），
        但数字直选照旧好使（按 1 直接写「未做」）。
        """
        self.close_popup()
        if row is None:
            return
        cur = row["状态"] if row["状态"] in STATES else None
        try:
            box = tree.bbox(str(row["_i"]))
        except tk.TclError:
            box = ""
        if box:
            x = tree.winfo_rootx() + box[0] + box[2] + 6
            y = tree.winfo_rooty() + box[1]
        else:
            x = tree.winfo_rootx() + 120
            y = tree.winfo_rooty() + 60
        pop = tk.Toplevel(self.root)
        pop.wm_overrideredirect(True)
        pop.configure(bg=C_ACCENT)
        lb = tk.Listbox(pop, height=len(STATES), width=13, font=(self.fam, 13),
                        activestyle="none", selectmode="browse", exportselection=False,
                        highlightthickness=0, bd=0, bg=C_PANEL, fg=C_TEXT,
                        selectbackground=C_ACCENT, selectforeground="#ffffff")
        lb.pack(padx=2, pady=2)
        for i, s in enumerate(STATES):
            lb.insert("end", "%d. %s" % (i + 1, s))   # v5：每项带序号（数字键 1~6 与之一一对应）
            if s == cur:
                lb.itemconfig(i, background=C_ACCENT_LIGHT, foreground=C_ACCENT_DARK)
        if cur is not None:                         # v10：历史旧值不在 6 项里 → 不预选（按 1 仍能写「未做」）
            idx = STATES.index(cur)
            lb.selection_clear(0, "end")
            lb.selection_set(idx)
            lb.activate(idx)
            lb.see(idx)
        for k in range(len(STATES)):                # v3：数字直选 1~6（按下即确认第 N 个状态）
            for _seq in self._seqs_for("status_%d" % (k + 1)):   # v26：跟着自定义键走（含小键盘副键）
                lb.bind(_seq, lambda e, i=k: self._popup_pick(i))
        lb.bind("<Up>", lambda e: self._popup_move(-1))
        lb.bind("<Down>", lambda e: self._popup_move(1))
        # v47：W / S 在浮层里同样好使（A / D 在浮层没对应活，不挂）—— 转发成 ↑ / ↓ 走上面两条
        for _k in ("w", "s"):
            lb.bind("<Key-%s>" % _k, self._on_wasd)
        # v26：浮层里回车永远是「确认」（固定）—— 自定义的回车键若不同于它，再补一条
        for _seq in dict.fromkeys(self._seqs_for("enter") + ["<Return>", "<KP_Enter>"]):
            lb.bind(_seq, lambda e: self._popup_confirm())
        lb.bind("<Escape>", lambda e: self._popup_cancel())
        lb.bind("<BackSpace>", lambda e: self._popup_cancel())   # v65：Backspace 同义
        lb.bind("<Double-1>", lambda e: self._popup_confirm())
        # v5：原来这里有底部一行「数字直选 ｜ Enter 确认 ｜ Esc 取消」提示，按用户要求删掉——
        # 加了序号后它也没用了；快捷键说明以 `?` 一览为唯一处。
        pop.bind("<Button-1>", self._popup_click)   # grab 会把浮层外的点击送到浮层这儿
        # v8：浮层也是独立 Toplevel —— 摘掉它（含列表框）的输入法，兜底挂到它自己身上
        self.ime.detach_tree(pop)
        self.ime.watch(pop)

        pop.update_idletasks()
        pw, ph = pop.winfo_reqwidth(), pop.winfo_reqheight()
        sw, sh = self.root.winfo_screenwidth(), self.root.winfo_screenheight()
        x = max(0, min(x, sw - pw - 6))
        y = max(0, min(y, sh - ph - 6))
        pop.geometry("+%d+%d" % (x, y))
        pop.deiconify()
        try:
            pop.grab_set()
        except tk.TclError:
            pass
        lb.focus_force()
        self.popup, self.popup_lb, self.popup_row, self.popup_tree = pop, lb, row, tree

    def _popup_click(self, event):
        """点浮层内部（列表框）不动；点浮层外（被本地 grab 重定向过来）＝取消。"""
        w = event.widget
        if w is not None:
            try:
                if w is self.popup_lb or w.winfo_toplevel() is self.popup:
                    return None
            except tk.TclError:
                return None
        return self._popup_cancel()

    def _popup_pick(self, i):
        """浮层里按 1~6：直接确认第 i+1 个状态（越界忽略）。"""
        lb = self.popup_lb
        if lb is None or not (0 <= i < lb.size()):
            return "break"
        lb.selection_clear(0, "end")
        lb.selection_set(i)
        lb.activate(i)
        lb.see(i)
        return self._popup_confirm()

    def _popup_move(self, delta):
        lb = self.popup_lb
        if lb is None:
            return "break"
        sel = lb.curselection()
        i = (sel[0] if sel else 0) + delta
        i = max(0, min(lb.size() - 1, i))
        lb.selection_clear(0, "end")
        lb.selection_set(i)
        lb.activate(i)
        lb.see(i)
        return "break"

    def _popup_confirm(self):
        lb, row, tree = self.popup_lb, self.popup_row, self.popup_tree
        sel = lb.curselection() if lb else ()
        state = STATES[sel[0]] if sel else None
        self.close_popup()
        if state and row:
            self.set_status(row, state, tree)
        return "break"

    def _popup_cancel(self):
        self.close_popup()
        return "break"

    def close_popup(self):
        pop = self.popup
        self.popup = self.popup_lb = self.popup_row = self.popup_tree = None
        if pop is not None:
            try:
                pop.grab_release()
            except tk.TclError:
                pass
            try:
                pop.destroy()
            except tk.TclError:
                pass

    # ------------------------------------------------------------ 数字直改 / 打开原题（v12）
    def _on_digit_key(self, i, tree, event=None):
        """v12：树上按 1~6 = 直接用第 i+1 个状态改选中行（= 浮层里按那个数字，但不开浮层）。

        绑在两棵树上、**不绑 root** —— 焦点在搜索框里时数字要照常打进输入框。浮层 / `?` 一览
        开着（`_busy()`）不响应（浮层的数字直选自己走，别双触发）；空表 / 没选中 → 静默 break。
        写盘 / 日期取今天 / 提示 / 自动下移 / 入撤销栈全交给 set_status，一个规矩。

        v26.2（用户实测报 bug「按 Ctrl+1 跟按 1 一样」）：**带 Ctrl / Alt 的数字不算改状态** ——
        Tk 的不带修饰模式 `<Key-1>` 连 Ctrl+1 也匹配，而本处理器是 widget 级、先于 root 跑，
        原来的 `return "break"` 会把 root 上的 `Ctrl+1/2/3` 菜单热键整个吞掉。这里改成
        **让位**（return None、不 break）→ 事件继续冒到 root，菜单热键才接得到。
        """
        if self._busy() or self.md_full:
            return "break"                   # v45：全屏 md 开着 = 表格被盖住 → 不盲改状态
        if event is not None and (getattr(event, "state", 0) & (0x4 | 0x8 | 0x20000)):
            return None                      # 带修饰键：不是「数字直改」，让给上层绑定（v26.2）
        row = self.tree_row(tree)
        if not row:
            return "break"
        if 0 <= i < len(STATES):
            self.set_status(row, STATES[i], tree)
        return "break"

    # ------------------------------------------------------------ 写动作
    def set_status(self, row, state, tree=None):
        """把一行的状态改成 state、日期改成今天，写回 md 并整表刷新。

        v4：改完选中行自动**下移一行**（总表 / 看板一个规矩，已经是最后一行就不动）；
        底部保存提示 3 秒后自动消失。Esc 取消不走这里，所以取消不会移动。
        v10：state 不在 6 个合法值里（旧值「卡住」「只读过」等）→ 直接拒绝，文件一个字不动。
        """
        if state not in STATES:              # v10：非法状态拒绝（浮层不会送来；直接调也要拦）
            self.set_msg("写入失败：%s 不是合法状态" % state, clear_after=TOAST_MS)
            return
        key = (row["场次"], row["题号"])
        tree = tree or self._active_tree()
        idx = self._index_of(tree)          # 改之前那一行在第几行（下移的基准）
        # v29：看板合并清单 —— 改前先记住「原来下一行」（是题目行才记）：改完它还在新清单里
        # 就选它（同类题被踢出时自动落到后一题）；没了 / 原来是类标题行 → 退回按行号下移。
        nxt_iid = None
        if tree is self.today_tree and idx is not None:
            iids_now = list(tree.get_children())
            if idx + 1 < len(iids_now) and not iids_now[idx + 1].startswith(SEG_PREFIX):
                nxt_iid = iids_now[idx + 1]
        # v27：统计页「按场次」视图里改 → 改完移到**本场的下一题**（跳过平台 / 场次行；
        # 已是本场最后一题 → None，退回普通下移逻辑）
        nxt = self._round_next_key(row) if tree is getattr(self, "round_tree", None) else None
        today = datetime.date.today().isoformat()
        old_status, old_date = row["状态"], row["日期"]     # v6 追加：Ctrl+Z 要记下旧值
        try:
            bak, _, _ = save_changes(self.path, key, {"状态": state, "日期": today},
                                     backup_src_root=self.backup_src_root)
        except Exception as e:
            self._error("写入失败", "%s\n\n%s %s" % (e, key[0], key[1]))
            self.set_msg("写入失败：%s" % e)
            return
        if bak is None:
            note = "没有变化，未写盘"
        else:
            # v6 追加：真写盘了才记；v12：改记撤销栈（栈顶 = 最近一步，_last_change 同步成栈顶）
            ch = {"round": key[0], "letter": key[1],
                  "old_status": old_status, "old_date": old_date,
                  "new_status": state, "new_date": today}
            self._undo_stack.append(ch)
            if len(self._undo_stack) > UNDO_MAX:     # 容量外的最老那步丢掉
                del self._undo_stack[0]
            self._redo_stack = []                    # v20：手改新状态 → 复原栈作废（老的重做记录对不上）
            self._last_change = ch
            note = "已保存：%s %s → %s" % (key[0], key[1], state)   # v9：短文案（备份 / 日期不上屏）
        self.reload(note=note, clear_after=TOAST_MS)
        if nxt is not None:                  # v27：按场次视图 → 选中本场下一题
            self._round_select_key(nxt)
        elif nxt_iid is not None and nxt_iid in tree.get_children():
            tree.selection_set(nxt_iid)      # v29：看板 —— 选原来那行的下一题（还在的话）
            tree.focus(nxt_iid)
            tree.see(nxt_iid)
        elif idx is not None:                # 下移一行；末尾（idx+1 越界）就留在原地（v29：看板跳过标题行）
            self._select_index(tree, idx + 1, skip_seg=(tree is self.today_tree))

    def _undo(self, event=None):
        """v6 追加 / v12 扩成多步：Ctrl+Z 撤销上一步状态改动（可连撤，本窗口内有效，不跨重启）。

        栈里的每一步走正常写回流程：重读 → 按 场次+题号 定位 → 只替换 状态/日期 两格 → 备份
        → 复读校验（就是把旧状态 / 旧日期再写一遍，save_changes 原样复用）—— 还原成功才把
        那步弹出（弹掉不压回）。选中行回到那题，底部提示 3 秒消失；栈空 → 只提示，文件一个字
        不动。任何焦点下都生效（挂 root；Entry 没有自己的 Ctrl+Z，不会打架）。
        """
        if self._busy():
            return None
        if not self._undo_stack:
            self.set_msg("没有可撤销的改动", clear_after=TOAST_MS)
            return "break"
        ch = self._undo_stack[-1]
        key = (ch["round"], ch["letter"])
        try:
            bak, _, _ = save_changes(self.path, key,
                                     {"状态": ch["old_status"], "日期": ch["old_date"]},
                                     backup_src_root=self.backup_src_root)
        except Exception as e:
            self._error("撤销失败", "%s\n\n%s %s" % (e, key[0], key[1]))
            self.set_msg("撤销失败：%s" % e)
            return "break"
        self._undo_stack.pop()               # v12：这一步还原成功 → 弹掉
        self._redo_stack.append(ch)          # v20：弹掉的这一步压进复原栈，供 Ctrl+Y 重新做回
        self._last_change = self._undo_stack[-1] if self._undo_stack else None
        if bak is None:
            note = "没有变化，未写盘"
        else:
            note = "已撤销：%s %s → %s" % (key[0], key[1], ch["old_status"])   # v9：短文案
        self.reload(note=note, clear_after=TOAST_MS)
        self._select_problem(key)
        return "break"

    def _redo(self, event=None):
        """v20：Ctrl+Y —— 把刚撤销的那一步状态改动**重新做回来**（撤销的反向）。

        与 `_undo` 对称：从复原栈顶取那一步，走正常写回流程把 **新状态 / 新日期** 再写一遍
        （真写盘 → 走备份、复读校验）—— 成功才把该步从复原栈弹出、压回撤销栈（所以还能再 Ctrl+Z
        撤回来）。复原栈空 → 只提示，文件一个字不动。任何焦点下都生效（挂 root）。
        """
        if self._busy():
            return None
        if not self._redo_stack:
            self.set_msg("没有可复原的改动", clear_after=TOAST_MS)
            return "break"
        ch = self._redo_stack[-1]
        key = (ch["round"], ch["letter"])
        try:
            bak, _, _ = save_changes(self.path, key,
                                     {"状态": ch["new_status"], "日期": ch["new_date"]},
                                     backup_src_root=self.backup_src_root)
        except Exception as e:
            self._error("复原失败", "%s\n\n%s %s" % (e, key[0], key[1]))
            self.set_msg("复原失败：%s" % e)
            return "break"
        self._redo_stack.pop()               # 复原成功 → 从复原栈弹出、压回撤销栈
        self._undo_stack.append(ch)
        if len(self._undo_stack) > UNDO_MAX:
            del self._undo_stack[0]
        self._last_change = ch
        if bak is None:
            note = "没有变化，未写盘"
        else:
            note = "已复原：%s %s → %s" % (key[0], key[1], ch["new_status"])   # v9：短文案
        self.reload(note=note, clear_after=TOAST_MS)
        self._select_problem(key)
        return "break"

    def _select_problem(self, key):
        """v6 追加：把选中行拉回（场次, 题号）那一题 —— 当前页有就留在当前页，没有就回总表看。"""
        cur = self._active_tree()
        here = False
        for iid in cur.get_children():
            r = self.row_by_iid(iid)
            if r and (r["场次"], r["题号"]) == key:
                here = True
                break
        if not here and cur is not self.tree:
            self._select_page(0)                    # v59：切页与第一行落实同一拍
        self.select_key(key, focus=True)

    # ------------------------------------------------------------ 设置界面（v40）
    def _make_settings(self):
        """设置界面（v40）= **整个窗口内容**的另一半：左列表 + 右面板，`?`（v87 起；原 Ctrl+Tab）与原界面互切。

        用户口径（2026-10-06）：「取消现在的题解包,主题,快捷键菜单,用切换页状态替代…现在在主表
        界面按对应快捷键会进入一个设置页界面,里边有导入题解包导出题解包,快捷键设置,主题设置,
        要求统一UI格式」；三问拍板 = **左侧四项 + 右面板** / **全内联、删弹窗** / **Ctrl+Tab 开关式**；
        补充口径：「是整个界面变成设置界面,不是新增…还是一样的上下左右,等等快捷键的操作逻辑」。

        结构（**不是** Notebook 第 4 页 —— 整窗替换；`enter_settings` / `leave_settings` 换 pack）：
            无第一行（v57.4：顶部整条删除、内容上移顶到窗口顶）；消息在**面板标题行右端**（跟标题同行）
            左：两项（快捷键设置 / 主题设置；ttk.Treeview，↑↓ 换项 —— v53 起导入 / 导出删除）
            右：两块面板叠在同一处，选哪项露哪块（`show_set_panel`）
        两块统一成 v31 的口径「顶层标题 + 内容」（16pt 粗体标题 + 12/13pt 内容）。
        键（v55）：↑↓ 换项 · `→` / `Enter` 进右面板 · `←` 回左列表（主题单选钮那处 ← 先在组内挪焦点，
        v63 起**最左端再按 ← 也回左列表**）·
        面板里 ↑↓ 走控件、主题块 ← / → 挪焦点 + **回车确认** · Esc 逐层退（面板 → 左列表 → 退出、回进来
        的那个界面）· `?` 开关（v87 起；原 Ctrl+Tab）· Tab / Shift+Tab 走两站环。设置页独立、不在 ← / → 环上。
        """
        win = tk.Frame(self.root, bg=C_BG)      # 先不 pack：`enter_settings` 才摆
        self.settings_frame = win
        # v57.4：设置页**顶部那一行整条删除**（用户点名「用界面填充上部空白」）—— 左列表 / 右面板
        #        整体上移顶到窗口顶（body 顶部只留 10px 呼吸）；旧的等高空占位 `set_head_spacer`
        #        一并删除（v52 的「设置页与主表第一行等高」对设置页放开 —— 主表三页之间照旧恒高）。
        #        消息（`var_msg2`）挪进**右面板标题行右端**（跟「快捷键设置 / 主题设置」合并一行）——
        #        每块面板的标题行各挂一个同 `textvariable` 的 Label，切块即跟着换。
        self.var_msg2 = tk.StringVar(value="")

        body = tk.Frame(win, bg=C_BG)
        body.pack(fill="both", expand=True, padx=12, pady=(10, 8))
        # 左：两项菜单（v53：导入 / 导出删除后）—— 用 Treeview，选中行的颜色自动跟主表同一套主题映射（「统一 UI」）
        self.set_left = ttk.Treeview(body, show="tree", selectmode="browse",
                                     style="Status.Treeview", height=4)
        # v40.1：列宽 132 → 170（当初为「导入题解包」五个字留的）；v53 后剩两项照旧 170
        self.set_left.column("#0", width=170, stretch=False)
        self.set_left.pack(side="left", fill="y")
        for iid, lab in SET_ITEMS:
            self.set_left.insert("", "end", iid=iid, text=" " + lab)
        # v82：开窗摆哪一块 —— 配置里记着的（上次退出设置页时摆的那块）优先，认不出才回第一项
        _b0 = normalize_set_block(self.cfg.get("set_block")) or SET_ITEMS[0][0]
        self.set_left.selection_set(_b0)
        self.set_left.focus(_b0)                 # v53：focus 行 —— 缺了它 Tk 的 ↑↓（Keynav）整个不响应
        self.set_left.bind("<<TreeviewSelect>>", lambda _e: self.show_set_panel())
        self.set_left.bind("<FocusIn>", lambda _e: self._set_focus_note("left"), add="+")   # v82
        # v55：设置页独立（不再占主表那一格）—— ← / → 改成页内分工：`→` 进右面板（= Enter，
        # 用户拍板「← 去列表、→ 进面板」）；`←` 在列表上不响应（面板里 `←` 回列表照旧）。
        self.set_left.bind("<Right>", self._set_focus_panel)
        for seq in ("<Return>", "<KP_Enter>"):    # Enter：进右面板
            self.set_left.bind(seq, self._set_focus_panel)
        self.set_left.bind("<FocusIn>", self._refresh_border_focus, add="+")
        self.set_left.bind("<FocusOut>", self._refresh_border_focus, add="+")
        self._row_border(self.set_left)          # 黑色边框档：左列表的选中项也画一圈线（v38 先例）

        right = tk.Frame(body, bg=C_BG)
        right.pack(side="left", fill="both", expand=True, padx=(14, 0))
        for key in ("keys", "theme", "help"):    # v87：加第三块「快捷键一览」（原 `?` 弹窗并进来）
            self.set_panels[key] = tk.Frame(right, bg=C_BG)
        self._build_set_keys(self.set_panels["keys"])
        self._build_set_theme(self.set_panels["theme"])
        self._build_set_help(self.set_panels["help"])       # v87
        self.show_set_panel(_b0)                 # v82：跟着左列表的初始选中（= 配置里那块）摆

    # --- 设置界面：切换 / 摆面板 / 焦点 ---------------------------------------
    def _in_settings(self):
        """设置界面开着吗（整窗替换，不是 Notebook 页 —— 判它有没有 pack 管理器）。"""
        return bool(self.settings_frame is not None and self.settings_frame.winfo_manager())

    def _on_settings_key(self, event=None):
        """`?`（可自定义；v87 起默认键 = `?`，原 Ctrl+Tab 解绑）：主界面 ⇄ 设置界面 整屏切换。

        **开关式**：主界面按一下进设置、设置里再按一下（或 Esc）退出。v55：设置页独立后
        退出 = 回**进来的那个界面**（`_settings_from_cell`；用户拍板「哪来的回哪去」）——
        v42「回主表那一格」的口径作废。
        浮层开着时不响应（它带 grab，叠上去要打架）。
        v62：全屏 md 里也不响应（独立界面 —— 别的界面进不去；Esc / md 里回车才是出口）。
        v87：**搜索框里打字让位** —— `?` 是裸键，焦点在搜索框时按它 = 打问号，这一发放行走
        Entry（不然每打一个问号就把整窗切成设置页）；判据 = `event.char` 非空（会产生字符）
        且不带 Ctrl / Alt —— 用户改回带修饰的组合键、或 F 键写法时照旧正常触发。
        """
        if self._in_text_widget() and event is not None and event.char and \
                not (event.state & (0x4 | 0x8 | 0x20000)):   # v87：裸字符键在搜索框里 = 打字
            return None
        if self._busy() or self.md_full or self.key_capture:   # v80：改键捕获中不动
            return "break"
        if self._in_settings():
            self.exit_settings()
        else:
            self.enter_settings()
        return "break"

    def _on_settings_esc(self, event=None):
        """root 级 Esc：设置在 = 逐层退；v45：全屏 md 开着 = 收它回主表（兜底）。

        树上 / 搜索框的 Esc 各有自己的绑定、会先吃掉事件 —— 那两个入口已单独接了 md 判断；
        这里接的是"冒到 root"的那条路（比如焦点在不吃 Esc 的控件上）。
        """
        if not self._in_settings():
            if self.md_full:
                return self._exit_md_full()
            return None
        return self._key_dialog_esc()

    def enter_settings(self):
        """进设置界面：主界面整块收起，摆设置界面、焦点落**上次退出时那一站**。

        v55：进来前先记 `_settings_from_cell`（此刻在哪个格）—— 退出回那儿（独立、不绑主表）；
        已在设置里时重进不动它（幂等）。
        v82（用户口径「记住最后一次退出设置页时的焦点位置」）：落点不再恒为左列表 —— 见
        `_restore_set_focus`（焦点站随 `_set_focus_mem`，运行内 → 配置 `set_focus`）。
        """
        if not self._in_settings():
            self._settings_from_cell = self._cell_of_current_page()
        self.main_frame.pack_forget()
        self.settings_frame.pack(fill="both", expand=True)
        self.show_set_panel()
        self._restore_set_focus()

    def _set_focus_note(self, station):
        """v82：记「此刻焦点在设置界面的哪一站」（FocusIn 一路记，退出时不用再补）。"""
        self._set_focus_mem = station

    def _restore_set_focus(self):
        """v82：把焦点落回**上次退出设置页时那一站**（左列表 / 快捷键表 / 主题块 / 一览块）。

        主题块那一站再精细一层：落回上次那颗钮（`_theme_focus_target` —— v76 的运行内记忆 →
        配置 `theme_focus`）。**只在「那一站此刻确实摆着」时才落**（比如流程里被
        `open_settings_section` 定位到别的块、或配置里的块与当前块对不上）→ 否则落左列表；
        任何 TclError（控件没建 / 已销毁）也回左列表 —— 这一支绝不许把进设置卡住。
        v87：加 help 站（一览块那份只读 Text）。
        """
        tgt = None
        if self._set_focus_mem == "keys" and self.set_panel == "keys":
            tgt = self.key_tv
        elif self._set_focus_mem == "theme" and self.set_panel == "theme":
            tgt = self._theme_focus_target()
        elif self._set_focus_mem == "help" and self.set_panel == "help":
            tgt = self.help_tx
        try:
            (tgt or self.set_left).focus_set()
        except tk.TclError:
            try:
                self.set_left.focus_set()
            except tk.TclError:
                pass

    def _set_focus_key(self):
        """v82：写进配置的「焦点站」值（认不出的站 / 没记过 → None）。"""
        return normalize_set_focus(self._set_focus_mem)

    def _set_block_key(self):
        """v82：写进配置的「摆着哪一块」值（= 左列表当前选中项；脏值 → None）。"""
        try:
            sel = self.set_left.selection() if self.set_left is not None else ()
        except tk.TclError:
            sel = ()
        return normalize_set_block(sel[0] if sel else None)

    def exit_settings(self):
        """v55：退出设置 = 回**进来的那个界面**（用户拍板「哪来的回哪去」）。

        设置页独立后不再占主表那一格（v42~v48 的「走开只是看不见 / 走回来原样再现」整族作废）——
        收起设置显示、`_goto_cell(_settings_from_cell)` 一步回到来源格：切页 / 重画 / 落焦点
        （离屏期间 bbox 拿不到值，黑框 / 遮色条先补摆一次 —— v25 先例）。
        Ctrl+Tab（开关式）、Esc（逐层退到底）、顶栏「返回 (Esc)」都走这里。
        """
        if not self._in_settings():
            return
        self.settings_frame.pack_forget()
        self.main_frame.pack(fill="both", expand=True)
        self._sync_all_row_borders()
        self._sync_today_bar()
        self._goto_cell(self._settings_from_cell)

    def leave_settings(self):
        """v55：保留老调用名 —— = `exit_settings`（回来源格）；关设置页的口径自此只有一条。"""
        self.exit_settings()

    def open_settings_section(self, key):
        """Ctrl+3（v40 立；v53 起 Ctrl+1 已删 —— 只剩「设置界面 · 快捷键设置」）：开界面并定位到某块。"""
        if not self._in_settings():
            self.enter_settings()
        try:
            self.set_left.selection_set(key)
            self.set_left.focus(key)         # v53：focus 行跟着走 —— Tk 的 ↑↓（Keynav）只认它
            self.set_left.see(key)
        except tk.TclError:
            pass
        self.show_set_panel(key)
        self._set_focus_panel()

    def show_set_panel(self, key=None):
        """左列表选中哪项、右面板就摆哪块（v40）。"""
        if key is None:
            sel = self.set_left.selection()
            key = sel[0] if sel else SET_ITEMS[0][0]
        self.set_panel = key
        for k, frame in self.set_panels.items():
            if k == key:
                frame.pack(fill="both", expand=True)
            else:
                frame.pack_forget()
        if key == "keys":
            self._key_dialog_refresh()       # 每次摆出来都按当前 keymap 重刷一遍
        elif key == "help":
            self._refresh_help_panel()       # v87：一览块同样「摆出来就按当前键重刷」
        self._set_border_sync(self.set_left)

    def _set_focus_panel(self, event=None):
        """左列表 → 右面板（v42 起由 `Enter` 触发；`→` 让给换界面）：焦点落到当前那块的第一件控件。

        v76：「主题设置」块例外 —— 先落**上次聚焦的那个钮**（本次运行记的 → 配置里存的，见
        `_theme_focus_target`），没有才回第一件（用户口径「主题设置记住上次进入最后的焦点位置」）。
        """
        if self.set_panel == "theme":
            tgt = self._theme_focus_target()
            if tgt is not None:
                try:
                    tgt.focus_set()
                    return "break"
                except tk.TclError:
                    pass
        for w in self._set_focus.get(self.set_panel, []):
            try:
                # 禁用的按钮跳过去（选了才亮的那些）；v87：只读 Text（一览块）**不跳** ——
                # 它 state=disabled 只是防编辑，聚焦进去才能 ↑↓ 滚动。
                if not isinstance(w, tk.Text) and "state" in w.keys() \
                        and str(w.cget("state")) == "disabled":
                    continue
                w.focus_set()
                break
            except tk.TclError:
                continue
        return "break"

    def _set_to_menu(self, event=None):
        """右面板 → 左列表（← 键；只挂在"← 本来没用途"的控件上 —— Entry / 下拉不挂；
        主题单选钮自己有活儿（组内挪焦点），**只在最左端**转到这里，v63）。"""
        try:
            self.set_left.focus_set()
        except tk.TclError:
            pass
        return "break"

    def _theme_rb_focus(self, edge, rb):
        """v76：主题块某个钮拿到焦点 —— 外框 edge 点亮（v57.2 原逻辑）+ 记「上次焦点位置」。

        v80：框色从写死的纯黑改成**主题相反色**（`_set_page_edge_bg`）—— 黑夜 / D 系深色
        界面下黑框看不见（用户口径「设置页的边框颜色统一为主题的相反色」）。
        """
        edge.configure(bg=self._set_page_edge_bg())
        self._theme_focus_mem = rb
        self._set_focus_mem = "theme"        # v82：焦点站在主题块

    def _theme_focus_key(self):
        """v76：主题块焦点钮的配置值 `"组:值"`（没聚焦过 / 找不到所属组 → None）。"""
        rb = self._theme_focus_mem
        if rb is None:
            return None
        for gk, rbs in self._set_groups.items():
            if rb in rbs:
                return "%s:%s" % (gk, _rb_val(rb))
        return None

    def _theme_focus_target(self):
        """v76：进「主题设置」块该落到哪个钮 —— 本次运行的最后焦点 → 配置里存的那份 → None。

        配置那份 = `"组:值"`（关窗写 / 开窗读，`theme_focus` 键）—— 按值在组里找钮；
        找不到（老配置 / 表改过）→ None，走原口径（面板第一件）。
        """
        if self._theme_focus_mem is not None:
            return self._theme_focus_mem
        raw = self.cfg.get("theme_focus")
        if raw:
            gk, _sep, val = raw.partition(":")
            for rb in self._set_groups.get(gk, []):
                if _rb_val(rb) == val:
                    return rb
        return None

    def _set_panel_step(self, key, delta, event=None):
        """v42：右面板里 ↑ / ↓ = 在**本块面板的控件之间**上 / 下走（走到头停住，不绕回）。

        清单 = `_set_focus[key]`（跟「进面板落第一件」同一张表）；**自己要用 ↑↓ 的控件照旧
        归自己**（快捷键表 ↑↓ 选行、导出块场次下拉 ↑↓ 换值 —— 它们没挂这个），所以从它们
        下面那件按 ↑ 正好能走回表 / 下拉上。禁用的按钮跳过（口径同 `_set_focus_panel`）。
        """
        items = []
        for w in self._set_focus.get(key, []):
            try:
                # v87：只读 Text（一览块）不跳（口径同 `_set_focus_panel`）
                if not isinstance(w, tk.Text) and "state" in w.keys() \
                        and str(w.cget("state")) == "disabled":
                    continue
            except tk.TclError:
                continue
            items.append(w)
        if not items:
            return "break"
        cur = self._focus_widget()
        try:
            i = items.index(cur)
        except ValueError:
            i = -1 if delta > 0 else len(items)   # 不在清单里：从"将要走来的那一端"起算
        j = max(0, min(len(items) - 1, i + delta))
        try:
            items[j].focus_set()
        except tk.TclError:
            pass
        return "break"

    def _set_theme_side(self, grp, delta, event=None):
        """v55：主题块 ← / → = 在**这一组单选钮内**挪焦点（**不再走到就改** —— 用户口径
        「不应该是左右方向键移动到不同选项就自动修改,还要按回车确定才行」）；回车 = `_set_theme_apply`。
        鼠标点击照旧即时生效（只收窄键盘口径）。

        v63：**最左端再按 ← = 回左列表**（用户口径「主题设置，在选项最左端按左方向键能回到主题设置」）——
        组内走到头不再原地卡住，转 `_set_to_menu`（焦点回左列表里选中的那一行「主题设置」）。
        右端到头仍停在原地（用户没提，不动）。

        v71.1：配色是 **3 列 × 4 行**的网格 —— ← / → **只在同一行内挪**（列 = 下标 % 3）：
        行首（列 0）再按 ← = 回左列表、行尾（列 2）再按 → 停在原地；换行走 ↑ / ↓。
        """
        rads = self._set_groups.get(grp, [])
        cur = self._focus_widget()
        if cur not in rads:
            return "break"
        j = rads.index(cur)
        i = j + delta
        if i < 0 or (grp == "scheme" and delta < 0 and j % 3 == 0):
            return self._set_to_menu()          # v63/v71.1：最左端再往左 = 回左列表（「主题设置」那一行）
        if grp == "scheme" and delta > 0 and j % 3 == 2:
            return "break"                      # v71.1：行尾再往右 = 停在原地（不跳下一行）
        if i < len(rads):
            try:
                rads[i].focus_set()
            except tk.TclError:
                pass
        return "break"

    def _set_theme_apply(self, rb, event=None):
        """v55：主题块**回车 = 应用**焦点所在选项（`invoke` 与鼠标点同一条路：写 var → on_theme_pick）。"""
        try:
            if str(rb.cget("state")) != "disabled":
                rb.invoke()
        except tk.TclError:
            pass
        return "break"

    def _set_theme_updown(self, delta, event=None):
        """v42：主题块 ↑ / ↓ = 在**四组之间**上 / 下走（只挪焦点、不自动改值 —— 选值：挪到位后回车确认，v55）。

        v71.1：焦点在**配色网格**（3 列 × 4 行）里时，↑ / ↓ 先在网格内**换行**（上下同列）——
        走到最上面一行再 ↑ / 最下面一行再 ↓，才去相邻的组（用户口径「上下左右移动」）。

        v74（用户拍板「全页统一，距离原来列最近」）：跨组落点 = **目标组里水平距离最近的钮**
        （`_theme_nearest`）—— 取代 v57 的「回该组上次停留位置」记忆机制（`_set_group_focus` 退役）。

        v76：从相邻组**进**配色网格 = 落靠来源那一行（上面来 ↓ 第 1 行、下面来 ↑ 第 4 行）、再按
        圆点列挑；距离指标同改「圆点 x」（等宽格后这才是真同列，见 `_theme_nearest`）。
        """
        keys = self._set_group_order
        cur = self._focus_widget()
        gi = 0
        for i, gk in enumerate(keys):
            if cur in self._set_groups.get(gk, []):
                gi = i
                break
        # v71.1：配色网格内先换行（同列上下；出界才落到下面的"换组"逻辑）
        if keys[gi] == "scheme" and cur in self._set_groups.get("scheme", []):
            rads0 = self._set_groups["scheme"]
            j = rads0.index(cur) + delta * 3
            if 0 <= j < len(rads0) and j % 3 == rads0.index(cur) % 3:
                try:
                    rads0[j].focus_set()
                except tk.TclError:
                    pass
                return "break"
        gi = max(0, min(len(keys) - 1, gi + delta))
        rads = self._set_groups.get(keys[gi], [])
        if not rads:
            return "break"
        cand = rads
        # v76：从相邻组**进**配色网格 —— 落靠来源那一行（上面来 ↓ 落第 1 行、下面来 ↑ 落最后
        #      一行），再按「圆点列最近」挑列；网格内换行在上面那支已处理（到这儿 = 已出网格）。
        if keys[gi] == "scheme" and cur not in rads and len(rads) > 3:
            cand = rads[:3] if delta > 0 else rads[-3:]
        pick = self._theme_nearest(cand, cur)   # v74：目标组里水平距离最近的钮（取代 v57 记忆）
        try:
            (pick or rads[0]).focus_set()
        except tk.TclError:
            pass
        return "break"

    @staticmethod
    def _theme_nearest(rads, cur):
        """在 `rads` 里找**水平距离最近**的钮（按屏幕 x 的「单选圆点」= 钮左缘算）。

        v74：用户口径「翻到哪一行，就落在那一行里离原来列最近的那颗」（例子：3×3 图里 8↑→5、
        7↑→4）。算不出几何（窗口还没映射）→ None（调用方回退第一个）。
        v76：指标从「钮中心」改成**钮左缘（圆点那一列）**—— 配色格改等宽后，圆点在列上对齐，
        「离原来列最近」按圆点算才是真同列（按中心算会把名字长短混进来，等宽前后落点会跳）。
        """
        try:
            cx = cur.winfo_rootx()
        except tk.TclError:
            return None
        best, bd = None, None
        for rb in rads:
            try:
                d = abs(rb.winfo_rootx() - cx)
            except tk.TclError:
                continue
            if bd is None or d < bd:
                best, bd = rb, d
        return best

    def _set_border_sync(self, tree, event=None):
        """某张表的选中项变了 →「黑色边框」档把线挪过去（填充档是空转，画笔自带收起）（v38 先例）。"""
        rb = self._row_borders.get(tree)
        if rb is None:
            return
        try:
            sel = tree.selection()
            rb.show(sel[0] if sel else None)
        except tk.TclError:
            pass

    def _ui_dark(self):
        """界面现在是不是深色板（D 系配色恒深 / 亮色配色按「黑夜模式」）——口径同 `_apply_framework`。"""
        return self.theme_scheme in FRAME_SCHEMES or self.theme_daynight == THEME_DAYNIGHT_NIGHT

    def _set_page_edge_bg(self):
        """设置页焦点框的颜色 = 主题的相反色（v80 用户口径）：深色界面 → 白；浅色界面 → 黑。"""
        return "#FFFFFF" if self._ui_dark() else "#000000"

    def _set_page_border(self):
        """设置页的边框统一取「主题的相反色」（v80 用户口径「设置页的边框颜色统一为主题的相反色」）。

        范围 = 左列表 + 快捷键表的**选中行框**、主题块单选钮的**焦点框**（edge）。
        **主表那几张表不动**（仍走用户选的「当前行边框」档）——设置页与主表解耦。
        挂点：`_apply_theme` 尾巴（换配色 / 昼夜 / 启动都要重刷）。
        """
        border = SEL_BORDER["white" if self._ui_dark() else "black"]
        for stv in (getattr(self, "key_tv", None), getattr(self, "set_left", None)):
            if stv is None:
                continue
            rb = self._row_borders.get(stv)
            if rb is not None:
                rb.set_style(border)
                rb.set_focused(self._tree_has_focus(stv))
        mem = getattr(self, "_theme_focus_mem", None)   # 主题块"亮着"的那颗 — 换色重刷
        if mem is not None:
            try:
                if self._focus_widget() is mem:
                    mem.master.master.configure(bg=self._set_page_edge_bg())   # edge 层
            except tk.TclError:
                pass

    # --- 设置界面 · 两块面板（v40：全部内联、四个独立弹窗删除；v53：导入 / 导出两块删除）---
    def _build_set_keys(self, panel):
        """「快捷键设置」块（v26 独立弹窗整窗删除，表格 / 改键逻辑照搬 —— v40 内联）。"""
        # v57.4：标题行右侧挂消息提示（设置页顶部那行删掉后，「右上角提示词」搬到这儿 —— 跟标题
        #        合并一行；主题块同款）。两块面板各挂一个同 `textvariable` 的 Label，切块跟着换。
        _head = tk.Frame(panel, bg=C_BG)
        _head.pack(fill="x")
        tk.Label(_head, text=KEY_DIALOG_TITLE, bg=C_BG, fg=C_ACCENT_DARK,
                 font=(self.fam, 16, "bold")).pack(side="left")
        tk.Label(_head, textvariable=self.var_msg2, bg=C_BG, fg=C_MUTED,
                 font=(self.fam, 11), anchor="e").pack(side="right")
        mid = tk.Frame(panel, bg=C_BG)
        mid.pack(fill="both", expand=True, pady=(8, 0))
        # v74：两键槽 —— 列 = 操作 / 键1（主绑定）/ 键2（替代键，两键都能触发同一操作）；
        #      两键列加宽（190 → 200：长键 Ctrl+Shift+Delete 显示完整），“默认键”列取消
        #      （恢复默认仍走键盘：Delete / Ctrl+Shift+Delete）。
        tv = ttk.Treeview(mid, columns=("op", "k1", "k2"), show="headings",
                          selectmode="browse", height=15, style="Status.Treeview")  # v57.3：13 → 15（按钮排删了）
        tv.heading("op", text="操作")
        tv.heading("k1", text="键1")
        tv.heading("k2", text="键2")
        tv.column("op", width=240, minwidth=170, anchor="w", stretch=True)
        tv.column("k1", width=200, minwidth=110, anchor="center", stretch=False)
        tv.column("k2", width=200, minwidth=110, anchor="center", stretch=False)
        vsb = ttk.Scrollbar(mid, orient="vertical", command=tv.yview, takefocus=0)
        # v38：滚动也要把选中框跟住 —— 停稳 80ms 补摆（口径同主表 v25.10）
        tv.configure(yscrollcommand=lambda a, b, _v=vsb: self._key_dialog_scrolled(a, b, _v))
        tv.pack(side="left", fill="both", expand=True)
        vsb.pack(side="right", fill="y")
        # v38：这个列表的选中行也要「看得见」（v75.3：颜色档走全局映射、天然生效；
        # v80：框色不跟「当前行边框」档 —— 设置页统一取**主题相反色**，见 `_set_page_border`）
        rb = self._row_border(tv)
        rb.set_style(SEL_BORDER["white" if self._ui_dark() else "black"])
        rb.set_focused(False)
        self.key_tv = tv
        # v57.3：底部三按钮（改键… / 此项恢复默认 / 全部恢复默认）**整排删除**（用户点名）——
        # 三条路全走键盘：回车 = 改键（捕获两步手势）、`Delete` = 此项恢复默认、
        # `Ctrl+Shift+Delete` = 全部恢复默认（后两条 = 注册表操作 key_reset / key_reset_all，可改键）。
        # 用法说明靠右上角消息提示（焦点进表时给一条，动态反映当前键）—— 用户拍板。
        tv.bind("<Key>", self._key_dialog_key)      # 捕获时压过 Treeview 的方向键
        tv.bind("<Double-1>", lambda _e: self._key_capture_start())   # v73：双击改「当前列」的键
        tv.bind("<<TreeviewSelect>>", lambda _e: self._key_dialog_border_sync())
        tv.bind("<FocusIn>", lambda _e: self._key_note(
            "← / → 切「键1 / 键2」· 回车 = 改当前列 · %s = 此项恢复默认 · %s = 全部恢复默认" % (
                pretty_seq(self.keymap.get("key_reset")),
                pretty_seq(self.keymap.get("key_reset_all")))), add="+")
        tv.bind("<FocusIn>", self._refresh_border_focus, add="+")
        tv.bind("<FocusIn>", lambda _e: self._set_focus_note("keys"), add="+")   # v82：焦点站在键表
        tv.bind("<FocusOut>", self._refresh_border_focus, add="+")
        tv.bind("<FocusOut>", lambda _e: self._key_capture_blur(), add="+")   # v80：捕获锁
        # v74：← / → = 在「键1 / 键2」两列间切“当前要改的列”（表头 ● 标出）；键1 上再按 ←
        #      照旧回左列表（v53 老路，层级退）；**捕获模式**下全部让回捕获通道
        #      （方向键本身是保留键、真按下会被拒）。
        tv.bind("<Left>", lambda e: self._key_dialog_key(e) if self.key_capture
                else self._key_col_move(-1))
        tv.bind("<Right>", lambda e: self._key_dialog_key(e) if self.key_capture
                else self._key_col_move(1))
        self._set_focus["keys"] = [tv]
        self._key_col_mark()                        # v74：表头 ● 标出当前改键列
        self._key_dialog_refresh()
        if not tv.selection():                  # v26.1：摆出来就选中第一行 —— 焦点看得见
            tv.selection_set(KEY_ACTIONS[0][0])
            tv.focus(KEY_ACTIONS[0][0])

    def _build_set_theme(self, panel):
        """「主题设置」块（原「主题」菜单的三个单选子菜单 → 三组单选钮；`on_theme_pick` 不改）。"""
        # v57.4：标题行右侧挂消息提示（同快捷键块）。
        _head = tk.Frame(panel, bg=C_BG)
        _head.pack(fill="x")
        tk.Label(_head, text="主题设置", bg=C_BG, fg=C_ACCENT_DARK,
                 font=(self.fam, 16, "bold")).pack(side="left")
        tk.Label(_head, textvariable=self.var_msg2, bg=C_BG, fg=C_MUTED,
                 font=(self.fam, 11), anchor="e").pack(side="right")
        widgets = []
        self._set_groups = {}                    # v42：组名 → [单选钮]（← / → 组内走）
        self._set_group_order = ["selb", "selc", "scheme", "today", "preview", "daynight"]   # v75.3
        for key, label, items in THEME_GROUPS:   # v76：组清单抽成常量（组名 / 标题 / 取值；v75 起五条）
            row = tk.Frame(panel, bg=C_BG)
            row.pack(fill="x", pady=(12, 0))
            tk.Label(row, text=label, bg=C_BG, fg=C_MUTED, font=(self.fam, 12),
                     width=10, anchor="w").pack(side="left")
            cur = {"selb": self.theme_sel_border, "selc": self.theme_sel_color,
                   "scheme": self.theme_scheme,
                   "today": self.theme_today,
                   "preview": self.preview_mode,
                   "daynight": self.theme_daynight}[key]     # v75.3：边框 / 颜色拆两组
            var = tk.StringVar(value=cur)
            self._sel_vars[key] = var
            grp = []                             # v42：本组单选钮
            # v71 / v71.1：配色 = 12 套 —— 排成 **3 列 × 4 行**的网格（用户口径「配色改为一行三列,
            #      排成多行,上下左右移动」）。v76：顺序 = `THEME_SCHEME_ITEMS` 的显示顺序
            #      （亮 / 深各按字母 + 一条龙蛇形），每格等宽（圆点按列对齐）。
            #      焦点走法：← / → **行内挪**（行首再 ← = 回左列表）、↑ / ↓ **网格内换行**（同列；
            #      到首 / 末行再走才去相邻组）—— 见 `_set_theme_side` / `_set_theme_updown`；
            #      `_set_groups` 仍是一条平表（列 = 下标 % 3）。
            lanes = [row]
            _cells = []                          # v76：配色组的 12 个等宽格（段末统一宽 / 高）
            if key == "scheme":
                _box = tk.Frame(row, bg=C_BG)
                _box.pack(side="left", anchor="n")
                lanes = [tk.Frame(_box, bg=C_BG) for _ in range(4)]
                for _n, _ln in enumerate(lanes):
                    _ln.pack(anchor="w", pady=((7, 0) if _n else 0))
            for _i, (val, lab) in enumerate(items):
                lane = lanes[min(_i // 3, len(lanes) - 1)]
                # v57.2（看图返工 ×2）：焦点落在 rb 上时，**挂在父控件上的 highlight 会被系统
                #      重绘擦掉**（最小实验实锤：无焦点时框在、焦点一进 rb 就没了 —— 而「有焦点」
                #      正是要显示框的时刻；v57/v57.1 的 highlight 配置法、v57.2 前半的 holder
                #      highlight 法都栽在这上面）。改用**双层套娃**：外层 `edge`（3px 边，用 bg
                #      色差显示边框：黑 ⇄ 背景色）+ 内层 `inner`（铺背景）+ rb —— bg 变化不受
                #      焦点重绘影响，实测焦点态下 3px 黑框稳定可见。
                # v76：每项再套一层 `cell`（等宽格）—— 焦点框仍只箍住 rb（edge / inner 照旧），
                #      等宽的是外层格；单行组也走同一结构（格宽 = 自然宽，视觉一字不变）。
                cell = tk.Frame(lane, bg=C_BG)
                edge = tk.Frame(cell, bg=C_BG)
                inner = tk.Frame(edge, bg=C_BG)
                if key == "daynight":
                    # v75.2（用户拍板「把黑夜模式设为一个开关选项，取消白天模式」）：第 5 组 =
                    # **单枚 Checkbutton「黑夜模式」**（勾 = night / 不勾 = day；variable 与
                    # Radiobutton 同机制 —— 勾选态 = var 值等于 onvalue）。Checkbutton 没有
                    # `value` 选项 → 贴 `_tb_value` 供 `_rb_val` 读（焦点记忆两处用）。
                    rb = tk.Checkbutton(inner, text=lab, variable=var,
                                        onvalue=THEME_DAYNIGHT_NIGHT,
                                        offvalue=THEME_DAYNIGHT_DAY,
                                        bg=C_BG, fg=C_TEXT, activebackground=C_BG,
                                        activeforeground=C_TEXT, selectcolor=C_PANEL,
                                        highlightthickness=0,
                                        font=(self.fam, 13), cursor="hand2",
                                        command=lambda k=key: self.on_theme_pick(k))
                    rb._tb_value = THEME_DAYNIGHT_NIGHT
                else:
                    rb = tk.Radiobutton(inner, text=lab, value=val, variable=var,
                                        bg=C_BG, fg=C_TEXT, activebackground=C_BG,
                                        activeforeground=C_TEXT, selectcolor=C_PANEL,
                                        highlightthickness=0,
                                        font=(self.fam, 13), cursor="hand2",
                                        command=lambda k=key: self.on_theme_pick(k))
                rb.pack()
                inner.pack(padx=3, pady=3)
                edge.pack(anchor="w")            # v76：格内左贴 —— 三列的圆点 / 字头同一竖线
                cell.pack(side="left", padx=(0, 16))
                _cells.append(cell)
                # v76：FocusIn 顺带记「上次焦点位置」（进块落回它；配置那份关窗写）
                rb.bind("<FocusIn>", lambda _e, e=edge, w=rb: self._theme_rb_focus(e, w))
                rb.bind("<FocusOut>", lambda _e, e=edge: e.configure(bg=C_BG))
                # v42/v55：主题块 ← / → = 组内**挪焦点**、↑ / ↓ = 组之间走（v45 起四组）、
                # **回车 = 应用**（v55：不再走到就改）；回左列表走 Esc —— 这块的 ← 有自己的活儿，
                # 不挂 `_set_to_menu`。**v71.1：配色那一组是 3 列 × 4 行网格** —— 四个方向键
                # 都先在网格内走（← / → 行内、↑ / ↓ 换行），出格才落到"换组 / 回列表"（见两个函数）。
                rb.bind("<Left>", lambda _e, k=key: self._set_theme_side(k, -1))
                rb.bind("<Right>", lambda _e, k=key: self._set_theme_side(k, 1))
                rb.bind("<Up>", lambda _e: self._set_theme_updown(-1))
                rb.bind("<Down>", lambda _e: self._set_theme_updown(1))
                for _seq in ("<Return>", "<KP_Enter>"):
                    rb.bind(_seq, lambda _e, w=rb: self._set_theme_apply(w))
                grp.append(rb)
                widgets.append(rb)
            # v76：配色组 —— 12 格统一到最大格的宽 / 高（= 最长的 "Catppuccin Latte / Mocha" 那两格），
            #   三列圆点 / 字头落同一条竖线上（用户口径「选择点水平竖直对齐」）；
            #   焦点框仍只箍住单项（edge 不动，等宽的是外层 cell）。
            if key == "scheme" and _cells:
                panel.update_idletasks()
                _cw = max(c.winfo_reqwidth() for c in _cells)
                _ch = max(c.winfo_reqheight() for c in _cells)
                for c in _cells:
                    c.pack_propagate(False)
                    c.configure(width=_cw, height=_ch)
            self._set_groups[key] = grp          # v42
        self._set_focus["theme"] = widgets

    def _build_set_help(self, panel):
        """「快捷键一览」块（v87）：**只读**展示当前键位表（原 `?` 独立弹窗整窗并进来）。

        用户口径：「把快捷键一览并进设置页,在左边加一行,写快捷键一览,只读,右侧界面显示快捷键」。
        内容 = `_help_text()`（v26 起跟着自定义键现渲染，默认 == `KEY_TABLE` 逐字节，selftest 钉死）；
        改键 / 恢复默认后由 `_refresh_help_panel` 重刷（`keymap_assign` / `_key_reset_all` 各调一发）。
        控件 = 只读 Text（`state="disabled"` —— 防编辑）+ 竖 / 横两条滚动条：
        29 行比窗口高、几行「设置界面 / ← / →」长文比窄窗宽，两条都得有；
        ↑↓ / PgUp / PgDn **显式绑成滚动**（disabled 的 Text 别指望内建编辑动作），滚轮走 Tk 默认。
        """
        _head = tk.Frame(panel, bg=C_BG)
        _head.pack(fill="x")
        tk.Label(_head, text="快捷键一览", bg=C_BG, fg=C_ACCENT_DARK,
                 font=(self.fam, 16, "bold")).pack(side="left")
        tk.Label(_head, textvariable=self.var_msg2, bg=C_BG, fg=C_MUTED,
                 font=(self.fam, 11), anchor="e").pack(side="right")
        mid = tk.Frame(panel, bg=C_BG)
        mid.pack(fill="both", expand=True, pady=(8, 0))
        tx = tk.Text(mid, wrap="none", font=(self._mono_family(), 12),
                     bg=C_BG, fg=C_TEXT, bd=0, highlightthickness=0,
                     insertwidth=0, padx=4, pady=2, cursor="arrow",
                     state="disabled")
        vsb = ttk.Scrollbar(mid, orient="vertical", command=tx.yview, takefocus=0)
        hsb = ttk.Scrollbar(mid, orient="horizontal", command=tx.xview, takefocus=0)
        tx.configure(yscrollcommand=vsb.set, xscrollcommand=hsb.set)
        tx.grid(row=0, column=0, sticky="nsew")
        vsb.grid(row=0, column=1, sticky="ns")
        hsb.grid(row=1, column=0, sticky="ew")
        mid.rowconfigure(0, weight=1)
        mid.columnconfigure(0, weight=1)

        def _roll(dy, what):                 # ↑↓ / PgUp / PgDn → 滚动（return "break" 压掉内建）
            def _f(_e):
                tx.yview_scroll(dy, what)
                return "break"
            return _f
        tx.bind("<Up>", _roll(-1, "units"))
        tx.bind("<Down>", _roll(1, "units"))
        tx.bind("<Prior>", _roll(-1, "pages"))
        tx.bind("<Next>", _roll(1, "pages"))
        tx.bind("<Left>", self._set_to_menu)     # ←（含 A）= 回左列表 —— 面板控件同款口径；
                                                 #   横向滚动走拖条 / shift+滚轮，不占这对键
        tx.bind("<FocusIn>", lambda _e: self._set_focus_note("help"), add="+")   # v82：焦点站在一览块
        self.help_tx = tx
        self._set_focus["help"] = [tx]
        self._refresh_help_panel()           # 建好先灌一次全文

    # ------------------------------------------------------------ 自定义快捷键（v26）
    def _action_name(self, aid):
        for a, n, _s in KEY_ACTIONS:
            if a == aid:
                return n
        return aid

    def _seqs_for(self, aid):
        """某操作此刻要绑的序列清单（键1 + 键2 + 各自大小写变体 + 固定副键）；两槽都空 → 空表。

        v68：裸字母主键展开成两种写法（`<Key-F>` ⇄ `<Key-f>`）—— f / F 是同一个物理键，
        都绑上都触发（用户口径「跳到搜索框……按大小写 f 都触发」）。
        v74：键2（替代键）并入同一清单（两键都能触发）；固定副键只要任一槽有绑定就挂。
        """
        seqs = [s for s in (self.keymap.get(aid), self.keymap2.get(aid)) if s]
        if not seqs:
            return []
        out = []
        for s in seqs + list(KEY_ALIASES.get(aid, ())):
            for v in key_case_variants(s):
                if v not in out:
                    out.append(v)
        return out

    def _key_sites(self):
        """[(action_id, widget, 处理函数, 是否 bind_all)] —— 可改键操作的全部挂点。

        （三棵树建好之后才能调；弹窗 / 浮层 / 一览这些临时窗口各自在创建时挂。）
        """
        sites = [
            ("undo", self.root, self._on_ctrl_z, False),
            ("redo", self.root, self._on_ctrl_y, False),
            # v32.3：search 从根级移走 —— 改裸 F、挂树上（见下方树批；搜索框里打字不受影响）
            ("jump_top", self.root, lambda e: self._jump_row(0), False),
            ("jump_end", self.root, lambda e: self._jump_row(-1), False),
            ("sort_prev", self.root, lambda e: self._sort_next_key(-1), False),
            ("sort_next", self.root, lambda e: self._sort_next_key(1), False),
            ("sort_asc", self.root, lambda e: self._sort_toggle_key(0), False),
            ("sort_desc", self.root, lambda e: self._sort_toggle_key(1), False),
            ("reload", self.root, self._on_reload_key, False),
            # v26.1：菜单热键（v53：只剩 Ctrl+3 —— Ctrl+1 随导入题解包一起删；v37 删 Ctrl+2）
            ("menu_keys", self.root, lambda e: self._on_menu_hotkey("keys"), False),
            # v40：设置界面开 / 关（Ctrl+Tab）—— 挂 root = 哪个界面都收得到（含设置界面里的控件：
            # 事件从控件往 toplevel 冒泡，root 的绑定就是这一层）
            ("settings", self.root, self._on_settings_key, False),
            ("know_mode", self.root, self._on_know_mode_key, False),   # v27：统计页视图切换
            ("goto_today", self.root, self._on_goto_today, False),     # v65：直达看板
            ("goto_know", self.root, self._on_goto_know, False),       # v65：直达统计页
            ("theme_cycle", self.root, self._on_theme_cycle, False),   # v65：切主题档
            ("preview_cycle", self.root, self._on_preview_cycle, False),  # v65：切题解预览档
            # v65：Tab / Shift+Tab —— 同一处理器，方向看事件 state 的 Shift 位（0x1）
            ("focus_next", self.root,
             lambda e: self._rotate_focus(-1 if (e.state & 0x1) else 1), False),
            ("cancel", self.root, self._on_settings_esc, False),   # v65：Esc / Backspace（设置页 / 全屏 md 兜底）
            # v11：F11 挂 bind_all —— 状态浮层 / `?` 一览（独立 Toplevel）开着时也要切换
            ("fullscreen", self.root, self._on_f11_key, True),
        ]
        # v27：统计页「按场次」视图（round_tree）与总表 / 看板**同级** —— 题目行 1~6 直改、
        # v46 起重排：**Ctrl+回车 = 状态浮层、回车 = 展开 / 收起题解 md、Alt+回车 = 跳转题目链接**
        # （原「回车 = 浮层」「Shift+回车 = 原题」「Alt+回车 = 资料」的挂法作废；双击各自另挂）。
        for tree, on_enter, on_md in ((self.tree, self._on_open_key, self._toggle_preview),
                                      (getattr(self, "tree_split", None),
                                       self._on_open_key, self._toggle_preview),   # v66：分屏页
                                      (self.today_tree, self._on_open_key, self._toggle_preview),
                                      (getattr(self, "round_tree", None),
                                       self._on_round_ctrl_enter, self._on_round_enter)):
            if tree is None:
                continue
            for k in range(len(STATES)):
                sites.append(("status_%d" % (k + 1), tree,
                              (lambda e, i=k, t=tree: self._on_digit_key(i, t)), False))
            sites.append(("enter", tree, on_enter, False))          # v46：Ctrl+回车 = 状态浮层
            sites.append(("problem", tree, self._on_problem_key, False))   # v46：Alt+回车 = 跳转题目链接
            sites.append(("preview", tree, on_md, False))           # v46：回车 = 展开 / 收起题解 md
            sites.append(("search", tree, self._on_focus_search, False))   # v32.3：F 进搜索框（裸键挂树上）
        # v26.3：菜单热键**也挂各棵树上** —— 树上还挂着「数字直改」`<Key-N>`，同一控件里
        # `<Control-Key-N>` 更具体、直接胜出（`<Alt-Return>` 同一先例）→ 不会被数字键先吃掉。
        for tree in (self.tree, getattr(self, "tree_split", None), self.today_tree, self.know_tree,
                     getattr(self, "round_tree", None)):
            if tree is None:
                continue
            sites.append(("menu_keys", tree, lambda e: self._on_menu_hotkey("keys"), False))
            # v65：四个新动作**同款双挂**（树级更具体、优先命中；root 那层照旧兜底——
            #      跟 menu_keys 同一先例：合成事件/负载下 root 冒泡不稳，树级这层最可靠）
            sites.append(("goto_today", tree, self._on_goto_today, False))
            sites.append(("goto_know", tree, self._on_goto_know, False))
            sites.append(("theme_cycle", tree, self._on_theme_cycle, False))
            sites.append(("preview_cycle", tree, self._on_preview_cycle, False))
            sites.append(("page_up", tree, lambda e, t=tree: self._move_sel(t, "pgup"), False))     # v65
            sites.append(("page_down", tree, lambda e, t=tree: self._move_sel(t, "pgdn"), False))   # v65
            # v85：**Ctrl+↑ / ↓ 也树级双挂** —— root 那份照旧兜底，树级这层负责 break 掉
            #      ttk 内建 Keynav（它会连带 Ctrl 一起认、顺手把选中行挪一行）；见 `_on_sort_site`。
            #      （← / → 不挂：Keynav 的左右只在真父子行上有活，而全库四张表都是**平铺**的
            #      —— 2026-10-07 实测「有真子行的行数 = 0」，内建左右键本来就没动作。）
            sites.append(("sort_asc", tree, lambda e: self._on_sort_toggle_site(0), False))
            sites.append(("sort_desc", tree, lambda e: self._on_sort_toggle_site(1), False))
            sites.append(("cancel", tree,
                          self._on_round_esc if tree is getattr(self, "round_tree", None)
                          else self._on_row_esc, False))           # v65：行上 Esc / Backspace
        # v46：知识点视图的行回车**语义不动**（父行 = 展开 / 收起、叶行 = 搜索跳转），但挂点从
        # `enter`（现在是 Ctrl+回车 / 浮层那族）挪到 `preview`（回车）—— 「回车」保持是它的主动作
        # （用户拍板「统计页知识点视图不受影响」）。
        sites.append(("preview", self.know_tree, self._on_know_enter, False))
        # v51：统计页（知识点视图）也挂 F —— 搜索框只留总表后，F = 切回总表并进框
        sites.append(("search", self.know_tree, self._on_focus_search, False))
        # v57.3：「此项 / 全部恢复默认」挂在设置界面的快捷键表上（控件级 —— 只在表上有焦点时生效；
        #         调用序已保证 key_tv 建好，见 __init__ 的 _apply_keys 挪位）。
        if self.key_tv is not None:
            sites.append(("key_reset", self.key_tv, self._key_op_reset, False))
            sites.append(("key_reset_all", self.key_tv, self._key_op_reset_all, False))
        return sites

    def _apply_keys(self):
        """把 keymap 落到各挂点：先撤上次绑的，再按当前序列挂（未绑定 = 一个都不挂）。

        撤的时候记着「上次到底绑过哪些序列」（`self._key_bound`）—— 直接 unbind 当前值会漏掉旧键。
        """
        for (w, aid), (seqs, allf) in list(self._key_bound.items()):
            for s in seqs:
                try:
                    if allf:
                        self.root.unbind_all(s)
                    else:
                        w.unbind(s)
                except tk.TclError:
                    pass
        self._key_bound = {}
        self._bind_wasd_all()      # v47：WASD 基础层先挂 —— 注册表随后绑，用户自定义键可覆盖它
        # v65（解锁批）：Tk 的默认 Tab 焦点遍历（`all` 级 `tk_focusNext`）显式吃掉 ——
        # `focus_next` 改到别的键后，旧 Tab 该"失效"（不该落回系统默认焦点环）；
        # 默认档下注册表随后把 `<Tab>` 重绑回轮换（同 widget 同序列，后绑覆盖先绑）。
        try:
            self.root.bind("<Tab>", lambda e: "break")
        except tk.TclError:
            pass
        for aid, w, handler, allf in self._key_sites():
            seqs = self._seqs_for(aid)
            if not seqs:
                continue
            for s in seqs:
                try:
                    if allf:
                        self.root.bind_all(s, handler)
                    else:
                        w.bind(s, handler)
                except tk.TclError:
                    continue
            self._key_bound[(w, aid)] = (seqs, allf)

    def _keyseq_tk_ok(self, seq):
        """Tk 认不认这个序列（只查不挂：`bind all <seq>` 查询式调用）。"""
        try:
            self.root.tk.call("bind", "all", seq)
            return True
        except tk.TclError:
            return False

    def _sanitize_keymap_tk(self):
        """手改配置里 Tk 认不出的序列（keysym 不存在那种）→ 回默认，别让一条坏键把绑定层带崩。"""
        for aid, seq in list(self.keymap.items()):
            if seq is not None and seq != DEFAULT_KEYMAP.get(aid) and not self._keyseq_tk_ok(seq):
                self.keymap[aid] = DEFAULT_KEYMAP[aid]

    def _key_overrides(self):
        """要写进配置的差量（只存跟默认不一样的；None = 未绑定）。"""
        return {aid: self.keymap.get(aid)
                for aid, d in DEFAULT_KEYMAP.items() if self.keymap.get(aid) != d}

    def _key_overrides2(self):
        """v74：键2 的差量（只存有值的；默认全 None = 未绑定 → 差量天然是空）。"""
        return {aid: seq for aid, seq in self.keymap2.items() if seq is not None}

    def _key_note(self, text):
        """改键的反馈：一律走主窗口消息行（第一行最右端，3 秒后自动消失）。

        v38（用户口径「下边的提示语就不需要了」）：设置窗底部那行状态提示**整行删除**——
        选中反馈改由行上高亮承担（v38 给设置窗挂了主题化的选中提示，见 `_key_dialog_border_sync`），
        改键 / 顶掉 / 拒绝这些操作反馈统一落主窗的 `set_msg`。
        """
        self.set_msg(text, clear_after=TOAST_MS)

    def _refresh_help_panel(self):
        """v87：设置页「快捷键一览」块跟着当前键重渲染（原 v26「一览开着时跟随」并进来）。

        没建 / 已销毁都静默跳过 —— 改键（`keymap_assign`）、恢复默认（`_key_reset_all`）都走它。
        """
        tx = getattr(self, "help_tx", None)
        if tx is None:
            return
        try:
            tx.configure(state="normal")
            tx.delete("1.0", "end")
            tx.insert("1.0", self._help_text())
            tx.configure(state="disabled")
        except tk.TclError:
            pass

    def keymap_assign(self, aid, seq, slot=0):
        """把 aid 的「键1 / 键2」（slot = 0 / 1）设成 seq（None = 解绑）。

        v73：顶掉语义扩到**两个池** —— 别的操作（任一槽）正占着 seq → 对方那一格变
        「未绑定」（同 aid 的另一槽不顶）。返回 True/False；提示带列名走消息行；
        捕获 / 恢复默认 / 冒烟都走这里 —— 换完立刻 `_apply_keys` 真挂上去 + 刷表 + 刷一览。
        """
        km = self.keymap if slot == 0 else self.keymap2
        col = "键1" if slot == 0 else "键2"
        if aid not in DEFAULT_KEYMAP:
            return False
        if seq is not None:
            reason = keyseq_reject_reason(seq, aid)
            if reason is None and not self._keyseq_tk_ok(seq):
                reason = "这个键 Tk 不认（换个试试）"
            if reason is not None:
                self._key_note("「%s」不能设：%s" % (seq, reason))
                return False
        if km.get(aid) == seq:
            self._key_note("「%s」的%s没变（还是 %s）" % (
                self._action_name(aid), col, pretty_seq(seq)))
            return True
        victim = None
        if seq is not None:
            want = set(key_case_variants(seq))     # v68：撞键按「物理键」判 —— f 与 F 是一家
            for v_km in (self.keymap, self.keymap2):
                for a, s in v_km.items():
                    if a != aid and s and set(key_case_variants(s)) & want:
                        victim = (a, v_km)
                        break
                if victim is not None:
                    break
        km[aid] = seq
        if victim is not None:
            victim[1][victim[0]] = None            # v73：受害者可能在另一池 —— 清它那一格
        self._apply_keys()
        if seq is None:
            msg = "已把「%s」的%s解绑（现在是未绑定）" % (self._action_name(aid), col)
        else:
            msg = "已把「%s」的%s改成 %s" % (self._action_name(aid), col, pretty_seq(seq))
        if victim is not None:
            msg += "；「%s」的原键被顶掉，现在是未绑定" % self._action_name(victim[0])
        self._key_note(msg)
        self._key_dialog_refresh()
        self._refresh_help_panel()
        return True

    # v40：原 `open_key_dialog` / `close_key_dialog`（独立弹窗的开关窗）**整组删除** ——
    # 快捷键设置搬进设置界面的右面板（`_build_set_keys`），开 / 关 = `enter_settings` /
    # `leave_settings`；v26.6 的「开窗锁焦点」「关窗还焦点」两条口径由设置界面的进出接管。

    def _key_dialog_esc(self, event=None):
        """设置界面里的 Esc（v40 立、v42 改「逐层退」）：改键捕获中先取消改键；否则
        **焦点在右面板里 → 先回左列表**（主题块那种「← / → 自己有活儿」的地方，Esc 就是
        回列表的出口）；**焦点已在左列表上 → 退出设置、回进来的那个界面**（`exit_settings`）。
        """
        if self.key_capture:
            self.key_capture = False
            self._key_note("已取消改键")
            return "break"
        cur = self._focus_widget()
        if cur is not None and cur is not self.set_left:
            try:
                self.set_left.focus_set()
            except tk.TclError:
                pass
            return "break"
        self.exit_settings()
        return "break"

    def _key_capture_start(self, event=None):
        """进入「等按键」状态：下一次按键就是选中行**当前列**（键1 / 键2）的新键（Esc 取消）。"""
        if self.key_tv is None or not self.key_tv.selection():
            self._key_note("先选中一行（要改哪个操作）再按回车改键")
            return "break"
        self.key_capture = True
        self.key_tv.focus_set()
        self._key_note("改「%s」：按下新的组合键…（Esc 取消；导航 / 系统键不能拿）"
                       % ("键1" if self._key_col == 0 else "键2"))
        return "break"

    def _key_capture_blur(self):
        """v80（捕获锁）：捕获中焦点离开快捷键表（鼠标点走等）→ 自动取消捕获。

        防「捕获悬空」：挂着捕获去别处，下一次按键会被莫名其妙绑走；焦点走了就收。
        （正常路径不触发：捕获只由表上的回车 / 双击开，`_key_capture_start` 里焦点就在表上。）
        """
        if not self.key_capture:
            return
        self.key_capture = False
        self._key_note("焦点离开了快捷键表，已退出改键")

    def _key_dialog_key(self, event):
        """弹窗里的按键：普通模式放行（↑↓ 选行）；捕获模式把这一键翻成序列换上去。

        v80（捕获锁，用户口径「捕获中只有新键、Esc、Backspace 有反应，其余一律吞掉」）：
        ① **Tab 家族**（Tab / Shift+Tab / Ctrl+Tab）= 界面导航键 —— 提示后吞掉、**保持捕获**
           （v65 曾放开 Tab 可绑；实测按 Tab 会把「焦点轮换」的键顶掉 = 用户眼里的乱，收回）；
        ② **被保留表拒的键**（方向键 / Delete / 空格 / ? …）提示后**保持捕获** —— 原来一拒
           就把捕获清掉（`key_capture = False` 判在绑定之前），用户得重新回车；
        ③ 只有**绑定真成功**才退出捕获（看 `keymap_assign` 返回值）。
        """
        if not self.key_capture:
            if event.keysym in ("Return", "KP_Enter"):
                return self._key_capture_start()     # 回车 = 开始改键（两步手势的第一步）
            # v57.3：Delete 收编成注册表操作（`key_reset`，其具体绑定优先于这条泛绑定）；
            #         这里不再处理 Delete —— 留着会跟注册表挂的具体绑定语义打架。
            return None
        if event.keysym in ("Escape", "BackSpace"):   # v65：Backspace 同义（取消捕获）
            return self._key_dialog_esc()
        if event.keysym in ("Tab", "ISO_Left_Tab"):   # v80：Tab / Shift+Tab / Ctrl+Tab
            self._key_note("Tab / Ctrl+Tab 是界面导航键，不能绑（Esc 退出改键）")
            return "break"
        seq = capture_seq(event.keysym, event.state)
        if seq is None:
            self._key_note("这是纯修饰键（Ctrl / Shift / Alt 本身），再带上一个别的键试试")
            return "break"
        sel = self.key_tv.selection() if self.key_tv is not None else ()
        if not sel:
            self._key_note("没选中行，已退出改键")
            self.key_capture = False
            return "break"
        if self.keymap_assign(sel[0], seq, self._key_col):   # v74：写进「当前列」（键1 / 键2）
            self.key_capture = False                          # v80：被拒（没绑上）→ 保持捕获
        return "break"

    def _key_reset_item(self):
        """v57.3 立、v74 扩：整项恢复默认 —— 键1 回默认键、**键2 一并清空**（“此项”= 整行）。"""
        if self.key_tv is None or not self.key_tv.selection():
            self._key_note("先选中一行再恢复默认")
            return
        aid = self.key_tv.selection()[0]
        self.key_capture = False
        had2 = self.keymap2.get(aid) is not None
        self.keymap2[aid] = None                     # v74：键2 清空
        self.keymap_assign(aid, DEFAULT_KEYMAP[aid])
        if had2:                                     # 键1 恰好没变的路径不会自带刷新 —— 补一发
            self._apply_keys()
            self._key_dialog_refresh()
            self._key_note("已把「%s」恢复默认（键1 = 默认键、键2 已清空）" % self._action_name(aid))

    def _key_reset_all(self):
        self.key_capture = False
        self.keymap = dict(DEFAULT_KEYMAP)
        self.keymap2 = {aid: None for aid in self.keymap2}   # v74：键2 一并全清
        self._apply_keys()
        self._key_dialog_refresh()
        self._refresh_help_panel()
        self._key_note("已全部恢复默认")

    def _key_op_reset(self, event=None):
        """v57.3：表上的「此项恢复默认」键（默认 `<Delete>`）。**捕获改键中让位**（同 `<Left>` 先例）——
        那时按下的键是「新键」候选，不该顺手把当前行恢复默认。"""
        if self.key_capture:
            return self._key_dialog_key(event)
        self._key_reset_item()
        return "break"

    def _key_op_reset_all(self, event=None):
        """v57.3：表上的「全部恢复默认」键（默认 `<Control-Shift-Delete>`）；捕获中同样让位。"""
        if self.key_capture:
            return self._key_dialog_key(event)
        self._key_reset_all()
        return "break"

    def _key_dialog_refresh(self):
        """刷新表三列（操作 / 键1 / 键2；保留选中的行；重建期间挂 `_key_refreshing` 挡掉选中提示的误刷）。"""
        tv = self.key_tv
        if tv is None:
            return
        self._key_refreshing = True
        try:
            keep = tv.selection()[0] if tv.selection() else None
            for iid in tv.get_children():
                tv.delete(iid)
            for aid, name, _d in KEY_ACTIONS:
                tv.insert("", "end", iid=aid,
                          values=(key_leader_text(name),
                                  pretty_seq(self.keymap.get(aid)),
                                  pretty_seq(self.keymap2.get(aid))))
            if keep and tv.exists(keep):
                tv.selection_set(keep)
                tv.focus(keep)               # v53：focus 行跟着补 —— Tk 的 ↑↓（Keynav）只认它
            elif KEY_ACTIONS:                # v53：没得保留时也补一个（幂等；选不了行的回归）
                tv.selection_set(KEY_ACTIONS[0][0])
                tv.focus(KEY_ACTIONS[0][0])
        except tk.TclError:
            pass
        finally:
            self._key_refreshing = False
        self._key_dialog_border_sync()              # v38：重建完把选中框补摆回保留的选中行

    def _key_col_mark(self, event=None):
        """v73：把「当前要改的列」标在表头上（● = 回车改这一列）。"""
        tv = self.key_tv
        if tv is None:
            return
        try:
            tv.heading("k1", text="键1" + (" ●" if self._key_col == 0 else ""))
            tv.heading("k2", text="键2" + (" ●" if self._key_col == 1 else ""))
        except tk.TclError:
            pass

    def _key_col_move(self, delta):
        """v74：← / → 在「键1 / 键2」两列间切“当前要改的列”。

        → 到键2 就到头（原地停）；← 在键2 = 回键1、在键1 = 回左列表（v53 老路，层级退）。
        """
        if delta > 0:
            new = 1
        elif self._key_col == 1:
            new = 0
        else:
            return self._set_to_menu()
        if new != self._key_col:
            self._key_col = new
            self._key_col_mark()
            self._key_note("当前改键列：%s（← / → 换列）" % ("键1" if new == 0 else "键2"))
        return "break"

    # v40：原 `_key_dialog_ring` / `_key_dialog_tab`（弹窗自己的两站焦点环）**整组删除** ——
    # 快捷键设置成了设置界面里的一块，Tab 交给 Tk 默认焦点环（见 `_rotate_focus_settings`）。

    def _key_dialog_border_sync(self, event=None):
        """把设置窗的「选中行」黑框挪到当前选中行（v38）。

        填充档（蓝底白字 / 淡蓝色底）下画笔自带收起（`set_style` 里 line=None），这里等于空转；
        重建行期间（`_key_refreshing`）挂起，重建完由 `_key_dialog_refresh` 的尾巴补一发。
        """
        tv = self.key_tv
        if tv is None or getattr(self, "_key_refreshing", False):
            return
        rb = self._row_borders.get(tv)
        if rb is None:
            return
        try:
            sel = tv.selection()
            rb.show(sel[0] if sel else None)
        except tk.TclError:
            pass

    def _key_dialog_scrolled(self, first, last, vsb):
        """设置窗列表滚动：滚动条照旧 + **停稳 80ms** 后把黑框补摆到位（v38）。

        口径同主表 v25.10：滚动进行中 `bbox()` 会给出不稳定坐标、照它摆会把框摆到行位
        网格之外 —— 滚动中先不动框，停稳一次摆到位（设置窗是低频操作，这档体感足够）。
        """
        vsb.set(first, last)
        tv = self.key_tv
        if tv is None:
            return
        if self._key_scroll_settle is not None:
            try:
                tv.after_cancel(self._key_scroll_settle)
            except (tk.TclError, ValueError):
                pass
        try:
            self._key_scroll_settle = tv.after(80, self._key_scroll_settled)
        except tk.TclError:
            self._key_scroll_settle = None

    def _key_scroll_settled(self):
        """滚动停稳：把选中框一次摆到位（v38）。"""
        self._key_scroll_settle = None
        self._key_dialog_border_sync()

    def _help_text(self):
        """设置页「快捷键一览」块的现文（v26：跟着自定义键渲染；没改过 == KEY_TABLE 逐字节）。"""
        return help_text_for(getattr(self, "keymap", None) or DEFAULT_KEYMAP)

    # --- v26.1 / v26.4：菜单热键（v37 删 Ctrl+2、v53 删 Ctrl+1 —— 只剩 Ctrl+3）----------------
    def _on_menu_hotkey(self, which):
        """Ctrl+3 —— **直接动作**（v26.4 起不再弹系统原生菜单：`tk_popup` 在 Windows 上
        会卡死解释器 / 留下收不掉的悬空菜单，实测废弃）：
        **v40：菜单栏整条删除** —— 热键改成「开设置界面并定位到某一块」：
        Ctrl+3 = 设置界面 · 快捷键设置。（v37：Ctrl+2「切换配色」已删 —— 配色恒 Radix；
        **v53：Ctrl+1（导入题解包）随该功能一起删** —— 只剩这一条。）
        浮层 / `?` 一览开着时不响应（它们带 grab，叠上去要打架）。
        """
        if self._busy():
            return "break"
        if which == "keys":
            self.open_settings_section("keys")
        return "break"

    # ------------------------------------------------------------ 主题（v23）
    def on_theme_pick(self, which):
        """主题菜单点了一下：把勾选读回来 → 落到内存 → 立刻生效（不写盘，关窗时统一存）。"""
        vars_ = getattr(self, "_sel_vars", {})
        selb = vars_.get("selb").get() if vars_.get("selb") else self.theme_sel_border   # v75.3
        selc = vars_.get("selc").get() if vars_.get("selc") else self.theme_sel_color
        scheme = vars_.get("scheme").get() if vars_.get("scheme") else self.theme_scheme
        today = vars_.get("today").get() if vars_.get("today") else self.theme_today
        prev = vars_.get("preview").get() if vars_.get("preview") else self.preview_mode
        dn = vars_.get("daynight").get() if vars_.get("daynight") else self.theme_daynight  # v75
        self.theme_sel_border, self.theme_sel_color = normalize_sel(selb, selc)
        self.theme_scheme = normalize_scheme(scheme)
        self.theme_today = today if today in (THEME_TODAY_ON, THEME_TODAY_OFF) else THEME_TODAY_ON
        # v75：界面模式（白天 / 黑夜）—— 脏值归白天
        self.theme_daynight = dn if dn in (THEME_DAYNIGHT_DAY, THEME_DAYNIGHT_NIGHT) else THEME_DAYNIGHT_DAY
        # v45：P 键题解显示方式（脏值归 side）；两种显示互斥 —— 切档当场把另一种收掉
        new_mode = prev if prev in (PREVIEW_MODE_SIDE, PREVIEW_MODE_FULL) else PREVIEW_MODE_SIDE
        if new_mode != self.preview_mode:
            self.preview_mode = new_mode
            if new_mode == PREVIEW_MODE_SIDE:
                self._exit_md_full()          # 切回右侧栏：全屏 md 收掉（在设置里 → 不动焦点）
            else:
                self._hide_preview()          # 切去全屏：右侧栏收掉（下次 P 起全屏）
        self._apply_theme()
        self.set_msg("边框：%s ｜ 颜色：%s ｜ 配色：%s ｜ 今天标记：%s ｜ 题解预览：%s ｜ 界面模式：%s"
                     % (dict(THEME_SELB_ITEMS).get(self.theme_sel_border, self.theme_sel_border),
                        dict(THEME_SELC_ITEMS).get(self.theme_sel_color, self.theme_sel_color),
                        dict(THEME_SCHEME_ITEMS).get(self.theme_scheme, self.theme_scheme),
                        dict(THEME_TODAY_ITEMS).get(self.theme_today, self.theme_today),
                        dict(THEME_PREVIEW_ITEMS).get(self.preview_mode, self.preview_mode),
                        dict(THEME_DAYNIGHT_ITEMS).get(self.theme_daynight, self.theme_daynight)),
                     clear_after=TOAST_MS)

    def _apply_sel_map(self, st=None):
        """「当前行颜色」档 → `Status.Treeview` 的选中样式映射（v75.3：底色归颜色组、框归边框组）。

        颜色有填充 → 铺底 + 换字色；颜色「无」→ 映射**全清空**（底 / 字交还行 tag —— 这正是原
        「纯边框」两档的行为，靠「颜色 = 无」还原）。

        v75：从 `_apply_theme` 开头抽出来 —— `_apply_framework` 重配 ttk 样式（`_setup_styles`
        里那份**初始** map）之后必须**再调一次**，否则会把用户选的档顶掉（清空映射会被顶回来）。
        """
        st = st or ttk.Style(self.root)
        color = SEL_COLOR.get(self.theme_sel_color)
        if color:
            st.map("Status.Treeview",
                   background=[("selected", "focus", color["bg"]),
                               ("selected", "!focus", color["bg_blur"])],
                   foreground=[("selected", "focus", color["fg"]),
                               ("selected", "!focus", color["fg_blur"])])
        else:
            # 「无」档（= 原边框两档同款）：**映射全清空** —— 选中行底 / 字原样不动（斑马纹 /
            # 状态色是什么还是什么），框只由 `_RowBorder` 画（有没有框看「当前行边框」档）。
            # 机制实测（edge_probe2）：ttk 在 "selected 无映射" 时会**回落 tag 的色** ——
            # 旧实现（映射成 C_PANEL）会把选中行刷成一个自带白底的行，用户点名不要那个。
            st.map("Status.Treeview", background=[], foreground=[])

    def _auto_swap_sel_border(self):
        """v85：界面**由亮变暗 / 由暗变亮那一刻**，「当前行边框」黑 ⇄ 白 自动互切。

        口径（用户 2026-10-07 拍板）：进暗色且当前是**黑框** → 换白框；进亮色且当前是**白框**
        → 换黑框；「无」不动；**只认翻面那一拍** —— 手动在深色下选黑框不强制纠偏。判据同 v80 的
        `_ui_dark()`（D 系配色恒深 / 亮色配色按黑夜模式）。落点 = `_apply_theme` 开头（换配色 /
        昼夜开关 / 启动都经过它）；翻完设置页那组单选钮跟着走、配置照旧关窗统一存。
        """
        dark = self._ui_dark()
        prev = getattr(self, "_ui_dark_prev", None)
        self._ui_dark_prev = dark
        if prev is None or prev == dark:
            return                                   # 开窗第一发（只记基准）与同色翻页都不动
        new = None
        if dark and self.theme_sel_border == "black":
            new = "white"
        elif (not dark) and self.theme_sel_border == "white":
            new = "black"
        if new is None:
            return
        self.theme_sel_border = new
        var = getattr(self, "_sel_vars", {}).get("selb")      # 设置页没建过 = None，跳过
        if var is not None:
            try:
                var.set(new)
            except tk.TclError:
                pass

    def _apply_theme(self):
        """把当前主题落到界面：选中行的样式 + 行 tag 的配色 + 今天竖条，然后重绘。

        ① **选中行**：`Status.Treeview` 的 `map(("selected", …))` 由主题给 —— 填充档（蓝底白字 /
           淡蓝色底）铺底 + 换字色；**边框档（黑色 / 白色，v72 加后者）把映射整个清空**（底 / 字
           全交还给行 tag，只由 `_RowBorder` 画一圈线 —— v25.1「纯边框」，选中行底色一个字不变）。
           （v75 起这段抽成 `_apply_sel_map` —— `_apply_framework` 里也要重设一遍。）
        ② **配色**（v71 起 = 12 套里选一套）：一状态一个行 tag（背景 = 状态色、前景 = 该状态的
           状态字色（v71.1：= HTML chip 的字色，v25 口径回归）；「未做」行走斑马纹）+
           今天日期字 + 行首竖条（#0 窄列）—— 斑马 / 层级四色 / 竖条色**都逐套配色**给。
        ③ **v85 前置**：进门先跑 `_auto_swap_sel_border()` —— 亮 / 暗翻面那一拍把「当前行边框」
           黑 ⇄ 白互切（必须在下面取 border 档**之前**，当拍就用上新档）。
        """
        self._auto_swap_sel_border()   # v85：黑 / 白框随亮暗翻面自动互切（用户拍板口径见方法注释）
        border = SEL_BORDER.get(self.theme_sel_border, SEL_BORDER["none"])  # v75.3：画笔档（下面两处用）
        self._apply_sel_map()                                     # 选中行样式映射（内部自取 st / 颜色档）
        scheme = SCHEME.get(self.theme_scheme, SCHEME["radix"])
        # v25：最左的 6px 窄列（#0）画「今天竖条」；
        # v28：**两档配色都放它出来**（用户口径「两档配色都显示竖条」+「关闭时位置仍保留」）——
        #      show 恒 "tree headings"，开关只控制画不画条，窄列位置恒占、行内容不左右跳
        for tv in (getattr(self, "tree", None), getattr(self, "tree_split", None)):
            if tv is not None:                       # v66：分屏页那张表也放 #0 窄列出来
                tv.configure(show="tree headings")
        trees = [t for t in (getattr(self, "tree", None), getattr(self, "tree_split", None),
                             getattr(self, "today_tree", None),
                             getattr(self, "know_tree", None),
                             getattr(self, "round_tree", None)) if t is not None]
        for tree in trees:
            self._configure_scheme_tags(tree, scheme, self.theme_scheme)   # v77：传键（unset 字色分深浅套）
            rb = self._row_border(tree)
            rb.set_style(border)
            rb.set_focused(self._tree_has_focus(tree))   # v25.2：换档时同步聚焦 / 失焦线色
        # v38 立、v40 扩、v80 改：设置界面那两张表（快捷键 / 左侧菜单）的选中框
        #      **不跟「当前行边框」档** —— 统一取主题相反色（用户口径；挂在文末 `_set_page_border`）
        for tree in trees:                       # 各表都重绘一遍（重建行 tag）
            try:
                if tree is self.tree:
                    self.refresh_view()
                elif tree is self.today_tree:
                    self.refresh_today()
                elif tree is getattr(self, "round_tree", None):
                    if self.know_mode == "round":       # v27：只重画当前露着的那张
                        self.refresh_rounds()
                elif self.know_mode == "know":
                    self.refresh_know()
            except tk.TclError:
                pass
        # v71：行首竖条颜色逐套配色（深色套 = 浅墨）—— 池子里的 Frame 是**建出来那一下**上的色，
        #      切配色得把已有条逐个刷一遍（总表 / 分屏页各一个池子；还没建过 = 空池子、无事发生）
        bar_c = scheme.get("bar") or TODAY_BAR_COLOR
        for _f in list(getattr(self, "_bar_frames", [])) + list(getattr(self, "_bar_frames_split", [])):
            try:
                _f.configure(bg=bar_c)
            except tk.TclError:
                pass
        self._sync_today_bar()      # v28：切主题 / 今天标记开关后，竖条立刻跟着变（关 = 全收起）
        self._sync_all_row_borders()
        self._apply_framework()     # v75：界面模式（白天 / 黑夜）→ 框架色（表行已刷完，最后落框架）
        self._set_page_border()     # v80：设置页框色 = 主题相反色（换配色 / 昼夜后重刷）

    # --- v75 黑夜模式：界面框架色（用户口径「黑夜模式中所有非表行的部分都变成深色」）-----

    def _apply_framework(self):
        """把「界面模式 + 配色」落成**界面框架色**（表行不动 —— 行色仍归那 12 套配色）。

        生效板 = `frame_palette(theme_scheme, theme_daynight)`；**D 系深色配色恒深**（v75.1 用户
        拍板），亮色配色按昼夜开关。只在「生效板变了」时动手（板身份：D 系 = 套键 / 亮+白天 =
        "light" / 亮+黑夜 = "fallback"）：
          ① global 覆盖模块常量（C_BG 等）→ **之后新建**的控件自动拿新色；
          ② `_setup_styles()` 重配 ttk 样式（表格空白区 / 表头 / 输入框 / 按钮 / 滚动条）；
          ③ `_apply_sel_map()` 重设「选择当前行」档映射（`_setup_styles` 那行初始 map 会顶掉它）；
          ④ 遍历现有控件（含已开的 Toplevel 弹窗）按「任一台板色 → 新板对应槽」刷颜色；
          ⑤ md 预览 `set_dark`（懒加载没起过就跳过 —— 起窗时 `_ensure_preview` 会补上）。

        ⚠️ 三类"覆盖件"跳刷（色属配色 / 主题，可能与框架板有同值 —— 照刷必串色）：
        今天竖条（`_bar_frames*`）、选中行边框（`_row_borders[*].frames`）、
        遮色条（`_pads[*].pads`）。
        """
        # v75 / v75.1：板身份只按"生效板"算 —— D 系深色配色**恒深**（不用开黑夜模式；用户拍板
        #   「切到 Radix Dark / Nord 这类深色配色时，整个界面也该跟着变深色」），亮色配色按
        #   白天浅色板 / 黑夜中性兜底。key = 板键（不带 daynight：D 系下拨昼夜开关不该重刷）。
        if self.theme_scheme in FRAME_SCHEMES:
            pal_id = self.theme_scheme
        else:
            pal_id = "fallback" if self.theme_daynight == THEME_DAYNIGHT_NIGHT else "light"
        key = pal_id
        prev_key = getattr(self, "_fw_key", None)
        if key == prev_key:
            return
        self._fw_key = key
        if pal_id == "light" and prev_key is None:
            return                       # 启动即「亮色 + 白天」：常量本就是浅色，无需刷
        night = pal_id != "light"        # "界面是深的"（D 系恒深 / 亮色黑夜兜底）——滚条 / md 用
        pal = frame_palette(self.theme_scheme, self.theme_daynight)
        self._set_global_frame_colors(pal)
        self._setup_styles()
        self._apply_sel_map()        # `_setup_styles` 那份初始选中 map 会顶掉「选择当前行」档 —— 重设
        self._recolor_framework(pal, night)
        prev = getattr(self, "prev", None)
        if prev is not None:
            try:
                prev.set_dark(self.theme_scheme if night else None)
            except Exception:
                pass

    def _set_global_frame_colors(self, pal):
        """把生效板写进模块常量 —— 之后**新建**的控件（弹窗 / 新竖条 / 占位提示…）直接是新色。"""
        global C_BG, C_PANEL, C_TEXT, C_MUTED, C_ACCENT, C_ACCENT_DARK, \
            C_ACCENT_LIGHT, C_LINE, C_SELECT_OFF, C_PLACEHOLDER, C_OK, C_ERR
        C_BG = pal["bg"]
        C_PANEL = pal["panel"]
        C_TEXT = pal["text"]
        C_MUTED = pal["muted"]
        C_ACCENT = pal["accent"]
        C_ACCENT_DARK = pal["accent_dark"]
        C_ACCENT_LIGHT = pal["accent_light"]
        C_LINE = pal["line"]
        C_SELECT_OFF = pal["select_off"]
        C_PLACEHOLDER = pal["placeholder"]
        C_OK = pal["ok"]
        C_ERR = pal["err"]

    def _framework_skip_ids(self):
        """三类覆盖件的 id 集合（见 `_apply_framework` docstring 的黑名单）。"""
        skip = set()
        for f in list(getattr(self, "_bar_frames", [])) + list(getattr(self, "_bar_frames_split", [])):
            skip.add(id(f))
        for rb in getattr(self, "_row_borders", {}).values():
            for f in getattr(rb, "frames", ()) or ():
                skip.add(id(f))
        for pads in getattr(self, "_pads", {}).values():
            for f in getattr(pads, "pads", ()) or ():
                skip.add(id(f))
        return skip

    def _recolor_framework(self, pal, night):
        """遍历主窗口（递归含已开的 Toplevel）按「任一板色 → 当前生效板」刷颜色属性；
        顺手把滚动条切到 "Dark.VScrollbar"（深）/ 默认 Vertical.TScrollbar（浅）。"""
        mapping = {}
        for src in [FRAME_LIGHT] + list(FRAME_SCHEMES.values()) + [FRAME_FALLBACK]:
            for k, v in src.items():
                try:
                    mapping[self.root.winfo_rgb(v)] = pal[k]
                except tk.TclError:
                    pass
        skip = self._framework_skip_ids()
        cache = {}
        sb_style = "Dark.VScrollbar" if night else "Vertical.TScrollbar"
        hb_style = "Dark.HScrollbar" if night else "Horizontal.TScrollbar"   # v87：横向那款（见 _setup_styles）
        stack = [self.root]
        while stack:
            w = stack.pop()
            if id(w) in skip:
                continue
            self._recolor_one(w, mapping, cache, sb_style, hb_style)
            try:
                stack.extend(w.winfo_children())
            except tk.TclError:
                pass

    @staticmethod
    def _recolor_one(w, mapping, cache, sb_style, hb_style):
        """一个控件的颜色属性刷一遍（属性值恰是某个板色才动；ttk 控件没这些属性、自然跳过）。"""
        for attr in ("bg", "fg", "background", "foreground", "activebackground",
                     "activeforeground", "selectcolor", "selectbackground",
                     "selectforeground", "highlightbackground", "highlightcolor",
                     "troughcolor"):
            try:
                cur = w.cget(attr)
            except tk.TclError:
                continue
            if not cur:
                continue
            rv = cache.get(cur)
            if rv is None:
                try:
                    rv = w.winfo_rgb(cur)
                except tk.TclError:
                    continue
                cache[cur] = rv
            new = mapping.get(rv)
            if new is None or str(new) == str(cur):
                continue
            try:
                w.configure(**{attr: new})
            except tk.TclError:
                pass
        # v75：滚动条（ttk）没有 bg 配置 —— 切样式名（"Dark.VScrollbar" 在 `_setup_styles` 里配）
        # v87：按方向选名 —— 竖向竖样式 / 横向横样式（横向套竖向布局会画错；v82 的方向前缀教训同源）
        try:
            if w.winfo_class() == "TScrollbar":
                w.configure(style=sb_style if str(w.cget("orient")) == "vertical" else hb_style)
        except tk.TclError:
            pass

    def _configure_scheme_tags(self, tree, scheme, scheme_key=None):
        """按配色把行 tag 配好（含**清掉另一套**）——切的瞬间不留旧色。

        v71 / v71.1：四类 tag 全部**逐套配色**给 —— 状态（底色 + **该状态自己的彩色字**，= HTML chip
        那对「底 / 字」）/ 斑马（两档 + 该套正文色）/ 层级四色（+ 该套正文色）/ 今天日期字。
        状态行用 `scheme["status"][s][1]`（该状态字色）；**没有状态的行**用 `scheme["ink"]`（该套默认正文色）。

        v77：**未做行**（含空状态）从 odd / even 换到 `unsetOdd` / `unsetEven`（底仍 = 该套斑马两档）——
        字色：**深色 6 套 = 该套「次要文字色」**（`FRAME_SCHEMES[key]["muted"]`；用户 2026-10-07 口径
        「默认行的字现在是白色的，改成深色」= 整行调暗一档 —— Radix Dark 下 = #B4B4B4），亮色 6 套
        = `ink`（与原来 odd / even 完全一致 ——「亮主题默认行不动」）。odd / even 原样保留（看板类
        标题行仍走它们）。
        """
        status = scheme.get("status")
        ink = scheme.get("ink") or C_TEXT
        # ① 状态 tag：先全清（清掉上一套配色留下的），再按当前配色配
        for s in STATES:
            tag = theme_tag(s)
            if status and s in status:
                # v71.1：背景 = 状态底色、前景 = 该状态**自己的彩色字**（= HTML chip 的字色）。
                # 没用的那一半必须显式写回默认值（tag_configure 不能"删除"，不写会留着旧值）。
                tree.tag_configure(tag, background=status[s][0], foreground=status[s][1])
            else:
                # 不用了就"配置成空"（tag_configure 不支持删除，配成和默认一样即可）
                tree.tag_configure(tag, background=C_PANEL, foreground=ink)
        # ② 斑马纹（v25.1；v71 逐套）：**每套配色自己的两档斑马** + 该套默认正文色 ——
        #    「未做」/ 空状态的行走它（用户口径「默认状态的行 = 斑马条纹」），看板类标题行也走它；
        #    深色套是深灰两档 + 浅墨字（白斑马在深色套里会亮得扎眼）。
        zeb = scheme.get("zebra") or (C_PANEL, C_ZEBRA)
        tree.tag_configure("odd", background=zeb[0], foreground=ink)
        tree.tag_configure("even", background=zeb[1], foreground=ink)
        # ②b v77：**未做行**（含空状态）专用 —— 底 = 同斑马两档；字 = 深色 6 套的「次要文字色」
        #     （`FRAME_SCHEMES` 的 muted；整行调暗一档），亮色 6 套仍 ink（见上面 docstring）。
        sk = scheme_key or self.theme_scheme
        unset_fg = FRAME_SCHEMES[sk]["muted"] if sk in FRAME_SCHEMES else ink
        tree.tag_configure("unsetOdd", background=zeb[0], foreground=unset_fg)
        tree.tag_configure("unsetEven", background=zeb[1], foreground=unset_fg)
        # ③ 层级色阶 tag（v30/v33 立；**v71 逐套配色**；**v86 加 lvl0 = 平台层**）：
        #    lvl0 / lvl0b = 最顶层的「浅档 / 深档」（**按场次视图的平台行** —— 牛客 / 洛谷 / …）；
        #    lvl1 / lvl1b = 顶层的「浅档 / 深档」（父行 / 平铺知识点 / 按场次系列行）；
        #    lvl2 / lvl2b = 二层的「浅档 / 深档」（子行 / 按场次场次行）—— 每套主题各配一组，
        #    用户口径「父行之间是一种配合色、子行之间是一种配合色」；
        #    v97：lvl3 / lvl3b = 知识点统计**第三层及更深**的两档（多级桶；按场次视图不用）。
        lv0 = scheme.get("lvl0") or (C_LVL0, C_LVL0B)
        lv1 = scheme.get("lvl1") or (C_LVL1, C_LVL1B)
        lv2 = scheme.get("lvl2") or (C_LVL2, C_LVL2B)
        lv3 = scheme.get("lvl3") or (C_LVL3, C_LVL3B)
        tree.tag_configure("lvl0", background=lv0[0], foreground=ink)
        tree.tag_configure("lvl0b", background=lv0[1], foreground=ink)
        tree.tag_configure("lvl1", background=lv1[0], foreground=ink)
        tree.tag_configure("lvl1b", background=lv1[1], foreground=ink)
        tree.tag_configure("lvl2", background=lv2[0], foreground=ink)
        tree.tag_configure("lvl2b", background=lv2[1], foreground=ink)
        tree.tag_configure("lvl3", background=lv3[0], foreground=ink)
        tree.tag_configure("lvl3b", background=lv3[1], foreground=ink)
        # ④ 今天：只剩 `today` = 日期字（只设前景；v71 起 = 该套默认正文色 —— 深色套是浅色，
        #    同时行首竖条也跟着换色，见 `_apply_theme` 的刷条那段）
        tree.tag_configure("today", foreground=(scheme.get("today_fg") or ink))

    def _row_tags(self, row, k, today):
        """一行挂哪些 tag（v25.1：这里就是「配色」真正生效的地方）。

        规则（v22.1 的教训照旧成立）：**同一属性只让一个 tag 说话**。
        - **除「未做」外**的状态行只挂它的状态 tag（背景 = 状态色、前景 = 状态字色）；
          **「未做」/ 状态为空的行走 `unsetOdd` / `unsetEven`**（v25.1 用户口径「默认状态、
          我没主动更新的行 = 斑马条纹」；v77 起这两个 tag 专门承载它们 —— 底 = 斑马两档，
          字 = 深色 6 套调暗到该套「次要文字色」、亮色 6 套仍是 ink，见 `_configure_scheme_tags`）
          —— 大片未做不再糊成一片灰，有色的行反而更跳出来；
        - 默认：全是斑马纹 —— v28 起「今天」**不再有淡绿整行底**（用户点名去掉），今天行也走
          斑马纹（它的标记 = 行首竖条，跟 tag 无关，见 `_sync_today_bar`）；
        - 「今天」的日期字深墨（`today`，只设前景）在 Radix 下另外挂，跟底色不打架。
        """
        scheme = SCHEME.get(self.theme_scheme, SCHEME["radix"])
        st = row.get("状态")
        if scheme.get("status"):
            base = [theme_tag(st)] if (st and st != ZEBRA_IN_RADIX) \
                else ["unsetEven" if k % 2 else "unsetOdd"]          # v77：未做 / 空状态行
            return base + (["today"] if today else [])
        return ["unsetEven" if k % 2 else "unsetOdd"]                # v77：同上（兜底路径）

    # --- 选中行的边框（v23）------------------------------------------------
    def _bind_theme_events(self, tree):
        """把「选中行边框」需要的绑定挂到某张表上（v23；v25.1 起统一走空闲重摆通道）。

        - `<<TreeviewSelect>>`：选中行变了 → 立即画一次 + 排空闲重摆（v29 起看板那棵就这一条；
          此前 v10 的 `_on_today_select` 占过一条，随四段合并删除）；
        - `<MouseWheel>`：滚动后补一次重摆（`after_idle` 错开一拍，让 Treeview 先滚完）；
        - `<FocusIn>` / `<FocusOut>`：焦点进出表格 → 黑框换聚焦 / 失焦线色（v25.2）；
        - `<Configure>`：改窗大小那一发已经在 `_on_tree_configure` 里带上了（见那里的 `_sync_all_row_borders`）。
        """
        tree.bind("<<TreeviewSelect>>", self._on_tree_sel_change, add="+")
        tree.bind("<MouseWheel>", self._on_wheel_redraw_border, add="+")
        tree.bind("<FocusIn>", self._refresh_border_focus, add="+")
        tree.bind("<FocusOut>", self._refresh_border_focus, add="+")

    def _row_border(self, tree):
        """拿（没有就建）某张表的"选中行边框"画笔。"""
        rb = self._row_borders.get(tree)
        if rb is None:
            rb = _RowBorder(tree)
            self._row_borders[tree] = rb
        return rb

    def _tree_has_focus(self, tree):
        """这个表格（或它族里的控件）还拿着键盘焦点吗（v25.2，黑框聚焦 / 失焦两档用）。"""
        try:
            cur = tree.focus_get()
        except (KeyError, tk.TclError):
            cur = None
        while cur is not None:
            if cur is tree:
                return True
            cur = getattr(cur, "master", None)
        return False

    def _refresh_border_focus(self, event=None):
        """`<FocusIn>` / `<FocusOut>`（三张表都挂着）→ 换聚焦 / 失焦线色并重画（v25.2）。

        v28：顺带把遮色条也刷一遍 —— 选中行四边条跟着选中色走，而聚焦 / 失焦是两档色
        （如 `#2f6fed` ⇄ `#c9d4e6`），焦点一搬家不刷会留一条亮蓝边。
        """
        for tree, rb in list(self._row_borders.items()):
            try:
                rb.set_focused(self._tree_has_focus(tree))
                rb.redraw()
            except tk.TclError:
                pass
        self._sync_row_pads()

    def _sync_all_row_borders(self):
        """三张表的选中行边框各重画一次（切主题 / 重绘 / 滚动 / 改窗大小之后都要喊一声）。

        v25.7：末尾顺带同步「遮色条」阵列（重药）—— 残留像素就靠它盖住。
        """
        for tree, rb in list(self._row_borders.items()):
            try:
                sel = tree.selection()
                rb.show(sel[0] if sel else None)
                # v60：顺手记「摆框时的选中」—— 重建里 `selection_set` 排下的 `<<TreeviewSelect>>`
                # 是**排队**事件，到点处理时看到的选中跟这里一模一样（= 重建回声），那发直接跳过
                # （框已摆好；它还会排一次 deep flush 整树重绘，平白拖慢切页）。
                self._rebuild_sel[tree] = tuple(sel)
            except tk.TclError:
                pass
        self._sync_row_pads()

    def _row_bg_of(self, tree, iid):
        """该行此刻的底色（按行 tag 的 background 取；没配 tag 就用面板白）。"""
        try:
            tags = tree.item(iid, "tags")
        except tk.TclError:
            return C_PANEL
        if not isinstance(tags, (list, tuple)):
            tags = (tags,)
        for t in tags:
            try:
                c = str(tree.tag_configure(t, "background") or "")
            except tk.TclError:
                c = ""
            if c:
                return c
        return C_PANEL

    def _selection_fill_color(self, tree):
        """选中行的**填充色**（「蓝底白字」/「淡蓝色底」两档）；边框档（黑色 / 白色）不铺底 → None。

        遮色条铺在选中行四边时用它（v28）：四边条原来跟着"行底色"走，选中行会被四条行色边
        "框住" —— 用户实测原话「蓝底没有完全覆盖当前行，在当前行的顶部有很小的宽度还是原色」。
        聚焦 / 失焦两档的判定与 ttk 选中映射（`("selected","focus")` / `("selected","!focus")`）
        同源，见 `_tree_has_focus`（v25.2 的口径）。
        """
        color = SEL_COLOR.get(getattr(self, "theme_sel_color", "blue"))
        if not color:                       # v75.3：「无」档不铺底 → 没有填充色（遮色条不铺）
            return None
        return color["bg"] if self._tree_has_focus(tree) else color["bg_blur"]

    def _sync_row_pads(self):
        """遮色条阵列（v25.7 重药）：把总表「可见行位」的底色同步给 pads（其他表先不做）。"""
        tree = getattr(self, "tree", None)
        if tree is None:
            return
        pads = self._pads.get(tree)
        if pads is None:
            pads = _RowPads(tree)
            self._pads[tree] = pads
        rows = []
        try:
            # v28：选中行的四条边用**选中色**（复现探针：修前顶部/底部 2px、左侧 6px、右侧 2px
            # 全是行底色 #FDDCDE；修后全变选中蓝 #2f6fed）。边框档不铺底 → fill 为 None，
            # 照旧用行底色（纯边框口径不变）。
            sel = set(tree.selection())
            fill = self._selection_fill_color(tree)
            for iid in tree.get_children():
                box = tree.bbox(iid)
                if not box:
                    continue
                color = self._row_bg_of(tree, iid)
                if fill and iid in sel:
                    color = fill
                rows.append((box, color))
        except tk.TclError:
            return
        # v25.18：左条加宽到 6px —— 今天竖条（也在 6px 窄列）挪走后，旧像素靠它盖住。
        # v28：两档配色都用 6px 窄列了（今天标记位置恒占），left_w 一律 6。
        pads.sync(rows, left_w=TODAY_BAR_W)
        # ⚠️ z 序：条是"后建 / 后 place"的窗口，新条会天然压到黑框与竖条之上（框会整片
        # 不可见 —— 探针逮到过）。每轮同步完把"框 + 竖条"抬回最上层。
        for rb in list(self._row_borders.values()):
            for f in rb.frames:
                try:
                    f.lift()
                except tk.TclError:
                    pass
        for f in getattr(self, "_bar_frames", []):
            try:
                f.lift()
            except tk.TclError:
                pass
        # v88：末尾原本还有一发「把 v22 列间竖线抬回遮色条之上」（v82c）—— 竖线已整条去掉，那段删

    # --- Radix 的「今天竖条」（v25）------------------------------------------
    def _bar_frame(self, i, tree=None):
        """竖条用的小 Frame（池子，用多少补多少）——条会把点击吃掉，自己转发选中那一行。

        v66：`tree` 给了就用分屏页那只池子（`_bar_frames_split`，父窗口是 `tree_split`）——
        两张表各有自己的竖条框（Frame 必须挂在它盖的那张表里才跟得上滚动）。
        v71：新框按**当前配色**的竖条色建（深色套 = 浅墨）；已有框的换色由 `_apply_theme` 刷。
        """
        pool = self._bar_frames if tree is None or tree is self.tree else self._bar_frames_split
        parent = self.tree if tree is None else tree
        bar_c = (SCHEME.get(self.theme_scheme, SCHEME["radix"]).get("bar") or TODAY_BAR_COLOR)
        while len(pool) <= i:
            f = tk.Frame(parent, bg=bar_c, bd=0,
                         highlightthickness=0, takefocus=0)
            f.bind("<Button-1>", self._on_bar_pick)
            f._iid = None
            f._shown = False                 # v25.2：摆放位置缓存（没变的帧不发 Tcl）
            f._pos = None
            pool.append(f)
        return pool[i]

    def _on_bar_pick(self, event):
        """点竖条 → 选中它盖住的那一行（Frame 会吃掉点击，得自己转发）。

        v66：转发到**它所在的那张表**（`event.widget.master`）—— 分屏页的竖条归分屏页那张表。
        """
        iid = getattr(event.widget, "_iid", None)
        tree = getattr(event.widget, "master", None) or self.tree
        try:
            if iid and tree.exists(iid):
                tree.selection_set(iid)
                tree.focus(iid)
                tree.focus_set()
        except tk.TclError:
            pass
        return "break"

    def _on_tree_scrolled(self, first, last, vsb):
        """滚动条更新 + 排一发空闲重摆（`after_idle` 合并 —— 拖滚动条时这个钩子会被连喊好几遍）。

        v25.1：重摆内容从「今天竖条」扩成「**竖条 + 全部选中行边框**」—— 键盘连按 ↑ / ↓ 时
        `see()` 的滚动不走 `<MouseWheel>`，黑框那 4 条线会停在滚动前的位置（用户实测
        「持续按方向键有画面更新跟不上的重影」）。所有会挪行位置的事件统一走这一条空闲通道。
        """
        vsb.set(first, last)
        if getattr(self, "tree", None) is not None and self._row_borders.get(self.tree) is not None:
            try:
                self._sync_row_pads()    # v25.19：滚轮 / 拖条也把遮色条的颜色跟住（同上一处注释）
            except tk.TclError:
                pass
        # v25.10（录屏实证驱动）：**滚动"停稳"后再重摆** —— 滚动进行中 `bbox()` 会给出不稳定
        # 坐标，照它 place 会把框摆到「行位网格之外」（录屏实锤：按住方向键时屏上累积一串错位
        # 黑框、松手才清）。滚动中先不动框（用户已拍板「可以慢一点点」），停稳 80ms 后一次摆到位。
        if self._scroll_settle is not None:
            try:
                self.tree.after_cancel(self._scroll_settle)
            except (tk.TclError, ValueError):
                pass
        self._scroll_settle = self.tree.after(80, self._scroll_settled)

    def _scroll_settled(self):
        """滚动停稳：一次性把「竖条 + 选中行框」摆到位（v25.10）。

        v25.17：擦除统一收进 `_repaint_idle` 的 `_flush_screen`，这里不再单发 `_paint_now`。
        """
        self._scroll_settle = None
        self._repaint_idle()

    def _paint_now(self):
        """同步把"已标脏的区域"画掉（v25.11）。

        `UpdateWindow` = 直接发一次 WM_PAINT，只画 update region（我们 `InvalidateRect` 标脏的
        旧框区），**不跑事件循环** —— 这是"单步手感"与"按住不累积"之间的平衡点：
        比 `update()`（全循环、数据越重越慢）便宜得多，又不像"纯等自然重绘"那样被按键饿死。
        """
        try:
            ctypes.windll.user32.UpdateWindow(self.tree.winfo_id())
        except Exception:
            pass

    def _schedule_repaint(self, delay_ms=1):
        """排一发重摆（连发的滚动 / 选中事件合并成一发；句柄共用 `_bar_after`）。

        v25.2：调度从 `after_idle` 改成 **`after(1)` 定时器** —— Tk 的事件优先级里
        定时器（timer）**高于空闲任务（idle）**：连按方向键时 idle 会被按键事件饿死，
        而定时器每 1ms 必然轮得到（按键重复间隔 ~33ms，空档足够）。
        v25.5：`delay_ms` 可调 —— 连按节流时用 `BORDER_SEL_GAP_MS` 排"押后补刷"。
        """
        if self._bar_after is not None:
            try:
                self.tree.after_cancel(self._bar_after)
            except (tk.TclError, ValueError):
                pass
        self._bar_after = self.tree.after(delay_ms, self._repaint_idle)

    def _cancel_pending_show(self):
        """撤掉"单步延迟显示"的定时器（v25.14）。"""
        if self._show_after is not None:
            try:
                self.tree.after_cancel(self._show_after)
            except (tk.TclError, ValueError):
                pass
            self._show_after = None

    def _cancel_pending_repaint(self):
        """v60：撤掉排队中的"延迟重摆"（`_bar_after` / `_scroll_settle` / `_show_after`）。

        重建（`refresh_view`）收尾用：整表是刚画的全新画面、框和竖条也在收尾同步摆过 ——
        那些按「旧行位」排下的重摆跑起来只是再做一次整树 deep 重绘（实测拖到切页后
        40~150ms 才到点，用户看到「切回来之后画面又闪一下」），纯浪费。
        """
        for attr in ("_bar_after", "_scroll_settle", "_show_after"):
            h = getattr(self, attr, None)
            if h:
                try:
                    self.tree.after_cancel(h)
                except (tk.TclError, ValueError):
                    pass
                setattr(self, attr, None)

    def _show_pending(self):
        """单步的延迟显示到点：把框摆到记录的目标并落地（v25.14）。"""
        self._show_after = None
        rb = self._row_borders.get(getattr(self, "tree", None))
        if rb is not None and rb.iid:
            rb.redraw()
            self._paint_now()

    def _repaint_idle(self):
        self._bar_after = None
        self._cancel_pending_show()
        boxes = self._overlay_boxes()        # 动之前先记旧位（框 / 竖条）
        self._sync_today_bar()
        self._sync_all_row_borders()
        self._flush_screen(boxes, deep=True)  # v25.18：盖条 + 整树 Expose 一发（低频路径，清错位残余）

    def _sync_today_bar(self, tree=None):
        """给总表「今天」各行在最左 #0 窄列贴一条深墨竖条（只总表，看板 / 统计不挂）。

        v28：**两档配色都画**（默认档的"今天"不再用淡绿底，改用这支竖条），
        由「主题 ▸ 今天标记」开关控制（默认开）；**关掉只是不摆条，6px 窄列位置保留**
        （用户口径「关闭时位置仍保留」—— 开关切换行内容不左右跳）。

        **为什么是 Frame 贴条**：v25 的第一版用 `item(image=…)` 挂 #0 列 —— **像素实测不可行**：
        ttk 的树列固定留 20px 缩进，图片被推到 x≈23，6px 窄列把它整条裁掉；indent 在 Tk 8.6
        改不了（`style configure("Treeview"/"X.Treeview", indent=…)` 与 `column anchor` 三条路
        都实测无效）。改回 v22 列间竖线的老办法：`tk.Frame` + `bbox` 定位 + 滚动重摆
        （ttk 的 bbox 是准的，这套机制列间竖线用了一个月没出过错）。
        v28 起两档配色都画（默认档的"今天"不再用淡绿底）；开关关 / 不是今天 → 全部收起。
        """
        if tree is None:
            tree = getattr(self, "tree", None)
        if tree is None:
            return
        pool = self._bar_frames if tree is self.tree else self._bar_frames_split
        n = 0
        if getattr(self, "theme_today", THEME_TODAY_ON) == THEME_TODAY_ON:
            today = datetime.date.today().isoformat()
            for iid in tree.get_children():
                r = self.row_by_iid(iid)
                if not (r and r.get("日期") == today):
                    continue
                try:
                    box = tree.bbox(iid)
                except tk.TclError:
                    box = ""
                if not box:
                    continue                        # 行滚出视口：这条不摆（滚回来会重摆）
                f = self._bar_frame(n, tree)
                f._iid = iid
                pos = (box[0], box[1], TODAY_BAR_W, box[3])
                if not getattr(f, "_shown", False) or getattr(f, "_pos", None) != pos:
                    f.place(x=box[0], y=box[1], width=TODAY_BAR_W, height=box[3])
                    if not getattr(f, "_shown", False):
                        f.lift()                    # 压在行内容之上（只在新显示那一下 lift）
                    f._shown = True
                    f._pos = pos
                n += 1
        for f in pool[n:]:
            if getattr(f, "_shown", False):
                try:
                    f.place_forget()
                except tk.TclError:
                    pass
                f._shown = False
            f._iid = None

    def _repaint_overlays_now(self):
        """给所有在屏浮层（选中框 / 今天竖条）补一发 Expose 并当场落实（v25.18.4）。

        ⚠️ 顺序不能反：**先 `update_idletasks()`（让 place 的 map 生效）再 Expose** ——
        `place()` 之后 `winfo_ismapped()` 还是 0（map 要等一拍），此时发的 Expose 会被白白丢掉，
        框就一直不画。按住滚到视口边（每步都伴随整树滚动重画）时"整段没有框"就是这么来的：
        探针实测 —— 只 update_idletasks 打不亮（还是行底色），补一发 Expose + idletasks 立刻变黑。
        """
        tree = getattr(self, "tree", None)
        if tree is None:
            return
        try:
            tree.update_idletasks()
            for f in self._overlay_frames():
                try:
                    if f.winfo_ismapped():
                        f.event_generate("<Expose>")
                except tk.TclError:
                    pass
            tree.update_idletasks()
        except tk.TclError:
            pass

    def _overlay_frames(self):
        """所有浮在表格上的小窗（三张表的选中框 + 今天竖条）—— 给"整树重画后补一发 Expose"用
        （v25.18.1）。"""
        out = []
        for rb in list(self._row_borders.values()):
            out.extend(rb.frames)
        out.extend(getattr(self, "_bar_frames", []))
        return out

    def _overlay_boxes(self, rb=None):
        """此刻「会动的浮层」的位置（选中框 / 今天竖条），tree 客户区坐标。

        v25.17：动它们之前先记下来 —— 动完由 `_flush_screen` 把压在旧位上的**遮色条**重画擦掉。
        `rb` 给定时只收那张表的框；不给就把三张表的框都收上（兜底重摆路径用）。
        ⚠️ v25.18.2：**别把遮色条自己收进来** —— 它们永不动、且每条都与自己相交，
        收进来会让"挑要重画的条"变成"全部 148 条都重画"（实测 45ms/步，还会把框的绘制饿掉）。
        """
        boxes = []
        for r in ([rb] if rb is not None else list(self._row_borders.values())):
            if r is not None and r._placed is not None:
                boxes.append(r._placed)
        for f in getattr(self, "_bar_frames", []):
            pos = getattr(f, "_pos", None)
            if pos and getattr(f, "_shown", False):
                boxes.append(pos)
        return boxes

    def _on_tree_sel_change(self, event=None):
        """选中行变了 → 直接把边框摆到新位置（`<<TreeviewSelect>>` 挂在三张表上）。

        v25.8（终版，用户拍板「单步手感不错、连续切换问题很大」后定）：
        **回到"直接移动"**。历史：v25.4~25.7 用过「先收 → 当场擦 → 再画」，动机是防"旧框
        影像"，代价是每一步开一个"无框期"（= `update()` 擦除的时长）—— 数据一重（今天行多）
        这窗口到 120ms，连按时窗口首尾重叠 → 用户看到「整个界面都没有黑色边框」+「框消失
        又出现」（整窗连拍有图证：停手后 60~120ms 框完全不在、~180ms 才出现）。
        **v25.7 的遮色条（`_RowPads`）已经能从机制上盖住旧框影像**（静态小条铺满行位网格
        的四条边、z 序在边框之下）—— 那套心跳机制就多余了：这里只"摆到新位置"，
        旧位置的影像由静态条盖住。
        """
        tree = event.widget if event is not None else None
        if tree in (getattr(self, "tree", None), getattr(self, "tree_split", None)):
            self._mirror_split_sel(tree)        # v66：总表 ⇄ 分屏页那张表，选中行互相跟
                                                #     （放在"重建回声"那道闸**前面** —— 那道闸会
                                                #      直接 return，漏掉的话分屏页的选中会落后）
        # v60：**重建回声**（重建收尾那发 `selection_set` 排下的 `<<TreeviewSelect>>`，
        # 一次重建可能连发好几发）——收尾已经把框和竖条摆好了，这一发直接返回：别做
        # 整洁刷新、更别排 deep flush（实测那发会拖到切页后 40~150ms 才到点、把整棵树
        # 重绘一次，用户看到「切回来之后画面又闪一下」）。判据 = 当前选中跟摆框时记的
        # 一模一样 —— 那种情况下框本来就已在正确位置，跳过永远安全（用户真改了选中就
        # 不相等，照走原路）。
        if tree is not None:
            try:
                if self._rebuild_sel.get(tree) == tuple(tree.selection()):
                    return
            except tk.TclError:
                pass
        rb = self._row_borders.get(tree)
        if rb is None:
            self._sync_all_row_borders()
        else:
            try:
                sel = tree.selection()
                target = sel[0] if sel else None
                now = time.monotonic()
                self._last_key_move = now
                if (now - self._last_step_force) * 1000.0 < STEP_FORCE_MS:
                    # v25.20（用户「按住 3 秒、松手后还走一会」）：距上一发整洁刷新不足
                    # `STEP_FORCE_MS` → **走便宜路**：只记目标（框的位置先不动，等下一发整洁刷新
                    # 一次跳到位）。完整刷新里那发强推重绘 ~45ms > 按键重复 32ms，每步都做会把
                    # 队列越压越长 —— 便宜路只花几毫秒，按键永远排得空。
                    rb.iid = target
                    self._schedule_repaint(delay_ms=STEP_FORCE_MS)
                    return
                self._last_step_force = now
                # v25.17（用户录屏「按住时前几行的框和行前今天竖线都不消失」）：**每步整洁刷新，
                # 但"擦"不再走 `update()`** —— 按键洪水下消息队列长期不空、WM_PAINT 合成被饿死，
                # update() 里可能一直在消化按键，旧框像素一行行留屏（= 残框阶梯）。改为：
                # 记旧位 → 收框（unmap 排队）→ 竖条重摆 → `_flush_screen`（idle 落实 + 标脏旧位
                # + `UpdateWindow` 当场擦，全程同步、不经过消息队列）→ 摆新框 → idle 落实（上线）。
                self._cancel_pending_show()
                boxes = self._overlay_boxes(rb)
                rb.hide()
                self._sync_today_bar()   # v25.16：竖条也每步重摆（此前只在"停止 150ms 的兜底"里，
                                         # 按住键时永远不会触发 → 竖线卡在旧屏幕位，用户录屏实锤）
                if tree is self.tree:
                    # v25.19（用户 16:25 录屏）：遮色条的**颜色**也要每步跟着行刷新 ——
                    # 它们只铺 2px 行边，颜色停在旧行时 = 行与行之间一条条**彩色细线**（按住滚动
                    # 时最明显，是"有颜色行留下的颜色痕迹"）。重染本身只要 ~4ms（119 行 bbox +
                    # 变色的那几条 configure），比 ttk 自己滚动重画的 ~40ms 便宜得多。
                    self._sync_row_pads()
                self._flush_screen(boxes)
                rb.iid = target
                rb.redraw()
                self._repaint_overlays_now()   # 只有"整洁刷新"这一支才强推补画（便宜路直接 return 了）
            except tk.TclError:
                pass
            self._schedule_repaint(delay_ms=FAST_KEY_MS)

    def _flush_screen(self, extra_boxes=(), deep=False):
        """把「旧像素的擦除 + place 的落地」在**本拍的同步链里**做完（v25.18，黑框残影终结者 ③）。

        病史（三版）：v25.3～15 用 `update()`（洪水下被饿死 → 残框一行行留屏，用户 15:24 录屏
        实锤最多同时 23 条横线）；v25.17 改 `InvalidateRect + UpdateWindow` ——**本机实测打不动**：
        Tk 的窗口只认它自己的 Expose/idle 重画路径，`UpdateWindow` / `RedrawWindow` / 外部
        `InvalidateRect` 全都原地不动（微型实验 4 组全黑）。

        v25.18 的解法（都是确定性调用，洪水饿不着）：
          ① **重画压在旧框上的"遮色条"**（`_RowPads`）—— 黑框四条边与遮色条四条边**同一个 bbox**，
             框挪走后把这几条 0.16ms/条的暴露重画一遍，残像素就被盖回行底色（实测有效）；
             竖条(6px)同理由加宽后的左条盖住。**不碰树**（树的整棵重画 ~40ms，太贵）。
          ② `tree.update_idletasks()` —— Tcl 空闲任务是解释器内部的事：Expose 的重画、
             以及排队中的 place（unmap/map）都在这一拍落实。
          `deep=True` 时（滚动停稳 / 松手兜底这种低频路径）额外给整棵树发一发 Expose ——
          把网格外的残余（滚动中 bbox 不稳导致的错位框）一次清干净。
        """
        if self._repainting:
            return
        self._repainting = True
        try:
            tree = getattr(self, "tree", None)
            if tree is None:
                return
            pads = self._pads.get(tree)
            if pads is not None and extra_boxes:
                for j, st in enumerate(pads.state):
                    if not st:
                        continue
                    if any(_rect_hit(st[0], b) for b in extra_boxes):
                        try:
                            pads.pads[j].event_generate("<Expose>")
                        except (tk.TclError, IndexError):
                            pass
            if deep:
                try:
                    tree.event_generate("<Expose>")     # 整树重画（低频路径才用）
                except tk.TclError:
                    pass
            tree.update_idletasks()                      # ① 先把 place / 标脏的重画落实
            if deep:
                self._repaint_overlays_now()             # ② 整树重画会盖掉浮层 → 落实之后再补画
        except tk.TclError:
            pass
        finally:
            self._repainting = False

    def _on_wheel_redraw_border(self, event=None):
        """滚轮之后补一次重画（错开一拍：让 Treeview 先把滚动做完）。v25.1：并入统一空闲通道。"""
        self._schedule_repaint()


    def _error(self, title, text):
        if not self.quiet:
            try:
                messagebox.showerror(title, text)
            except tk.TclError:
                pass


# ================================================================ 自测
def _sha256(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        h.update(f.read())
    return h.hexdigest()


def _mirror_dir(src_dir):
    """源目录 → 备份镜像目录（口径与 toolutil.backup_to_repo 的镜像规则一致）。"""
    d = os.path.abspath(src_dir)
    mirror = d.replace(":", "").replace("\\", "_").replace("/", "_")
    return os.path.join(toolutil.BACKUP_ROOT, mirror)


def _count_bak(d):
    if not os.path.isdir(d):
        return 0
    return len([n for n in os.listdir(d) if n.endswith(".bak")])


def _run_report(md, extra=()):
    """跨工具一致性：把 status_report.py 当子进程跑一遍，返回 (退出码, 输出文本)。

    extra 会加在 --file 后（v13：拿命令行的筛选模式跟 GUI 比命中集合，真跑子进程）。
    """
    p = subprocess.run([sys.executable, SR.__file__, "--file", md] + list(extra),
                       capture_output=True)
    return p.returncode, p.stdout.decode("utf-8", "replace")


def selftest():
    print("=== status_gui --selftest（v4：全程只用自造的 fixture，不碰真 md）===")
    cfg_state0 = _cfg_state(config_path_default())   # v4：自测也不许碰脚本同目录的配置文件
    tmpdir = tempfile.mkdtemp(prefix="status_gui_selftest_")
    tmp = write_fixture(os.path.join(tmpdir, "fixture.md"))
    orig_bytes = open(tmp, "rb").read()
    orig_text = read_text(tmp)
    orig_lines = orig_text.split("\n")
    src_root = TEST_BACKUP_ROOT                      # 夹具的 .bak 只进测试镜像目录
    bak_dir = _mirror_dir(src_root)
    n0 = _count_bak(bak_dir)
    print("[0] fixture = %s ｜ %d 字节 ｜ sha256(前) = %s"
          % (tmp, len(orig_bytes), _sha256(tmp)[:16]))
    print("    备份目录 = %s（现有 .bak %d 份；夹具的 .bak 只落这里，不碰真 md 的备份目录）"
          % (bak_dir, n0))
    print("    tools/status_report.py 的表头已同步到 v2 = %s" % SR_SYNCED)

    rows = annotate(parse_rows(tmp), datetime.date.today())
    states = set(r["状态"] for r in rows)
    rounds = [round_num(r["场次"]) for r in rows]
    assert len(rows) == len(FIXTURE_ROWS), len(rows)
    assert states == set(STATES), states
    assert any(r["日期"] == "" for r in rows), "fixture 要有空日期"
    assert any("｜" in r["知识点"] for r in rows), "fixture 要有带全角竖线的知识点"
    assert rounds != sorted(rounds), "fixture 的场次要是乱序的"
    print("[1] 解析：共 %d 题 ｜ %s" % (
        len(rows), " ｜ ".join("%s %d" % (s, c) for s, c in state_counts(rows).items() if c)))
    print("    6 个状态全覆盖 ✓ ｜ 有空日期 ✓ ｜ 有「｜」知识点 ✓ ｜ 场次乱序 ✓")
    assert list(SORTABLE) == ["场次", "难度", "日期"], SORTABLE
    print("    排序键（v4）= " + " / ".join(SORTABLE) + "（知识点不可排）✓")

    for i in range(4):
        print("    看板第 %d 段（%s）：%d 题" % (i + 1, segment_specs()[i][0],
                                                len(segment_rows(rows, i))))

    row = next(r for r in rows if r["日期"] == "" and r["状态"] != "待重写")
    key = (row["场次"], row["题号"])
    old = (row["状态"], row["日期"])
    idx = locate_row(orig_lines, key)
    today = datetime.date.today().isoformat()
    print("[2] 选中：%s %s（原状态 %s / 日期 %r），在第 %d 行"
          % (key[0], key[1], old[0], old[1], idx + 1))

    # 写回边界：不存在的题 / 不许改的列 → 必须拒绝，且不产生备份
    for bad_key, bad_ch in ((("不存在 Round 1", "Z"), {"状态": "未做"}),
                            (key, {"知识点": "不许改"}), (key, {"状态": "没有这个状态"})):
        try:
            save_changes(tmp, bad_key, bad_ch, backup_src_root=src_root)
            raise AssertionError("应当拒绝：%r %r" % (bad_key, bad_ch))
        except ValueError:
            pass
    assert _count_bak(bak_dir) == n0, "被拒绝的写不该产生备份"
    print("[3] 拒绝越界写（不存在的题 / 改知识点 / 非法状态）✓，未产生备份 ✓")

    bak1, _, _ = save_changes(tmp, key, {"状态": "待重写", "日期": today}, backup_src_root=src_root)
    print("[4] save_changes：状态 → 待重写，日期 → %s；备份 = %s" % (today, os.path.basename(bak1)))
    got = next(r for r in parse_rows(tmp) if (r["场次"], r["题号"]) == key)
    assert got["状态"] == "待重写" and got["日期"] == today, got
    print("    (a) 该行状态 / 日期写对了 ✓")

    new_lines = read_text(tmp).split("\n")
    diff = [k for k in range(len(orig_lines)) if orig_lines[k] != new_lines[k]]
    assert len(new_lines) == len(orig_lines) and diff == [idx], diff
    c0 = row_segments(orig_lines[idx])[1]
    c1 = row_segments(new_lines[idx])[1]
    for k, name in enumerate(HEADER):
        if name in EDITABLE:
            continue
        assert c1[k] == c0[k], (name, c0[k], c1[k])
    assert c1[CELL_STATE] == "待重写" and c1[CELL_DATE] == today, c1
    assert new_lines[idx] == render_row(c1), "目标行排版被改了"
    print("    (b) 其余行逐字节不变（唯一改动 = 第 %d 行）、该行其余格与排版原样 ✓" % (idx + 1))

    raw = open(tmp, "rb").read()
    crlf, cr = raw.count(b"\r\n"), raw.count(b"\r")
    assert crlf == 0 and cr == 0 and not raw.startswith(b"\xef\xbb\xbf"), (crlf, cr)
    print("    (c) 纯 LF（CRLF=%d、CR=%d）、无 BOM ✓" % (crlf, cr))

    n1 = _count_bak(bak_dir)
    assert n1 == n0 + 1, (n0, n1)
    print("    (d) 备份目录 .bak：%d → %d ✓" % (n0, n1))

    code, out = _run_report(tmp)
    n_hard = len(segment_rows(parse_rows(tmp), 0))
    if code == 0:
        sec1 = next((ln.rstrip() for ln in out.splitlines() if ln.startswith("① ")), "")
        assert sec1.endswith("：%d 题" % n_hard), sec1
        print("    (f) 跨工具：status_report.py --file <fixture> 退出码 0，%s ✓" % sec1)
    else:
        assert not SR_SYNCED, "表头已同步却读不了 fixture（退出码 %d）\n%s" % (code, out)
        ctrl = os.path.join(tmpdir, "control_fixture.md")
        write_text(ctrl, control_fixture_text())
        print("    (f) ★ 跨工具闸门暂缓：tools/status_report.py 的表头还没同步到 v2"
              "（现在是 %s），读不了 v2 fixture（退出码 %d）" % (" | ".join(_SR_HEADER), code))
        print("        主会话把它的 HEADER 同步成新表头后，重跑本条即通过；"
              "本次先验证子进程调用链本身可用：", end=" ")
        code2, _ = _run_report(ctrl)
        assert code2 == 0, "连「与 tools 同表头」的对照件都跑不通（退出码 %d）" % code2
        print("同表头对照件退出码 %d ✓" % code2)

    bak2, _, _ = save_changes(tmp, key, {"状态": old[0], "日期": old[1]}, backup_src_root=src_root)
    assert open(tmp, "rb").read() == orig_bytes, "改回后与原件不逐字节相同"
    print("    (e) 改回去：整份与原件逐字节相同 ✓；备份 %d → %d" % (n1, _count_bak(bak_dir)))

    code3, _ = _run_report(tmp)
    if SR_SYNCED:
        assert code3 == 0, "改回后 status_report --file 退出码 %d" % code3
        print("    (g) 改回后 status_report.py --file <fixture> 退出码 0 ✓")
    else:
        print("    (g) 改回后仍受「tools 未同步」影响（退出码 %d），同上待同步后重跑" % code3)

    assert _count_bak(bak_dir) == n0 + 2, _count_bak(bak_dir)
    assert _cfg_state(config_path_default()) == cfg_state0, \
        "--selftest 碰了脚本同目录的 %s（v4 要求一律不碰）" % CONFIG_NAME
    print("    (h) 脚本同目录的 %s 全程没被碰过 ✓" % CONFIG_NAME)
    print("[5] fixture 收尾：sha256 = %s（与改回后一致）｜ 临时目录保留在 %s"
          % (_sha256(tmp)[:16], tmpdir))


    # --- v26：[7] 自定义快捷键的纯逻辑（不开窗口）——
    #   注册表不变量 / capture_seq / pretty_seq / resolve_keymap / `?` 一览默认逐字节
