    assert len(aids) == len(set(aids)) == 33, aids   # v65：+4 新动作 +page_up/page_down +focus_next +cancel     # v37 删 Ctrl+2 → 25；v40 加 settings → 26；v46 删 material → 25；v53 删 menu_pack → 24；v57.3 加 key_reset / key_reset_all → 26；v65 加四个 → 34；**v87 删 help（一览并进设置页）→ 33**
