    assert capture_seq("u", 0) == "<Key-u>"
    assert capture_seq("1", 0) == "<Key-1>"
    assert capture_seq("Return", 0x1) == "<Shift-Return>"
    assert capture_seq("F5", 0) == "<F5>"
    assert capture_seq("question", 0) == "<Key-question>"
    assert capture_seq("Shift_L", 0x1) is None and capture_seq("", 0) is None
