    assert capture_seq("1", 0x4) == "<Control-Key-1>", "Ctrl+数字必须带 Key-（v26.2：光写 1 会被 Tk 当鼠标键）"
    assert pretty_seq("<Control-Key-1>") == "Ctrl+1"
    assert keyseq_reject_reason("<Control-1>") is not None, "歧义写法要拒（= Ctrl+鼠标左键）"
    assert keyseq_reject_reason("<Control-Key-1>") is None
    assert pretty_seq("<Control-z>") == "Ctrl+Z"
    assert pretty_seq("<Shift-Return>") == "Shift+Enter"
    assert pretty_seq("<Key-question>") == "?"
    assert pretty_seq("<Key-1>") == "1" and pretty_seq(None) == "未绑定"
    assert pretty_seq("<Control-Home>") == "Ctrl+Home"
    assert pretty_seq(capture_seq("A", 0x1)) == "A"
    km2 = resolve_keymap(None)
    assert km2 == DEFAULT_KEYMAP
    km2 = resolve_keymap({"undo": "<Control-u>", "redo": None})
    assert km2["undo"] == "<Control-u>" and km2["redo"] is None \
        and km2["search"] == "<Key-F>"           # v32.3：搜索键改裸 F（v68：默认写法改大写）
    km2 = resolve_keymap({"undo": "<Control-y>", "乱写的东西": "<F2>", "redo": "不是序列"})
    assert km2["undo"] == "<Control-y>" and km2["redo"] is None, km2
    assert resolve_keymap({"undo": "<Escape>"})["undo"] == "<Control-z>", "保留键该被丢掉（回默认；v65 起 Tab 已不是保留键，改用 Esc）"
    assert resolve_keymap({"reload": "<Key-u>"})["reload"] == "<F5>", "根级裸键该被丢掉"
    # v74：键2（替代键）纯逻辑 —— 默认全 None / 脏值丢 / 键1 先占先得 / 池内先占先得
    kx2 = resolve_keymap2(None)
    assert set(kx2) == set(DEFAULT_KEYMAP) and set(kx2.values()) == {None}, "键2 默认该是全长 None"
