    assert "Ctrl+U" in ht3 and "Ctrl+Z" not in ht3
    assert len(ht3.splitlines()) == len(KEY_TABLE.splitlines()) == 29          # v65：加 Backspace + 3 个新动作行   # v42 加「设置界面」行 → 26；v46 删资料行 → 25；v49 加 Alt 行 → 26；v87 删 Ctrl+Tab 行 → 29
    km4 = dict(DEFAULT_KEYMAP, status_1="<Key-q>")
    assert "q" in help_text_for(km4).splitlines()[9], "改状态那行该现渲染（v49 行号 +1；v65 又 +1）"
    # v40：设置界面那条 —— 拼法 / 显示 / 根级规则 / 改键后一览跟着走
