    # --- v3 闸门 (a)：排序键只留 场次 / 难度 / 日期（知识点不可排）
    assert list(SORTABLE) == ["场次", "难度", "日期"], SORTABLE
    assert gui.tree.heading("知识点", "command") == "", "「知识点」不该再接排序命令"
    gui.sort_col, gui.sort_desc = "场次", False
    gui.refresh_view()
    seen = []
    for _ in range(3):                       # Ctrl+→ 循环：场次 → 难度 → 日期 → 场次
        gui._sort_next_key(1)
        seen.append(gui.sort_col)
    assert seen == ["难度", "日期", "场次"], seen
    gui._sort_next_key(-1)                   # v21：Ctrl+← 反着退一格（场次 → 日期）
    assert gui.sort_col == "日期", gui.sort_col
    gui.sort_col, gui.sort_desc = "场次", False
    gui._sort_next_key(1)
    assert gui.sort_desc is False, "换字段后应回到升序"
    print("(a) 排序键 Ctrl+→ 循环：场次 → %s（Ctrl+← 反向一步 = 日期；知识点不在列）✓"
          % " → ".join(seen))

    # --- v4 闸门 (b)：点表头 / S / R 换排序后，选中行**钉在原行号**（v4 翻盘：不再跟题走）
    def _sel_key():
        r = gui.tree_row(gui.tree)
        return (r["场次"], r["题号"]) if r else None

    def _sel_row():
        iid = gui.tree.focus()
        return gui.tree.index(iid) if iid else None

    gui.sort_col, gui.sort_desc = "场次", False
    gui.refresh_view()
    ids = list(gui.tree.get_children())
    pick = len(ids) // 2
    gui.tree.selection_set(ids[pick])
    gui.tree.focus(ids[pick])
    gui.tree.see(ids[pick])
    key0, row0 = _sel_key(), _sel_row()
    changed = []
    for step, call in (("Ctrl+→", lambda: gui._sort_next_key(1)),
                       ("Ctrl+↑", lambda: gui._sort_toggle_key(0))):
        call()
        assert _sel_row() == row0, \
            "%s 换排序后行号应原样不动（v4 钉行号）：第 %s 行 → 第 %s 行" % (step, row0, _sel_row())
        assert gui.tree.focus() == gui.tree.selection()[0], "selection 与 focus 都要跟上"
        changed.append(_sel_key() != key0)
    gui.on_sort("日期")                                   # 点表头同效
    assert _sel_row() == row0, "点表头换排序后行号应原样不动：第 %s 行" % (_sel_row(),)
    assert gui.tree.focus() == gui.tree.selection()[0], "selection 与 focus 都要跟上"
    changed.append(_sel_key() != key0)
    assert any(changed), "换了三次排序、行里的题一次都没变 —— 这条断言等于白测"
    print("(b) 换排序钉在原行号：第 %d 行从头到尾没动（Ctrl+→ / Ctrl+↑ / 点表头各一次）；"
          "行里的题 %s %s → %s %s ✓"
          % (row0, key0[0], key0[1], _sel_key()[0], _sel_key()[1]))

    other = {"场次": "日期", "难度": "场次", "日期": "难度"}
    for col in SORTABLE:                     # 点一下升序、再点一下降序（每个可排序键各一遍）
        gui.sort_col, gui.sort_desc = other[col], False   # 先让「当前排序列」不是它
        gui.refresh_view()
        gui.on_sort(col)
        up, first_up = gui.tree.heading(col)["text"], _first_row_cell(gui, col)
        gui.on_sort(col)
        down, first_dn = gui.tree.heading(col)["text"], _first_row_cell(gui, col)
        assert up.endswith("▼") and down.endswith("▲"), (col, up, down)   # v74：▼ = 升序、▲ = 降序
        print("排序 %s：升「%s」首行=%s ｜ 降「%s」首行=%s" % (col, up, first_up, down, first_dn))
    dates = [c for c in map(lambda i: gui.tree.item(i, "values")[HEADER.index("日期")],
                            gui.tree.get_children())]
    assert dates == sorted([d for d in dates if d], reverse=True) + [""] * dates.count(""), \
        "日期降序时空日期应排最后：%r" % (dates,)
    gui.sort_col, gui.sort_desc = "场次", False      # 回到默认：场次升序 → 题号升序
    gui.refresh_view()

    ids = list(gui.tree.get_children())
    gui.tree.selection_set(ids[0])
    gui.tree.focus(ids[0])
    gui._move_sel(gui.tree, "pgdn")
    assert _sel_row() == min(12, len(ids) - 1), _sel_row()
    gui._move_sel(gui.tree, "pgup")
    assert _sel_row() == 0, _sel_row()
    print("PgUp / PgDn 翻页 ✓（Home / End 已删）")

    # --- v3 闸门 (g)：两棵树都不再有 Home / End 绑定（一个功能只留一个键）
    for t, name in ((gui.tree, "总表"), (gui.today_tree, "看板")):
        assert t.bind("<Home>") == "" and t.bind("<End>") == "", \
            "%s树上还有 Home / End 绑定" % name
    print("(g) 无 <Home> / <End> 绑定 ✓")

    # --- v23 闸门 (hh5)：`today` 这个 tag 只许管前景（今天那行的日期字，Radix 配色用）
    # v23（2026-10-06）：`today` 由「今天那行的日期字」（前景 = 深墨，Radix 配色用）改成**只设前景**
    # （同属性多 tag 会按 tag_configure 先后定胜负，v22.1 的坑）。谁把两个属性又揉回一个 tag，先改这条。
    # v28（2026-10-06）：`todayz`（淡绿整行底 tag）已整条删除 —— 用户点名去掉默认配色的淡绿底，
    # 今天改走行首竖条（`_sync_today_bar`，两档通用）。谁把「今天 = 底色 tag」加回来，先改这条闸门。
    assert str(gui.tree.tag_configure("today", "background")) in ("", "None"), \
        "today 只许管前景（日期字）：%r" % (gui.tree.tag_configure("today", "background"),)
    assert str(gui.tree.tag_configure("today", "foreground")).upper() in (
        RADIX_TODAY_INK.upper(), C_TEXT.upper(), "", "NONE",
        SCHEME[gui.theme_scheme]["today_fg"].upper()), \
        "today 的前景该是「今天日期字」那支色（v71 起逐套配色）：%r" \
        % (gui.tree.tag_configure("today", "foreground"),)
    # v22.2（2026-10-06）：**红字 tag 整条没了** —— 用户口径「TB 不要未做 / 不会 这类行染红」。
    # 这里连配置一起断言掉：谁哪天把 todo 加回来（哪怕只是 tag_configure）都得先改这条闸门。
    assert str(gui.tree.tag_configure("todo", "foreground")) in ("", "None") \
        and str(gui.tree.tag_configure("todo", "background")) in ("", "None"), \
        "todo 红字 tag 该已删除：%r" % (gui.tree.tag_configure("todo", "foreground"),)
    td = datetime.date.today().isoformat()
    tagfix = os.path.join(tmpdir, "v22_tags.md")
    tag_rows = [("牛客周赛 Round 401", "A", "今天改过", "模拟", "CF 800", "独立AC", td),
                ("牛客周赛 Round 401", "B", "待重写行", "模拟", "CF 800", "待重写", "2026-08-01"),
                ("牛客周赛 Round 401", "C", "不会行", "模拟", "CF 800", "不会", "2026-08-02"),
                ("牛客周赛 Round 401", "D", "今天且待重写", "模拟", "CF 800", "待重写", td)]
    write_text(tagfix, "\n".join(["# v22.2 行着色 fixture", "",
                                  "| " + " | ".join(HEADER) + " |",
                                  "|" + "|".join(["---"] * len(HEADER)) + "|"]
                                 + [render_row(list(c)) for c in tag_rows] + [""]) + "\n")
    gui.path = tagfix
    gui.var_search.set("")
    gui.reload()
    tag_of = {gui.row_by_iid(i)["题号"]: gui.tree.item(i, "tags") for i in gui.tree.get_children()}
    # v37：配色恒 Radix —— 行 tag = 状态色 +（今天行另挂 `today` 深墨日期字；
    # 今天竖条是另一回事，由「今天标记」开关控制、控件断言见 (hh6-3) / (hh6-5)）。
    assert theme_tag("独立AC") in tag_of["A"] and "today" in tag_of["A"], tag_of["A"]
    assert theme_tag("待重写") in tag_of["D"] and "today" in tag_of["D"], tag_of["D"]
    # v22.2：不会 / 待重写行 → 只有状态色，**没有任何** todo tag、也不该带今天 tag。
    for _k in ("B", "C"):
        assert "todo" not in tag_of[_k] and "today" not in tag_of[_k], tag_of[_k]
    assert theme_tag("待重写") in tag_of["B"], tag_of["B"]
    assert theme_tag("不会") in tag_of["C"], tag_of["C"]
    for _k in ("A", "B", "C", "D"):
        assert "todo" not in tag_of[_k], "v22.2 起不该再有 todo（红字）tag：%r" % (tag_of[_k],)
    print("(hh3) 行着色（v22.2 / v37）：配色恒 Radix —— 行 tag = 状态色，今天行另挂 `today`"
          "（深墨日期字）；**红字 tag 已删**（不会 / 待重写行只有状态色）✓")
    gui.path = tmp
    gui.reload()

    # --- v40 闸门 (vv40)：菜单栏整套删除 → **设置界面**（Ctrl+Tab 整屏切换；左列表 + 右面板）
    #     用户口径 2026-10-06：「取消现在的题解包,主题,快捷键菜单,用切换页状态替代…整个界面变成
    #     设置界面,不是新增…还是一样的上下左右」+ 拍板「左列表+右面板 / 全内联删弹窗 / 开关式」。
    #     谁把菜单栏加回来 / 把设置界面改回独立弹窗，先改这条。
    #     v53：左列表只剩 快捷键 / 主题 两块 + ↑↓ **真按键**回归（focus 行缺失 bug 不许再回来）。
    #     v87（用户点名）：开关键 Ctrl+Tab → **`?`**（解绑 Ctrl+Tab）；左列表加第三项「快捷键一览」
    #     （原 `?` 独立弹窗并进来，只读 Text）—— 这块的断言在本段中后部。
    assert not hasattr(gui, "menubar") and not hasattr(gui, "_menu_bar") \
        and not hasattr(gui, "_menu_btns") and not hasattr(gui, "key_win"), \
        "v40：菜单栏三个菜单 + 快捷键独立弹窗（key_win）该整套删除"
    assert not hasattr(gui, "open_key_dialog") and not hasattr(gui, "close_key_dialog") \
        and not hasattr(gui, "pack_flow") and not hasattr(gui, "pack_export_dialog") \
        and not hasattr(gui, "_open_pack_report") and not hasattr(gui, "_ask_pack_path"), \
        "v40：四个题解包弹窗函数 + 快捷键开 / 关窗函数该整组删除（全内联进设置界面）"
    assert not hasattr(gui, "set_import_text") and not hasattr(gui, "set_export_cb") \
        and not hasattr(gui, "_pack_job") and not hasattr(gui, "_set_import_path"), \
        "v53：导入 / 导出题解包两块 + 后台任务整组删除（见 (yy) 段）"
    assert str(root.cget("menu")) in ("", "None"), \
        "v40：原生菜单栏该为空：%r" % (root.cget("menu"),)
    assert gui.settings_frame is not None and gui.settings_frame.winfo_manager() == "", \
        "v40：设置界面默认该**不摆**（还没按 ?）"
    assert gui._in_settings() is False
    assert gui.keymap["settings"] == "<Key-question>", gui.keymap["settings"]   # v87：默认键 = ?
    assert root.bind("<Control-Tab>") == "", "v87：Ctrl+Tab 该解绑（原默认键让给 ?）"
    # `?` 进设置：主界面整块收、设置界面摆上、焦点落左列表
    gui._on_settings_key()
    root.update()
    assert gui._in_settings() and gui.settings_frame.winfo_manager() == "pack"
    assert gui.main_frame.winfo_manager() == "", "v40：进设置后主界面该整块收起"
    assert root.focus_get() is gui.set_left, "v40：进设置焦点该落左列表：%r" % root.focus_get()
    assert [gui.set_left.item(i, "text").strip() for i in gui.set_left.get_children()] == \
        [lab for _iid, lab in SET_ITEMS], \
        [gui.set_left.item(i, "text") for i in gui.set_left.get_children()]
    assert gui.set_left.selection() == (SET_ITEMS[0][0],)
    assert gui.set_panel == "keys" and gui.set_panels["keys"].winfo_manager() == "pack", \
        "v53：默认该摆「快捷键设置」那块（导入 / 导出两块已删）"
    assert gui.set_panels["theme"].winfo_manager() == "", "v40：没选中的面板不许摆"
    # v53 回归：左列表 ↑↓ **真按键** —— 修「focus 行缺失」（Keynav 没有 focus 行就整个不响应）
    assert gui.set_left.focus() != "", "v53：左列表该有 focus 行（没有它 ↑↓ 就是死的）"
    gui.set_left.focus_force()
    root.update()
    gui.set_left.event_generate("<KeyPress>", keysym="Down")
    root.update()
    assert gui.set_left.selection() == ("theme",) and gui.set_panel == "theme", \
        "v53：左列表按 ↓ 该换到下一项（focus 行缺失的回归）：%r" % (gui.set_left.selection(),)
    gui.set_left.event_generate("<KeyPress>", keysym="Up")
    root.update()
    assert gui.set_left.selection() == ("keys",) and gui.set_panel == "keys"
    # v87：左列表第三项 =「快捷键一览」—— ↓↓ 走到它，右面板摆一览块（只读 Text，默认文 = KEY_TABLE）
    gui.set_left.event_generate("<KeyPress>", keysym="Down")
    root.update()
    gui.set_left.event_generate("<KeyPress>", keysym="Down")
    root.update()
    assert gui.set_left.selection() == ("help",) and gui.set_panel == "help", \
        "v87：↓↓ 该走到第三项「快捷键一览」：%r" % (gui.set_left.selection(),)
    assert gui.set_panels["help"].winfo_manager() == "pack"
    assert gui.help_tx is not None and str(gui.help_tx.cget("state")) == "disabled", \
        "v87：一览是只读 Text（state=disabled）"
    assert gui.help_tx.get("1.0", "end-1c") == KEY_TABLE, "v87：一览块默认文 == KEY_TABLE 逐字节"
    assert gui._set_focus["help"] == [gui.help_tx], "v87：进面板清单 = 只读文本一件"
    # 文本能拿键盘焦点（只读 ≠ 禁聚焦，disabled 跳过规则对它放行）；↑↓ 滚动（显式绑）；← 回左列表
    gui.help_tx.focus_force()
    root.update()
    gui.help_tx.event_generate("<KeyPress>", keysym="Down")
    root.update()
    assert root.focus_get() is gui.help_tx, "v87：只读文本该能拿键盘焦点（↑↓ 滚动的前提）"
    gui.help_tx.event_generate("<KeyPress>", keysym="Left")
    root.update()
    assert root.focus_get() is gui.set_left, "v87：一览里 ← 该回左列表"
    # → / Enter 进面板：落只读文本（`_set_focus_panel` 对 Text 不跳 disabled）
