    root.update()
    gui._set_focus_panel()
    root.update()
    assert root.focus_get() is gui.help_tx, "v87：help 块「→ 进面板」该落只读文本：%r" % (root.focus_get(),)
    gui.set_left.selection_set("keys")
    gui.show_set_panel("keys")
    gui.set_left.focus_set()
    root.update()
