    gui.show_set_panel("keys")
    gui.set_left.focus_set()
    gui._set_focus_panel()
    root.update()
    assert root.focus_get() is gui._set_focus["keys"][0], \
        "v40 / v42：进面板该把焦点送进第一件控件：%r" % root.focus_get()
    # Esc 回去（v42 改「逐层退」：焦点在右面板里第一下先回左四项、第二下才退出）、
    # 再按 Ctrl+Tab 回来、再按一次回主表（开关式）
    gui._on_settings_esc()
    root.update()
    assert gui._in_settings() and root.focus_get() is gui.set_left, \
        "v42：Esc 第一层 = 从右面板回左四项：%r" % (root.focus_get(),)
    gui._on_settings_esc()
    root.update()
    assert not gui._in_settings() and gui.main_frame.winfo_manager() == "pack"
    gui._on_settings_key()
    root.update()
    assert gui._in_settings()
    gui._on_settings_key()
    root.update()
    assert not gui._in_settings(), "v40：Ctrl+Tab 开关式（再按一次回主界面）"
    # Ctrl+3：开设置界面并定位到对应块（v53：Ctrl+1 随导入块删除 —— 「pack」这条动作没了）
    gui._on_menu_hotkey("keys")
    root.update()
    assert gui.set_panel == "keys" and gui.set_left.selection() == ("keys",)
    assert gui.key_tv is not None and gui.key_tv.winfo_manager() == "pack", \
        "v40：快捷键表该在「快捷键设置」块里摆着（不再是独立弹窗）"
    gui.leave_settings()
    root.update()
    gui.tree.focus_set()
    root.update()
    # v42→v55（设置页导航）：**设置页已独立**（不再占主表那一格、不在 ← / → 环上）——
    #   ① 左列表上 ← 不响应、→ 进右面板；② 面板里 ← / → 不换界面；③ 退出（Ctrl+Tab / Esc）
    #   回**进来的那个界面**（用户拍板「哪来的回哪去」）。
    #   v48 的「走开只是看不见 / 走回来原样再现」整族随独立作废（`settings_open` 已删）。
    assert not gui._in_settings() and not hasattr(gui, "settings_open")
    gui.nb.select(1)                            # 从看板进 —— 退出该回看板
    root.update()
    gui.enter_settings()
    root.update()
    assert gui._settings_from_cell == 2, "v55：从看板进来该记来源格 2：%r" % (gui._settings_from_cell,)
    gui.set_left.focus_force()
    root.update()
    # ① 左列表：← 不响应、→ 进右面板（页内分工；设置页不在环上）
    _nb0 = gui.nb.index(gui.nb.select())
    gui.set_left.event_generate("<KeyPress>", keysym="Left")
    root.update()
    assert gui._in_settings() and gui.nb.index(gui.nb.select()) == _nb0, \
        "v55：左列表上 ← 不该走界面、也不该离开设置"
    gui.set_left.event_generate("<KeyPress>", keysym="Right")
    root.update()
    assert gui._in_settings() and root.focus_get() is gui._set_focus["keys"][0], \
        "v55：左列表上 → 该进右面板（落到该块第一件）：%r" % (root.focus_get(),)
    # ② 面板里 ← / → 不换界面；真按键冒到 root 也被守卫拦（用户就是在这儿按出不来）
    gui._nav_arrow(1)
    root.update()
    assert gui._in_settings(), "v55：焦点在右面板里时 ← / → 不该换界面"
    gui.key_tv.focus_force()
    root.update()
    gui.key_tv.event_generate("<KeyPress>", keysym="Right")
    root.update()
    assert gui._in_settings() and gui.nb.index(gui.nb.select()) == _nb0, \
        "v55：右面板控件上按真 → 冒到 root 也该被拦（设置页不换界面）"
    # ③ Ctrl+Tab 退出 = 回来源（看板）
    gui._on_settings_key()
    root.update()
    assert (not gui._in_settings()) and gui.nb.index(gui.nb.select()) == 1, \
        "v55：从看板进来、退出该回看板：%r" % (gui.nb.index(gui.nb.select()),)
    # ④ 从主表进 → Esc 退出 → 回主表
    gui._goto_cell(0)
    root.update()
    gui.enter_settings()
    root.update()
    assert gui._settings_from_cell == 0
    gui.set_left.focus_force()
    root.update()
    gui._on_settings_esc()
    root.update()
    assert not gui._in_settings() and gui.nb.index(gui.nb.select()) == 0, \
        "v55：从主表进来、Esc 退出该回主表"
    # 焦点进右面板：← / → 不换界面；↓ 在面板控件间走
    # v53：原「导出块（场次下拉 / 输出框）」那几拍随导出块删除 —— 改在快捷键块上验同样的事，
    #   并补快捷键表 ↑↓ 的**真按键**回归（focus 行缺失 bug 的直接复盘）
    gui.enter_settings()
    gui.show_set_panel("keys")
    gui.set_left.focus_set()
    gui._set_focus_panel()
    root.update()
    assert root.focus_get() is gui.key_tv, root.focus_get()
    assert gui.key_tv.focus() != "", "v53：快捷键表该有 focus 行（没有它 ↑↓ 就是死的）"
    _k_sel0 = gui.key_tv.selection()[0]
    gui.key_tv.event_generate("<KeyPress>", keysym="Down")
    root.update()
    assert gui.key_tv.selection() and gui.key_tv.selection()[0] != _k_sel0, \
        "v53：快捷键表按 ↓ 该真换行（focus 行缺失的回归）"
    gui._nav_arrow(1)
    root.update()
    assert gui._in_settings(), "v42：焦点在右面板里时 ← / → 不该换界面"
    gui._set_panel_step("keys", 1)
    root.update()
    assert root.focus_get() is gui.key_tv, \
        "v57.3：快捷键块只剩表一件（三按钮删除），↓ 后焦点仍在表上：%r" % (root.focus_get(),)
    gui.key_tv.selection_set(KEY_ACTIONS[0][0])   # 还原现场：后面 (oo) 段要验「开窗选中第一行」
    gui.key_tv.focus(KEY_ACTIONS[0][0])
    # 主题块（v55）：← / → = 组内**挪焦点**（不改值）、回车 = 应用、↑ / ↓ = 组间走（只挪焦点）
    gui.show_set_panel("theme")
    gui.set_left.focus_set()
    gui._set_focus_panel()
    root.update()
    _grp_sel = gui._set_groups["selc"]
    assert root.focus_get() is gui._set_groups["selb"][0], \
        "v42/v75.3：进主题块该落面板第一件（当前行边框 ▸ 黑色）：%r" % (root.focus_get(),)
    _grp_sel[0].focus_set()          # v75.3：本段测「当前行颜色」组的 ←→ / 回车，先显式移过去
    root.update()
    _sel_old = gui.theme_sel_color
    gui._set_theme_side("selc", 1)
    root.update()
    assert root.focus_get() is _grp_sel[1] and gui.theme_sel_color == _sel_old, \
        "v55：主题块 → 只挪焦点、不改值：%r / %r" % (root.focus_get(), gui.theme_sel_color)
    gui._set_theme_apply(_grp_sel[1])
    root.update()
    assert gui.theme_sel_color == _rb_val(_grp_sel[1]), \
        "v55：主题块回车该应用焦点所在选项（写 var + on_theme_pick）：%r" % (gui.theme_sel_color,)
    gui._set_theme_side("selc", -1)
    root.update()
    assert root.focus_get() is _grp_sel[0] and gui.theme_sel_color == _rb_val(_grp_sel[1]), \
        "v55：主题块 ← 只挪焦点回上一项（值不动）：%r" % (gui.theme_sel_color,)
    for _rb in _grp_sel:                        # 还原原来那档（免得影响后面的老断言）
        if str(_rb.cget("value")) == _sel_old:
            _rb.invoke()
    root.update()
    assert gui.theme_sel_color == _sel_old, (gui.theme_sel_color, _sel_old)
    gui._set_focus_panel()
    root.update()
    gui._set_theme_updown(1)
    root.update()
    assert root.focus_get() in gui._set_groups["scheme"], \
        "v42：主题块 ↓ 该走到下一组（配色）：%r" % (root.focus_get(),)
    gui._set_theme_updown(-1)
    root.update()
    assert root.focus_get() in gui._set_groups["selc"], \
        "v42/v75.3：主题块 ↑ 该走回上一组（当前行颜色）：%r" % (root.focus_get(),)

    # v71.1：配色 = **3 列 × 4 行的网格** —— ↑ / ↓ 先在网格内换行（同列）、到首 / 末行再走才去
    #        相邻组；← / → **只在同一行内挪**（行首再 ← = 回左列表、行尾再 → 停原地）
    _sch = gui._set_groups["scheme"]
    assert len(_sch) == 12, len(_sch)
    _sch[0].focus_set(); root.update()
    gui._set_theme_updown(1); root.update()
    assert root.focus_get() is _sch[3], "v71.1：↓ 该落到同列下一行：%r" % (root.focus_get(),)
    gui._set_theme_updown(1); root.update()
    assert root.focus_get() is _sch[6], "v71.1：再 ↓ 到第 3 行：%r" % (root.focus_get(),)
    gui._set_theme_updown(-1); root.update()
    assert root.focus_get() is _sch[3], "v71.1：↑ 该回到上一行同列：%r" % (root.focus_get(),)
    _sch[9].focus_set(); root.update()
    gui._set_theme_updown(1); root.update()
    assert root.focus_get() in gui._set_groups["today"], \
        "v71.1：末行（第 4 行）再 ↓ 才去下一组：%r" % (root.focus_get(),)
    gui._set_theme_updown(-1); root.update()          # 回到配色（落上次记住的那一格）
    _sch[0].focus_set(); root.update()
    gui._set_theme_side("scheme", 1); root.update()
    assert root.focus_get() is _sch[1], "v71.1：→ 行内右挪：%r" % (root.focus_get(),)
    gui._set_theme_side("scheme", 1); root.update()
    assert root.focus_get() is _sch[2], "v71.1：→ 到行尾：%r" % (root.focus_get(),)
    gui._set_theme_side("scheme", 1); root.update()
    assert root.focus_get() is _sch[2], "v71.1：行尾再 → 该停在原地（不跳下一行）"
    _sch[4].focus_set(); root.update()
    gui._set_theme_side("scheme", -1); root.update()
    assert root.focus_get() is _sch[3], "v71.1：← 行内左挪：%r" % (root.focus_get(),)
    _sch[3].focus_set(); root.update()
    gui._set_theme_side("scheme", -1); root.update()
    assert root.focus_get() is gui.set_left, \
        "v71.1：行首（列 0）再 ← 该回左列表：%r" % (root.focus_get(),)
    gui.set_left.focus_set(); root.update()      # 清场（v74：_set_group_focus 记忆已删，无需还原落点）
    # v57.2：选项框 = 双层套娃（外层 edge 的 bg 当边框 —— 父控件 highlight 会被焦点重绘擦掉，
    #   最小实验实锤）；验：套娃结构；清场后所有 edge 回背景色；焦点进 rb → 它黑、别的仍背景。
    _rbs_all = [rb for gk in gui._set_group_order for rb in gui._set_groups[gk]]
    assert _rbs_all and all(rb.master.winfo_class() == "Frame"
                            and rb.master.master.winfo_class() == "Frame"
                            and int(rb.cget("highlightthickness")) == 0
                            for rb in _rbs_all), \
        "v57.2：单选钮该是 edge / inner / rb 套娃、自身虚线框关掉：%r" % (
            [(rb.master.winfo_class(), rb.master.master.winfo_class(),
              str(rb.cget("highlightthickness"))) for rb in _rbs_all],)
    gui.set_left.focus_set()      # 清场：前面的用例可能把焦点留在某个钮上（edge 已点亮）
    root.update()
    assert all(str(rb.master.master.cget("bg")).lower() == C_BG.lower() for rb in _rbs_all), \
        "v57.2：焦点离开后所有 edge 该回背景色：%r" % (
            [str(rb.master.master.cget("bg")) for rb in _rbs_all],)
    _soft_rb = next(rb for rb in gui._set_groups["selc"] if _rb_val(rb) == "soft")
    _soft_rb.focus_set()
    root.update()
    assert str(_soft_rb.master.master.cget("bg")).lower() in ("#000000", "black"), \
        "v57.2：焦点进来该把外框 edge 变纯黑：%r" % (_soft_rb.master.master.cget("bg"),)
    _other_rb = next(rb for rb in _rbs_all if rb.master.master is not _soft_rb.master.master)
    assert str(_other_rb.master.master.cget("bg")).lower() == C_BG.lower(), \
        "v57.2：没焦点的其它 edge 该保持跟背景同色：%r" % (_other_rb.master.master.cget("bg"),)
    # v74：跨组落点 = 「水平距离最近」（取代 v57「回该组上次停留位置」）——
    # 构造：边框档设成最右的「白色」；焦点放配色第一行最左（_sch[0]）→ ↑ 回「当前行颜色」组，
    # 期望落 x 最近的钮（不是生效档白框、也不是任何"记忆位置"）
    _old_sel_mem = (gui.theme_sel_border, gui.theme_sel_color)   # v75.3：两组各存一份还原
    _w_rb = next(rb for rb in gui._set_groups["selb"] if _rb_val(rb) == "white")   # v75.3：白框在边框组
    _w_rb.invoke()                                # 边框档 = 白色（组内最右）
    root.update()
    _sch[0].focus_set()
    root.update()
    gui._set_theme_updown(-1)                     # ↑ 回「当前行颜色」组
    root.update()
    _exp_near = gui._theme_nearest(gui._set_groups["selc"], _sch[0])
    assert root.focus_get() is _exp_near, \
        "v74：跨组该落「水平距离最近」的钮（期望 %r，实得 %r）" % (_exp_near, root.focus_get())
    assert _exp_near is not _w_rb, \
        "v74：落点不该是「当前生效档」的钮（白框在最右、离 Tailwind 最远——且在另一组）"
    next(rb for rb in gui._set_groups["selb"]
         if _rb_val(rb) == _old_sel_mem[0]).invoke()   # 还原边框档（v75.3）
    next(rb for rb in gui._set_groups["selc"]
         if _rb_val(rb) == _old_sel_mem[1]).invoke()   # 还原颜色档
    root.update()
    # v76：① 配色 12 格等宽（圆点 / 字头按列对齐，cell 等宽、焦点框仍贴字）；
    #      ② 顺序 = 亮 / 深各按字母 + 一条龙（第 2 / 4 行反向存）；③ 主题块焦点记忆
    _cells12 = [rb.master.master.master for rb in _sch]
    assert all(c.winfo_class() == "Frame" for c in _cells12), "v76：配色每项该多包一层等宽 cell"
    _wset = {int(c.cget("width")) for c in _cells12}
    assert len(_wset) == 1 and _wset.pop() > 0, \
        "v76：配色 12 格该等宽：%r" % ([int(c.cget("width")) for c in _cells12],)
    assert all(int(c.cget("height")) == int(_cells12[0].cget("height")) for c in _cells12), \
        "v76：12 格高度也该一致（等宽段里一起定的）"
    _names12 = [str(rb.cget("text")) for rb in _sch]
    assert _names12 == ["Catppuccin Latte", "Chakra", "Kanagawa Lotus",
                        "Tailwind", "Rose Pine Dawn", "Radix",
                        "Bootstrap Dark", "Catppuccin Mocha", "Dracula",
                        "Radix Dark", "Nord", "Kanagawa Wave"], _names12
    gui._theme_focus_mem = None               # 清场：从「没记过」起
    _sch[7].focus_set()
    root.update()
    assert gui._theme_focus_mem is _sch[7], "v76：聚焦该被记住：%r" % (gui._theme_focus_mem,)
    assert gui._theme_focus_key() == "scheme:%s" % _sch[7].cget("value"), gui._theme_focus_key()
    gui._set_to_menu()
    root.update()
    gui._set_focus_panel()
    root.update()
    assert root.focus_get() is _sch[7], \
        "v76：再进主题块该落回上次焦点位：%r" % (root.focus_get(),)
    gui._theme_focus_mem = None               # 模拟「重开」：只剩配置里那份
    gui.cfg["theme_focus"] = "scheme:%s" % _sch[11].cget("value")
    gui._set_to_menu()
    root.update()
    gui._set_focus_panel()
    root.update()
    assert root.focus_get() is _sch[11], \
        "v76：配置里那份（重开路径）也要认：%r" % (root.focus_get(),)
    gui._theme_focus_mem = None
    gui.cfg["theme_focus"] = "scheme:zzz"     # 脏值：认不出的档 → 回第一件
    gui._set_to_menu()
    root.update()
    gui._set_focus_panel()
    root.update()
    assert root.focus_get() is gui._set_groups["selb"][0], \
        "v76/v75.3：脏配置该回第一件（当前行边框 ▸ 黑色）：%r" % (root.focus_get(),)
    gui.cfg["theme_focus"] = None             # 还原现场（cfg 是默认副本）
    gui._theme_focus_mem = None
    # v76：进出网格按方向落边界行（上面来 ↓ 第 1 行、下面来 ↑ 第 4 行）+ 往返对称
    _grp_sel[0].focus_set()
    root.update()
    gui._set_theme_updown(1)
    root.update()
    assert root.focus_get() in _sch[:3], \
        "v76：从上面 ↓ 进网格该落第 1 行：%r" % (root.focus_get(),)
    gui._set_theme_updown(-1)
    root.update()
    assert root.focus_get() is _grp_sel[0], \
        "v76：↑ 出来该回上面那组（往返对称）：%r" % (root.focus_get(),)
    _sch[11].focus_set()
    root.update()
    gui._set_theme_updown(1)
    root.update()
    assert root.focus_get() in gui._set_groups["today"], \
        "v76：从末行 ↓ 出网格该去下一组：%r" % (root.focus_get(),)
    gui._set_theme_updown(-1)
    root.update()
    assert root.focus_get() in _sch[9:], \
        "v76：从下面 ↑ 进网格该落第 4 行：%r" % (root.focus_get(),)
    gui._theme_focus_mem = None
    # v75 / v75.2：第 5 组「界面模式」= **单开关「黑夜模式」**；勾上当场生效（非表行全深 / tag 不动）
    _dn = gui._set_groups.get("daynight", [])
    assert len(_dn) == 1 and _dn[0].winfo_class() == "Checkbutton", [str(w) for w in _dn]
    assert str(_dn[0].cget("text")) == "黑夜模式"
    assert gui._set_group_order[-1] == "daynight", gui._set_group_order
    assert gui.theme_scheme == "radix", gui.theme_scheme      # 前提（v76 段收尾已切回 Radix）
    _dn[0].invoke()                                           # 勾上 = 黑夜
    root.update()
    assert gui.theme_daynight == "night", gui.theme_daynight
    _p_fb = FRAME_FALLBACK                                    # radix 是亮色键 → 黑夜走中性兜底
    assert C_BG.upper() == _p_fb["bg"].upper(), C_BG
    _st5 = ttk.Style(root)
    assert str(_st5.lookup("Status.Treeview", "fieldbackground")).upper() \
        == _p_fb["panel"].upper()
    assert str(gui.lbl_count.cget("fg")).upper() == _p_fb["text"].upper(), gui.lbl_count.cget("fg")
    assert str(gui.lbl_count.cget("bg")).upper() == _p_fb["bg"].upper()
    # 表行 tag 一位不动（黑夜只改非表行）
    assert str(gui.tree.tag_configure("st_不会", "background")).upper() \
        == SCHEME["radix"]["status"]["不会"][0].upper()
    assert str(gui.tree.tag_configure("even", "background")).upper() \
        == SCHEME["radix"]["zebra"][1].upper()
    _dn[0].invoke()                                           # 再点 = 取消 = 白天（v75.2 单开关）
    root.update()
    assert gui.theme_daynight == "day", gui.theme_daynight
    assert C_BG.upper() == "#F4F6FB", C_BG
    assert str(gui.lbl_count.cget("fg")).upper() == FRAME_LIGHT["text"].upper()
    # v75.1（用户拍板「深色配色要带深界面」）：D 系配色**不开黑夜也深** —— 切 d2（白天模式）即变深
    gui.theme_scheme = "d2"
    gui._sel_vars["scheme"].set("d2")
    gui._apply_theme()
    root.update()
    assert gui.theme_daynight == "day", gui.theme_daynight
    assert C_BG.upper() == FRAME_SCHEMES["d2"]["bg"].upper(), C_BG
    assert str(gui.lbl_count.cget("fg")).upper() == FRAME_SCHEMES["d2"]["text"].upper(), \
        gui.lbl_count.cget("fg")
    assert str(gui.tree.tag_configure("even", "background")).upper() \
        == SCHEME["d2"]["zebra"][1].upper(), "表行 tag 该跟配色走（d2 斑马）"
    # 还原：radix + 白天 → 界面回浅（斑马 tag 也回浅 —— 用户会话报过疑似的"回不去"，这里钉住）
    gui.theme_scheme = "radix"
    gui._sel_vars["scheme"].set("radix")
    gui._apply_theme()
    root.update()
    assert C_BG.upper() == "#F4F6FB", C_BG
    assert str(gui.tree.tag_configure("even", "background")).upper() \
        == SCHEME["radix"]["zebra"][1].upper(), "切回 radix 后斑马 tag 该回浅色"
    print("(hh6-8) 界面模式：单开关「黑夜模式」勾上 / 取消当场生效（框架换色 / 计数行字跟随 / 表行 "
          "tag 不动 / 切回复原）+ v75.1：D 系配色（d2）不开黑夜也深、切回 radix 复原 ✓")
    # Esc 逐层退（v55：来源 = 主表，退出回主表）；Ctrl+Tab 退出口径 = **回来源格**
    gui._on_settings_esc()
    root.update()
    assert gui._in_settings() and root.focus_get() is gui.set_left, \
        "v42：Esc 第一层 = 面板回左四项：%r" % (root.focus_get(),)
    gui._on_settings_esc()
    root.update()
    assert (not gui._in_settings()) and gui.nb.index(gui.nb.select()) == 0, \
        "v55：Esc 第二层 = 退出设置、回来源格（这里来源 = 主表）"
    # v55：从今天要做的进去、Ctrl+Tab 退出该回**今天要做的**（哪来的回哪去）
    gui.nb.select(1)
    root.update()
    gui.enter_settings()
    root.update()
    gui._on_settings_key()
    root.update()
    assert (not gui._in_settings()) and gui.nb.index(gui.nb.select()) == 1, \
        "v55：从今天要做的进去、Ctrl+Tab 退出该回它（用户口径「哪来的回哪去」）"
    gui._goto_cell(0)             # 收尾：切回主表（后面 (hh6) 段要在总表上验黑框 —— 段尾要还原现场）
    root.update()
    gui.tree.focus_force()
    root.update()
    print("(vv40) 菜单栏整套删除 → 设置界面：Ctrl+Tab 开关（整窗替换：主界面整块收 / 摆回来）、"
          "左列表两项（SET_ITEMS 顺序；v53：导入 / 导出两块删除）、↑↓ 真按键换项 / 换项换面板 / Enter 进面板 /"
          "Esc 逐层退（v42）、Ctrl+3 定位到「快捷键」块；v48：设置里 ← / → 走开只是看不见、走回来原样再现"
          "（Ctrl+Tab / Esc 才真关）；快捷键表在页里（独立弹窗 + key_win 已删）、↑↓ 真按键换行（v53）✓")

    # --- v23/v25/v37/v40/v45/v71/v72/v75 闸门 (hh6)：主题设置 = 设置界面「主题设置」块里的五组单选钮
    #     「选择当前行 ▸ 蓝底白字 / 淡蓝色底 / 黑色边框 / 白色边框（v72 加末档）」+
    #     「配色 ▸ 12 套现成主题（v71）」+
    #     「今天标记 ▸ 开 / 关」+「题解预览 ▸ 右侧栏 / 全屏」（v45）+
    #     「界面模式 ▸ 白天模式 / 黑夜模式」（v75）
    #     口径（2026-10-06 用户拍板 + v40 从菜单搬进设置界面 + v71 用户点名加 12 套配色）。
    _theme_panel = gui.set_panels["theme"]
    _tgroups = []
    for _row in _theme_panel.winfo_children():
        if _row.winfo_class() != "Frame":
            continue
        _labs = [w for w in _walk_set(_row)]
        _title = [str(w.cget("text")) for w in _labs if w.winfo_class() == "Label"]
        _radios = [str(w.cget("text")) for w in _labs
                   if w.winfo_class() in ("Radiobutton", "Checkbutton")]   # v75.2：含单开关
        if _radios:
            _tgroups.append((_title[0] if _title else "", _radios))
    assert _tgroups == [
        (THEME_SELB_MENU_LABEL, [lb for _v, lb in THEME_SELB_ITEMS]),   # v75.3：拆两组
        (THEME_SELC_MENU_LABEL, [lb for _v, lb in THEME_SELC_ITEMS]),
        (THEME_SCHEME_MENU_LABEL, [lb for _v, lb in THEME_SCHEME_ITEMS]),
        (THEME_TODAY_MENU_LABEL, [lb for _v, lb in THEME_TODAY_ITEMS]),
        (THEME_PREVIEW_MENU_LABEL, [lb for _v, lb in THEME_PREVIEW_ITEMS]),
        (THEME_DAYNIGHT_MENU_LABEL, [lb for _v, lb in THEME_DAYNIGHT_ITEMS])], _tgroups   # v75
    # v76：顺序 = 显示顺序 —— 亮 6 / 深 6 各自按字母 + 一条龙蛇形（第 2 / 4 行反向存）；
    #      Radix（v37~v70 的唯一档，键名 `radix`）现在名列第 6（亮色组按字母的最后一位）
    assert _tgroups[2][1] == [                 # v75.3：组序第 3 条是「配色」（前两条 = 边框 / 颜色）
        "Catppuccin Latte", "Chakra", "Kanagawa Lotus",
        "Tailwind", "Rose Pine Dawn", "Radix",
        "Bootstrap Dark", "Catppuccin Mocha", "Dracula",
        "Radix Dark", "Nord", "Kanagawa Wave"], _tgroups[2][1]
    assert gui.theme_sel_color == "blue" and gui.theme_sel_border == "none" and gui.theme_scheme == "radix", \
        "v37/v75.3 默认该是「边框无 + 蓝底白字 + Radix」：%r" % (
            (gui.theme_sel_border, gui.theme_sel_color, gui.theme_scheme),)
    assert gui.theme_today == "on", "「今天标记」默认该是「开启」：%r" % (gui.theme_today,)
    assert gui.preview_mode == PREVIEW_MODE_SIDE, \
        "v45：题解预览默认该是「右侧栏」（现状一字不变）：%r" % (gui.preview_mode,)

    def _pick(label):
        """在设置界面「主题设置」块里点一下某个单选钮（跟鼠标点同一条路：invoke → command）。"""
        for w in _walk_set(_theme_panel):
            if w.winfo_class() in ("Radiobutton", "Checkbutton") \
                    and str(w.cget("text")) == label:      # v75.2：黑夜模式开关也能被 _pick 到
                w.invoke()
                return True
        return False

    def _pickg(gk, val):
        """v75.3：按「组 + 值」invoke 某颗钮 —— 边框 / 颜色两组拆开后各有「无」等重名档，
        按 text 点会撞；`_rb_val` 对 Radiobutton / Checkbutton 通用。"""
        for rb in gui._set_groups.get(gk, []):
            if _rb_val(rb) == val:
                rb.invoke()
                return True
        return False

    # ① 选中行 = 黑色边框（v25.1「纯边框」；v75.3 拆组后 = **边框 ▸ 黑色 + 颜色 ▸ 无**）：
    #    **选中映射整个清空** —— 底色 / 字色回落行 tag，只由 `_RowBorder` 画线
    #    （edge_probe2 实测：selected 无映射时 ttk 回落 tag 的色）。
    assert _pickg("selb", "black")
    assert _pickg("selc", "none")
    stl = ttk.Style(root)
    assert not stl.map("Status.Treeview", "background"), \
        "黑色边框档该把选中背景映射清空（纯边框）：%r" % (stl.map("Status.Treeview", "background"),)
    assert not stl.map("Status.Treeview", "foreground"), \
        "黑色边框档该把选中前景映射清空：%r" % (stl.map("Status.Treeview", "foreground"),)
    # v25.12：前面的用例可能触发「快按让位」把框收了 —— 先复位 + 补位，再断言边框
    gui._last_key_move = 0.0
    gui._repaint_idle()
    root.update()
    rb = gui._row_border(gui.tree)
    root.update()
    iid0 = gui.tree.selection()[0]
    box = rb.redraw()
    assert box, "边框没画出来（bbox 为空）"
    for _n, f in enumerate(rb.frames):
        info = f.place_info()
        assert info and f.winfo_ismapped(), "第 %d 条边没摆出来" % _n
    assert str(rb.frames[0].cget("bg")).upper() == SEL_BORDER["black"]["line"].upper(), \
        rb.frames[0].cget("bg")
    # v41：线宽 2 → 3；v55 曾 4、v57 回 3（「改回3px」）—— 画框的 `_RowBorder` 与盖残影的
    #      `_RowPads` 必须同宽，否则旧框位置会留一条 1px 细线（v25.7 那套重药就白上了）
    assert rb.w == SEL_BORDER_W == 3, rb.w
    assert int(rb.frames[0].place_info()["height"]) == SEL_BORDER_W, \
        rb.frames[0].place_info()
    assert int(rb.frames[2].place_info()["width"]) == SEL_BORDER_W, \
        rb.frames[2].place_info()
    print("(hh6-1) 主题「当前行边框 ▸ 黑色 + 当前行颜色 ▸ 无」：选中行四周 4 条 %dpx 线（%s）、"
          "选中映射清空（底色 / 字色原样不动 = 纯边框）✓" % (SEL_BORDER_W, SEL_BORDER["black"]["line"]))

    # ①b v25.2 失焦变淡：焦点挪出表格 → 线变灰（line_blur）；回来 → 变回黑
    root.focus_set()
    root.update()
    gui._refresh_border_focus()
    assert str(rb.frames[0].cget("bg")).upper() == str(SEL_BORDER["black"]["line_blur"]).upper(), \
        "失焦时线该变 %s：%r" % (SEL_BORDER["black"]["line_blur"], rb.frames[0].cget("bg"))
    gui.tree.focus_set()
    root.update()
    gui._refresh_border_focus()
    assert str(rb.frames[0].cget("bg")).upper() == str(SEL_BORDER["black"]["line"]).upper(), \
        "焦点回来后线该变回 %s：%r" % (SEL_BORDER["black"]["line"], rb.frames[0].cget("bg"))
    print("(hh6-1b) 黑框失焦变淡：焦点出去 → 线 %s；焦点回来 → %s ✓"
          % (SEL_BORDER["black"]["line_blur"], SEL_BORDER["black"]["line"]))

    # ①c v72 / v75.3：「当前行边框 ▸ 白色」—— 与黑框同机制、线换纯白
    #     （v71 的 6 套深色配色下黑线看不见）；失焦 = 中灰 #999999（深底上"淡一档"往暗走）
    assert _pickg("selb", "white")
    gui._last_key_move = 0.0
    gui._repaint_idle()
    root.update()
    box = rb.redraw()
    assert box, "白色边框没画出来（bbox 为空）"
    assert str(rb.frames[0].cget("bg")).upper() == SEL_BORDER["white"]["line"].upper(), \
        "白色边框档线色该是 %s：%r" % (SEL_BORDER["white"]["line"], rb.frames[0].cget("bg"))
    assert not stl.map("Status.Treeview", "background"), \
        "白色边框档该与黑框同规（选中映射清空）：%r" % (stl.map("Status.Treeview", "background"),)
    root.focus_set()
    root.update()
    gui._refresh_border_focus()
    assert str(rb.frames[0].cget("bg")).upper() == str(SEL_BORDER["white"]["line_blur"]).upper(), \
        "白框失焦时线该变 %s：%r" % (SEL_BORDER["white"]["line_blur"], rb.frames[0].cget("bg"))
    gui.tree.focus_set()
    root.update()
    gui._refresh_border_focus()
    assert str(rb.frames[0].cget("bg")).upper() == SEL_BORDER["white"]["line"].upper(), \
        "焦点回来后线该变回 %s：%r" % (SEL_BORDER["white"]["line"], rb.frames[0].cget("bg"))
    print("(hh6-1c) 主题「当前行边框 ▸ 白色」：线 %s、失焦 %s、选中映射清空（v72；v75.3 拆组后同规）✓"
          % (SEL_BORDER["white"]["line"], SEL_BORDER["white"]["line_blur"]))

    # ② 选中行 = 蓝底白字：样式映射铺深蓝 + 白字，边框收起来
    def _map_get(spec, key):
        """从 `style.map(...)` 的结果里取某个状态组合的值。

        ttk 返回的是 `[(state_spec, value), …]`，其中 state_spec 有两 / 三元（`("selected", "focus")`）
        —— 直接 `dict()` 会炸「element #0 has length 3」，所以按元组比对取。
        """
        for item in spec:
            if tuple(item[:-1]) == tuple(key):
                return item[-1]
        return None

    assert _pickg("selc", "blue")            # v75.3：颜色 ▸ 蓝底白字
    assert _pickg("selb", "none")            # 边框 ▸ 无（「边框收起」断言的前提）
    bgmap = stl.map("Status.Treeview", "background")
    fgmap = stl.map("Status.Treeview", "foreground")
    assert str(_map_get(bgmap, ("selected", "focus"))).upper() == SEL_COLOR["blue"]["bg"].upper(), bgmap
    assert str(_map_get(fgmap, ("selected", "focus"))).upper() == SEL_COLOR["blue"]["fg"].upper(), fgmap
    root.update()
    assert not any(f.winfo_ismapped() for f in rb.frames), "蓝底白字档不该再画边框"
    print("(hh6-2) 主题「当前行颜色 ▸ 蓝底白字 + 边框 ▸ 无」：选中行铺 %s + 白字（失焦 %s）、"
          "边框收起 ✓" % (SEL_COLOR["blue"]["bg"], SEL_COLOR["blue"]["bg_blur"]))
    # ②b 选中行 = 淡蓝色底（v25 新档）：映射铺 #c9d4e6 + 深字（失焦再浅一档），边框同样收起
    assert _pickg("selc", "soft")
    bgmap = stl.map("Status.Treeview", "background")
    fgmap = stl.map("Status.Treeview", "foreground")
    assert str(_map_get(bgmap, ("selected", "focus"))).upper() == SEL_COLOR["soft"]["bg"].upper(), bgmap
    assert str(_map_get(bgmap, ("selected", "!focus"))).upper() == SEL_COLOR["soft"]["bg_blur"].upper(), bgmap
    assert str(_map_get(fgmap, ("selected", "focus"))).upper() == SEL_COLOR["soft"]["fg"].upper(), fgmap
    root.update()
    assert not any(f.winfo_ismapped() for f in rb.frames), "淡蓝色底档不该再画边框"
    print("(hh6-2b) 主题「当前行颜色 ▸ 淡蓝色底 + 边框 ▸ 无」：选中行铺 %s + 深字（失焦 %s）、"
          "边框收起 ✓" % (SEL_COLOR["soft"]["bg"], SEL_COLOR["soft"]["bg_blur"]))

    # ③ 配色 = Radix（v71 起 12 套之一）：铺状态底色 + **该状态自己的彩色字**（v71.1：= chip 字色）
    #    + 今天日期字 / 行首竖条；「未做」行走斑马纹（v25.1）
    assert _pick("Radix")
    assert gui.theme_scheme == "radix", gui.theme_scheme
    for _s in STATES:
        _tag = theme_tag(_s)
        assert str(gui.tree.tag_configure(_tag, "background")).upper() == RADIX_BG[_s].upper(), \
            "%s 的行底该是 %s" % (_s, RADIX_BG[_s])
        # v71.1：行字色 = **该状态自己的彩色字**（= HTML chip 的字色；v25「整行染色」口径回归，
        # v71 初版的「统一墨色」被用户看后否掉）
        assert str(gui.tree.tag_configure(_tag, "foreground")).upper() == \
            SCHEME["radix"]["status"][_s][1].upper(), \
            "%s 的行 tag 前景该是该状态字色 %s：%r" % (
                _s, SCHEME["radix"]["status"][_s][1], gui.tree.tag_configure(_tag, "foreground"))
    assert str(gui.tree.tag_configure("even", "background")).upper() == C_ZEBRA.upper(), \
        "v25.1 起「未做」行走斑马纹（L2 的 even 底该是 %s）" % C_ZEBRA
    assert str(gui.tree.tag_configure("even", "foreground")).upper() == \
        SCHEME["radix"]["ink"].upper(), "v71.1：斑马行的字色该是该套默认正文色"
    radix_rows = [("牛客周赛 Round 402", "A", "整行铺色", "模拟", "CF 800", "独立AC", td),
                  ("牛客周赛 Round 402", "B", "状态色二", "模拟", "CF 800", "不会", "2026-08-01"),
                  ("牛客周赛 Round 402", "C", "未做走斑马", "模拟", "CF 800", "未做", "")]
    radix_fix = os.path.join(tmpdir, "v23_theme.md")
    write_text(radix_fix, "\n".join(["# v23/v25 主题 fixture（Radix 配色）", "",
                                     "| " + " | ".join(HEADER) + " |",
                                     "|" + "|".join(["---"] * len(HEADER)) + "|"]
                                    + [render_row(list(c)) for c in radix_rows] + [""]) + "\n")
    gui.path = radix_fix
    gui.reload()
    rtag = {gui.row_by_iid(i)["题号"]: gui.tree.item(i, "tags") for i in gui.tree.get_children()}
    assert theme_tag("独立AC") in rtag["A"] and "even" not in rtag["A"] and "odd" not in rtag["A"], rtag["A"]
    assert "today" in rtag["A"], "今天那行还要挂 today（管日期字深墨）：%r" % (rtag["A"],)
    assert theme_tag("不会") in rtag["B"], rtag["B"]
    # v25.1：Radix 下「未做」行走斑马纹（不铺灰底）——用户口径「默认状态的行 = 斑马条纹」
    assert theme_tag("未做") not in rtag["C"], \
        "Radix 下「未做」行不该再挂状态 tag：%r" % (rtag["C"],)
    assert ("unsetOdd" in rtag["C"]) != ("unsetEven" in rtag["C"]), \
        "v77：Radix 下「未做」行该恰好带一个未做斑马 tag（unset 系列）：%r" % (rtag["C"],)
    # v25：今天竖条（Frame 贴条）—— show 切到 "tree headings"（#0 窄列放出来）、
    #      今天行摆一条 6px 深色条（位置 = 该行 bbox）、非今天行没有
    assert "tree" in show_items(gui.tree), \
        "Radix 档该把 #0 窄列放出来画竖条：%r" % (gui.tree.cget("show"),)
    assert int(gui.tree.column("#0", "width")) == TODAY_BAR_W
    riid = {gui.row_by_iid(i)["题号"]: i for i in gui.tree.get_children()}
    root.update()
    bars = [f for f in gui._bar_frames if f.winfo_ismapped()]
    assert len(bars) == 1, "今天只有一行 → 该只摆一条竖条：%r" % ([f._iid for f in gui._bar_frames],)
    bar = bars[0]
    assert bar._iid == riid["A"], "竖条该贴在今天那行（A）：%r" % (bar._iid,)
    box = gui.tree.bbox(riid["A"])
    pos = bar.place_info()
    if not pos:                      # v25.12 容错：极端时序下竖条还没重新摆 → 补一发再读
        gui._repaint_idle()
        root.update()
        pos = bar.place_info()
    assert (int(pos["x"]), int(pos["y"]), int(pos["width"]), int(pos["height"])) == \
        (int(box[0]), int(box[1]), TODAY_BAR_W, int(box[3])), \
        "竖条该跟今天行的 bbox 对齐：%r vs %r" % (pos, box)
    assert str(bar.cget("bg")).upper() == TODAY_BAR_COLOR.upper(), bar.cget("bg")
    print("(hh6-3) 主题「配色 ▸ Radix」：一状态一个行 tag（背景 %s + 该状态字色 %s，v71.1 起 = chip 字色）"
          "+ 「未做」行走斑马纹（v25.1）+ 今天日期字 / 行首竖条（Frame 贴条 %dpx）✓"
          % (RADIX_BG["不会"], SCHEME["radix"]["status"]["不会"][1], TODAY_BAR_W))

    # ④ v37：「配色 ▸ 默认」整段闸门删除 —— 「默认」档已随用户点名整条移除。
    #    （原来这段测默认档"不额外着色 + 全表斑马纹 + 今天竖条"；其中"竖条 / 窄列恒占"
    #     由 (hh6-3) 与 (hh6-5) 守着，不丢覆盖。）

    # ④b v28 闸门 (hh6-5)：「今天标记」开关 —— 关掉竖条全收起、**窄列位置保留**；开回来复原
    assert _pick("关闭")
    assert gui.theme_today == "off", gui.theme_today
    root.update()
    assert not any(f.winfo_ismapped() for f in gui._bar_frames), "关掉今天标记后竖条该全收起"
    assert "tree" in show_items(gui.tree) and int(gui.tree.column("#0", "width")) == TODAY_BAR_W, \
        "关掉今天标记后窄列位置要保留（行内容不左右跳）：%r" % (gui.tree.cget("show"),)
    assert _pick("开启")
    assert gui.theme_today == "on", gui.theme_today
    root.update()
    obars = [f for f in gui._bar_frames if f.winfo_ismapped()]
    assert len(obars) == 1, "开回来竖条该回来：%r" % ([f._iid for f in gui._bar_frames],)
    print("(hh6-5) 主题「今天标记 ▸ 关闭 / 开启」：关掉竖条全收、窄列保留；开回来竖条复原 ✓")

    # ⑥ v71 闸门 (hh6-6)：12 套配色逐套上色 —— tag 实际色值逐项 == `SCHEME` 表（状态底色 / 状态字色 /
    #    斑马两档 / 父行子行四色 / 今天日期字）、行首竖条跟着换色；跑完切回 radix。
    for _key, _lab in THEME_SCHEME_ITEMS:
        assert _pick(_lab), "设置页里点不到「%s」" % _lab
        root.update()
        assert gui.theme_scheme == _key, (gui.theme_scheme, _key)
        _sch = SCHEME[_key]
        for _s in STATES:
            _t = theme_tag(_s)
            assert str(gui.tree.tag_configure(_t, "background")).upper() == \
                _sch["status"][_s][0].upper(), (_key, _s, "底")
            assert str(gui.tree.tag_configure(_t, "foreground")).upper() == \
                _sch["status"][_s][1].upper(), (_key, _s, "字")
        assert str(gui.tree.tag_configure("odd", "background")).upper() == _sch["zebra"][0].upper(), _key
        assert str(gui.tree.tag_configure("even", "background")).upper() == _sch["zebra"][1].upper(), _key
        assert str(gui.tree.tag_configure("even", "foreground")).upper() == _sch["ink"].upper(), _key
        # v77：未做行 unset* —— 底 = 同斑马两档；字 = 深色 6 套的次要文字色（muted）/ 亮色 6 套 ink
        _want_unset = FRAME_SCHEMES[_key]["muted"].upper() if _key in FRAME_SCHEMES else _sch["ink"].upper()
        assert str(gui.tree.tag_configure("unsetOdd", "background")).upper() == _sch["zebra"][0].upper(), _key
        assert str(gui.tree.tag_configure("unsetEven", "background")).upper() == _sch["zebra"][1].upper(), _key
        assert str(gui.tree.tag_configure("unsetOdd", "foreground")).upper() == _want_unset, (_key, "unsetOdd 字")
        assert str(gui.tree.tag_configure("unsetEven", "foreground")).upper() == _want_unset, (_key, "unsetEven 字")
        for _tg, _c in (("lvl0", _sch["lvl0"][0]), ("lvl0b", _sch["lvl0"][1]),
                        ("lvl1", _sch["lvl1"][0]), ("lvl1b", _sch["lvl1"][1]),
                        ("lvl2", _sch["lvl2"][0]), ("lvl2b", _sch["lvl2"][1])):
            assert str(gui.tree.tag_configure(_tg, "background")).upper() == _c.upper(), (_key, _tg)
            assert str(gui.tree.tag_configure(_tg, "foreground")).upper() == _sch["ink"].upper(), (_key, _tg)
        assert str(gui.tree.tag_configure("today", "foreground")).upper() == _sch["today_fg"].upper(), _key
        _bars = [f for f in gui._bar_frames if f.winfo_ismapped()]
        assert len(_bars) == 1, "（%s）今天那行该有一条竖条：%r" % (_key, _bars)
        assert str(_bars[0].cget("bg")).upper() == _sch["bar"].upper(), (_key, _bars[0].cget("bg"))
    assert _pick("Radix"), "收尾切回 Radix"
    root.update()
    assert gui.theme_scheme == "radix"
    print("(hh6-6) 12 套配色逐套上色：状态底 / 状态字色 / 斑马两档 / 层级六色（v86：lvl0 两档 + lvl1 两档 + lvl2 两档）/"
          "今天字 + 竖条色 逐项 == SCHEME 表 ✓")
    gui.path = tmp
    gui.reload()

    # --- v23.1 的 (hh7)「状态列单格上色」整段已删（v25 改整行染色，label 补丁整族移除；
    #     现行断言见上面的 (hh6-3)：tag 的 foreground = 状态字色、六列一起变）。
    gui.path = tmp
    gui.reload()

    # --- v23 闸门 (e3)：主题进配置（关窗存 / 开窗还原；脏值归默认；v75.3 老键迁移）
    cfg3 = os.path.join(tmpdir, "theme_cfg.json")
    save_config(cfg3, {"geometry": "", "theme_sel_border": "black", "theme_sel_color": "soft",
                       "theme_scheme": "radix",
                       "theme_today": "off", "theme_daynight": "night"})   # v28/v75 开关也进往返
    got3 = load_config(cfg3)
    assert got3["theme_sel_border"] == "black" and got3["theme_sel_color"] == "soft", got3
    assert got3["theme_scheme"] == "radix", got3
    assert got3["theme_today"] == "off", got3
    assert got3["theme_daynight"] == "night", got3
    # v75.3：**老配置迁移** —— 手写一份只含老 `theme_sel` 单键的 JSON（save_config 只写白名单
    #         键、造不出"老格式文件"），load_config 要把它迁移成两新键。
    io.open(cfg3, "w", encoding="utf-8", newline="").write(
        json.dumps({"geometry": "", "theme_sel": "white", "theme_scheme": "radix"}))
    got3 = load_config(cfg3)
    assert got3["theme_sel_border"] == "white" and got3["theme_sel_color"] == "none", \
        "v75.3：老 theme_sel=white 该迁移成「边框白 + 颜色无」：%r" % (got3,)
    # 脏值（含新键同时被手改坏）：加载时归默认。同样手写文件（save 的归一化会先滤掉脏值）。
    io.open(cfg3, "w", encoding="utf-8", newline="").write(
        json.dumps({"geometry": "", "theme_sel": "乱写", "theme_sel_border": "乱写",
                    "theme_sel_color": 42, "theme_scheme": 42, "theme_today": 7,
                    "theme_daynight": "乱写"}))
    got3 = load_config(cfg3)
    assert got3["theme_sel_border"] == "none" and got3["theme_sel_color"] == "blue", \
        "v75.3：脏值该归「边框无 + 蓝底白字」：%r" % (got3,)
    assert got3["theme_scheme"] == "radix", got3
    assert got3["theme_today"] == "on", "theme_today 脏值该归 on：%r" % (got3,)
    assert got3["theme_daynight"] == "day", "theme_daynight 脏值该归 day：%r" % (got3,)
    print("(e3) 主题写进配置能往返（边框/颜色两键、radix、今天标记 off、界面模式 night）；"
          "老 theme_sel 单键自动迁移；脏值归「边框无 + 蓝底白字 + Radix + 开启 + 白天」✓")

    # --- v75 / v75.1 闸门 (hh6-7)：界面框架色 —— 板函数四态 + 「D 系恒深」全窗换色（含计数行字）
    #     + 切回复原 + 设置页新组
    _pal_day = frame_palette("radix", THEME_DAYNIGHT_DAY)
    assert _pal_day is FRAME_LIGHT and _pal_day["bg"].upper() == "#F4F6FB", _pal_day
    # v75.1（用户拍板「深色配色要带深界面」）：D 系恒深 —— 昼夜开关都不影响
    assert frame_palette("d6", THEME_DAYNIGHT_DAY) is FRAME_SCHEMES["d6"], "d6 + 白天也该走逐套深板"
    assert frame_palette("d6", THEME_DAYNIGHT_NIGHT) is FRAME_SCHEMES["d6"]
    assert frame_palette("l1", THEME_DAYNIGHT_NIGHT) is FRAME_FALLBACK, "亮色 + 黑夜走兜底"
    assert frame_palette("乱写", THEME_DAYNIGHT_NIGHT) is FRAME_FALLBACK, "认不出的键也走兜底"
    gui.theme_sel_border, gui.theme_sel_color, gui.theme_scheme, gui.theme_daynight = "none", "none", "d6", "day"   # 白天模式！照深
    gui._apply_theme()
    root.update()
    _p6 = FRAME_SCHEMES["d6"]
    assert C_BG.upper() == _p6["bg"].upper(), C_BG
    assert str(gui.main_frame.cget("bg")).upper() == _p6["bg"].upper(), gui.main_frame.cget("bg")
    _stl = ttk.Style(root)
    assert str(_stl.lookup("Status.Treeview", "fieldbackground")).upper() \
        == _p6["panel"].upper(), _stl.lookup("Status.Treeview", "fieldbackground")
    assert str(_stl.lookup("Status.Treeview.Heading", "background")).upper() \
        == _p6["accent_light"].upper()
    assert str(_stl.lookup("Nav.TEntry", "fieldbackground")).upper() == _p6["panel"].upper()
    # 计数行（head 里的 Label）也要跟着换 —— v75 覆盖「所有非表行」（bg + 字色两件）
    assert str(gui.lbl_count.cget("bg")).upper() == _p6["bg"].upper(), gui.lbl_count.cget("bg")
    assert str(gui.lbl_count.cget("fg")).upper() == _p6["text"].upper(), gui.lbl_count.cget("fg")
    # 竖条没被框架色污染（仍 = 该套配色的 bar 色）
    _bars = [f for f in gui._bar_frames if f.winfo_ismapped()]
    assert all(str(f.cget("bg")).upper() == SCHEME["d6"]["bar"].upper() for f in _bars), \
        [str(f.cget("bg")) for f in _bars]
    # 回归（v75 自查逮到）：切深色板（d 系恒深 / 亮色黑夜）时 `_setup_styles` 会重配 ttk 样式 ——
    # 黑框档的清空映射不许被它的「初始 map」顶回去（修法 = `_setup_styles` 后补 `_apply_sel_map`）
    assert not _stl.map("Status.Treeview", "background"), \
        "切深色板后黑框档 map 该仍清空：%r" % (_stl.map("Status.Treeview", "background"),)
    # v75.1：d6 下把昼夜开关拨到 night —— 板身份不变（还是 "d6"），界面纹丝不动（不重刷）
    gui.theme_daynight = THEME_DAYNIGHT_NIGHT
    gui._apply_theme()
    root.update()
    assert gui._fw_key == "d6" and C_BG.upper() == _p6["bg"].upper(), (gui._fw_key, C_BG)
    gui.theme_daynight = THEME_DAYNIGHT_DAY
    gui._apply_theme()
    root.update()
    # 切回白天：色全部原样回来
    gui.theme_daynight = THEME_DAYNIGHT_DAY
    gui.theme_scheme, gui.theme_sel_border, gui.theme_sel_color = "radix", "none", "blue"
    gui._apply_theme()
    root.update()
    assert C_BG.upper() == "#F4F6FB", C_BG
    assert str(gui.main_frame.cget("bg")).upper() == "#F4F6FB"
    assert str(gui.lbl_count.cget("fg")).upper() == FRAME_LIGHT["text"].upper(), \
        gui.lbl_count.cget("fg")
    _bm = _stl.map("Status.Treeview", "background")
    assert _bm and str(_bm[0][-1]).lower() == SEL_COLOR["blue"]["bg"].lower(), \
        "切回白天后「蓝底白字」档的填充 map 该回来：%r" % (_bm,)
    # 设置页「界面模式」组：**单开关**（v75.2）—— 一枚「黑夜模式」Checkbutton、组序在末位
    _dn = gui._set_groups.get("daynight", [])
    assert len(_dn) == 1 and _dn[0].winfo_class() == "Checkbutton", [str(w) for w in _dn]
    assert str(_dn[0].cget("text")) == "黑夜模式"
    assert _rb_val(_dn[0]) == "night"
    assert gui._set_group_order[-1] == "daynight", gui._set_group_order
    assert gui._sel_vars["daynight"].get() == "day"
    print("(hh6-7) 界面框架色：板四态（light / D 系恒深 / 兜底）+ 「d6 + 白天模式」全窗换色（窗口底 /"
          " 表格空白区 / 表头 / 搜索框 / 计数行字）+ 今天竖条不受污染 + 昼夜开关对 D 系不重刷 +"
          " 切回亮色复原 + 设置页「界面模式」组单开关 ✓")
    # 主题这一节改过样式映射，**给后面的老闸门还原成标准主题**（不然后面按老口径断言会误报）
    gui.theme_sel_border, gui.theme_sel_color, gui.theme_scheme, gui.theme_today = "none", "blue", "radix", "on"
    for _key, _val in (("sel", "blue"), ("scheme", "radix"), ("today", "on")):
        if gui._sel_vars.get(_key) is not None:
            gui._sel_vars[_key].set(_val)
    gui._apply_theme()
    hot = [str(w.cget("text")) for w in _walk(root)
           if w.winfo_class() == "Label"
           and ("看快捷键" in str(w.cget("text")) or "F5 重读" in str(w.cget("text")))]
    assert hot == [], "主窗口还有常驻快捷键提示：%r" % hot
    tvs = [str(w.cget("textvariable")) for w in _walk(root)
           if w.winfo_class() == "Label" and str(w.cget("textvariable"))]
    assert str(gui.var_count) in tvs, "计数行被误删了"
    assert str(gui.var_msg) in tvs, "消息提示行（v9 在第一行最右端）被误删了"
    print("(k) 主窗口无常驻快捷键提示行（只在 ? 一览里）；计数行 / 消息提示行仍在 ✓")

    # --- v26 闸门 (oo)：自定义快捷键（第三项菜单 / 弹窗 / 改键真生效 / 顶掉 / 拒绝 / 恢复默认 /
    #     配置往返 / `?` 一览与浮层跟随）。口径 2026-10-06 用户拍板：可改范围 = 常用操作键（导航键固定）｜
    #     一览跟着当前键显示 ｜ 撞键 = **顶掉对方**（被顶的变「未绑定」）。
    # v40：快捷键设置搬进设置界面「快捷键设置」块（菜单栏整条删除）—— Ctrl+3 定位过去
    gui.open_settings_section("keys")
    root.update()
    assert gui._in_settings() and gui.set_panel == "keys" and gui.key_tv is not None, \
        "Ctrl+3 该开设置界面并定位「快捷键设置」块"
    # v38：选中提示 = 行上高亮（列表挂了主题画笔）；底部提示行整行删除、改键反馈走消息行
    assert gui.key_tv in gui._row_borders, "v38：快捷键表该挂上「选中行边框」画笔"
    assert not hasattr(gui, "key_lbl"), "v38：设置窗底部提示行该已删除"
    print("(oo-1) v40：快捷键设置 = 设置界面「%s」块（Ctrl+3 定位；独立弹窗 + key_win 已删）；"
          "v38：选中提示挂在行上（画笔已挂）、底部提示行已删 ✓" % KEY_DIALOG_TITLE)
    rows = gui.key_tv.get_children()
    assert len(rows) == len(KEY_ACTIONS), len(rows)
    for iid in rows:                             # 没改过 → 键1 == 默认键、键2 = 未绑定（v74）
        v = gui.key_tv.item(iid, "values")
        assert v[1] == pretty_seq(DEFAULT_KEYMAP[iid]) and v[2] == "未绑定", (iid, v)
    assert gui.key_tv.selection() and gui.key_tv.selection()[0] == KEY_ACTIONS[0][0], \
        "v26.1：开窗就该选中第一行（焦点看得见）"
    # v68：搜索键两列都显示大写 F；「操作」列 = 名字 + 空格 + 点线（用户口径「虚线连接」）
    v_search = gui.key_tv.item("search", "values")
    assert v_search[1] == "F" and v_search[2] == "未绑定", v_search   # v74：键2 默认未绑定
    assert "·" in v_search[0] and v_search[0].startswith("跳到搜索框 "), \
        "v68：操作列该是「名字 + 空格 + 点线」：%r" % (v_search[0],)
    # v68：树上的「跳到搜索框」大小写两种写法都绑着（F / f 都进框 —— 真按键在 (c) 段再走一遍）
    assert set(gui._seqs_for("search")) == {"<Key-f>", "<Key-F>"}, gui._seqs_for("search")
    assert gui.tree.bind("<Key-f>") != "" and gui.tree.bind("<Key-F>") != "", "v68：f / F 都该挂上"

    class _Ev(object):                           # 喂「按键事件」（捕获只读 keysym / state）
        def __init__(self, ks, st=0):
            self.keysym, self.state, self.widget = ks, st, None

    # v26.1：全键盘 —— 回车进改键 / Esc 退 / Tab 焦点环 / Delete 恢复默认项
    gui._key_dialog_key(_Ev("Return"))           # 正常模式：回车 = 开始改键（两步手势的第一步）
    assert gui.key_capture, "回车该进入改键状态"
    gui._key_dialog_key(_Ev("Escape"))           # Esc = 取消改键
    assert not gui.key_capture
    # v40：原弹窗的「两站焦点环」整组删除 —— Tab 交给 Tk 默认遍历（设置界面里挨个控件走）
    assert not hasattr(gui, "_key_dialog_ring") and not hasattr(gui, "_key_dialog_tab"), \
        "v40：原弹窗焦点环该整组删除"
    gui.key_tv.focus_set()
    root.update()
    assert root.focus_get() is gui.key_tv, "先把焦点摆到快捷键表上：%r" % root.focus_get()
    gui._rotate_focus(1)
    root.update()
    assert root.focus_get() is not None and root.focus_get() is not gui.key_tv, \
        "v40：设置界面里 Tab 该走 Tk 默认环（焦点挪到下件控件）：%r" % root.focus_get()
    gui.key_tv.focus_set()
    root.update()
    gui.keymap_assign("redo", "<Control-F4>")    # 先改一个，验证 Delete 能还原
    gui.key_tv.selection_set("redo")
    gui._key_op_reset()                           # v57.3：Delete 收编成注册表操作（key_reset）
    assert gui.keymap["redo"] == "<Control-y>", "Delete 该把选中项恢复默认"
    assert root.bind("<Control-F4>") == ""

    # v74：键2（替代键）全流程 —— ← / → 切列（表头 ●）、回车改“当前列”、两键都真挂上、
    #      跨池顶掉、Delete 整项恢复默认（键2 清空）；段尾回默认现场（后面接着走 Ctrl+Z 那步）
    gui._key_col = 0                             # 造前提（前面 (vv40) 的 ← / → 真按键测试动过它）
    gui._key_col_mark()
    assert "●" in gui.key_tv.heading("k1")["text"] and "●" not in gui.key_tv.heading("k2")["text"], \
        (gui.key_tv.heading("k1")["text"], gui.key_tv.heading("k2")["text"])
    gui._key_col_move(1)
    assert gui._key_col == 1 and "●" in gui.key_tv.heading("k2")["text"], "→ 该切到键2"
    gui._key_col_move(1)
    assert gui._key_col == 1, "键2 上再按 → 该停原地"
    gui._key_col_move(-1)
    assert gui._key_col == 0 and "●" in gui.key_tv.heading("k1")["text"], "← 该切回键1"
    gui._key_col_move(-1)
    root.update()
    assert root.focus_get() is gui.set_left, \
        "键1 上再按 ← 该回左列表（层级退）：%r" % (root.focus_get(),)
    gui.key_tv.focus_set()
    root.update()
    gui._key_col = 1
    gui.key_tv.selection_set("search")
    gui.key_tv.focus("search")
    gui._key_capture_start()
    assert gui.key_capture and "键2" in gui.var_msg.get(), \
        "捕获提示该报「键2」：%s" % gui.var_msg.get()
    gui._key_dialog_key(_Ev("g", 0))
    assert gui.keymap2["search"] == "<Key-g>" and gui.keymap["search"] == "<Key-F>", \
        "键2 改键不该动键1：(键2=%r，键1=%r)" % (gui.keymap2["search"], gui.keymap["search"])
    assert gui.key_tv.item("search", "values")[1:3] == ("F", "g"), \
        gui.key_tv.item("search", "values")
    assert set(gui._seqs_for("search")) == {"<Key-f>", "<Key-F>", "<Key-g>", "<Key-G>"}, \
        "v74：两键（带变体）都进挂点清单：%r" % (gui._seqs_for("search"),)
    assert gui.tree.bind("<Key-g>") != "", "键2 该真挂到树上"
    gui._key_col = 0
    assert gui.keymap_assign("redo", "<Control-i>", 1)
    assert gui.keymap_assign("undo", "<Control-i>", 1)
    assert gui.keymap2["undo"] == "<Control-i>" and gui.keymap2["redo"] is None, \
        "v74：键2 撞键2 —— 后设的顶掉先设的"
    assert gui.keymap_assign("cancel", "<Control-z>", 1)   # 此刻 undo 键1 还是默认 Ctrl+Z
    assert gui.keymap["undo"] is None and gui.keymap2["cancel"] == "<Control-z>", \
        "v74：键2 该能顶掉别家键1"
    gui.key_tv.selection_set("search")
    gui.key_tv.focus("search")
    gui._key_op_reset()
    assert gui.keymap["search"] == "<Key-F>" and gui.keymap2["search"] is None, \
        "v74：此项恢复默认 = 键1 回默认 + 键2 清空"
    gui._key_reset_all()                          # v74 段收尾：键2 全清、键1 全回默认（下面从默认现场继续）
    assert gui._key_col == 0
    print("(oo-2b) v74 键2（替代键）：← / → 切列（表头 ●）· 回车改当前列 · 两键都真挂上 · "
          "跨池顶掉（键2 撞键2 / 键2 顶键1）· Delete 整项恢复默认（键2 一并清空）✓")

    gui.key_tv.selection_set("undo")
    gui._key_capture_start()
    assert gui.key_capture, "该进入等按键状态"
    gui._key_dialog_key(_Ev("Shift_L", 0x1))     # 纯修饰键：不收，继续等
    assert gui.key_capture and gui.keymap["undo"] == "<Control-z>"
    gui._key_dialog_key(_Ev("u", 0x4))           # 捕获 Ctrl+U
    assert not gui.key_capture
    assert gui.keymap["undo"] == "<Control-u>", gui.keymap["undo"]
    assert root.bind("<Control-z>") == "" and root.bind("<Control-u>") != "", \
        "改键该撤旧挂新（Ctrl+Z 撤掉、Ctrl+U 生效）"
    assert gui.key_tv.item("undo", "values")[1] == "Ctrl+U", gui.key_tv.item("undo", "values")
    gui.leave_settings()                         # v40：下面回到主界面口径（Ctrl+U 真按键要生效）
    root.update()
    gui._undo_stack.clear()                      # 改完的键真能用：Ctrl+U 撤销空栈 → 底部提示
    gui.tree.focus_force()
    root.update()
    gui.tree.event_generate("<KeyPress>", keysym="u", state=0x4)
    root.update()
    assert gui.var_msg.get() == "没有可撤销的改动", gui.var_msg.get()
    print("(oo-2) 快捷键表 %d 行、摆出来就选中第一行、键1 == 默认键 / 键2 = 未绑定（v74）；全键盘"
          "（回车 = 改键 / Esc = 退 / Tab 焦点环 / Delete = 恢复默认项）✓；捕获 Ctrl+U 覆盖「撤销」"
          "并**真生效**（旧键 Ctrl+Z 已撤、新键按下去走撤销）✓" % len(rows))

    # ② 顶掉：把「复原」也设成 Ctrl+U →「撤销」变未绑定（用户口径：撞键 = 顶掉对方）
    gui.key_tv.selection_set("redo")
    gui._key_capture_start()
    gui._key_dialog_key(_Ev("u", 0x4))
    assert gui.keymap["redo"] == "<Control-u>" and gui.keymap["undo"] is None, gui.keymap
    assert gui.key_tv.item("undo", "values")[1] == "未绑定", gui.key_tv.item("undo", "values")
    assert "顶掉" in gui.var_msg.get(), gui.var_msg.get()   # v38：提示走主窗消息行（原 key_lbl 已删）
    print("(oo-3) 顶掉：「复原」拿走 Ctrl+U →「撤销」变未绑定（原来那个键真被撤下来）✓")

    # ③ 保留键 / 根级规则：↑ 拒（固定键位；v65 起 Tab 成了 focus_next 的主键、不再保留）、
    #    光秃秃的 u 给根级操作也拒；**v80（捕获锁）：被拒 = 保持捕获**（用户接着按，不用再回车）
    gui.key_tv.selection_set("reload")
    gui._key_capture_start()
    gui._key_dialog_key(_Ev("Up", 0))
    assert gui.keymap["reload"] == "<F5>" and gui.key_capture, \
        "v80：被拒的键不落键、也不退出捕获：cap=%r" % gui.key_capture
    assert "固定键位" in gui.var_msg.get(), gui.var_msg.get()   # v38：提示走主窗消息行
    # v80：Tab 家族（Tab / Shift+Tab / Ctrl+Tab）= 界面导航键 —— 吞掉、保持捕获，
    #      不许把「焦点轮换 / 设置界面」的键顶掉（用户实测「乱」的两个来源）
    gui._key_dialog_key(_Ev("Tab", 0))
    assert gui.key_capture and gui.keymap["focus_next"] == "<Tab>", \
        "v80：捕获中 Tab 该被吞（不顶「焦点轮换」）：cap=%r" % gui.key_capture
    gui._key_dialog_key(_Ev("Tab", 0x4))
    assert gui.key_capture and gui.keymap["settings"] == "<Key-question>", \
        "v80：捕获中 Ctrl+Tab 该被吞（不顶「设置界面」开关；v87 起其默认键 = ?）"
    gui._key_dialog_key(_Ev("Escape", 0))        # 出口：Esc 取消捕获
    assert not gui.key_capture
    gui.key_tv.selection_set("reload")
    gui._key_capture_start()
    gui._key_dialog_key(_Ev("u", 0))             # 根级操作不给 Ctrl/Alt → 拒（同样保持捕获）
    assert gui.keymap["reload"] == "<F5>" and gui.key_capture
    assert "Ctrl / Alt" in gui.var_msg.get(), gui.var_msg.get()   # v38：提示走主窗消息行
    gui.key_tv.selection_set("status_1")         # 树级操作可以收光键（不受根级规则管）
    gui._key_capture_start()                     # （捕获本来还开着，重开一次幂等）
    gui._key_dialog_key(_Ev("q", 0))
    assert gui.keymap["status_1"] == "<Key-q>" and not gui.key_capture, \
        "v80：绑定成功才退出捕获：%r" % gui.keymap["status_1"]
    print("(oo-4) 保留键拒绝（方向键 = 固定键位；被拒保持捕获）· Tab 家族捕获中吞掉（v80）· "
          "根级操作强制带 Ctrl / Alt；树级操作（改状态）收光键 ✓")

    # --- v80：设置页键盘修复批（用户 2026-10-07 点名）—— ① Tab = 两站环「左列表 ⇄ 当前面板」
    #     （v40 的 Tk 默认环会让 Tab 一颗一颗过 23 颗单选钮，瘦身）② WASD 也挂设置页
    #     ③ 设置页边框 = 主题相反色 ④ 捕获锁在 (oo-4) 段已验
    gui.enter_settings()
    gui.show_set_panel("keys")
    gui.set_left.focus_force()
    root.update()
    gui.set_left.event_generate("<KeyPress>", keysym="Tab")
    root.update()
    assert root.focus_get() is gui.key_tv, "v80：Tab 该从左列表进面板：%r" % (root.focus_get(),)
    gui.key_tv.event_generate("<KeyPress>", keysym="Tab")
    root.update()
    assert root.focus_get() is gui.set_left, "v80：Tab 该从面板回左列表：%r" % (root.focus_get(),)
    gui.show_set_panel("theme")
    gui.set_left.focus_force()
    root.update()
    gui.set_left.event_generate("<KeyPress>", keysym="Tab")
    root.update()
    assert root.focus_get() in gui._set_focus["theme"], \
        "v80：Tab 进主题面板该直落单选钮（不走 Tk 环）：%r" % (root.focus_get(),)
    gui.set_left.event_generate("<KeyPress>", keysym="Tab")     # 站在主题钮上再 Tab
    root.update()
    assert root.focus_get() is gui.set_left, "v80：主题钮上 Tab 该回左列表"
    # WASD：设置页各处都挂（v87 起含一览文本）；捕获中 W = 新键候选（不转方向键）
    assert gui.set_left.bind("<Key-w>") != "" and gui.key_tv.bind("<Key-w>") != "" \
        and gui.help_tx.bind("<Key-w>") != "" \
        and all(rb.bind("<Key-w>") != "" for gk in gui._set_group_order
                for rb in gui._set_groups[gk]), "v80/v87：设置页控件都该挂 WASD"
    gui.show_set_panel("keys")
    gui._set_focus_panel()
    gui._key_col = 0
    gui.key_tv.selection_set("status_2")
    gui.key_tv.focus("status_2")
    root.update()
    gui._key_capture_start()
    gui.key_tv.event_generate("<KeyPress>", keysym="w")
    root.update()
    assert not gui.key_capture and gui.keymap["status_2"] == "<Key-w>", \
        "v80：捕获中 W 该当新键（不是转成方向键）：%r / cap=%r" % (
            gui.keymap["status_2"], gui.key_capture)
    gui.keymap_assign("status_2", DEFAULT_KEYMAP["status_2"])   # 现场还原（键1 回 <Key-2>）
    # 边框 = 主题相反色：浅色 → 黑；黑夜模式 → 白（左列表 / 表 / 主题钮焦点框一起跟）
    # （断言画笔的**目标线色** `line`：失焦档另有淡色 line_blur，属既有机制、不在这里验）
    assert not gui._ui_dark() and gui._set_page_edge_bg() == "#000000"
    gui._set_page_border()
    assert str(gui._row_borders[gui.set_left].line).upper() == "#000000", \
        "v80：浅色界面设置页框线该是黑的：%r" % gui._row_borders[gui.set_left].line
    _dn0 = gui.theme_daynight
    gui.theme_daynight = THEME_DAYNIGHT_NIGHT
    gui._set_page_border()
    assert str(gui._row_borders[gui.set_left].line).upper() == "#FFFFFF", \
        "v80：黑夜模式设置页框该反白：%r" % gui._row_borders[gui.set_left].line
    assert str(gui._row_borders[gui.key_tv].line).upper() == "#FFFFFF"
    gui.show_set_panel("theme")                          # 面板摆出来才能聚焦（unmapped 不收焦点）
    _focusrb = gui._set_groups["selb"][0]
    _focusrb.focus_force()
    root.update()
    assert str(_focusrb.master.master.cget("bg")).upper() == "#FFFFFF", \
        "v80：黑夜模式主题钮焦点框该反白：%r" % _focusrb.master.master.cget("bg")
    gui.theme_daynight = _dn0                            # 还原白天 + 框色回黑
    gui._set_page_border()
    root.update()
    assert str(_focusrb.master.master.cget("bg")).upper() == "#000000", \
        "v80：切回白天该把亮着的焦点框改回黑"
    gui.leave_settings()
    root.update()
    print("(vv80) 设置页键盘（v80）：Tab 两站环（左列表 ⇄ 面板；主题块直落单选钮，不再一颗颗过）· "
          "WASD 挂左列表 / 表 / 全部单选钮（捕获中 W = 新键）· 边框 = 主题相反色（黑夜反白 / "
          "白天回黑）✓")

    # --- v82 闸门 (vv82)：① 深色滚动条样式名能解析（ttk 竖向滚动条拼 "Vertical." 前缀查布局）
    #     ② 退出设置页时的焦点位置被记住（左列表 / 快捷键表 / 主题块三站）---
    _sb82 = ttk.Scrollbar(root, orient="vertical")
    _err82 = None
    try:
        _sb82.configure(style="Dark.VScrollbar")
    except tk.TclError as _e:
        _err82 = _e
    assert _err82 is None and str(_sb82.cget("style")) == "Dark.VScrollbar", \
        "v82：深色滚动条样式名要能落到竖向滚动条上（改名前报 Layout Vertical.Dark.VScrollbar " \
        "not found）：%r" % (_err82,)
    assert ttk.Style(root).layout("Vertical.Dark.VScrollbar"), \
        "v82：派生样式要继承默认布局（Vertical.TScrollbar）"
    _sb82.destroy()
    _p82, _sel82 = gui.set_panel, gui.set_left.selection()
    gui.enter_settings()
    root.update()
    assert root.focus_get() is gui.set_left, \
        "v82：前提/默认口径：没记过焦点时进设置落左列表：%r" % (root.focus_get(),)
    gui._set_focus_panel()                       # 进面板（快捷键块 = 键表）
    root.update()
    assert gui._set_focus_mem == "keys" and root.focus_get() is gui.key_tv, \
        "v82：焦点站该记成 keys：%r / %r" % (gui._set_focus_mem, root.focus_get())
    gui.exit_settings()
    root.update()
    gui.enter_settings()
    root.update()
    assert root.focus_get() is gui.key_tv, \
        "v82：再进设置该落回上次那一站（快捷键表）：%r" % (root.focus_get(),)
    gui.set_left.selection_set("theme")
    gui.show_set_panel("theme")
    root.update()
    gui._set_focus_panel()
    root.update()
    _rb82 = gui._theme_focus_target()
    assert gui._set_focus_mem == "theme" and root.focus_get() is _rb82, \
        "v82：主题站的落点该是上次那颗钮：%r / %r" % (gui._set_focus_mem, root.focus_get())
    assert gui._set_focus_key() == "theme" and gui._set_block_key() == "theme", \
        "v82：写配置的两值：%r / %r" % (gui._set_focus_key(), gui._set_block_key())
    gui.exit_settings()
    root.update()
    gui.enter_settings()
    root.update()
    assert root.focus_get() is _rb82, \
        "v82：主题站也要落回上次那颗钮：%r" % (root.focus_get(),)
    gui.exit_settings()                          # 还原现场：摆回原来那块 + 选回原来那项
    root.update()
    if _sel82:
        gui.set_left.selection_set(_sel82[0])
    gui.show_set_panel(_p82)
    gui._set_focus_mem = None
    root.update()
    # v88：本地原本挂着 v82c 的「列间竖线 z 序」检查 —— 竖线已整条去掉，那段删

    print("(vv82) 深色滚动条样式名可解析（Vertical.Dark.VScrollbar + 继承布局）· "
          "设置页焦点记忆：键表站 / 主题站（落回那颗钮）各自进出往返 ✓")

    # ④ 浮层跟随：status_1 = q → 浮层里 q 直选第 1 项（数字 1 已被顶掉）
    iid0 = gui.tree.get_children()[0]
    gui.tree.selection_set(iid0)
    gui.tree.focus(iid0)
    gui.open_status_popup(gui.row_by_iid(iid0), gui.tree)
    root.update()
    assert gui.popup_lb is not None
    assert gui.popup_lb.bind("<Key-q>") != "" and gui.popup_lb.bind("<Key-1>") == "", \
        ("浮层该跟着自定义键（q 直选第 1 项、数字 1 已顶掉）",
         gui.popup_lb.bind("<Key-q>"), gui.popup_lb.bind("<Key-1>"))
    assert gui.popup_lb.bind("<Return>") != "", "浮层里回车永远是确认（固定）"
    gui.close_popup()
    root.update()

    # ④b v26.1 / v26.4 / v37 / v53 / **v65**：菜单热键 —— v37 删 Ctrl+2、v53 删 Ctrl+1；
    #    v65 把这两个键**重新启用**为「直达看板 / 统计页」（旧用途 menu_pack / menu_theme 仍整个删掉）
    assert root.bind("<Control-Key-1>") != "", "v65：Ctrl+1 = 直达看板（该挂上）"
    assert root.bind("<Control-Key-3>") != "", "菜单热键该挂上（Ctrl+3）"
    assert root.bind("<Control-Key-2>") != "", "v65：Ctrl+2 = 直达统计页（该挂上）"
    assert "menu_pack" not in gui.keymap, "v53：menu_pack 动作该整个删掉"
    assert gui.keymap["menu_keys"] == "<Control-Key-3>"
    assert "menu_theme" not in gui.keymap, "v37：menu_theme 动作该整个删掉"
    # v26.2 / v26.3 回归（用户实测 bug：带 Ctrl 的数字在树上被「数字直改」吞掉）：
    #   v53：原用 Ctrl+1 验 —— 它删了，改用还在的 Ctrl+3（树上同样挂着 `<Key-3>` 数字直改）。
    #   ① 树级直接命中：树上按 Ctrl+3 → 更具体的 `<Control-Key-3>` 在**控件级**就赢、数字直改不跑；
    #   ② 让位规则：带 Ctrl / Alt 的数字**直接调用**验 —— `return None` 让位、光数字照旧 `"break"`。
    #   （⚠️ ① 必须把**树级 + root 两处**处理器都换成 spy：树级返回 None 后事件会继续冒到 root；
    #     合成事件在负载下还会抖，② 因此改成纯直调。）
    _iidt = gui.tree.get_children()[0]
    gui.tree.selection_set(_iidt)
    gui.tree.focus_force()
    root.update()
    _st0 = gui.row_by_iid(_iidt)["状态"]
    _hitc = {"n": 0}
    gui.tree.bind("<Control-Key-3>", lambda e: _hitc.__setitem__("n", _hitc["n"] + 1))
    root.bind("<Control-Key-3>", lambda e: None)   # root 备用位点也换空转：树级返回 None 后事件会冒上去
    gui.tree.event_generate("<KeyPress>", keysym="3", state=0x4)
    root.update()
    assert _hitc["n"] == 1, "树上按 Ctrl+3 该在树级命中菜单热键（被数字键吞掉 = 那个 bug）"
    assert gui.row_by_iid(_iidt)["状态"] == _st0, "Ctrl+3 不该改状态"
    # ②「让位」规则用**直接调用**验（合成事件的链式行为在负载下会抖 —— 别依赖它）：
    #   带 Ctrl / Alt 的数字必须 return None（让位）、光数字照旧走原路（返回 "break"）。
    #   i=6 越界 → 两次调用都不会真写状态，纯查返回值。
    class _EvS(object):
        def __init__(self, st):
            self.keysym, self.state, self.widget = "1", st, None
    assert gui._on_digit_key(6, gui.tree, _EvS(0x4)) is None, "带 Ctrl 的数字要「让位」（None、不 break）"
    assert gui._on_digit_key(6, gui.tree, _EvS(0)) == "break", "光数字照旧走原路（break）"
    gui._apply_keys()                             # 还原（撤 spy、挂回正式绑定）
    assert gui.tree.bind("<Control-Key-3>") != "" and gui.today_tree.bind("<Control-Key-3>") != "", \
        "v26.3：菜单热键要挂在四棵树上（更具体、压过数字直改）"
    gui.leave_settings()                         # v40：出去 = 设置界面整块收起（不再是关弹窗）
    root.update()
    assert not gui._in_settings() and gui.main_frame.winfo_manager() == "pack"
    assert gui.key_tv is not None and gui.key_tv in gui._row_borders, \
        "v40：快捷键表常驻设置界面（画笔不再随开窗 / 关窗摘挂）"
    gui._on_menu_hotkey("keys")                  # = 按下 Ctrl+3
    root.update()
    assert gui._in_settings() and gui.set_panel == "keys", "Ctrl+3 该开设置界面并定位到快捷键块"
    assert gui.keymap_assign("menu_keys", "<Control-F3>")   # 可改：换个带 Ctrl 的键
    assert root.bind("<Control-Key-3>") == "" and root.bind("<Control-F3>") != "", "改键该真换绑"
    gui._key_reset_all()
    assert gui.keymap["menu_keys"] == "<Control-Key-3>" and root.bind("<Control-Key-3>") != ""
    print("(oo-4b) 菜单热键 v26.1/v26.4/v37/v53：Ctrl+3 进列表可改（改完真换绑）、直接动作"
          "（Ctrl+3 → 设置界面 · 快捷键设置）；Ctrl+2 / Ctrl+1 已删（都不绑任何键）；"
          "「带 Ctrl 的数字不被数字直改吞」回归改用 Ctrl+3 ✓")

    # ⑤ 一览跟随（v87：独立弹窗并进设置页 —— 改看「快捷键一览」块）：改过 undo → 那行现渲染；行数不变
    gui.set_left.selection_set("help")
    gui.show_set_panel("help")
    root.update()
    gui.keymap_assign("undo", "<Control-u>")     # 块摆着时改键 → 当场重刷（原「一览开着时跟随」的落点）
    root.update()
    ht = gui.help_tx.get("1.0", "end-1c")
    assert "Ctrl+U" in ht and "Ctrl+Z" not in ht, ht.splitlines()[13]   # v65：Backspace 行插入后 +1
    assert len(ht.splitlines()) == len(KEY_TABLE.splitlines())
    print("(oo-5) 浮层数字直选 / 回车确认跟着自定义键；一览块现渲染（Ctrl+U 顶掉 Ctrl+Z、行数不变）✓")

    # ⑥ 配置往返：只存差量（含 None = 未绑定）；脏条目（认不出的 id / 保留键 / 非法写法）洗净
    cfk = os.path.join(tmpdir, "key_cfg.json")
    save_config(cfk, {"geometry": "", "keys": {"undo": "<Control-u>", "redo": None},
                      "keys2": {"redo": "<Control-i>"}})          # v74：键2 差量
    gotk = load_config(cfk)
    assert gotk["keys"] == {"undo": "<Control-u>", "redo": None}, gotk["keys"]
    assert gotk["keys2"] == {"redo": "<Control-i>"}, gotk["keys2"]
    kmx = resolve_keymap(gotk["keys"])
    assert kmx["undo"] == "<Control-u>" and kmx["redo"] is None \
        and kmx["search"] == "<Key-F>"           # v32.3：搜索键改裸 F（v68：默认写法改大写）
    kmx2 = resolve_keymap2(gotk["keys2"], kmx)                    # v74：键2 解析
    assert kmx2["redo"] == "<Control-i>" and kmx2["undo"] is None, kmx2
    save_config(cfk, {"geometry": "",
                      "keys": {"不认识": "<F2>", "undo": "<Tab>",
                               "redo": "乱写", "reload": "<Key-u>"},
                      "keys2": {"不认识": "<F2>", "reload": "<Key-u>", "undo": "乱写"}})
    gotk = load_config(cfk)
    assert gotk["keys"] == {}, "脏条目该被洗掉（含根级规则的漏网之鱼）：%r" % (gotk["keys"],)
    assert gotk["keys2"] == {}, "v74：键2 脏条目同样洗净：%r" % (gotk["keys2"],)
    print("(oo-6) 配置往返：只存差量（含 None = 未绑定；v74 键2 只存有值的）；脏条目写不进也读不回"
          "（认不出的 id / 保留键 / 非法写法 / 根级裸键）✓")

    # ⑥b v57.3：两个「恢复默认」的快捷键（真按键）—— Delete = 此项、Ctrl+Shift+Delete = 全部
    assert gui.keymap["key_reset"] == "<Delete>"
    assert gui.keymap["key_reset_all"] == "<Control-Shift-Delete>"
    gui.keymap_assign("undo", "<Control-u>")     # 制造一个差异
    gui.key_tv.focus_force()
    gui.key_tv.selection_set("undo")
    gui.key_tv.focus("undo")
    root.update()
    gui.key_tv.event_generate("<KeyPress>", keysym="Delete")
    root.update()
    assert gui.keymap["undo"] == "<Control-z>", \
        "v57.3：表上按 Delete 该把选中行恢复默认：%r" % (gui.keymap["undo"],)
    gui.keymap_assign("undo", "<Control-u>")
    gui.keymap_assign("redo", "<Control-i>")
    gui.key_tv.focus_force()
    root.update()
    gui.key_tv.event_generate("<KeyPress>", keysym="Delete", state=0x5)   # Ctrl(4)+Shift(1)
    root.update()
    assert gui.keymap == DEFAULT_KEYMAP, \
        "v57.3：表上按 Ctrl+Shift+Delete 该全部恢复默认：%r" % (
            [k for k, v in gui.keymap.items() if v != DEFAULT_KEYMAP[k]],)
    # ⑦ 恢复默认（全部）→ 一切回默认、旧绑定回来（后面的老闸门按默认口径继续）
    gui._key_reset_all()
    assert gui.keymap == DEFAULT_KEYMAP
    assert set(gui.keymap2.values()) == {None}, "v74：全部恢复默认该把键2 也全清"
    assert root.bind("<Control-z>") != "" and root.bind("<Control-u>") == ""
    assert gui.key_tv.item("undo", "values")[1] == "Ctrl+Z"
    assert help_text_for(gui.keymap) == KEY_TABLE
    gui.leave_settings()
    root.update()
    assert not gui._in_settings(), "v40：收尾该回主界面（后面的老闸门按主界面口径继续）"
    print("(oo-7) 全部恢复默认：map 回默认、Ctrl+Z 挂回 / Ctrl+U 撤掉、一览回到默认逐字、"
          "设置界面已退回主界面 ✓")

    # --- v7 闸门 (z)：页签栏整条隐藏 —— 客户端区贴顶 + nb.select() 语义照旧
    #     （改之前这个差 = 48px = 页签高度；负向探针见交付说明。）
    root.update()
    tab_gap = gui.tab_all.winfo_rooty() - gui.nb.winfo_rooty()
    assert tab_gap <= 4, \
        "Notebook 标签区还在：客户端区距 nb 顶 %d px（页签高度约 48px）" % tab_gap
    gui.nb.select(0)
    root.update()
    assert gui.nb.index(gui.nb.select()) == 0 and gui.tab_all.winfo_ismapped() \
        and not gui.tab_today.winfo_ismapped(), "nb.select(0) 后可见的该是总表页"
    gui.nb.select(1)
    root.update()
    assert gui.nb.index(gui.nb.select()) == 1 and gui.tab_today.winfo_ismapped() \
        and not gui.tab_all.winfo_ismapped(), "nb.select(1) 后可见的该是看板页"
    gui.nb.select(0)
    root.update()
    print("(z) 页签栏整条隐藏：客户端区距 nb 顶 %d px（≤4；改前 48px = 页签高度）；"
          "nb.select(0)/select(1) 照旧切页（可见的是对应 frame）✓" % tab_gap)

    # --- v7 闸门 (aa)：界面上没有「提示括号」（主窗口 Label / Entry 的文案 + 两棵树的单元格）
    BANNED = ("（场次", "（卡住", "（筛选显示", "（无匹配", "（无）", "← / → 换段")
    seen_txt = []
    for w in _walk(root):                        # Toplevel（? 一览 / 浮层）不在 _walk 里
        try:
            if w.winfo_class() == "Label":
                seen_txt.append(str(w.cget("text")))
            tv = str(w.cget("textvariable"))
        except tk.TclError:
            tv = ""
        if tv:                                   # textvariable 的那几个（计数行 / 消息行）要按「值」查
            try:
                seen_txt.append(str(root.getvar(tv)))
            except tk.TclError:
                pass
    for tr in (gui.tree, gui.today_tree):
        for iid in tr.get_children():
            seen_txt.extend(str(v) for v in tr.item(iid, "values"))
    hit = sorted(set(s for s in seen_txt for b in BANNED if b in s))
    assert hit == [], "界面上还有提示括号：%r" % hit
    print("(aa) 界面上没有提示括号：扫了 %d 段文案（Label / 计数行 / 消息行 / 两棵树的单元格），"
          "%d 个禁用子串 %s 一个都没命中 ✓" % (len(seen_txt), len(BANNED), "/".join(BANNED)))

    # --- v7 闸门 (bb)：看板类标题行 / 搜索标签的文案定死（v15：标签插了全角空格；v29：卡片 → 标题行）
    cap2 = gui.today_tree.item(SEG_PREFIX + "1", "values")[0]
    sea = gui.lbl_search.cget("text")
    assert cap2 == "待补题 · %d" % len(segment_rows(gui.rows, 1)), cap2
    assert sea == "搜" + LABEL_PAD + "索", sea
    print("(bb) 看板「待补题」类标题行 = %r；搜索标签 = %r ✓" % (cap2, sea))

    # --- v7 闸门 (cc) 已随「状态筛选」整块删除（下拉框没了，样式断言无处可测）——
    #     替代断言 = (ii)：窗口里遍历不到 TCombobox / 没有 var_filter / cmb_filter / F 键。

    # --- v8 闸门 (dd)~(ff)：输入法守卫 —— 只有搜索框收中文，别处一律摘掉
    #     断言里查 ImmGetContext 一律走 ctypes.windll.imm32；判「有没有挂」用 is None（不跟 0/False 比）。
    root.update()
    imm_ok = False
    try:
        _imm = ctypes.windll.imm32
        _imm.ImmGetContext.restype = ctypes.c_void_p
        _imm.ImmGetContext.argtypes = [ctypes.c_void_p]
        imm_ok = True
    except Exception as e:
        print("(dd)~(ff) ★ 跳过：拿不到 imm32（%s）" % e)

    def _hctx(w):
        return _imm.ImmGetContext(ctypes.c_void_p(w.winfo_id()))

    if not imm_ok:
        print("(dd)~(ff) ★ 跳过：拿不到 imm32 —— 不假装通过")
    else:
        # 「跳不跳」要独立量一次：新造一个没被守卫碰过的控件，它的上下文 = 线程默认；
        # 只有它也是 None（系统根本没有输入法环境）才允许跳过 —— 「守卫自己没跑」不在此列。
        probe_w = tk.Frame(root)
        probe_w.update_idletasks()
        default_seen = _hctx(probe_w)
        probe_w.destroy()
        if default_seen is None:
            print("(dd)~(ff) ★ 跳过：系统没有输入法上下文（新控件 ImmGetContext 也是 None）"
                  "—— 不假装通过")
        else:
            assert gui.ime.available, "imm32 拿得到、守卫就该是可用的"
            assert gui.ime.default_ctx is not None, "守卫没在窗口建好时取到默认上下文（install 没跑？）"
            assert _hctx(gui.tree) is None, "总表树的输入法没摘掉：%r" % (_hctx(gui.tree),)
            assert _hctx(gui.today_tree) is None, "看板清单的输入法没摘掉：%r" % (_hctx(gui.today_tree),)
            print("(dd) 建好窗口后输入法已摘：总表树 / 看板清单 ImmGetContext 都是 None ✓")
            gui.ent_search.focus_set()
            root.update()
            assert _hctx(gui.ent_search) is not None, "搜索框里中文要能打（ImmGetContext 不该是 None）"
            print("(ee) 焦点进搜索框：搜索框 ImmGetContext=%r（非 None，中文打得出来）✓"
                  % (_hctx(gui.ent_search),))
            gui.tree.focus_set()
            root.update()
            assert _hctx(gui.ent_search) is None, "离开搜索框后输入法该立刻摘掉"
            print("(ff) 焦点回总表树：搜索框 ImmGetContext=None（离开就摘）✓")

    # --- v8 闸门 (gg)：守卫不可用时（非 Windows / 拿不到 imm32）整条路是 no-op，不许抛异常
    g8 = gui.ime
    was_avail, was_imm = g8.available, g8._imm
    ctx8 = _hctx(gui.ent_search) if imm_ok else None
    calls8 = []

    class _Spy8(object):                 # 假 imm32：被碰到就记一笔（不可用时一个都不该来）
        def ImmGetContext(self, *a):
            calls8.append("ImmGetContext")
            return None

        def ImmAssociateContext(self, *a):
            calls8.append("ImmAssociateContext")
            return None

    g8.available = False                 # 临时置假：模拟「非 Windows / 拿不到 imm32」
    g8._imm = _Spy8()
    for w in (gui.tree, gui.today_tree, gui.ent_search, root, None):
        g8.detach(w)                     # 一律 no-op，不许抛异常
        g8.attach(w)
    g8.on_focus_in()
    g8.detach_tree(root)
    g8.watch(root)
    g8.install()
    g8.available, g8._imm = was_avail, was_imm       # 还原：后面还要真用
    assert calls8 == [], "不可用时不该碰 imm32（%d 次：%r）" % (len(calls8), calls8)
    assert gui.tree.winfo_exists() and gui.ent_search.winfo_exists(), "窗口该照常可用"
    gui.refresh_view()
    assert gui.tree.get_children(), "窗口照常可用（重绘后总表里有行）"
    if imm_ok:
        assert _hctx(gui.ent_search) == ctx8, "不可用时不许动输入法状态（no-op）"
    print("(gg) 守卫置假：attach / detach / on_focus_in / detach_tree / watch / install 全不抛异常、"
          "一次都没碰到 imm32，输入法状态没动、窗口照常可用 ✓")

    # --- v3 闸门 (c)(d)：进搜索框 / Esc 回表格（键盘进得去）；v32.3：F 取代原来的 `/`
    gui.nb.select(0)
    gui.tree.focus_set()
    root.update()
    gui.tree.event_generate("<KeyPress>", keysym="f")           # v32.3：树上按 F = 进搜索框
    root.update()
    assert root.focus_get() is gui.ent_search, root.focus_get()
    gui.tree.focus_set()                                        # v68：大写 F（Shift+f 的形态）同效
    root.update()
    gui.tree.event_generate("<KeyPress>", keysym="F")
    root.update()
    assert root.focus_get() is gui.ent_search, \
        "v68：树上按大写 F 也该进搜索框：%r" % root.focus_get()
    print("(c) 按 F （大小写都行，v68）：焦点进搜索框 ✓（v32.3 起取代原来的 `/`）")
    gui.ent_search.event_generate("<KeyPress>", keysym="f")     # 搜索框里 F 是普通字符
    root.update()
    assert root.focus_get() is gui.ent_search, "搜索框里打 F 不该被抢走"
    gui.var_search.set("双指针")
    gui.ent_search.event_generate("<Escape>")                   # v14 起逐层退回：有字先清空（人留在框里）
    root.update()
    assert gui.var_search.get() == "", gui.var_search.get()
    assert root.focus_get() is gui.ent_search, root.focus_get()
    gui.ent_search.event_generate("<Escape>")                   # 再按一次（空框、面板收着）才回表格
    root.update()
    assert root.focus_get() is gui.tree, root.focus_get()
    print("(d) 搜索框 Esc 逐层退回（v14）：有字先清空、再按一次才回表格 ✓")
    n_focus_before = root.focus_get()
    gui.tree.event_generate("<KeyPress>", keysym="slash")       # v32.3：`/` 副键已删
    root.update()
    assert root.focus_get() is n_focus_before, \
        "按 / 不该跳焦点（v32.3 起搜索键只认 F）：%r" % root.focus_get()
    print("(c2) 按 / ：不再跳搜索框（v32.3：`Ctrl+F / /` 收成裸 F）✓")
    # --- v6 闸门 (q)：← / → 走 3 格横排（总表 → 统计 → 今天要做的），两头绕回
    #     （v29：看板四类合并成一个清单后，6 格里的 1~4 段格没了 → 收成 3 格）
    gui.nb.select(0)
    gui.tree.focus_set()
    root.update()
    gui.tree.event_generate("<KeyPress>", keysym="Right")
    root.update()
    assert gui.nb.index(gui.nb.select()) == 2, "总表按 → 应先进「知识点统计」页"
    assert root.focus_get() is gui.know_tree, "进统计页后焦点要落到统计清单上"
    gui.know_tree.event_generate("<KeyPress>", keysym="Right")
    root.update()
    assert gui.nb.index(gui.nb.select()) == 1, "统计页按 → 应进「今天要做的」"
    assert root.focus_get() is gui.today_tree, "进看板后焦点要落到该页清单上"
    # v29：选中落**第一道题目行**（跳过开头的类标题行）
    kids_q = list(gui.today_tree.get_children())
    assert gui.today_tree.focus() != "" and gui._index_of(gui.today_tree) == \
        next(j for j, x in enumerate(kids_q) if not x.startswith(SEG_PREFIX)), \
        "进看板后选中行该是第一道题目行（v29：不落类标题行）"
    gui.today_tree.event_generate("<KeyPress>", keysym="Right")
    root.update()
    assert gui.nb.index(gui.nb.select()) == 0, "看板按 → 应回总表（3 格两头绕回）"
    gui.tree.event_generate("<KeyPress>", keysym="Left")
    root.update()
    assert gui.nb.index(gui.nb.select()) == 1, "总表按 ← 应绕回进看板"
    gui.today_tree.event_generate("<KeyPress>", keysym="Left")
    root.update()
    assert gui.nb.index(gui.nb.select()) == 2, "看板按 ← 应回「知识点统计」页"
    gui.know_tree.event_generate("<KeyPress>", keysym="Left")
    root.update()
    assert gui.nb.index(gui.nb.select()) == 0, "统计页按 ← 应回总表"
    assert root.focus_get() is gui.tree, "回总表后焦点在总表树"
    # 浮层开着时 ← / → 不响应（v5 的规则原样保留）
    iid_t = gui.tree.get_children()[0]
    gui.tree.selection_set(iid_t)
    gui.tree.focus(iid_t)
    gui.open_status_popup(gui.row_by_iid(iid_t), gui.tree)
    root.update()
    gui.tree.event_generate("<KeyPress>", keysym="Right")
    root.update()
    assert gui.nb.index(gui.nb.select()) == 0, "浮层开着时 ← / → 不该动（页不动）"
    assert gui._nav_arrow(1) is None, "浮层开着时导航处理要「不响应」"
    assert gui.nb.index(gui.nb.select()) == 0, "浮层开着时不该动（直接调用也不行）"
    gui._popup_cancel()
    root.update()
    print("(q) ← / → 走 3 格（总表 → 统计 → 今天要做的 → 总表，两头绕回；v29 四类合并收成 3 格）："
          "进看板时清单 / 选中行（第一道题目行）/ 焦点都到位；浮层开着时不响应 ✓")

    # --- (o) 焦点在搜索框里时 ← / → 不切页，控件行为照旧（v9：筛选半边删除）
    gui.nb.select(0)
    gui.var_search.set("abc")
    gui.refresh_view()
    # 焦点前置用 focus_force：浮层（Toplevel）关掉后 Tk 的显示焦点是空，
    # 非强制的 focus_set 要等系统把主窗口激活才生效（无人值守/别的窗口占前台时会推迟），
    # 合成按键就送不到控件上 —— 强制设置让这段自测与「窗口有没有被激活」无关（断言不变）
    gui.ent_search.focus_force()
    gui.ent_search.icursor("end")
    root.update()
    gui.ent_search.event_generate("<KeyPress>", keysym="Left")
    root.update()
    assert gui.nb.index(gui.nb.select()) == 0, "搜索框里按 ← 不该切页"
    assert gui.ent_search.index("insert") == 2, "搜索框里 ← 应照常挪光标（3 → 2）"
    assert gui.var_search.get() == "abc", "搜索框内容不该被动"
    gui.ent_search.event_generate("<KeyPress>", keysym="Right")
    root.update()
    assert gui.nb.index(gui.nb.select()) == 0, "搜索框里按 → 不该切页"
    assert gui.ent_search.index("insert") == 3, "搜索框里 → 应照常挪光标（2 → 3）"
    # v6：看板页上（焦点在搜索框里）← / → 同样只做控件自己的事，不换格
    gui.nb.select(1)
    root.update()
    gui.ent_search.focus_force()        # 同上：浮层关掉之后非强制 focus_set 会被推迟
    root.update()
    gui.ent_search.event_generate("<KeyPress>", keysym="Left")
    gui.ent_search.event_generate("<KeyPress>", keysym="Right")
    root.update()
    assert gui.nb.index(gui.nb.select()) == 1, \
        "看板页上焦点在搜索框时 ← / → 不该换格"
    print("(o) 搜索框里 ← / → 不换格、光标照常（3→2→3）、内容没动（看板页同样）✓")
    gui.var_search.set("")
    gui.refresh_view()
    gui.nb.select(0)
    gui.tree.focus_set()
    root.update()

    # --- v88 闸门 (hh4)：列间竖线已整条去掉 —— 画线那套（方法 / 缓存 / 颜色槽）一个都不该在
    root.update()
    assert not hasattr(gui, "_sync_grid_lines"), \
        "v88：`_sync_grid_lines` 该已删（用户点名去掉列间竖线）"
    assert not hasattr(gui, "_grid_frames") and not hasattr(gui, "_grid_at"), \
        "v88：竖线缓存 `_grid_frames` / `_grid_at` 该已删"
    assert "C_GRID" not in globals(), "v88：`C_GRID` 颜色槽该已删"
    print("(hh4) 列间竖线（v88 去掉）：`_sync_grid_lines` / `_grid_frames` / `_grid_at` / C_GRID 均已删 ✓")

    # --- v22 闸门 (q2)：Ctrl+Home / Ctrl+End 跳当前页清单的首 / 末行（浮层 / 搜索框里让位）
    ids = list(gui.tree.get_children())
    assert len(ids) >= 3, "台账太短，这条测不动"
    gui._select_index(gui.tree, 2)
    gui.tree.focus_force()
    gui.tree.event_generate("<KeyPress>", keysym="Home", state=0x4)     # 0x4 = Control
    root.update()
    assert gui._index_of(gui.tree) == 0, "Ctrl+Home 该跳首行（现在是 %r）" % gui._index_of(gui.tree)
    gui.tree.event_generate("<KeyPress>", keysym="End", state=0x4)
    root.update()
    assert gui._index_of(gui.tree) == len(ids) - 1, \
        "Ctrl+End 该跳末行（现在是 %r）" % gui._index_of(gui.tree)
    # 看板页同样跳**当前页**的清单（不是总表）；v29：Ctrl+Home 跳过类标题行、落第一道题目行
    gui.nb.select(1)
    root.update()
    seg_ids = list(gui.today_tree.get_children())
    assert len(seg_ids) >= 2, "看板清单太短，这条测不动"
    first_row_q2 = next(x for x in seg_ids if not x.startswith(SEG_PREFIX))
    gui.today_tree.selection_set(seg_ids[-1])
    gui.today_tree.focus_force()
    gui.today_tree.event_generate("<KeyPress>", keysym="Home", state=0x4)
    root.update()
    assert gui.today_tree.focus() == first_row_q2, \
        "看板页 Ctrl+Home 该跳第一道题目行（v29：跳过类标题行），现在是 %r" % (gui.today_tree.focus(),)
    gui.today_tree.event_generate("<KeyPress>", keysym="End", state=0x4)
    root.update()
    assert gui._index_of(gui.today_tree) == len(seg_ids) - 1, "看板页 Ctrl+End 该跳清单末行（末行恒是题目行）"
    # 搜索框里 Ctrl+Home 归 Entry（此时 Entry 的 handler 会 return "break" 拦下，轮不到我们的绑定）
    gui.nb.select(0)
    gui.ent_search.focus_force()
    root.update()
    gui.ent_search.event_generate("<KeyPress>", keysym="Home", state=0x4)
    root.update()
    assert gui._index_of(gui.tree) == len(ids) - 1, "焦点在搜索框时 Ctrl+Home 不该动表格选中"
    gui.tree.focus_set()
    root.update()
    print("(q2) Ctrl+Home / Ctrl+End 跳当前页清单首 / 末行（v22）：总表跳第 0 / 末行、"
          "看板 Ctrl+Home 跳过类标题行落第一道题、Ctrl+End 跳末行；焦点在搜索框时不动表格 ✓")

    # --- v22 闸门 (c2)：Ctrl+F 跳搜索框（`/` 的替代键；浮层开着不响应、已在框里不抢）
    gui.nb.select(0)
    gui.var_search.set("")
    gui.tree.focus_force()
    root.update()
    gui.tree.event_generate("<KeyPress>", keysym="f", state=0x4)
    root.update()
    assert root.focus_get() is gui.ent_search, "Ctrl+F 该把焦点送进搜索框（现在是 %r）" % root.focus_get()
    gui.var_search.set("双指针")
    gui.ent_search.event_generate("<Escape>")
    gui.ent_search.event_generate("<Escape>")
