    assert root.focus_get() is gui.tree, root.focus_get()
    print("(c2) Ctrl+F 跳搜索框（v22，与 / 同 handler）✓")

    # --- v6 闸门 (r)：看板页数字键不切段（浮层里 1~6 直选照旧）
    #     v12 口径更新：数字键仍不切段，但已改挂到两棵树上做「直接改状态」——root 上依然一个
    #     数字键都不许有；「无选中」时按数字静默：不切段、文件一个字不动。
    for k in range(1, 5):
        assert root.bind("<Key-%d>" % k) == "" and root.bind("<KP_%d>" % k) == "", \
            "root 上还挂着数字键 %d（v12 起数字键只许挂树上）" % k
    gui.nb.select(1)
    root.update()
    sel_r = gui.today_tree.selection()
    if sel_r:
        gui.today_tree.selection_remove(*sel_r)
    gui.today_tree.focus("")            # v12：tree_row 无选中时会拿 focus 当当前行 —— 真「无选中」两样都清
    gui.today_tree.focus_force()        # v29：Tk 合成键盘事件按**焦点**派发 —— 按键前焦点必须在看板树上
    root.update()                       #      （老版本靠 show_segment 顺带设焦点；段合并后要显式设）
    bytes_r0 = open(tmp, "rb").read()
    for k in (1, 2, 3, 4):
        gui.today_tree.event_generate("<KeyPress>", keysym=str(k))
        root.update()
        assert gui.nb.index(gui.nb.select()) == 1, "看板页按 %d 不该切页（v29：数字键只改状态）" % k
    assert open(tmp, "rb").read() == bytes_r0, "没选中行时按数字不许改任何东西（v12）"
    print("(r) 看板页数字键只改状态（不切页；root 上没有数字键；无选中按数字文件不动）")
    # 浮层里数字键照旧：按「待重写」的序号 = 直选那个状态（别把浮层的数字直选一起删了）
    gui.nb.select(0)
    want3 = "待重写"                             # v10：按状态名取，不依赖顺序下标
    key3 = STATES.index(want3) + 1
    iid = next(x for x in gui.tree.get_children()
               if gui.row_by_iid(x)["状态"] != want3)
    gui.tree.selection_set(iid)
    gui.tree.focus(iid)
    row3 = gui.row_by_iid(iid)
    gui.open_status_popup(row3, gui.tree)
    assert gui.popup is not None, "浮层没弹出来"
    root.update()
    assert gui.popup_lb.winfo_viewable(), "浮层应已可见"
    gui.popup_lb.event_generate("<KeyPress>", keysym=str(key3))
    root.update()
    assert gui.popup is None, "数字直选后浮层应关闭"
    got = next(r for r in parse_rows(tmp) if (r["场次"], r["题号"]) == (row3["场次"], row3["题号"]))
    assert got["状态"] == want3 and row3["状态"] != want3, (row3["状态"], got["状态"])
    print("(r) 浮层里按 %d → 直接写入第 %d 个状态「%s」（浮层数字直选没被误删）✓"
          % (key3, key3, want3))

    # --- 【v49】闸门 (jj)：焦点轮换两套 —— **Tab = 当前页清单 ⇄ 搜索框**（v32.3 之前的老两站，
    #     用户口径「tab 恢复为原来的作用」）；**单按 Ctrl = 当前页清单 ⇄ 右侧 md 预览**
    #     （v49 从 Tab 挪给 Alt，v91 再挪给 Ctrl；判定三件套见绑定区注释）。
    #     预览收起 = 只有一站 → Ctrl 不响应；进预览走 `prev.focus_webview()`；v40：设置界面里
    #     Tab 走 Tk 默认焦点环（`_rotate_focus_settings`）。
    assert root.bind("<Tab>") != "" and root.bind("<Shift-Tab>") != "", \
        "root 上要挂 Tab / Shift-Tab 焦点轮换"
    assert root.bind("<KeyPress-Control_L>") != "" and root.bind("<KeyPress-Control_R>") != "", \
        "v91：root 上要挂单按 Ctrl（左右）的 md 轮换（『起』）"
    assert root.bind("<KeyRelease-Control_L>") != "" and root.bind("<KeyRelease-Control_R>") != "", \
        "v91：root 上要挂单按 Ctrl 的『收』（keyup 判定）"
    assert root.bind("<Control-KeyPress>") != "" and root.bind("<Control-KeyRelease>") != "" \
        and root.bind("<KeyRelease>") != "", \
        "v91：清 flag 的三条通配（<Control-KeyPress> / <Control-KeyRelease> / <KeyRelease>）都要挂上"
    gui.nb.select(0)
    gui.tree.focus_force()                   # 合成按键 / 反复查 focus_get 前先 focus_force：
    root.update()                            # 窗口没拿到 OS 焦点时 focus_get() 会给 None（v10 踩过）
    # ① Tab：清单 ⇄ 搜索框（搜索框挂着 → 两站）
    assert gui._search_box_visible(), "前提：这时候搜索框该是挂着的"
    gui.tree.focus_force(); root.update()
    gui.tree.event_generate("<KeyPress>", keysym="Tab")
    root.update()
    assert root.focus_get() is gui.ent_search, "v49：Tab 该从表格走到搜索框：%r" % root.focus_get()
    gui.ent_search.event_generate("<KeyPress>", keysym="Tab")
    root.update()
    assert root.focus_get() is gui.tree, "v49：搜索框里再 Tab 回表格：%r" % root.focus_get()
    gui.tree.focus_force(); root.update()
    gui.tree.event_generate("<KeyPress>", keysym="Tab", state=0x1)      # Shift+Tab 反向：同样是搜索框
    root.update()
    assert root.focus_get() is gui.ent_search, "v49：Shift+Tab 反向也到搜索框：%r" % root.focus_get()
    # ①b v58：进搜索框那一下**光标落末尾**（用户报：知识点页回车跳回总表后按 Tab，打字插到最前面）
    #     —— `_know_search` 就是那一下跳转（写词 + 切总表 + 焦点回树）。
    _sv58, _org56 = gui.var_search.get(), gui._know_search_origin
    gui._know_search("双指针")
    root.update()
    gui.tree.focus_force(); root.update()
    gui.tree.event_generate("<KeyPress>", keysym="Tab")
    root.update()
    assert root.focus_get() is gui.ent_search, root.focus_get()
    assert int(gui.ent_search.index("insert")) == len("双指针"), \
        "v58：Tab 进搜索框该把光标送末尾（实得 insert=%r）" % (gui.ent_search.index("insert"),)
    assert not gui.ent_search.selection_present(), "v58：进框不带选区（灰底）"
    gui.tree.focus_force(); root.update()
    gui.tree.event_generate("<KeyPress>", keysym="Tab", state=0x1)      # Shift+Tab 同一条路
    root.update()
    assert int(gui.ent_search.index("insert")) == len("双指针"), "v58：Shift+Tab 进框同样落末尾"
    gui.var_search.set(_sv58)
    gui._know_search_origin = _org56
    gui.tree.focus_force(); root.update()
    # ② v49：搜索框失焦 → 选区清掉（修「Tab 走开后残留灰底白字」）
    #    （放 ③ 前测：③ 要 unpack 搜索框，而本机实测 unpack 后 repack 不保证再 map，
    #       unmapped 的控件 Tk 不给焦点、也就不会发 FocusOut —— 先测干净的）
    _sv0 = gui.var_search.get()
    gui.var_search.set("abc")
    gui.tree.focus_force(); root.update()
    gui.ent_search.focus_set(); root.update()
    gui.ent_search.selection_range(0, "end")
    root.update()
    assert gui.ent_search.selection_present(), "前提：先得真的选上"
    gui.tree.focus_force(); root.update()
    assert not gui.ent_search.selection_present(), "v49：失焦后搜索框选区该被清掉"
    gui.var_search.set(_sv0)
    # ③ 搜索框收起来（别的页 pack_forget 它）→ 只有一站，Tab 不响应（焦点留在表格）
    _head_slaves = gui.ent_search.master.pack_slaves()
    _before_w = _head_slaves[2] if len(_head_slaves) > 2 else None
    gui.ent_search.pack_forget()
    root.update()
    gui.tree.focus_force(); root.update()
    assert gui._search_box_visible() is False, "v49：pack_forget 后可见判据该回 False"
    gui.tree.event_generate("<KeyPress>", keysym="Tab")
    root.update()
    assert root.focus_get() is gui.tree, "v49：搜索框收着时 Tab 不该动焦点：%r" % root.focus_get()
    assert gui._rotate_focus(1) == "break"
    gui.ent_search.pack(side="left", padx=(6, 16), before=_before_w)    # 原位放回（不带 before 会挂到队尾）
    root.update()
    assert gui._search_box_visible(), "放回后该又可见"
    # ④ 单按 Ctrl：清单 ⇄ md 预览（替身记录 focus_webview 调用，不真起 WebView2）
    class _FakePrev49(object):
        def __init__(self):
            self.calls = []
            self.vis = []
        def set_visible(self, v):
            self.vis.append(v)
        def focus_webview(self):
            self.calls.append(1)
    fake49 = _FakePrev49()
    _prev0, gui.prev = gui.prev, fake49
    gui.prev_open = True                         # v50：焦点环认「露着的」那份 —— 得真摆出来
    gui.prev_cell = gui._cell_of_current_page()
    gui._prev_show_view()
    try:
        assert gui._focus_ring() == [gui._active_tree(), "preview"], gui._focus_ring()
        assert gui._focus_ring()[0] is gui.tree_split, \
            "v66：预览开着时摆的是分屏页 —— 焦点环里的『清单』= 分屏页那张表"
        gui._active_tree().focus_force(); root.update()
        gui._active_tree().event_generate("<KeyPress>", keysym="Control_L")       # v91 单按 Ctrl：↓
        gui._active_tree().event_generate("<KeyRelease>", keysym="Control_L")     #               ↑
        root.update()
        assert fake49.calls == [1], "v91：单按 Ctrl 该调 focus_webview（%r）" % (fake49.calls,)
        # v91 反例：Ctrl+字母 不算单按 —— 期间别的键动过 → flag 清掉 → 松开 Ctrl 不轮换
        gui._active_tree().focus_force(); root.update()
        gui._active_tree().event_generate("<KeyPress>", keysym="Control_L")
        gui._active_tree().event_generate("<KeyPress>", keysym="f", state=0x4)    # Ctrl+f（state 位手动给）
        gui._active_tree().event_generate("<KeyRelease>", keysym="f", state=0x4)
        gui._active_tree().event_generate("<KeyRelease>", keysym="Control_L")
        root.update()
        assert len(fake49.calls) == 1, "v91：Ctrl+字母 不算单按，不该轮换（%r）" % (fake49.calls,)
    finally:
        gui._prev_hide_view()                    # v50：先拆显示，再换回真身
        gui.prev, gui.prev_open, gui.prev_cell = _prev0, False, None
    # ④ 预览收起：Alt 不响应（唯一一站）
    gui.prev_open = False
    assert gui._focus_ring() == [gui.tree], gui._focus_ring()
    assert gui._rotate_md_focus(1) == "break"
    # ⑥ 「中间控件」都不进轮换：takefocus 关掉；Tab 处理只在 root 一处
    for w, name in ((gui.nb, "Notebook"),):
        assert str(w.cget("takefocus")) in ("0", "False", "false"), \
            "%s 的 takefocus 没关：%r" % (name, w.cget("takefocus"))
    for w, name in ((gui.tree, "总表树"), (gui.today_tree, "看板树"),
                    (gui.know_tree, "统计树"), (gui.ent_search, "搜索框"),
                    (gui.nb, "Notebook"), (gui.tab_all, "总表页"),
                    (gui.tab_today, "看板页")):
        assert w.bind("<Tab>") == "" and w.bind("<Shift-Tab>") == "", \
            "%s 上也挂了 Tab 绑定（应该只在 root 一处处理）" % name
    assert root.bind_all("<Tab>") == "" and root.bind_all("<Shift-Tab>") == "", \
        "bind_all 上还有 Tab 处理"
    # ⑦ v40：设置界面里 Tab 走 Tk 默认环（不套上面的两站逻辑）；Alt 在设置里也不响应
    gui.enter_settings()
    root.update()
    gui.key_tv.focus_set()
    root.update()
    gui._rotate_focus(1)
    root.update()
    assert root.focus_get() is not None and root.focus_get() is not gui.key_tv, \
        "v40：设置界面里 Tab 交给 Tk 默认环：%r" % root.focus_get()
    assert gui._rotate_md_focus(1) is None, "v91：设置界面里 Ctrl 不响应"
    gui.leave_settings()
    root.update()
    gui.tree.focus_force()
    root.update()
    print("(jj) 焦点轮换（v49 / v91 改键）：**Tab = 当前页清单 ⇄ 搜索框**（搜索框收起时不响应）；"
          "**单按 Ctrl = 当前页清单 ⇄ md 预览**（收起时不响应；进预览走 focus_webview；"
          "Ctrl+字母 不算单按 —— 替身验）；"
          "搜索框失焦清选区；**v58：Tab / Shift+Tab 进搜索框 → 光标落末尾（不带选区）**"
          "（`_know_search` 跳转后实测）；页签 takefocus 全关、Tab 处理只在 root；"
          "v40：设置界面里 Tab 交给 Tk 默认环 ✓")

    # --- v43 闸门 (jj2)：预览开着时**行上 Esc 先收预览**（只收预览、不动搜索词；第二下才走原路）
    class _FakePrev2(object):
        def __init__(self):
            self.vis = []
        def set_visible(self, v):
            self.vis.append(v)
    fp2 = _FakePrev2()
    _prev0b, _org0b = gui.prev, gui._know_search_origin
    gui.prev, gui._know_search_origin = fp2, None
    try:
        gui.nb.select(0)
        gui.tree.focus_force()
        gui.var_search.set("小月")
        gui.refresh_view()
        root.update()
        gui.prev_open = True                     # v50：得真摆出来才算「露着」（_prev_shown 判据）
        gui.prev_cell = gui._cell_of_current_page()
        gui._prev_show_view()
        gui._on_row_esc()                        # 第一下：只收预览
        assert gui.prev_open is False, "v43：预览开着时行上 Esc 该先收起预览"
        assert fp2.vis[-1] is False, "v43：收起要通知组件 set_visible(False)：%r" % (fp2.vis,)
        assert gui.var_search.get() == "小月", "v43：第一下 Esc 不许顺带清搜索词"
        gui._on_row_esc()                        # 第二下：才是原来的清搜索
        assert gui.var_search.get() == "", "v43：第二下 Esc 该清搜索"
        gui.prev_open = True                     # 按场次视图同口径：预览开着先收预览
        gui.prev_cell = gui._cell_of_current_page()
        gui._prev_show_view()
        gui._on_round_esc()
        assert gui.prev_open is False, "v43：按场次视图行上 Esc 同样先收预览"
        gui._on_preview_status("esc", None)      # 预览已收起 → 幂等 no-op（不炸、不再通知）
        assert fp2.vis == [True, False, True, False], \
            "v43：'esc' 消息收起要通知组件 / 已收起则不重复：%r" % (fp2.vis,)
    finally:
        gui._prev_hide_view()                    # v50：先拆显示，再还原
        gui.prev, gui._know_search_origin, gui.prev_open = _prev0b, _org0b, False
        gui.prev_cell = None
    gui.var_search.set("")
    gui.refresh_view()
    root.update()
    print("(jj2) 预览开着时行上 Esc 只收预览（v43）：搜索词留着、第二下才清；按场次视图同口径；"
          "组件收到一次 set_visible(False)、再按幂等 ✓")

    # --- v6 闸门 (t)：两个焦点各有可见指示（选中行 / 输入框边框 + 底色换强调色；
    #     v89：焦点边框跟深浅走；v92：**光标竖线**也跟深浅走 —— 深白 / 浅黑）
    #     v23（2026-10-06）：选中行现在由**主题**决定 —— 边框档不铺底（只画 2px 线、文字加粗），
    #     蓝底白字档铺深蓝 + 白字。所以这里不断言"等于哪个色号"（那是 (hh6-1/2) 的活），
    #     只断言"两档都真的配上了、失焦档确实不同"。
    st = ttk.Style(root)
    bg_on = st.lookup("Status.Treeview", "background", ("selected", "focus"))
    bg_off = st.lookup("Status.Treeview", "background", ("selected", "!focus"))
    fg_on = st.lookup("Status.Treeview", "foreground", ("selected", "focus"))
    fg_off = st.lookup("Status.Treeview", "foreground", ("selected", "!focus"))
    assert len(str(bg_on).strip()) > 0 and len(str(bg_off).strip()) > 0, (bg_on, bg_off)
    en_b = dict((s, st.lookup("Nav.TEntry", "bordercolor", s)) for s in (("focus",), ("!focus",)))
    en_g = dict((s, st.lookup("Nav.TEntry", "fieldbackground", s)) for s in (("focus",), ("!focus",)))
    # v89：焦点边框色跟着界面深浅走 —— 深色界面 = 纯白、亮色界面 = 强调色（断言按当前深浅算）
    _want_b = "#ffffff" if frame_palette(gui.theme_scheme, gui.theme_daynight) is not FRAME_LIGHT \
        else C_ACCENT
    assert str(en_b[("focus",)]).upper() == _want_b.upper() \
        and en_b[("focus",)] != en_b[("!focus",)], en_b
    assert en_g[("focus",)] != en_g[("!focus",)], en_g
    # v92：搜索框的**光标竖线**（插入符）颜色走同一条尺 —— 深色界面纯白 / 浅色界面纯黑
    #     （它是 ttk 的元素选项 `-insertcolor`，从**样式**读，不在控件选项上）
    _want_c = "#ffffff" if frame_palette(gui.theme_scheme, gui.theme_daynight) is not FRAME_LIGHT \
        else "#000000"
    _caret_c = str(st.lookup("Nav.TEntry", "insertcolor"))
    assert _caret_c.upper() == _want_c.upper(), \
        "v92：搜索框光标竖线该随界面深浅走（%r != %r）" % (_caret_c, _want_c)
    assert fg_on and fg_off, (fg_on, fg_off)
    gui.tree.focus_set()
    root.update()
    assert gui.tree.instate(["focus"]), "总表聚焦时 ttk 要有 focus 状态（样式才切得动）"
    gui.ent_search.focus_set()
    root.update()
    assert gui.ent_search.instate(["focus"]) and not gui.tree.instate(["focus"])
    print("(t) 焦点可见：选中行由主题给（当前「%s / %s」→ 底 %s｜字 %s）；搜索框边框 %s + 底色变化、"
          "光标竖线 %s（v92）；两个控件都真挂得上 focus 状态 ✓"
          % (gui.theme_sel_color, gui.theme_scheme, bg_on, fg_on, en_b[("focus",)], _caret_c))

    # v29：合并清单 —— 四类都在一个清单里（类标题行 + 题目行）；刷新后选中恒在第一道题目行
    gui.nb.select(1)
    gui.refresh_today()
    root.update()
    kids_m = list(gui.today_tree.get_children())
    seg_list = [x for x in kids_m if x.startswith(SEG_PREFIX)]
    row_list = [x for x in kids_m if not x.startswith(SEG_PREFIX)]
    assert len(seg_list) == sum(1 for i in range(4) if segment_rows(gui.rows, i)), seg_list
    assert len(row_list) == sum(len(segment_rows(gui.rows, i)) for i in range(4)), row_list
    print("合并清单：%d 条类标题行 + %d 道题" % (len(seg_list), len(row_list)))
    assert gui.today_tree.focus() != "" and not gui.today_tree.focus().startswith(SEG_PREFIX), \
        "刷新后清单要有选中行，且是第一道题目行（v29：不落类标题行）"

    # 看板页也回车弹浮层
    gui.nb.select(1)

    class _Ev(object):
        widget = None

    ev = _Ev()
    ev.widget = gui.today_tree
    iid = next(x for x in gui.today_tree.get_children() if not x.startswith(SEG_PREFIX))
    gui.today_tree.selection_set(iid)
    gui.today_tree.focus(iid)
    gui._on_open_key(ev)                            # 等价于在看板清单里按回车
    assert gui.popup is not None, "看板页回车也要弹浮层"
    gui._popup_cancel()
    gui.nb.select(0)

    iid = gui.tree.get_children()[0]
    gui.tree.selection_set(iid)
    gui.tree.focus(iid)
    row = gui.row_by_iid(iid)
    print("浮层目标：%s %s（原状态 %s）" % (row["场次"], row["题号"], row["状态"]))
    gui.open_status_popup(row, gui.tree)
    assert gui.popup is not None and gui.popup_lb.size() == len(STATES)
    raw = [gui.popup_lb.get(i) for i in range(gui.popup_lb.size())]
    texts = [re.sub(r"^\d+\.\s*", "", t) for t in raw]
    assert texts == STATES, texts
    assert gui.popup_lb.curselection() == (STATES.index(row["状态"]),), "浮层应默认选在当前状态"
    want_no = ["%d. " % (k + 1) for k in range(len(STATES))]     # v5 闸门 (l)
    assert all(t.startswith(w) for t, w in zip(raw, want_no)), raw
    bad = [str(w.cget("text")) for w in _walk(gui.popup)          # v5 闸门 (m)
           if w.winfo_class() == "Label"
           and ("直选" in str(w.cget("text")) or "Enter 确认" in str(w.cget("text")))]
    assert bad == [], "浮层里还有提示行：%r" % bad
    print("浮层：%d 项带序号、顺序 = %s，当前状态高亮选中（首项 = %r）"
          % (gui.popup_lb.size(), " / ".join(texts), raw[0]))
    print("(l) 浮层 6 项依次以 1. ~ 6. 开头（数字键与序号一一对应）✓")
    print("(m) 浮层里没有「直选 / Enter 确认」提示行（只剩 6 个编号选项）✓")
    gui._popup_move(1)
    sel = gui.popup_lb.curselection()[0]
    want = STATES[sel]
    gui._popup_confirm()
    assert gui.popup is None, "确认后浮层应关闭"
    got = next(r for r in parse_rows(tmp) if (r["场次"], r["题号"]) == (row["场次"], row["题号"]))
    assert got["状态"] == want, (got["状态"], want)
    assert got["日期"] == datetime.date.today().isoformat(), got["日期"]
    print("回车确认后：%s ｜ %s → %s，日期 %s（写入 fixture）✓"
          % (got["题号"], row["状态"], got["状态"], got["日期"]))

    gui.open_status_popup(next(r for r in gui.rows if r["题号"] == row["题号"]), gui.tree)
    assert gui.popup_lb.curselection()[0] == STATES.index(want), "浮层应把当前状态选上"
    before_idx = gui._index_of(gui.tree)
    gui._popup_cancel()
    assert gui.popup is None, "Esc 取消后浮层应关闭"
    assert gui._index_of(gui.tree) == before_idx, "Esc 取消不该动选中行"
    print("Esc 取消：浮层关闭、文件未改、选中行没动 ✓")

    # --- v4 闸门 (d)：改完状态选中行自动下移一行（最后一行则不动）+ 闸门 (f) 保存提示 3 秒清空
    gui.nb.select(0)
    gui.sort_col, gui.sort_desc = "场次", False
    gui.var_search.set("")
    gui.refresh_view()
    ids = list(gui.tree.get_children())
    at = 3                                          # 取中间一行，上下都有人
    gui.tree.selection_set(ids[at])
    gui.tree.focus(ids[at])
    up_row, down_row = gui.row_by_iid(ids[at]), gui.row_by_iid(ids[at + 1])
    gui.open_status_popup(up_row, gui.tree)
    gui.popup_lb.selection_clear(0, "end")
    gui.popup_lb.selection_set(0)                   # 选个和原状态不同的，确保真写盘
    assert STATES[0] != up_row["状态"], "这条要换个状态才有意义"
    gui._popup_confirm()
    assert gui._index_of(gui.tree) == at + 1, \
        "改完状态应自动下移一行：第 %s 行 → 第 %s 行" % (at, gui._index_of(gui.tree))
    now = gui.row_by_iid(gui.tree.focus())
    assert (now["场次"], now["题号"]) == (down_row["场次"], down_row["题号"]), \
        "下移后应停在原来它下面那一行（%s）" % down_row["题号"]
    print("(d) 改完状态下移一行：第 %d 行改完 → 选中第 %d 行（%s → %s）✓"
          % (at, gui._index_of(gui.tree), up_row["题号"], now["题号"]))

    # --- v4 闸门 (f) + v9 闸门 (ll)：保存消息 = 短文案（无备份名 / 日期），3 秒后自动清空
    want_msg = "已保存：%s %s → %s" % (up_row["场次"], up_row["题号"], STATES[0])
    assert gui.var_msg.get() == want_msg, gui.var_msg.get()
    assert ".bak" not in gui.var_msg.get() \
        and datetime.date.today().isoformat() not in gui.var_msg.get(), \
        "消息里不该出现备份文件名 / 日期：%r" % gui.var_msg.get()
    assert TOAST_MS == 3000, TOAST_MS
    assert gui._msg_after is not None, "保存后应注册「3 秒后清空」的 after 回调"
    assert root.tk.call("after", "info", gui._msg_after), "回调要真的挂在 Tk 的 after 表里"
    gui._clear_msg()                                # 等价于 3 秒到点
    assert gui.var_msg.get() == "" and gui._msg_after is None, gui.var_msg.get()
    print("(ll) 消息：改状态后 = %r（无 .bak / 日期）；(f) 3 秒后自动清空（after 回调已注册 %d ms）✓"
          % (want_msg, TOAST_MS))

    ids = list(gui.tree.get_children())
    last = len(ids) - 1
    gui.tree.selection_set(ids[last])
    gui.tree.focus(ids[last])
    last_row = gui.row_by_iid(ids[last])
    gui.open_status_popup(last_row, gui.tree)
    pick = 0 if STATES.index(last_row["状态"]) != 0 else 1
    gui.popup_lb.selection_clear(0, "end")
    gui.popup_lb.selection_set(pick)
    gui._popup_confirm()
    assert gui._index_of(gui.tree) == last, "最后一行改完应留在最后一行不动"
    print("(d) 最后一行改完仍停在最后一行（不动）✓")

    # 看板页同样：清单里改状态也下移一行（v29：挑「待补题」类第一道题、重选同一个状态 ——
    # 只有日期变（仍是真写盘），行不会被踢出这一类，下移才测得出）
    gui.nb.select(1)
    gui.refresh_today()
    root.update()
    cap = segment_specs()[1][0]
    tr_ids = list(gui.today_tree.get_children())
    assert len(segment_rows(gui.rows, 1)) >= 2, "「待补题」类至少要有两道题才测得出下移"
    i_seg1 = tr_ids.index(SEG_PREFIX + "1")
    r0_iid = tr_ids[i_seg1 + 1]
    nxt_expect = tr_ids[i_seg1 + 2]                  # 改完该选中的 = 原下一道题（还在的话）
    gui.today_tree.selection_set(r0_iid)
    gui.today_tree.focus(r0_iid)
    r0 = gui.row_by_iid(r0_iid)
    gui.open_status_popup(r0, gui.today_tree)
    assert r0["状态"] == "不会", "待补题类里只该有「不会」：%r" % (r0["状态"],)
    pick = STATES.index("不会")                      # 重选同一个状态：只改日期，仍留在这一类
    gui.popup_lb.selection_clear(0, "end")
    gui.popup_lb.selection_set(pick)
    gui._popup_confirm()
    assert gui.today_tree.focus() == nxt_expect, \
        "看板页改完应选中原下一道题（v29），现在是 %r" % (gui.today_tree.focus(),)
    print("(d) 看板页同样下移一行：%s 类第 1 道改完 → 选中原下一道 ✓" % cap)
    gui.nb.select(0)

    # --- v3 闸门 (e)：浮层里按数字键 = 直接选中对应状态并写入（v10：按状态名取序号）
    iid = gui.tree.get_children()[1]
    gui.tree.selection_set(iid)
    gui.tree.focus(iid)
    row4 = gui.row_by_iid(iid)
    want4 = "复现AC"                                  # v10：按状态名取，不依赖顺序下标
    key4 = STATES.index(want4) + 1
    assert row4["状态"] != want4, "这条要换个状态才有意义：%r" % (row4["状态"],)
    gui.open_status_popup(row4, gui.tree)
    assert gui.popup is not None, "浮层没弹出来"
    root.update()                                     # 等浮层真画出来，按键才送得到
    assert gui.popup_lb.winfo_viewable(), "浮层应已可见"
    gui.popup_lb.event_generate("<KeyPress>", keysym=str(key4))
    root.update()
    assert gui.popup is None, "数字直选后浮层应关闭"
    got = next(r for r in parse_rows(tmp) if (r["场次"], r["题号"]) == (row4["场次"], row4["题号"]))
    assert got["状态"] == want4, (got["状态"], want4)
    assert got["日期"] == datetime.date.today().isoformat(), got["日期"]
    print("(e) 浮层里按 %d → 直接写入「%s」+ 日期今天 ✓" % (key4, want4))

    # --- v3 闸门 (f)：页签选中只换色、不改尺寸
    # 注：ttk.Notebook.bbox 在某些 Tk 版本恒返回 (0,0,0,0)（实测），所以用两条真能照出问题的量：
    #   ① 决定标签尺寸的样式项 padding / font 在「选中 / 未选中」两态必须相同
    #      —— clam 默认 padding 是「选中 6 4 6 2 / 未选中 6 2 6 2」，选中时会高 2px（v2 就是这个）
    #   ② 页面 reqwidth 前后一致（派发里点名的口径）
    st = ttk.Style(root)
    probe_root = tk.Tk()                          # 独立解释器：干净 clam，没被本程序的 map 影响
    probe_root.withdraw()
    st_probe = ttk.Style(probe_root)
    st_probe.theme_use("clam")
    probe_sel = st_probe.lookup("TNotebook.Tab", "padding", ("selected",))
    probe_un = st_probe.lookup("TNotebook.Tab", "padding", ("!selected",))
    probe_root.destroy()
    assert probe_sel != probe_un, \
        "探针失效：clam 默认本应让选中的页签更大，照不出来这条检查就没意义（两态都是 %s）" % (probe_sel,)
    for opt in ("padding", "font"):
        a = st.lookup("TNotebook.Tab", opt, ("selected",))
        b = st.lookup("TNotebook.Tab", opt, ("!selected",))
        assert a == b, ("选中页签的 %s 变了" % opt, a, b)
    tabs = gui.nb.tabs()
    gui.nb.select(tabs[0])
    root.update()
    w0 = [root.nametowidget(t).winfo_reqwidth() for t in tabs]
    gui.nb.select(tabs[1])
    root.update()
    w1 = [root.nametowidget(t).winfo_reqwidth() for t in tabs]
    assert w0 == w1, (w0, w1)
    print("(f) 页签选中不改尺寸：padding/font 两态一致（clam 默认两态差 %r，已被压平）；"
          "页面 reqwidth %s ✓" % (probe_sel, w0))

    # --- v3 立、v87 改：? = 设置界面开关（原「弹快捷键一览」—— 一览并进设置页「快捷键一览」块）
    gui.nb.select(0)
    gui.tree.focus_force()          # 合成按键前必须 focus_force：窗口没拿到 OS 焦点时
    root.update()                   # focus_set 是空操作，event_generate 送不到（v10 老坑）
    gui.tree.event_generate("<KeyPress>", keysym="question")
    root.update()
    assert gui._in_settings(), "v87：按 ? 该进设置界面（原来弹一览）"
    gui.set_left.selection_set("help")
    gui.show_set_panel("help")
    root.update()
    assert gui.help_tx.get("1.0", "end-1c") == KEY_TABLE, "一览块内容应与键位表一字不差"
    ks = KEY_TABLE.splitlines()
    assert any(re.match(r"^F(\s|$)", ln) and "搜索框" in ln for ln in ks), \
        "v32.3：键位表里该有裸 F「跳到搜索框」那行：%r" % ks
    assert not any(re.match(r"^F(\s|/|$)", ln) and "筛选" in ln for ln in ks), \
        "v9 删过的「F = 筛选」那行不许回来：%r" % ks
    assert any(ln.startswith("F11") and "全屏" in ln for ln in ks), \
        "键位表里该有 F11 全屏那行（v11）：%r" % ks
    assert any(ln.startswith("1 ~ 6") and "直接改状态" in ln for ln in ks), \
        "键位表里该有 1~6 直接改状态那行（v12）：%r" % ks
    # v46：回车族重排 —— Enter = 展开 / 收起题解 md、Ctrl+Enter = 状态浮层、Alt+Enter = 跳转题目链接；
    # 原 Shift+Enter / P / 「打开这题的资料」三行删干净
    assert any(ln.startswith("Alt+Enter") and "跳转题目链接" in ln for ln in ks), \
        "v46：键位表里该有 Alt+Enter 跳转题目链接那行：%r" % ks
    assert any(ln.startswith("Ctrl+Enter") and "状态浮层" in ln for ln in ks), \
        "v46：键位表里该有 Ctrl+Enter 状态浮层那行：%r" % ks
    assert any(ln.startswith("Enter") and "题解 md" in ln for ln in ks), \
        "v46：键位表里该有 Enter 展开 / 收起题解 md 那行：%r" % ks
    assert not any(ln.startswith("Shift+Enter") for ln in ks), \
        "v46：Shift+Enter 那行该删干净：%r" % ks
    assert not any(re.match(r"^P(\s|$)", ln) for ln in ks), \
        "v46：P 预览那行该删干净（回车取代）：%r" % ks
    assert not any("打开这题的资料" in ln for ln in ks), \
        "v46：「打开这题的资料」那行该删干净：%r" % ks
    assert any(ln.startswith("Ctrl+Z") and "可连撤" in ln for ln in ks), \
        "键位表里 Ctrl+Z 那行该写出「可连撤」（v12）：%r" % ks
    assert any(ln.startswith("Ctrl+Z") and "一个词一步" in ln for ln in ks), \
        "键位表里 Ctrl+Z 那行该写出搜索框按词分段（v20）：%r" % ks
    assert any(ln.startswith("Ctrl+Y") and "复原" in ln for ln in ks), \
        "键位表里该有 Ctrl+Y 复原那行（v20）：%r" % ks
    # v18：筛选下拉面板拆除 —— 键位表里不再有「下拉面板 / 面板里 ↓ / ↑」两行，
    # 改成「搜索框」多字段一行；「下拉框」（v9 删的只读控件）字样照旧不许出现。
    assert "下拉框" not in KEY_TABLE, "键位表里还有「下拉框」控件字样（v9 删的不是这个）"
    assert not any(ln.startswith("下拉面板") or ln.startswith("面板里") for ln in ks), \
        "v18 面板拆除后键位表不该再有「下拉面板 / 面板里」两行：%r" % ks
    assert any(ln.startswith("搜索框") and "多字段" in ln and "任一命中" in ln for ln in ks), \
        "键位表里该有「搜索框 = 多字段任一命中」那行（v18）：%r" % ks
    assert any(ln.startswith("Tab / Shift+Tab") and "搜索框" in ln for ln in ks), \
        "v49：键位表里 Tab 那行该写出两站 = 左边表格 ⇄ 搜索框：%r" % ks
    assert any(ln.startswith("Ctrl") and "焦点轮换" in ln and "预览" in ln for ln in ks), \
        "v91：焦点轮换挪 Ctrl 后，键位表该有 Ctrl 行（左边表格 ⇄ 右侧 md 预览）：%r" % ks
    # v17：← / → 那行要写出 6 格（含「统计」）；统计页两行（走法 + S / R 反转）
    assert any(ln.startswith("← / →") and "统计" in ln for ln in ks), \
        "键位表里 ← / → 那行该写出「统计」一格（v17）：%r" % ks
    assert any(ln.startswith("统计页 Ctrl+方向键") and "降序" in ln for ln in ks), \
        "键位表里该有统计页排序那行（v17；v27 改口径为「反转升 / 降序」）：%r" % ks
    # v22 立、v32.3 改：F 跳搜索框（`/` 副键随「只要 F」删除）；Ctrl+Home / End 跳首末行
    assert any(ln.startswith("F ") and "搜索框" in ln for ln in ks), \
        "v32.3：键位表里该有 F 跳搜索框那行：%r" % ks
    assert any(ln.startswith("Ctrl+Home") and "第一行" in ln and "最后一行" in ln for ln in ks), \
        "键位表里该有 Ctrl+Home / End 跳首末行那行（v22）：%r" % ks
    # v26.1：菜单热键一行（v37 删 Ctrl+2；v53：Ctrl+1 随导入块删除 —— 只剩 Ctrl+3）
    assert any(ln.startswith("Ctrl+3") and "快捷键设置" in ln for ln in ks), \
        "键位表里该有 Ctrl+3 菜单热键那行（v26.1 立、v37 删 Ctrl+2、v53 删 Ctrl+1）：%r" % ks
    # v65：Ctrl+1 / Ctrl+2 重新启用为「直达看板 / 统计页」（v53 删的「导入块」用途不回来）
    assert any(ln.startswith('Ctrl+1 / Ctrl+2') and '直达看板' in ln for ln in ks), \
        'v65：键位表该有 Ctrl+1 / Ctrl+2 直达那行：%r' % ks
    assert any(ln.startswith('Ctrl+T') and '当前行颜色' in ln for ln in ks), \
        'v65/v75.3：键位表该有 Ctrl+T 切当前行颜色那行：%r' % ks
    assert any(ln.startswith('Ctrl+P') and '题解预览档' in ln for ln in ks), \
        'v65：键位表该有 Ctrl+P 题解预览档那行：%r' % ks
    # v40 立、v87 改：设置界面一行（`?`；菜单栏整条删除后的新入口 —— Ctrl+Tab 行已并进它）
    assert any(ln.startswith("?") and "整个界面" in ln and "设置页" in ln for ln in ks), \
        "v87：键位表里该有 `?` 设置界面那行：%r" % ks
    assert not any(ln.startswith("Ctrl+Tab") for ln in ks), \
        "v87：Ctrl+Tab 那行该删干净：%r" % ks
    # v42：设置界面**走法**一行；v55：设置页独立 —— 走法行补 → 进面板 / 回车确认、← / → 行去掉「设置页」
    assert any(ln.startswith("设置界面") and "左列表" in ln and "回车确认" in ln for ln in ks), \
        "键位表里该有「设置界面」走法那行（v42 / v55）：%r" % ks
    assert any(ln.startswith("← / →") and "右侧题解预览" in ln and "走开只是看不见" in ln
               and "设置页" not in ln for ln in ks), \
        "v50/v55：← / → 那行该写「右侧题解预览跟着它那一格走：走开只是看不见、走回来还在」（设置页已独立）：%r" % ks
    assert any(ln.startswith("← / →") and "全屏 md 里 = 上一题 / 下一题" in ln for ln in ks), \
        "v83：← / → 那行该写出「全屏 md 里 = 上一题 / 下一题」：%r" % ks
    # v32 立、v46 改：右侧题解预览 / 展开 md 那行现在挂在「Enter」上（上面已断言），P 行须已删
    # v27：统计页「按场次」视图切换一行（Ctrl+K）+ 统计页两行改口径
    assert any(ln.startswith("统计页 Ctrl+K") and "视图切换" in ln for ln in ks), \
        "键位表里该有「统计页 Ctrl+K 视图切换」那行（v27）：%r" % ks
    assert any(ln.startswith("统计页 Ctrl+方向键") and "题目行 = 题解 md" in ln for ln in ks), \
        "v46：统计页排序那行该写「题目行 = 题解 md」：%r" % ks
    # ---- v87：`?` = 开关（进出都它）；搜索框里 = 打字（让位不切界面）；Esc 退出设置页 ----
    gui.set_left.focus_set()
    root.update()
    gui._on_settings_esc()
    root.update()
    assert not gui._in_settings(), "v87：Esc 应退出设置页"
    assert gui.main_frame.winfo_manager() == "pack", "退出后主界面该摆回来"
    gui.tree.focus_force()
    root.update()
    gui.tree.event_generate("<KeyPress>", keysym="question")
    root.update()
    assert gui._in_settings(), "v87：主界面按 ? 进设置"
    gui.set_left.focus_force()
    root.update()
    gui.set_left.event_generate("<KeyPress>", keysym="question")
    root.update()
    assert not gui._in_settings(), "v87：设置里再按 ? = 关（开关式）"
    gui.ent_search.focus_force()
    root.update()
    gui.var_search.set("")
    root.update()
    gui.ent_search.event_generate("<KeyPress>", keysym="question")
    root.update()
    assert (not gui._in_settings()) and gui.var_search.get() == "?", \
        "v87：搜索框里打 ? = 打字符、不切界面（打字让位）：%r" % gui.var_search.get()
    gui.var_search.set("")
    gui.refresh_view()
    root.update()
    print("? 快捷键一览（v87：设置页第三块）：%d 行键位表原文；? 开关进出 / Esc 退出 / 搜索框里照常打字" % len(ks))
    print("(kk) 一览与 KEY_TABLE 一字不差：%d 行（v26.1 起 22、v27 起 23、v32 起 24、v40 起 25、v42 起 26、"
          "v46 删资料行 = 25、v49 加 Alt 行 = 26、v53 改 Ctrl+3 行仍 26、v87 删 Ctrl+Tab 行 = 29）、"
          "有裸 F 跳到搜索框行（v32.3；F5 / F11 不算）、有 F11 全屏行、"
          "有「搜索框」多字段一行（v18）、有统计页两行（v17）、"
          "有 Ctrl+Y 复原一行（v20）、有 Ctrl+Home / End 跳首末行行（v22）、"
          "有 `?` 设置界面行 + Ctrl+3 设置界面热键行（v40 立、v53 删 Ctrl+1、v87 Ctrl+Tab 并进 ?）、有设置界面走法行（v42）、"
          "有回车族三行（v46：Enter 展开 md / Ctrl+Enter 浮层 / Alt+Enter 跳题目链接）、"
          "无 Shift+Enter 行、无 P 行、无「打开这题的资料」行、"
          "无「下拉面板 / 面板里」两行、无「下拉框」控件字样 ✓" % len(ks))

    # --- v4 闸门 (c)：搜索**跟题**（选中的题还在结果里 → 仍选它；被搜掉 → 回第一行）（v9：筛选半边删除）
    gui.sort_col, gui.sort_desc = "场次", False
    gui.var_search.set("")
    gui.refresh_view()
    hits = [x for x in gui.tree.get_children()
            if "双指针" in gui.row_by_iid(x)["知识点"]
            or "双指针" in gui.row_by_iid(x)["题名"]]
    assert len(hits) >= 2, "fixture 里「双指针」应至少命中两行，这条才测得动"
    gui.tree.selection_set(hits[1])               # 挑第 2 条命中：保得住才算真跟题
    gui.tree.focus(hits[1])
    srow = gui.row_by_iid(hits[1])
    gui.var_search.set("双指针")
    gui.refresh_view()
    got = gui.row_by_iid(gui.tree.focus())
    assert got is not None and (got["场次"], got["题号"]) == (srow["场次"], srow["题号"]), \
        "搜索后选中的题还在结果里，就该继续选它（现在是 %s）" % (got and got["题号"],)
    assert gui._index_of(gui.tree) == 1, "它应落在结果第 1 行（真跟题，不是被贴回第 0 行）"
    print("(c) 搜索跟题：搜「双指针」后仍选中原来那条（第 1 行）✓")

    gui.var_search.set("")
    gui.refresh_view()
    other_iid = next(x for x in gui.tree.get_children()
                     if "双指针" not in gui.row_by_iid(x)["知识点"]
                     and "双指针" not in gui.row_by_iid(x)["题名"])
    gui.tree.selection_set(other_iid)             # 先选一道搜「双指针」搜不到的题
    gui.tree.focus(other_iid)
    gui.tree.see(other_iid)
    gui.var_search.set("双指针")
    gui.refresh_view()
    assert gui.tree.focus() == gui.tree.get_children()[0], \
        "原来选中的题被搜掉后，选中应贴回第一行（focus 也在第一行）"
    print("(c) 搜索搜掉选中行：「双指针」结果里没有它 → 贴回第一行（focus 也在第一行）✓")
    gui.var_search.set("")
    gui.refresh_view()

    # --- v5 闸门 (i)：搜索框里 Enter 跳回总表（搜索词保留、结果不丢、选中跟题；v14 起 ↓ 改作展开下拉）
    gui.var_search.set("")
    gui.refresh_view()
    hits = [x for x in gui.tree.get_children()
            if "双指针" in gui.row_by_iid(x)["知识点"]
            or "双指针" in gui.row_by_iid(x)["题名"]]
    assert len(hits) >= 2, "fixture 里「双指针」应至少命中两行，这条才测得动"
    gui.tree.selection_set(hits[1])
    gui.tree.focus(hits[1])
    srow = gui.row_by_iid(hits[1])
    gui.var_search.set("双指针")
    gui.refresh_view()
    want_rows = len(gui.tree.get_children())
    gui.ent_search.focus_set()
    root.update()
    assert root.focus_get() is gui.ent_search, root.focus_get()
    gui.ent_search.event_generate("<KeyPress>", keysym="Return")
    root.update()
    assert root.focus_get() is gui.tree, root.focus_get()
    assert gui.var_search.get() == "双指针", "Enter 跳转不该动搜索词"
    assert len(gui.tree.get_children()) == want_rows, "Enter 跳转不该改搜索出的结果"
    got = gui.row_by_iid(gui.tree.focus())
    assert got is not None and (got["场次"], got["题号"]) == (srow["场次"], srow["题号"]), \
        "跳回总表后该保住的还是原来那道题（现在是 %s）" % (got and got["题号"],)
    gui.ent_search.focus_set()
    root.update()
    gui.ent_search.event_generate("<KeyPress>", keysym="Down")   # v21：↓ 进主表
    root.update()
    assert root.focus_get() is gui.tree, "v21：搜索框 ↓ 应进主表（焦点给表格）"
    gui.ent_search.focus_set()
    root.update()
    gui.ent_search.event_generate("<KeyPress>", keysym="Up")     # v21：↑ 同样进主表
    root.update()
    assert root.focus_get() is gui.tree, "v21：搜索框 ↑ 应进主表（焦点给表格）"
    gui.nb.select(1)                                             # 看板页上跳转也先切回总表
    gui._jump_to_table()
    assert gui.nb.index(gui.nb.select()) == 0, "看板页上跳转要先切回总表页"
    print("(i) 搜索框里 Enter 跳回总表：焦点在表格、搜索词没清、结果仍是搜出来的、"
          "选中跟题（看板页上先切回总表）✓")
    gui.var_search.set("")
    gui.refresh_view()

    # --- v5 闸门 (j) 已随「状态筛选」整块删除（没有筛选下拉了，Enter 跳转只剩搜索框那一半，
    #     由上面的 (i) 覆盖）。

    # 搜索打「知识点」与空结果：v9 起搜不到就是空表（不再有「无匹配」占位行）
    gui.var_search.set("双指针")
