    url_w3, why_w3 = gui.parse_problem_url({"场次": "周赛 164", "题号": "A"})
    assert (url_w3, why_w3) == (None, "没找到这场比赛的原题链接"), (url_w3, why_w3)
    url_w4, why_w4 = gui.parse_problem_url({"场次": "洛谷训练赛 Round 5", "题号": "A"})
    assert (url_w4, why_w4) == (None, "这场还没接"), (url_w4, why_w4)
    # v79：AtCoder / CF 两条新分支（md 头部链接 → 单题 url）
