    gui.tree.focus_force()          # 合成按键前一律 focus_force（见 (jj) 注释）
    root.update()
    gui.tree.event_generate("<KeyPress>", keysym="Return", state=0x20000)   # = Alt+Enter（state=0x20000 实测口径）
    root.update()
    row_v["场次"], row_v["题号"] = saved_v
    assert gui.popup is None, "Alt+Enter 不该弹状态浮层（树自己的回车别抢）"
    assert opened == [url_w], "Alt+Enter 该把拼好的原题 URL 交给 opener：%r" % (opened,)
    # 场次不是「牛客周赛 Round N」形式 → 「打不开：这场还没接」（经按键，提示同风格）
