    gui._undo()                                       # = Ctrl+Z
    back_y = open(tmp, "rb").read()
    assert len(back_y) == len(bytes_y0), (len(bytes_y0), len(back_y))
    assert back_y == bytes_y0, "空日期行撤销后该与改前逐字节相同（空日期格恢复两空格形态）"
    assert gui._last_change is None, "撤销后记录清空（只记一步）"
