        {"场次": "Codeforces Round 161", "题号": "B", "_i": 1},
        {"场次": "洛谷月赛 Round 5", "题号": "A", "_i": 2},          # 认不出：该排最后
        {"场次": "牛客周赛 Round 161", "题号": "A", "_i": 3},
        {"场次": "Codeforces Round 161", "题号": "A", "_i": 4},
        {"场次": "牛客周赛 Round 99", "题号": "F", "_i": 5},
