    assert gui.nb.index(gui.nb.select()) == 2, "还在统计页"
    assert root.focus_get() is gui.know_tree, "v51：统计页行上 Esc 不再往搜索框送焦点"
    gui.var_search.set("")
    gui.refresh_know()
    root.update()
