    gui._on_digit_key(2, gui.know_tree)         # 不抛即可
    print("(ab) 知识点统计页（v17 立 / v18 扩）：拆名保重复（组合计数 ×2）、父子折叠（父行=子孙合计 / "
          "子行不进顶层 / **v33 层级色阶：顶层行（父+平铺）杏黄浅深整片交替、子行草绿 lvl2/lvl2b 块内交替**）、Enter 展开收起、子行 / 叶行 Enter 跳总表搜（**灰字提示已隐、不挡字**）、"
          "升 / 降序单调、**v51：统计页不再按搜索词过滤**（计数恒「共 N 个知识点」）、"
          "**行上 Esc 清搜索 + 原路退回**（v18：只要还含知识点名就退、追加字段照退 / 名字被改则不退；v51：清搜索只在总表页）、"
          "**统计页 Esc 收起展开的父行**（v18：子行 / 父行上都收、光标落父行，没展开的行不归它管）、"
          "换排序钉原行号、统计行不当题目处理 ✓（顶层 %d 行 / %d 题）" % (len(tops), len(gui.rows)))

    # --- v27 闸门 (ab2)：统计页「按场次」视图 —— 三层展开 + 题目行 1~6 直改 + Esc（v51：不再按词筛）
    write_fixture(tmp)                           # 前面几段改过夹具状态 → 重造一份干净的
    gui.reload()
    gui.var_search.set("")
