    r203 = "R|牛客周赛 Round 203"
    assert "（1 题·AC 0·0%）" in gui.round_tree.item(r203, "values")[0], \
        gui.round_tree.item(r203, "values")      # 203D = 巩固 → 0%
    # v27.2（用户点名）：表头带当前排序的三角；Ctrl+方向键反转 → ▲ 且场次倒序、再按回来
    # （v74：▲ = 降序、▼ = 升序 —— 用户拍板对调）
    assert gui.round_tree.heading("场次")["text"].endswith("▼"), \
        gui.round_tree.heading("场次")["text"]
